{
  "name": "SISREQ - Sistema de Requerimientos",
  "description": "Workflow management system for interdepartmental requests with strict role-based progression (Admin, Heads, Analysts)."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum UserRole {
  ADMIN = 'ADMIN', // Evelin
  HEAD = 'HEAD',   // Jefatura (Vania, Rodrigo, Yerman)
  ANALYST = 'ANALYST' // Analistas
}

export enum Area {
  CONTABILIDAD = 'Contabilidad',
  RRHH = 'RRHH',
  ACREDITACION = 'Acreditación'
}

export enum Status {
  RECIBIDO = 'Recibido',
  DERIVACION = 'En Derivación',
  EJECUCION = 'En Ejecución',
  FINALIZADO = 'Finalizado'
}

export enum Priority {
  HIGH = 'Alta',
  MEDIUM = 'Media',
  LOW = 'Baja'
}

export interface User {
  id: string;
  name: string;
  role: UserRole;
  area?: Area; // Admin doesn't need an area
}

export interface LogEntry {
  id: string;
  timestamp: string;
  message: string;
  actor: string;
}

export interface RequestCard {
  id: string;
  title: string;
  detail: string;
  requester: string;
  area: Area;
  status: Status;
  priority: Priority;
  responsibleHead: string; // Name of the head
  assignedAnalyst?: string; // Name of the analyst
  logs: LogEntry[];
  createdAt: string;
  finishedAt?: string;
  isReturned?: boolean; // Flag if it was returned by head
}

import { Area, Status, User, UserRole } from './types';

export const USERS: User[] = [
  { id: 'u1', name: 'Evelin (Admin)', role: UserRole.ADMIN },
  { id: 'u2', name: 'Vania (Jefa Contabilidad)', role: UserRole.HEAD, area: Area.CONTABILIDAD },
  { id: 'u3', name: 'Rodrigo (Jefe RRHH)', role: UserRole.HEAD, area: Area.RRHH },
  { id: 'u4', name: 'Yerman (Jefe Acreditación)', role: UserRole.HEAD, area: Area.ACREDITACION },
  { id: 'u5', name: 'Analista Cont.', role: UserRole.ANALYST, area: Area.CONTABILIDAD },
  { id: 'u6', name: 'Analista RRHH', role: UserRole.ANALYST, area: Area.RRHH },
  { id: 'u7', name: 'Analista Acred.', role: UserRole.ANALYST, area: Area.ACREDITACION },
];

export const AREA_HEADS: Record<Area, string> = {
  [Area.CONTABILIDAD]: 'Vania',
  [Area.RRHH]: 'Rodrigo',
  [Area.ACREDITACION]: 'Yerman',
};

export const STATUS_COLORS: Record<Status, string> = {
  [Status.RECIBIDO]: 'border-l-4 border-blue-500 bg-blue-50',
  [Status.DERIVACION]: 'border-l-4 border-orange-500 bg-orange-50',
  [Status.EJECUCION]: 'border-l-4 border-yellow-500 bg-yellow-50',
  [Status.FINALIZADO]: 'border-l-4 border-green-500 bg-green-50',
};

export const STATUS_BADGE_COLORS: Record<Status, string> = {
  [Status.RECIBIDO]: 'bg-blue-100 text-blue-800',
  [Status.DERIVACION]: 'bg-orange-100 text-orange-800',
  [Status.EJECUCION]: 'bg-yellow-100 text-yellow-800',
  [Status.FINALIZADO]: 'bg-green-100 text-green-800',
};

import { RequestCard, Priority, Status, Area, UserRole } from '../types';
import { AREA_HEADS } from '../constants';

const STORAGE_KEY = 'SISREQ_DATA_V1';

const INITIAL_DATA: RequestCard[] = [
  {
    id: 'req-1',
    title: 'Balance Mensual Agosto',
    detail: 'Se requiere el balance ajustado para presentación de directorio.',
    requester: 'Gerencia General',
    area: Area.CONTABILIDAD,
    status: Status.RECIBIDO,
    priority: Priority.HIGH,
    responsibleHead: AREA_HEADS[Area.CONTABILIDAD],
    createdAt: new Date().toISOString(),
    logs: [
      {
        id: 'l1',
        timestamp: new Date().toISOString(),
        message: 'Requerimiento creado en Control General',
        actor: 'Evelin (Admin)'
      }
    ]
  },
  {
    id: 'req-2',
    title: 'Contratación Reemplazo',
    detail: 'Búsqueda de reemplazo para licencia médica en operaciones.',
    requester: 'Jefe Operaciones',
    area: Area.RRHH,
    status: Status.DERIVACION,
    priority: Priority.MEDIUM,
    responsibleHead: AREA_HEADS[Area.RRHH],
    createdAt: new Date().toISOString(),
    logs: [
      {
        id: 'l2',
        timestamp: new Date().toISOString(),
        message: 'Requerimiento derivado a RRHH',
        actor: 'Evelin (Admin)'
      }
    ]
  }
];

export const loadRequests = (): RequestCard[] => {
  const stored = localStorage.getItem(STORAGE_KEY);
  return stored ? JSON.parse(stored) : INITIAL_DATA;
};

export const saveRequests = (requests: RequestCard[]) => {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(requests));
};

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { User, RequestCard, Status, LogEntry, Priority, Area, UserRole } from '../types';
import { USERS, AREA_HEADS } from '../constants';
import { loadRequests, saveRequests } from '../services/storage';

interface SisreqContextType {
  currentUser: User;
  setCurrentUser: (user: User) => void;
  requests: RequestCard[];
  addRequest: (title: string, detail: string, area: Area, priority: Priority, requester: string) => void;
  updateStatus: (id: string, newStatus: Status) => void;
  returnRequest: (id: string, reason: string) => void;
  assignAnalyst: (id: string, analystName: string) => void;
  addLog: (id: string, message: string) => void;
}

const SisreqContext = createContext<SisreqContextType | undefined>(undefined);

export const SisreqProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User>(USERS[0]); // Default to Evelin
  const [requests, setRequests] = useState<RequestCard[]>([]);

  useEffect(() => {
    setRequests(loadRequests());
  }, []);

  useEffect(() => {
    if (requests.length > 0) {
      saveRequests(requests);
    }
  }, [requests]);

  const addRequest = useCallback((title: string, detail: string, area: Area, priority: Priority, requester: string) => {
    const newRequest: RequestCard = {
      id: `req-${Date.now()}`,
      title,
      detail,
      area,
      status: Status.RECIBIDO,
      priority,
      requester,
      responsibleHead: AREA_HEADS[area],
      createdAt: new Date().toISOString(),
      logs: [{
        id: `log-${Date.now()}`,
        timestamp: new Date().toISOString(),
        message: `Requerimiento creado por ${currentUser.name}`,
        actor: currentUser.name
      }]
    };
    setRequests(prev => [...prev, newRequest]);
  }, [currentUser]);

  const addLog = useCallback((id: string, message: string) => {
    setRequests(prev => prev.map(req => {
      if (req.id !== id) return req;
      return {
        ...req,
        logs: [
          ...req.logs,
          {
            id: `log-${Date.now()}`,
            timestamp: new Date().toISOString(),
            message,
            actor: currentUser.name
          }
        ]
      };
    }));
  }, [currentUser]);

  const updateStatus = useCallback((id: string, newStatus: Status) => {
    setRequests(prev => prev.map(req => {
      if (req.id !== id) return req;

      const statusChangeLog = `Estado cambiado a: ${newStatus}`;
      const finishedLog = newStatus === Status.FINALIZADO ? `Requerimiento finalizado por ${currentUser.name}` : statusChangeLog;

      return {
        ...req,
        status: newStatus,
        finishedAt: newStatus === Status.FINALIZADO ? new Date().toISOString() : req.finishedAt,
        isReturned: false, // Reset returned flag if it moves forward
        logs: [
          ...req.logs,
          {
            id: `log-${Date.now()}`,
            timestamp: new Date().toISOString(),
            message: newStatus === Status.DERIVACION 
              ? `Requerimiento derivado al área ${req.area} por ${currentUser.name}`
              : newStatus === Status.EJECUCION
                ? `Ejecución iniciada por ${currentUser.name}`
                : finishedLog,
            actor: currentUser.name
          }
        ]
      };
    }));
  }, [currentUser]);

  const returnRequest = useCallback((id: string, reason: string) => {
    setRequests(prev => prev.map(req => {
      if (req.id !== id) return req;
      return {
        ...req,
        status: Status.RECIBIDO, // Back to start for Admin to review
        isReturned: true,
        logs: [
          ...req.logs,
          {
            id: `log-${Date.now()}`,
            timestamp: new Date().toISOString(),
            message: `DEVUELTO: ${reason}`,
            actor: currentUser.name
          }
        ]
      };
    }));
  }, [currentUser]);

  const assignAnalyst = useCallback((id: string, analystName: string) => {
    setRequests(prev => prev.map(req => {
      if (req.id !== id) return req;
      return {
        ...req,
        assignedAnalyst: analystName,
        logs: [
          ...req.logs,
          {
            id: `log-${Date.now()}`,
            timestamp: new Date().toISOString(),
            message: `Analista asignado: ${analystName}`,
            actor: currentUser.name
          }
        ]
      };
    }));
  }, [currentUser]);

  return (
    <SisreqContext.Provider value={{
      currentUser,
      setCurrentUser,
      requests,
      addRequest,
      updateStatus,
      returnRequest,
      assignAnalyst,
      addLog
    }}>
      {children}
    </SisreqContext.Provider>
  );
};

export const useSisreq = () => {
  const context = useContext(SisreqContext);
  if (context === undefined) {
    throw new Error('useSisreq must be used within a SisreqProvider');
  }
  return context;
};

import React, { useState } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { Area, Priority } from '../types';
import { X } from 'lucide-react';

interface Props {
  isOpen: boolean;
  onClose: () => void;
}

export const NewRequestModal: React.FC<Props> = ({ isOpen, onClose }) => {
  const { addRequest } = useSisreq();
  const [title, setTitle] = useState('');
  const [detail, setDetail] = useState('');
  const [requester, setRequester] = useState('');
  const [area, setArea] = useState<Area>(Area.CONTABILIDAD);
  const [priority, setPriority] = useState<Priority>(Priority.MEDIUM);

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title || !detail || !requester) return;
    addRequest(title, detail, area, priority, requester);
    setTitle('');
    setDetail('');
    setRequester('');
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50 backdrop-blur-sm">
      <div className="bg-white rounded-lg shadow-xl w-full max-w-lg p-6 animate-in fade-in zoom-in duration-200">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-xl font-bold text-gray-800">Nuevo Requerimiento</h2>
          <button onClick={onClose} className="text-gray-500 hover:text-gray-700">
            <X size={24} />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700">Solicitante</label>
            <input
              type="text"
              required
              className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500"
              value={requester}
              onChange={(e) => setRequester(e.target.value)}
              placeholder="Ej: Gerencia Comercial"
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700">Título</label>
            <input
              type="text"
              required
              className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="Resumen corto del pedido"
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700">Área Destino</label>
            <select
              className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500"
              value={area}
              onChange={(e) => setArea(e.target.value as Area)}
            >
              {Object.values(Area).map((a) => (
                <option key={a} value={a}>{a}</option>
              ))}
            </select>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700">Prioridad</label>
              <select
                className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500"
                value={priority}
                onChange={(e) => setPriority(e.target.value as Priority)}
              >
                {Object.values(Priority).map((p) => (
                  <option key={p} value={p}>{p}</option>
                ))}
              </select>
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700">Detalle</label>
            <textarea
              required
              rows={3}
              className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500"
              value={detail}
              onChange={(e) => setDetail(e.target.value)}
              placeholder="Descripción completa..."
            />
          </div>

          <div className="flex justify-end pt-4 space-x-3">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 text-sm font-medium text-gray-700 bg-gray-100 rounded-md hover:bg-gray-200"
            >
              Cancelar
            </button>
            <button
              type="submit"
              className="px-4 py-2 text-sm font-medium text-white bg-blue-600 rounded-md hover:bg-blue-700 shadow-sm"
            >
              Crear Requerimiento
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { RequestCard as RequestCardType, UserRole, Status, Area } from '../types';
import { useSisreq } from '../context/SisreqContext';
import { STATUS_COLORS, STATUS_BADGE_COLORS, USERS } from '../constants';
import { AlertCircle, ArrowRight, User as UserIcon, MessageSquare, Clock, CheckCircle } from 'lucide-react';

interface Props {
  data: RequestCardType;
}

export const RequestCard: React.FC<Props> = ({ data }) => {
  const { currentUser, updateStatus, returnRequest, assignAnalyst, addLog } = useSisreq();
  const [showLogs, setShowLogs] = useState(false);
  const [showReturnInput, setShowReturnInput] = useState(false);
  const [returnReason, setReturnReason] = useState('');
  const [showAnalystSelect, setShowAnalystSelect] = useState(false);
  const [newComment, setNewComment] = useState('');
  const [showCommentInput, setShowCommentInput] = useState(false);

  // LOGIC HELPERS
  const isAdmin = currentUser.role === UserRole.ADMIN;
  const isHead = currentUser.role === UserRole.HEAD;
  const isAnalyst = currentUser.role === UserRole.ANALYST;

  // Can current user see buttons?
  const canAct = () => {
    if (isAdmin) {
      // Admin only acts on Recibido
      return data.status === Status.RECIBIDO;
    }
    if (isHead) {
      // Head acts on Derivation, Execution, and matches Area
      return (data.status === Status.DERIVACION || data.status === Status.EJECUCION) && currentUser.area === data.area;
    }
    // Analyst cannot change status
    return false;
  };

  const handleDerive = () => {
    if (confirm('¿Derivar este requerimiento al área correspondiente?')) {
      updateStatus(data.id, Status.DERIVACION);
    }
  };

  const handleStartExecution = () => {
    updateStatus(data.id, Status.EJECUCION);
  };

  const handleFinalize = () => {
    if (confirm('¿Confirmar finalización del requerimiento?')) {
      updateStatus(data.id, Status.FINALIZADO);
    }
  };

  const handleReturnSubmit = () => {
    if (returnReason.trim()) {
      returnRequest(data.id, returnReason);
      setShowReturnInput(false);
      setReturnReason('');
    }
  };

  const handleAssignAnalyst = (analystName: string) => {
    assignAnalyst(data.id, analystName);
    setShowAnalystSelect(false);
  };

  const handleAddComment = () => {
    if (newComment.trim()) {
      addLog(data.id, `Nota: ${newComment}`);
      setNewComment('');
      setShowCommentInput(false);
    }
  };

  // Filter analysts for dropdown
  const availableAnalysts = USERS.filter(u => u.role === UserRole.ANALYST && u.area === data.area);

  return (
    <div className={`bg-white rounded-lg shadow-sm mb-4 p-4 transition-all hover:shadow-md ${STATUS_COLORS[data.status]} relative group`}>

      {/* Header */}
      <div className="flex justify-between items-start mb-2">
        <span className={`px-2 py-1 rounded text-xs font-semibold ${STATUS_BADGE_COLORS[data.status]}`}>
          {data.status.toUpperCase()}
        </span>
        <div className="flex items-center space-x-1">
            {data.isReturned && (
                 <span className="text-xs bg-red-100 text-red-700 px-2 py-1 rounded font-bold animate-pulse">DEVUELTO</span>
            )}
           <span className={`text-xs px-2 py-1 rounded border ${
             data.priority === 'Alta' ? 'bg-red-50 border-red-200 text-red-700' : 
             data.priority === 'Media' ? 'bg-yellow-50 border-yellow-200 text-yellow-700' : 
             'bg-gray-50 border-gray-200 text-gray-600'
           }`}>
             {data.priority}
           </span>
        </div>
      </div>

      <h3 className="font-bold text-gray-800 mb-1">{data.title}</h3>
      <p className="text-sm text-gray-600 mb-3 line-clamp-2">{data.detail}</p>

      {/* Meta Data */}
      <div className="text-xs text-gray-500 space-y-1 mb-4">
        <div className="flex items-center gap-1">
            <UserIcon size={12}/>
            <span>Solicita: {data.requester}</span>
        </div>
        <div className="flex items-center gap-1">
            <div className="w-3 h-3 rounded-full bg-blue-500"></div>
            <span>Destino: {data.area} ({data.responsibleHead})</span>
        </div>
        {data.assignedAnalyst && (
          <div className="flex items-center gap-1 font-medium text-purple-700">
             <div className="w-3 h-3 rounded-full bg-purple-500"></div>
             <span>Analista: {data.assignedAnalyst}</span>
          </div>
        )}
      </div>

      {/* Actions Section */}
      <div className="border-t pt-3 mt-2 flex flex-col gap-2">

        {/* Admin Actions */}
        {isAdmin && data.status === Status.RECIBIDO && (
          <button 
            onClick={handleDerive}
            className="w-full flex justify-center items-center gap-2 bg-orange-600 hover:bg-orange-700 text-white py-1.5 px-3 rounded text-sm transition-colors"
          >
            Derivar <ArrowRight size={14}/>
          </button>
        )}

        {/* Head Actions - Derivation Phase */}
        {isHead && data.status === Status.DERIVACION && data.area === currentUser.area && (
          <div className="flex flex-col gap-2">
            <div className="flex gap-2">
                <button 
                onClick={handleStartExecution}
                className="flex-1 bg-yellow-500 hover:bg-yellow-600 text-white py-1.5 px-2 rounded text-sm font-medium"
                >
                Iniciar
                </button>
                <button 
                onClick={() => setShowAnalystSelect(!showAnalystSelect)}
                className="flex-1 bg-purple-600 hover:bg-purple-700 text-white py-1.5 px-2 rounded text-sm font-medium"
                >
                Asignar
                </button>
            </div>

            {!showReturnInput ? (
                 <button 
                 onClick={() => setShowReturnInput(true)}
                 className="w-full bg-gray-200 hover:bg-gray-300 text-gray-700 py-1.5 px-2 rounded text-sm"
               >
                 Devolver / Rechazar
               </button>
            ) : (
                <div className="bg-gray-50 p-2 rounded border">
                    <input 
                        className="w-full text-xs p-1 border rounded mb-2"
                        placeholder="Razón de devolución..."
                        value={returnReason}
                        onChange={e => setReturnReason(e.target.value)}
                    />
                    <div className="flex gap-2">
                        <button onClick={handleReturnSubmit} className="bg-red-500 text-white px-2 py-1 rounded text-xs">Confirmar</button>
                        <button onClick={() => setShowReturnInput(false)} className="text-gray-500 px-2 py-1 text-xs">Cancelar</button>
                    </div>
                </div>
            )}

            {showAnalystSelect && (
                 <div className="bg-purple-50 p-2 rounded border border-purple-100 animate-in slide-in-from-top-2">
                    <p className="text-xs text-purple-800 mb-1 font-semibold">Seleccionar Analista:</p>
                    <div className="grid grid-cols-1 gap-1">
                        {availableAnalysts.map(a => (
                            <button 
                                key={a.id} 
                                onClick={() => handleAssignAnalyst(a.name)}
                                className="text-left text-xs bg-white hover:bg-purple-100 p-1.5 rounded border border-purple-100"
                            >
                                {a.name}
                            </button>
                        ))}
                    </div>
                 </div>
            )}
          </div>
        )}

        {/* Head Actions - Execution Phase */}
        {isHead && data.status === Status.EJECUCION && data.area === currentUser.area && (
             <button 
             onClick={handleFinalize}
             className="w-full flex justify-center items-center gap-2 bg-green-600 hover:bg-green-700 text-white py-2 px-3 rounded text-sm font-medium shadow-sm"
             >
             <CheckCircle size={16}/> Finalizar Tarea
             </button>
        )}

        {/* Comment / Log Actions (Available to everyone involved) */}
        {(isHead || isAnalyst || isAdmin) && (
            <div className="mt-2">
                {!showCommentInput ? (
                    <div className="flex justify-between text-xs text-gray-400">
                         <button onClick={() => setShowLogs(!showLogs)} className="hover:text-blue-500 flex items-center gap-1">
                            <Clock size={12}/> Historial ({data.logs.length})
                        </button>
                        <button onClick={() => setShowCommentInput(true)} className="hover:text-blue-500 flex items-center gap-1">
                            <MessageSquare size={12}/> Nota
                        </button>
                    </div>
                ) : (
                    <div className="mt-1">
                        <textarea
                            value={newComment}
                            onChange={e => setNewComment(e.target.value)}
                            className="w-full text-xs p-2 border rounded focus:ring-1 focus:ring-blue-500"
                            placeholder="Escribe una nota interna..."
                            rows={2}
                        />
                         <div className="flex justify-end gap-2 mt-1">
                            <button onClick={() => setShowCommentInput(false)} className="text-xs text-gray-500">Cancelar</button>
                            <button onClick={handleAddComment} className="text-xs bg-blue-600 text-white px-2 py-1 rounded">Guardar</button>
                        </div>
                    </div>
                )}
            </div>
        )}
      </div>

        {/* Logs Overlay */}
        {showLogs && (
            <div className="absolute inset-0 bg-white z-10 p-4 rounded-lg overflow-y-auto border border-gray-200 shadow-inner text-xs">
                <div className="flex justify-between items-center mb-3 pb-2 border-b">
                    <h4 className="font-bold text-gray-700">Historial de Movimientos</h4>
                    <button onClick={() => setShowLogs(false)}><XIcon size={14}/></button>
                </div>
                <div className="space-y-3">
                    {data.logs.map((log) => (
                        <div key={log.id} className="relative pl-3 border-l-2 border-gray-200">
                            <div className="text-gray-500 text-[10px]">{new Date(log.timestamp).toLocaleString()}</div>
                            <div className="font-semibold text-gray-800">{log.actor}</div>
                            <div className="text-gray-600">{log.message}</div>
                        </div>
                    ))}
                </div>
            </div>
        )}
    </div>
  );
};

