import React from 'react';
import { useSisreq } from '../context/SisreqContext';
import { RequestCard } from './RequestCard';
import { Status, UserRole } from '../types';

export const Board: React.FC = () => {
  const { requests, currentUser } = useSisreq();

  // Filter requests based on role
  const filteredRequests = requests.filter(req => {
    // Admin sees everything
    if (currentUser.role === UserRole.ADMIN) return true;

    // Heads and Analysts see:
    // 1. Their own area
    // 2. Unless it is in "RECIBIDO" (Not yet derived to them)
    if (req.area === currentUser.area && req.status !== Status.RECIBIDO) {
        return true;
    }
    return false;
  });

  const getRequestsByStatus = (status: Status) => {
    return filteredRequests.filter(req => req.status === status);
  };

  const columns = [
    { title: 'Recibido', status: Status.RECIBIDO, color: 'border-blue-500' },
    { title: 'En Derivación', status: Status.DERIVACION, color: 'border-orange-500' },
    { title: 'En Ejecución', status: Status.EJECUCION, color: 'border-yellow-500' },
    { title: 'Finalizado', status: Status.FINALIZADO, color: 'border-green-500' }
  ];

  return (
    <div className="flex-1 overflow-x-auto overflow-y-hidden">
      <div className="h-full flex px-6 py-6 gap-6 min-w-[1000px]">
        {columns.map((col) => {
            const items = getRequestsByStatus(col.status);
            return (
                <div key={col.status} className="flex-1 flex flex-col min-w-[280px] max-w-[350px]">
                    <div className={`flex items-center justify-between mb-4 pb-2 border-b-2 ${col.color}`}>
                        <h2 className="font-bold text-gray-700 uppercase text-sm tracking-wide">{col.title}</h2>
                        <span className="bg-gray-200 text-gray-700 px-2 py-0.5 rounded-full text-xs font-bold">
                            {items.length}
                        </span>
                    </div>

                    <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar pb-10">
                        {items.length === 0 ? (
                            <div className="h-24 border-2 border-dashed border-gray-200 rounded-lg flex items-center justify-center text-gray-400 text-sm italic">
                                Sin tarjetas
                            </div>
                        ) : (
                            items.map(req => (
                                <RequestCard key={req.id} data={req} />
                            ))
                        )}
                    </div>
                </div>
            )
        })}
      </div>
    </div>
  );
};

