import { RequestCard as RequestCardType, UserRole, Status, Area } from '../types';
import { useSisreq } from '../context/SisreqContext';
import { STATUS_COLORS, STATUS_BADGE_COLORS, USERS } from '../constants';
import { AlertCircle, ArrowRight, User as UserIcon, MessageSquare, Clock, CheckCircle, GripVertical, Pencil, X, Save } from 'lucide-react';

interface Props {
  data: RequestCardType;
}

export const RequestCard: React.FC<Props> = ({ data }) => {
  const { currentUser, updateStatus, returnRequest, assignAnalyst, addLog, updateRequestDetails } = useSisreq();
  const [showLogs, setShowLogs] = useState(false);
  const [showReturnInput, setShowReturnInput] = useState(false);
  const [returnReason, setReturnReason] = useState('');
  const [showAnalystSelect, setShowAnalystSelect] = useState(false);
  const [newComment, setNewComment] = useState('');
  const [showCommentInput, setShowCommentInput] = useState(false);

  // Edit Mode States
  const [isEditing, setIsEditing] = useState(false);
  const [editTitle, setEditTitle] = useState(data.title);
  const [editDetail, setEditDetail] = useState(data.detail);

  // LOGIC HELPERS
  const isAdmin = currentUser.role === UserRole.ADMIN;
  const isHead = currentUser.role === UserRole.HEAD;
  const isAnalyst = currentUser.role === UserRole.ANALYST;

  // Can current user see buttons?
  const canAct = () => {
    if (isAdmin) {
      // Admin only acts on Recibido
      return data.status === Status.RECIBIDO;
    }
    if (isHead) {
      // Head acts on Derivation, Execution, and matches Area
      return (data.status === Status.DERIVACION || data.status === Status.EJECUCION) && currentUser.area === data.area;
    }
    // Analyst cannot change status, but can edit/comment
    return false;
  };

  // Check if user can drag this card
  const isDraggable = () => {
    if (isAdmin && data.status === Status.RECIBIDO) return true;
    if (isHead && data.area === currentUser.area) {
        // Can drag from Derivacion -> Ejecucion OR Ejecucion -> Finalizado
        if (data.status === Status.DERIVACION || data.status === Status.EJECUCION) return true;
    }
    return false;
  };

  const handleDragStart = (e: React.DragEvent) => {
    e.dataTransfer.setData('requestId', data.id);
    e.dataTransfer.setData('currentStatus', data.status);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDerive = () => {
    if (confirm('¿Derivar este requerimiento al área correspondiente?')) {
      updateStatus(data.id, Status.DERIVACION);
    }
  };

  const handleStartExecution = () => {
    updateStatus(data.id, Status.EJECUCION);
  };

  const handleFinalize = () => {
    if (confirm('¿Confirmar finalización del requerimiento?')) {
      updateStatus(data.id, Status.FINALIZADO);
    }
  };

  const handleReturnSubmit = () => {
    if (returnReason.trim()) {
      returnRequest(data.id, returnReason);
      setShowReturnInput(false);
      setReturnReason('');
    }
  };

  const handleAssignAnalyst = (analystName: string) => {
    assignAnalyst(data.id, analystName);
    setShowAnalystSelect(false);
  };

  const handleAddComment = () => {
    if (newComment.trim()) {
      addLog(data.id, `Nota: ${newComment}`);
      setNewComment('');
      setShowCommentInput(false);
    }
  };

  const handleSaveEdit = () => {
    updateRequestDetails(data.id, editTitle, editDetail);
    setIsEditing(false);
  };

  const canEditDetails = () => {
    // Admin can always edit
    if (isAdmin) return true;
    // Head/Analyst can edit if it's their area
    if ((isHead || isAnalyst) && data.area === currentUser.area) return true;
    return false;
  };

  // Filter analysts for dropdown
  const availableAnalysts = USERS.filter(u => u.role === UserRole.ANALYST && u.area === data.area);

  return (
    <div 
        draggable={!isEditing && isDraggable()}
        onDragStart={handleDragStart}
        className={`bg-white rounded-lg shadow-sm mb-4 p-4 transition-all hover:shadow-md border-l-4 ${STATUS_COLORS[data.status].split(' ')[1] || 'border-gray-200'} border-y border-r border-gray-100 relative group ${isDraggable() ? 'cursor-grab active:cursor-grabbing' : ''}`}
    >

      {/* Drag Handle & Status Header */}
      <div className="flex justify-between items-start mb-2">
        <div className="flex items-center gap-2">
            {isDraggable() && <GripVertical size={14} className="text-gray-300" />}
            <span className={`px-2 py-1 rounded text-xs font-semibold ${STATUS_BADGE_COLORS[data.status]}`}>
            {data.status.toUpperCase()}
            </span>
        </div>
        <div className="flex items-center space-x-1">
            {data.isReturned && (
                 <span className="text-xs bg-red-100 text-red-700 px-2 py-1 rounded font-bold animate-pulse">DEVUELTO</span>
            )}
           <span className={`text-xs px-2 py-1 rounded border ${
             data.priority === 'Alta' ? 'bg-red-50 border-red-200 text-red-700' : 
             data.priority === 'Media' ? 'bg-yellow-50 border-yellow-200 text-yellow-700' : 
             'bg-gray-50 border-gray-200 text-gray-600'
           }`}>
             {data.priority}
           </span>
           {canEditDetails() && !isEditing && (
               <button onClick={() => setIsEditing(true)} className="ml-1 p-1 text-gray-400 hover:text-blue-500 rounded-full hover:bg-blue-50 transition-colors">
                   <Pencil size={12}/>
               </button>
           )}
        </div>
      </div>

      {/* Content Area (View or Edit) */}
      {isEditing ? (
        <div className="mb-3 space-y-2 animate-in fade-in">
            <input 
                value={editTitle}
                onChange={(e) => setEditTitle(e.target.value)}
                className="w-full text-sm font-bold border rounded px-2 py-1 focus:ring-2 focus:ring-blue-100 outline-none"
            />
            <textarea 
                value={editDetail}
                onChange={(e) => setEditDetail(e.target.value)}
                className="w-full text-sm border rounded px-2 py-1 h-20 focus:ring-2 focus:ring-blue-100 outline-none resize-none"
            />
            <div className="flex justify-end gap-2">
                <button onClick={() => setIsEditing(false)} className="p-1 text-gray-500 hover:bg-gray-100 rounded"><X size={14}/></button>
                <button onClick={handleSaveEdit} className="p-1 text-blue-600 hover:bg-blue-50 rounded"><Save size={14}/></button>
            </div>
        </div>
      ) : (
        <>
            <h3 className="font-bold text-gray-800 mb-1 leading-tight">{data.title}</h3>
            <p className="text-sm text-gray-600 mb-3 line-clamp-3">{data.detail}</p>
        </>
      )}

      {/* Meta Data */}
      <div className="text-xs text-gray-500 space-y-1 mb-4">
        <div className="flex items-center gap-1">
            <UserIcon size={12}/>
            <span>Solicita: {data.requester}</span>
        </div>
        <div className="flex items-center gap-1">
            <div className="w-3 h-3 rounded-full bg-blue-500"></div>
            <span>Destino: {data.area} ({data.responsibleHead})</span>
        </div>
        {data.assignedAnalyst && (
          <div className="flex items-center gap-1 font-medium text-purple-700">
             <div className="w-3 h-3 rounded-full bg-purple-500"></div>
             <span>Analista: {data.assignedAnalyst}</span>
          </div>
        )}
      </div>

      {/* Actions Section */}
      <div className="border-t pt-3 mt-2 flex flex-col gap-2">

        {/* Admin Actions */}
        {isAdmin && data.status === Status.RECIBIDO && (
          <button 
            onClick={handleDerive}
            className="w-full flex justify-center items-center gap-2 bg-orange-600 hover:bg-orange-700 text-white py-1.5 px-3 rounded text-sm transition-colors"
          >
            Derivar <ArrowRight size={14}/>
          </button>
        )}

        {/* Head Actions - Derivation Phase */}
        {isHead && data.status === Status.DERIVACION && data.area === currentUser.area && (
          <div className="flex flex-col gap-2">
            <div className="flex gap-2">
                <button 
                onClick={handleStartExecution}
                className="flex-1 bg-yellow-500 hover:bg-yellow-600 text-white py-1.5 px-2 rounded text-sm font-medium"
                >
                Iniciar
                </button>
                <button 
                onClick={() => setShowAnalystSelect(!showAnalystSelect)}
                className="flex-1 bg-purple-600 hover:bg-purple-700 text-white py-1.5 px-2 rounded text-sm font-medium"
                >
                Asignar
                </button>
            </div>

            {!showReturnInput ? (
                 <button 
                 onClick={() => setShowReturnInput(true)}
                 className="w-full bg-gray-200 hover:bg-gray-300 text-gray-700 py-1.5 px-2 rounded text-sm"
               >
                 Devolver / Rechazar
               </button>
            ) : (
                <div className="bg-gray-50 p-2 rounded border">
                    <input 
                        className="w-full text-xs p-1 border rounded mb-2"
                        placeholder="Razón de devolución..."
                        value={returnReason}
                        onChange={e => setReturnReason(e.target.value)}
                    />
                    <div className="flex gap-2">
                        <button onClick={handleReturnSubmit} className="bg-red-500 text-white px-2 py-1 rounded text-xs">Confirmar</button>
                        <button onClick={() => setShowReturnInput(false)} className="text-gray-500 px-2 py-1 text-xs">Cancelar</button>
                    </div>
                </div>
            )}

            {showAnalystSelect && (
                 <div className="bg-purple-50 p-2 rounded border border-purple-100 animate-in slide-in-from-top-2">
                    <p className="text-xs text-purple-800 mb-1 font-semibold">Seleccionar Analista:</p>
                    <div className="grid grid-cols-1 gap-1">
                        {availableAnalysts.map(a => (
                            <button 
                                key={a.id} 
                                onClick={() => handleAssignAnalyst(a.name)}
                                className="text-left text-xs bg-white hover:bg-purple-100 p-1.5 rounded border border-purple-100"
                            >
                                {a.name}
                            </button>
                        ))}
                    </div>
                 </div>
            )}
          </div>
        )}

        {/* Head Actions - Execution Phase */}
        {isHead && data.status === Status.EJECUCION && data.area === currentUser.area && (
             <button 
             onClick={handleFinalize}
             className="w-full flex justify-center items-center gap-2 bg-green-600 hover:bg-green-700 text-white py-2 px-3 rounded text-sm font-medium shadow-sm"
             >
             <CheckCircle size={16}/> Finalizar Tarea
             </button>
        )}

        {/* Comment / Log Actions (Available to everyone involved) */}
        {(isHead || isAnalyst || isAdmin) && (
            <div className="mt-2">
                {!showCommentInput ? (
                    <div className="flex justify-between text-xs text-gray-400">
                         <button onClick={() => setShowLogs(!showLogs)} className="hover:text-blue-500 flex items-center gap-1">
                            <Clock size={12}/> Historial ({data.logs.length})
                        </button>
                        <button onClick={() => setShowCommentInput(true)} className="hover:text-blue-500 flex items-center gap-1">
                            <MessageSquare size={12}/> Nota
                        </button>
                    </div>
                ) : (
                    <div className="mt-1">
                        <textarea
                            value={newComment}
                            onChange={e => setNewComment(e.target.value)}
                            className="w-full text-xs p-2 border rounded focus:ring-1 focus:ring-blue-500"
                            placeholder="Escribe una nota interna..."
                            rows={2}
                        />
                         <div className="flex justify-end gap-2 mt-1">
                            <button onClick={() => setShowCommentInput(false)} className="text-xs text-gray-500">Cancelar</button>
                            <button onClick={handleAddComment} className="text-xs bg-blue-600 text-white px-2 py-1 rounded">Guardar</button>
                        </div>
                    </div>
                )}
            </div>
        )}
      </div>

        {/* Logs Overlay */}
        {showLogs && (
            <div className="absolute inset-0 bg-white z-10 p-4 rounded-lg overflow-y-auto border border-gray-200 shadow-inner text-xs">
                <div className="flex justify-between items-center mb-3 pb-2 border-b">
                    <h4 className="font-bold text-gray-700">Historial de Movimientos</h4>
                    <button onClick={() => setShowLogs(false)}><X size={14}/></button>
                </div>
                <div className="space-y-3">
                    {data.logs.map((log) => (
                        <div key={log.id} className="relative pl-3 border-l-2 border-gray-200">
                            <div className="text-gray-500 text-[10px]">{new Date(log.timestamp).toLocaleString()}</div>
                            <div className="font-semibold text-gray-800">{log.actor}</div>
                            <div className="text-gray-600">{log.message}</div>
                        </div>
                    ))}
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { RequestCard } from './RequestCard';
import { Status, UserRole } from '../types';

export const Board: React.FC = () => {
  const { requests, currentUser, updateStatus } = useSisreq();
  const [dragOverColumn, setDragOverColumn] = useState<Status | null>(null);

  // Filter requests based on role
  const filteredRequests = requests.filter(req => {
    // Admin sees everything
    if (currentUser.role === UserRole.ADMIN) return true;

    // Heads and Analysts see:
    // 1. Their own area
    // 2. Unless it is in "RECIBIDO" (Not yet derived to them)
    if (req.area === currentUser.area && req.status !== Status.RECIBIDO) {
        return true;
    }
    return false;
  });

  const getRequestsByStatus = (status: Status) => {
    return filteredRequests.filter(req => req.status === status);
  };

  const handleDragOver = (e: React.DragEvent, status: Status) => {
    e.preventDefault();
    if (dragOverColumn !== status) {
        setDragOverColumn(status);
    }
  };

  const handleDragLeave = () => {
    setDragOverColumn(null);
  };

  const handleDrop = (e: React.DragEvent, targetStatus: Status) => {
    e.preventDefault();
    setDragOverColumn(null);
    const requestId = e.dataTransfer.getData('requestId');
    const currentStatus = e.dataTransfer.getData('currentStatus') as Status;

    // Strict Workflow Rules for Drag & Drop
    let isValidMove = false;

    // Admin: Recibido -> Derivacion
    if (currentUser.role === UserRole.ADMIN) {
        if (currentStatus === Status.RECIBIDO && targetStatus === Status.DERIVACION) isValidMove = true;
    }

    // Head: Derivacion -> Ejecucion -> Finalizado
    if (currentUser.role === UserRole.HEAD) {
        // Find the request to check area owner
        const req = requests.find(r => r.id === requestId);
        if (req && req.area === currentUser.area) {
            if (currentStatus === Status.DERIVACION && targetStatus === Status.EJECUCION) isValidMove = true;
            if (currentStatus === Status.EJECUCION && targetStatus === Status.FINALIZADO) isValidMove = true;
        }
    }

    if (isValidMove) {
        updateStatus(requestId, targetStatus);
    } else {
        // Optional: Show a toast or shake animation for invalid move
        console.warn("Movimiento no permitido según reglas de negocio");
    }
  };

  const columns = [
    { title: 'Recibido', status: Status.RECIBIDO, color: 'border-blue-400 text-blue-700' },
    { title: 'En Derivación', status: Status.DERIVACION, color: 'border-orange-400 text-orange-700' },
    { title: 'En Ejecución', status: Status.EJECUCION, color: 'border-amber-400 text-amber-700' },
    { title: 'Finalizado', status: Status.FINALIZADO, color: 'border-emerald-400 text-emerald-700' }
  ];

  return (
    <div className="flex-1 overflow-x-auto overflow-y-hidden">
      <div className="h-full flex px-6 py-6 gap-6 min-w-[1000px]">
        {columns.map((col) => {
            const items = getRequestsByStatus(col.status);
            const isOver = dragOverColumn === col.status;

            return (
                <div 
                    key={col.status} 
                    className={`flex-1 flex flex-col min-w-[280px] max-w-[350px] transition-colors rounded-xl ${isOver ? 'bg-indigo-50/50 ring-2 ring-indigo-200 ring-inset' : ''}`}
                    onDragOver={(e) => handleDragOver(e, col.status)}
                    onDragLeave={handleDragLeave}
                    onDrop={(e) => handleDrop(e, col.status)}
                >
                    <div className={`flex items-center justify-between mb-4 pb-2 border-b-2 mx-1 ${col.color.split(' ')[0]}`}>
                        <h2 className={`font-bold uppercase text-xs tracking-wider ${col.color.split(' ')[1]}`}>{col.title}</h2>
                        <span className="bg-white border border-slate-200 text-slate-600 px-2 py-0.5 rounded-full text-[10px] font-bold shadow-sm">
                            {items.length}
                        </span>
                    </div>

                    <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar pb-10 px-1">
                        {items.length === 0 ? (
                            <div className={`h-32 border-2 border-dashed rounded-xl flex items-center justify-center text-slate-400 text-sm italic transition-colors ${isOver ? 'border-indigo-300 bg-indigo-50' : 'border-slate-200 bg-slate-50/50'}`}>
                                {isOver ? 'Soltar aquí' : 'Sin tarjetas'}
                            </div>
                        ) : (
                            items.map(req => (
                                <RequestCard key={req.id} data={req} />
                            ))
                        )}
                    </div>
                </div>
            )
        })}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { RequestCard as RequestCardType, UserRole, Status, Area } from '../types';
import { useSisreq } from '../context/SisreqContext';
import { STATUS_BADGE_COLORS, USERS } from '../constants';
import { ArrowRight, User as UserIcon, MessageSquare, Clock, CheckCircle, GripVertical, Pencil, X, Save } from 'lucide-react';

interface Props {
  data: RequestCardType;
}

export const RequestCard: React.FC<Props> = ({ data }) => {
  const { currentUser, updateStatus, returnRequest, assignAnalyst, addLog, updateRequestDetails } = useSisreq();
  const [showLogs, setShowLogs] = useState(false);
  const [showReturnInput, setShowReturnInput] = useState(false);
  const [returnReason, setReturnReason] = useState('');
  const [showAnalystSelect, setShowAnalystSelect] = useState(false);
  const [newComment, setNewComment] = useState('');
  const [showCommentInput, setShowCommentInput] = useState(false);

  // Edit Mode States
  const [isEditing, setIsEditing] = useState(false);
  const [editTitle, setEditTitle] = useState(data.title);
  const [editDetail, setEditDetail] = useState(data.detail);

  // LOGIC HELPERS
  const isAdmin = currentUser.role === UserRole.ADMIN;
  const isHead = currentUser.role === UserRole.HEAD;
  const isAnalyst = currentUser.role === UserRole.ANALYST;

  // Can current user see buttons?
  const canAct = () => {
    if (isAdmin) {
      // Admin only acts on Recibido
      return data.status === Status.RECIBIDO;
    }
    if (isHead) {
      // Head acts on Derivation, Execution, and matches Area
      return (data.status === Status.DERIVACION || data.status === Status.EJECUCION) && currentUser.area === data.area;
    }
    // Analyst cannot change status, but can edit/comment
    return false;
  };

  // Check if user can drag this card
  const isDraggable = () => {
    if (isAdmin && data.status === Status.RECIBIDO) return true;
    if (isHead && data.area === currentUser.area) {
        // Can drag from Derivacion -> Ejecucion OR Ejecucion -> Finalizado
        if (data.status === Status.DERIVACION || data.status === Status.EJECUCION) return true;
    }
    return false;
  };

  const handleDragStart = (e: React.DragEvent) => {
    e.dataTransfer.setData('requestId', data.id);
    e.dataTransfer.setData('currentStatus', data.status);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDerive = () => {
    if (confirm('¿Derivar este requerimiento al área correspondiente?')) {
      updateStatus(data.id, Status.DERIVACION);
    }
  };

  const handleStartExecution = () => {
    updateStatus(data.id, Status.EJECUCION);
  };

  const handleFinalize = () => {
    if (confirm('¿Confirmar finalización del requerimiento?')) {
      updateStatus(data.id, Status.FINALIZADO);
    }
  };

  const handleReturnSubmit = () => {
    if (returnReason.trim()) {
      returnRequest(data.id, returnReason);
      setShowReturnInput(false);
      setReturnReason('');
    }
  };

  const handleAssignAnalyst = (analystName: string) => {
    assignAnalyst(data.id, analystName);
    setShowAnalystSelect(false);
  };

  const handleAddComment = () => {
    if (newComment.trim()) {
      addLog(data.id, `Nota: ${newComment}`);
      setNewComment('');
      setShowCommentInput(false);
    }
  };

  const handleSaveEdit = () => {
    updateRequestDetails(data.id, editTitle, editDetail);
    setIsEditing(false);
  };

  const canEditDetails = () => {
    // Admin can always edit
    if (isAdmin) return true;
    // Head/Analyst can edit if it's their area
    if ((isHead || isAnalyst) && data.area === currentUser.area) return true;
    return false;
  };

  // Filter analysts for dropdown
  const availableAnalysts = USERS.filter(u => u.role === UserRole.ANALYST && u.area === data.area);

  // Helper for border colors
  const getBorderColor = (status: Status) => {
    switch (status) {
        case Status.RECIBIDO: return 'border-blue-400';
        case Status.DERIVACION: return 'border-orange-400';
        case Status.EJECUCION: return 'border-amber-400';
        case Status.FINALIZADO: return 'border-emerald-400';
        default: return 'border-gray-200';
    }
  };

  return (
    <div 
        draggable={!isEditing && isDraggable()}
        onDragStart={handleDragStart}
        className={`
            bg-white rounded-lg mb-4 p-4 relative group
            transition-all duration-300 ease-out
            shadow-sm hover:shadow-lg hover:shadow-slate-200/60
            border-y border-r border-gray-100
            border-l-[4px] hover:border-l-[8px]
            ${getBorderColor(data.status)}
            ${isDraggable() && !isEditing ? 'cursor-grab active:cursor-grabbing hover:-translate-y-1' : ''}
        `}
    >

      {/* Drag Handle & Status Header */}
      <div className="flex justify-between items-start mb-2">
        <div className="flex items-center gap-2">
            {isDraggable() && <GripVertical size={14} className="text-gray-300" />}
            <span className={`px-2 py-1 rounded text-xs font-semibold ${STATUS_BADGE_COLORS[data.status]}`}>
            {data.status.toUpperCase()}
            </span>
        </div>
        <div className="flex items-center space-x-1">
            {data.isReturned && (
                 <span className="text-xs bg-red-100 text-red-700 px-2 py-1 rounded font-bold animate-pulse">DEVUELTO</span>
            )}
           <span className={`text-xs px-2 py-1 rounded border ${
             data.priority === 'Alta' ? 'bg-red-50 border-red-200 text-red-700' : 
             data.priority === 'Media' ? 'bg-yellow-50 border-yellow-200 text-yellow-700' : 
             'bg-gray-50 border-gray-200 text-gray-600'
           }`}>
             {data.priority}
           </span>
           {canEditDetails() && !isEditing && (
               <button onClick={() => setIsEditing(true)} className="ml-1 p-1 text-gray-400 hover:text-blue-500 rounded-full hover:bg-blue-50 transition-colors">
                   <Pencil size={12}/>
               </button>
           )}
        </div>
      </div>

      {/* Content Area (View or Edit) */}
      {isEditing ? (
        <div className="mb-3 space-y-2 animate-in fade-in">
            <input 
                value={editTitle}
                onChange={(e) => setEditTitle(e.target.value)}
                className="w-full text-sm font-bold border rounded px-2 py-1 focus:ring-2 focus:ring-blue-100 outline-none"
            />
            <textarea 
                value={editDetail}
                onChange={(e) => setEditDetail(e.target.value)}
                className="w-full text-sm border rounded px-2 py-1 h-20 focus:ring-2 focus:ring-blue-100 outline-none resize-none"
            />
            <div className="flex justify-end gap-2">
                <button onClick={() => setIsEditing(false)} className="p-1 text-gray-500 hover:bg-gray-100 rounded"><X size={14}/></button>
                <button onClick={handleSaveEdit} className="p-1 text-blue-600 hover:bg-blue-50 rounded"><Save size={14}/></button>
            </div>
        </div>
      ) : (
        <>
            <h3 className="font-bold text-gray-800 mb-1 leading-tight">{data.title}</h3>
            <p className="text-sm text-gray-600 mb-3 line-clamp-3">{data.detail}</p>
        </>
      )}

      {/* Meta Data */}
      <div className="text-xs text-gray-500 space-y-1 mb-4">
        <div className="flex items-center gap-1">
            <UserIcon size={12}/>
            <span>Solicita: {data.requester}</span>
        </div>
        <div className="flex items-center gap-1">
            <div className="w-3 h-3 rounded-full bg-blue-500"></div>
            <span>Destino: {data.area} ({data.responsibleHead})</span>
        </div>
        {data.assignedAnalyst && (
          <div className="flex items-center gap-1 font-medium text-purple-700">
             <div className="w-3 h-3 rounded-full bg-purple-500"></div>
             <span>Analista: {data.assignedAnalyst}</span>
          </div>
        )}
      </div>

      {/* Actions Section */}
      <div className="border-t pt-3 mt-2 flex flex-col gap-2">

        {/* Admin Actions */}
        {isAdmin && data.status === Status.RECIBIDO && (
          <button 
            onClick={handleDerive}
            className="w-full flex justify-center items-center gap-2 bg-orange-600 hover:bg-orange-700 text-white py-1.5 px-3 rounded text-sm transition-colors"
          >
            Derivar <ArrowRight size={14}/>
          </button>
        )}

        {/* Head Actions - Derivation Phase */}
        {isHead && data.status === Status.DERIVACION && data.area === currentUser.area && (
          <div className="flex flex-col gap-2">
            <div className="flex gap-2">
                <button 
                onClick={handleStartExecution}
                className="flex-1 bg-yellow-500 hover:bg-yellow-600 text-white py-1.5 px-2 rounded text-sm font-medium"
                >
                Iniciar
                </button>
                <button 
                onClick={() => setShowAnalystSelect(!showAnalystSelect)}
                className="flex-1 bg-purple-600 hover:bg-purple-700 text-white py-1.5 px-2 rounded text-sm font-medium"
                >
                Asignar
                </button>
            </div>

            {!showReturnInput ? (
                 <button 
                 onClick={() => setShowReturnInput(true)}
                 className="w-full bg-gray-200 hover:bg-gray-300 text-gray-700 py-1.5 px-2 rounded text-sm"
               >
                 Devolver / Rechazar
               </button>
            ) : (
                <div className="bg-gray-50 p-2 rounded border">
                    <input 
                        className="w-full text-xs p-1 border rounded mb-2"
                        placeholder="Razón de devolución..."
                        value={returnReason}
                        onChange={e => setReturnReason(e.target.value)}
                    />
                    <div className="flex gap-2">
                        <button onClick={handleReturnSubmit} className="bg-red-500 text-white px-2 py-1 rounded text-xs">Confirmar</button>
                        <button onClick={() => setShowReturnInput(false)} className="text-gray-500 px-2 py-1 text-xs">Cancelar</button>
                    </div>
                </div>
            )}

            {showAnalystSelect && (
                 <div className="bg-purple-50 p-2 rounded border border-purple-100 animate-in slide-in-from-top-2">
                    <p className="text-xs text-purple-800 mb-1 font-semibold">Seleccionar Analista:</p>
                    <div className="grid grid-cols-1 gap-1">
                        {availableAnalysts.map(a => (
                            <button 
                                key={a.id} 
                                onClick={() => handleAssignAnalyst(a.name)}
                                className="text-left text-xs bg-white hover:bg-purple-100 p-1.5 rounded border border-purple-100"
                            >
                                {a.name}
                            </button>
                        ))}
                    </div>
                 </div>
            )}
          </div>
        )}

        {/* Head Actions - Execution Phase */}
        {isHead && data.status === Status.EJECUCION && data.area === currentUser.area && (
             <button 
             onClick={handleFinalize}
             className="w-full flex justify-center items-center gap-2 bg-green-600 hover:bg-green-700 text-white py-2 px-3 rounded text-sm font-medium shadow-sm"
             >
             <CheckCircle size={16}/> Finalizar Tarea
             </button>
        )}

        {/* Comment / Log Actions (Available to everyone involved) */}
        {(isHead || isAnalyst || isAdmin) && (
            <div className="mt-2">
                {!showCommentInput ? (
                    <div className="flex justify-between text-xs text-gray-400">
                         <button onClick={() => setShowLogs(!showLogs)} className="hover:text-blue-500 flex items-center gap-1">
                            <Clock size={12}/> Historial ({data.logs.length})
                        </button>
                        <button onClick={() => setShowCommentInput(true)} className="hover:text-blue-500 flex items-center gap-1">
                            <MessageSquare size={12}/> Nota
                        </button>
                    </div>
                ) : (
                    <div className="mt-1">
                        <textarea
                            value={newComment}
                            onChange={e => setNewComment(e.target.value)}
                            className="w-full text-xs p-2 border rounded focus:ring-1 focus:ring-blue-500"
                            placeholder="Escribe una nota interna..."
                            rows={2}
                        />
                         <div className="flex justify-end gap-2 mt-1">
                            <button onClick={() => setShowCommentInput(false)} className="text-xs text-gray-500">Cancelar</button>
                            <button onClick={handleAddComment} className="text-xs bg-blue-600 text-white px-2 py-1 rounded">Guardar</button>
                        </div>
                    </div>
                )}
            </div>
        )}
      </div>

        {/* Logs Overlay */}
        {showLogs && (
            <div className="absolute inset-0 bg-white z-10 p-4 rounded-lg overflow-y-auto border border-gray-200 shadow-inner text-xs">
                <div className="flex justify-between items-center mb-3 pb-2 border-b">
                    <h4 className="font-bold text-gray-700">Historial de Movimientos</h4>
                    <button onClick={() => setShowLogs(false)}><X size={14}/></button>
                </div>
                <div className="space-y-3">
                    {data.logs.map((log) => (
                        <div key={log.id} className="relative pl-3 border-l-2 border-gray-200">
                            <div className="text-gray-500 text-[10px]">{new Date(log.timestamp).toLocaleString()}</div>
                            <div className="font-semibold text-gray-800">{log.actor}</div>
                            <div className="text-gray-600">{log.message}</div>
                        </div>
                    ))}
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState } from 'react';
import { RequestCard as RequestCardType, UserRole, Status, Area } from '../types';
import { useSisreq } from '../context/SisreqContext';
import { STATUS_BADGE_COLORS, USERS } from '../constants';
import { ArrowRight, User as UserIcon, MessageSquare, Clock, CheckCircle, GripVertical, Pencil, X, Save, MapPin, AlertCircle } from 'lucide-react';

interface Props {
  data: RequestCardType;
}

export const RequestCard: React.FC<Props> = ({ data }) => {
  const { currentUser, updateStatus, returnRequest, assignAnalyst, addLog, updateRequestDetails } = useSisreq();
  const [showLogs, setShowLogs] = useState(false);
  const [showReturnInput, setShowReturnInput] = useState(false);
  const [returnReason, setReturnReason] = useState('');
  const [showAnalystSelect, setShowAnalystSelect] = useState(false);
  const [newComment, setNewComment] = useState('');
  const [showCommentInput, setShowCommentInput] = useState(false);

  // Edit Mode States
  const [isEditing, setIsEditing] = useState(false);
  const [editTitle, setEditTitle] = useState(data.title);
  const [editDetail, setEditDetail] = useState(data.detail);

  // LOGIC HELPERS
  const isAdmin = currentUser.role === UserRole.ADMIN;
  const isHead = currentUser.role === UserRole.HEAD;
  const isAnalyst = currentUser.role === UserRole.ANALYST;

  // Check if user can drag this card
  const isDraggable = () => {
    if (isAdmin && data.status === Status.RECIBIDO) return true;
    if (isHead && data.area === currentUser.area) {
        // Can drag from Derivacion -> Ejecucion OR Ejecucion -> Finalizado
        if (data.status === Status.DERIVACION || data.status === Status.EJECUCION) return true;
    }
    return false;
  };

  const handleDragStart = (e: React.DragEvent) => {
    e.dataTransfer.setData('requestId', data.id);
    e.dataTransfer.setData('currentStatus', data.status);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDerive = () => {
    if (confirm('¿Derivar este requerimiento al área correspondiente?')) {
      updateStatus(data.id, Status.DERIVACION);
    }
  };

  const handleStartExecution = () => {
    updateStatus(data.id, Status.EJECUCION);
  };

  const handleFinalize = () => {
    if (confirm('¿Confirmar finalización del requerimiento?')) {
      updateStatus(data.id, Status.FINALIZADO);
    }
  };

  const handleReturnSubmit = () => {
    if (returnReason.trim()) {
      returnRequest(data.id, returnReason);
      setShowReturnInput(false);
      setReturnReason('');
    }
  };

  const handleAssignAnalyst = (analystName: string) => {
    assignAnalyst(data.id, analystName);
    setShowAnalystSelect(false);
  };

  const handleAddComment = () => {
    if (newComment.trim()) {
      addLog(data.id, `Nota: ${newComment}`);
      setNewComment('');
      setShowCommentInput(false);
    }
  };

  const handleSaveEdit = () => {
    updateRequestDetails(data.id, editTitle, editDetail);
    setIsEditing(false);
  };

  const canEditDetails = () => {
    // Admin can always edit
    if (isAdmin) return true;
    // Head/Analyst can edit if it's their area
    if ((isHead || isAnalyst) && data.area === currentUser.area) return true;
    return false;
  };

  // Filter analysts for dropdown
  const availableAnalysts = USERS.filter(u => u.role === UserRole.ANALYST && u.area === data.area);

  // Helper for border colors
  const getBorderColor = (status: Status) => {
    switch (status) {
        case Status.RECIBIDO: return 'border-blue-400';
        case Status.DERIVACION: return 'border-orange-400';
        case Status.EJECUCION: return 'border-amber-400';
        case Status.FINALIZADO: return 'border-emerald-400';
        default: return 'border-slate-200';
    }
  };

  return (
    <div 
        draggable={!isEditing && isDraggable()}
        onDragStart={handleDragStart}
        className={`
            bg-white rounded-xl mb-4 p-5 relative group
            transition-all duration-300 ease-out
            shadow-sm hover:shadow-xl hover:shadow-slate-200/60
            border-y border-r border-slate-100
            border-l-[4px] hover:border-l-[6px]
            ${getBorderColor(data.status)}
            ${isDraggable() && !isEditing ? 'cursor-grab active:cursor-grabbing hover:-translate-y-0.5' : ''}
        `}
    >

      {/* Header: Status, Drag Handle, Actions */}
      <div className="flex justify-between items-start mb-3">
        <div className="flex items-center gap-2">
            {isDraggable() && <GripVertical size={14} className="text-slate-300 hover:text-slate-500 transition-colors" />}
            <span className={`px-2.5 py-0.5 rounded-full text-[10px] font-bold tracking-wide uppercase ${STATUS_BADGE_COLORS[data.status]}`}>
            {data.status}
            </span>
        </div>
        <div className="flex items-center gap-1.5">
            {data.isReturned && (
                 <span className="flex items-center gap-1 text-[10px] bg-red-50 text-red-600 px-2 py-0.5 rounded-full font-bold ring-1 ring-red-100">
                    <AlertCircle size={10} /> DEVUELTO
                 </span>
            )}
           <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full border ${
             data.priority === 'Alta' ? 'bg-red-50 border-red-100 text-red-600' : 
             data.priority === 'Media' ? 'bg-amber-50 border-amber-100 text-amber-600' : 
             'bg-slate-50 border-slate-200 text-slate-500'
           }`}>
             {data.priority}
           </span>
           {canEditDetails() && !isEditing && (
               <button 
                  onClick={() => setIsEditing(true)} 
                  className="ml-1 p-1.5 text-slate-400 hover:text-indigo-600 rounded-full hover:bg-indigo-50 transition-colors opacity-0 group-hover:opacity-100"
                  title="Editar"
               >
                   <Pencil size={12}/>
               </button>
           )}
        </div>
      </div>

      {/* Main Content Area */}
      <div className="mb-4">
        {isEditing ? (
            <div className="space-y-3 animate-in fade-in duration-200 bg-slate-50/50 p-3 rounded-lg border border-slate-100">
                <div>
                    <label className="block text-[10px] uppercase font-bold text-slate-400 mb-1">Título</label>
                    <input 
                        value={editTitle}
                        onChange={(e) => setEditTitle(e.target.value)}
                        className="w-full text-sm font-semibold text-slate-800 bg-white border border-slate-200 rounded-md px-3 py-2 focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 outline-none transition-all shadow-sm"
                        placeholder="Título del requerimiento"
                        autoFocus
                    />
                </div>
                <div>
                    <label className="block text-[10px] uppercase font-bold text-slate-400 mb-1">Detalle</label>
                    <textarea 
                        value={editDetail}
                        onChange={(e) => setEditDetail(e.target.value)}
                        className="w-full text-sm text-slate-600 bg-white border border-slate-200 rounded-md px-3 py-2 h-24 focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 outline-none resize-none transition-all shadow-sm leading-relaxed"
                        placeholder="Descripción detallada..."
                    />
                </div>
                <div className="flex justify-end gap-2 pt-1 border-t border-slate-200/60 mt-2">
                    <button 
                        onClick={() => setIsEditing(false)} 
                        className="flex items-center gap-1 px-3 py-1.5 text-xs font-medium text-slate-600 bg-white border border-slate-200 hover:bg-slate-50 rounded-md transition-colors shadow-sm"
                    >
                        <X size={14}/> Cancelar
                    </button>
                    <button 
                        onClick={handleSaveEdit} 
                        className="flex items-center gap-1 px-3 py-1.5 text-xs font-medium text-white bg-indigo-600 hover:bg-indigo-700 rounded-md shadow-sm transition-all active:scale-95"
                    >
                        <Save size={14}/> Guardar
                    </button>
                </div>
            </div>
        ) : (
            <div className="px-1">
                <h3 className="font-bold text-slate-800 text-[15px] mb-2 leading-snug tracking-tight">
                    {data.title}
                </h3>
                <p className="text-sm text-slate-600 leading-relaxed line-clamp-4 font-normal">
                    {data.detail}
                </p>
            </div>
        )}
      </div>

      {/* Meta Data Section */}
      <div className="flex flex-col gap-2 mb-4 px-1">
        <div className="flex items-center gap-2 text-xs text-slate-500">
            <UserIcon size={14} className="text-slate-400 flex-shrink-0"/>
            <span className="truncate">Por: <span className="font-medium text-slate-700">{data.requester}</span></span>
        </div>
        <div className="flex items-center gap-2 text-xs text-slate-500">
            <MapPin size={14} className="text-slate-400 flex-shrink-0"/>
            <span className="truncate">Destino: <span className="font-medium text-slate-700">{data.area}</span> <span className="text-slate-400">({data.responsibleHead})</span></span>
        </div>
        {data.assignedAnalyst && (
          <div className="flex items-center gap-2 text-xs bg-indigo-50 text-indigo-700 p-2 rounded-lg border border-indigo-100 mt-1">
             <div className="w-2 h-2 rounded-full bg-indigo-500 animate-pulse"></div>
             <span className="font-semibold">Analista: {data.assignedAnalyst}</span>
          </div>
        )}
      </div>

      {/* Actions Section */}
      <div className="border-t border-slate-100 pt-3 mt-2 flex flex-col gap-2.5">

        {/* Admin Actions */}
        {isAdmin && data.status === Status.RECIBIDO && (
          <button 
            onClick={handleDerive}
            className="w-full flex justify-center items-center gap-2 bg-gradient-to-r from-orange-500 to-orange-600 hover:from-orange-600 hover:to-orange-700 text-white py-2 px-3 rounded-lg text-sm font-medium transition-all shadow-md hover:shadow-lg active:scale-95"
          >
            Derivar Requerimiento <ArrowRight size={16}/>
          </button>
        )}

        {/* Head Actions - Derivation Phase */}
        {isHead && data.status === Status.DERIVACION && data.area === currentUser.area && (
          <div className="flex flex-col gap-2">
            <div className="grid grid-cols-2 gap-2">
                <button 
                onClick={handleStartExecution}
                className="bg-amber-500 hover:bg-amber-600 text-white py-2 px-2 rounded-lg text-xs font-bold uppercase tracking-wide shadow-sm transition-colors"
                >
                Iniciar Ejecución
                </button>
                <button 
                onClick={() => setShowAnalystSelect(!showAnalystSelect)}
                className="bg-indigo-600 hover:bg-indigo-700 text-white py-2 px-2 rounded-lg text-xs font-bold uppercase tracking-wide shadow-sm transition-colors"
                >
                Asignar Analista
                </button>
            </div>

            {!showReturnInput ? (
                 <button 
                 onClick={() => setShowReturnInput(true)}
                 className="w-full bg-slate-100 hover:bg-slate-200 text-slate-600 py-1.5 px-2 rounded-lg text-xs font-semibold transition-colors border border-slate-200"
               >
                 Devolver / Rechazar
               </button>
            ) : (
                <div className="bg-red-50 p-3 rounded-lg border border-red-100 animate-in slide-in-from-top-2">
                    <label className="text-[10px] font-bold text-red-500 mb-1 block uppercase">Motivo de devolución</label>
                    <input 
                        className="w-full text-xs p-2 border border-red-200 rounded-md mb-2 focus:outline-none focus:ring-1 focus:ring-red-300 bg-white"
                        placeholder="Describa el problema..."
                        value={returnReason}
                        onChange={e => setReturnReason(e.target.value)}
                        autoFocus
                    />
                    <div className="flex gap-2 justify-end">
                        <button onClick={() => setShowReturnInput(false)} className="text-slate-500 px-3 py-1 text-xs font-medium hover:text-slate-700">Cancelar</button>
                        <button onClick={handleReturnSubmit} className="bg-red-500 hover:bg-red-600 text-white px-3 py-1 rounded text-xs font-bold shadow-sm">Confirmar</button>
                    </div>
                </div>
            )}

            {showAnalystSelect && (
                 <div className="bg-white p-3 rounded-lg border border-indigo-100 shadow-lg animate-in slide-in-from-top-2 absolute left-0 right-0 z-20 mt-[-10px] mx-4">
                    <div className="flex justify-between items-center mb-2">
                        <p className="text-xs text-indigo-900 font-bold uppercase">Seleccionar Analista</p>
                        <button onClick={() => setShowAnalystSelect(false)} className="text-slate-400 hover:text-slate-600"><X size={14}/></button>
                    </div>
                    <div className="flex flex-col gap-1 max-h-[150px] overflow-y-auto custom-scrollbar">
                        {availableAnalysts.length > 0 ? availableAnalysts.map(a => (
                            <button 
                                key={a.id} 
                                onClick={() => handleAssignAnalyst(a.name)}
                                className="text-left text-xs text-slate-600 hover:text-indigo-700 bg-slate-50 hover:bg-indigo-50 p-2 rounded transition-colors flex items-center gap-2"
                            >
                                <div className="w-6 h-6 rounded-full bg-indigo-200 flex items-center justify-center text-[10px] font-bold text-indigo-700">
                                    {a.name.substring(0,2).toUpperCase()}
                                </div>
                                {a.name}
                            </button>
                        )) : (
                            <p className="text-xs text-slate-400 italic p-2">No hay analistas disponibles para esta área.</p>
                        )}
                    </div>
                 </div>
            )}
          </div>
        )}

        {/* Head Actions - Execution Phase */}
        {isHead && data.status === Status.EJECUCION && data.area === currentUser.area && (
             <button 
             onClick={handleFinalize}
             className="w-full flex justify-center items-center gap-2 bg-emerald-600 hover:bg-emerald-700 text-white py-2.5 px-3 rounded-lg text-sm font-bold shadow-md hover:shadow-lg transition-all active:scale-95"
             >
             <CheckCircle size={18}/> Finalizar Tarea
             </button>
        )}

        {/* Comment / Log Actions */}
        {(isHead || isAnalyst || isAdmin) && (
            <div className="mt-1">
                {!showCommentInput ? (
                    <div className="flex justify-between text-xs pt-2">
                         <button 
                            onClick={() => setShowLogs(!showLogs)} 
                            className="text-slate-400 hover:text-indigo-600 flex items-center gap-1.5 transition-colors font-medium"
                         >
                            <Clock size={14}/> Historial ({data.logs.length})
                        </button>
                        <button 
                            onClick={() => setShowCommentInput(true)} 
                            className="text-slate-400 hover:text-indigo-600 flex items-center gap-1.5 transition-colors font-medium"
                        >
                            <MessageSquare size={14}/> Nota Interna
                        </button>
                    </div>
                ) : (
                    <div className="mt-2 bg-slate-50 p-3 rounded-lg border border-slate-200 animate-in fade-in">
                        <textarea
                            value={newComment}
                            onChange={e => setNewComment(e.target.value)}
                            className="w-full text-xs p-2 border border-slate-300 rounded focus:ring-1 focus:ring-indigo-500 bg-white mb-2"
                            placeholder="Escribe una nota interna..."
                            rows={2}
                            autoFocus
                        />
                         <div className="flex justify-end gap-2">
                            <button onClick={() => setShowCommentInput(false)} className="text-xs text-slate-500 font-medium hover:text-slate-700">Cancelar</button>
                            <button onClick={handleAddComment} className="text-xs bg-indigo-600 hover:bg-indigo-700 text-white px-3 py-1 rounded font-bold shadow-sm">Guardar</button>
                        </div>
                    </div>
                )}
            </div>
        )}
      </div>

        {/* Logs Overlay */}
        {showLogs && (
            <div className="absolute inset-0 bg-white/95 backdrop-blur-sm z-20 p-5 rounded-xl overflow-y-auto custom-scrollbar animate-in fade-in zoom-in-95 duration-200">
                <div className="flex justify-between items-center mb-4 pb-2 border-b border-slate-100">
                    <h4 className="font-bold text-slate-800 flex items-center gap-2">
                        <Clock size={16} className="text-indigo-500"/> Historial
                    </h4>
                    <button 
                        onClick={() => setShowLogs(false)}
                        className="p-1 rounded-full hover:bg-slate-100 text-slate-400 hover:text-slate-600 transition-colors"
                    >
                        <X size={18}/>
                    </button>
                </div>
                <div className="space-y-4">
                    {data.logs.map((log) => (
                        <div key={log.id} className="relative pl-4 border-l-2 border-indigo-100">
                            <div className="absolute -left-[5px] top-1.5 w-2.5 h-2.5 rounded-full bg-indigo-200 border-2 border-white"></div>
                            <div className="text-[10px] text-slate-400 font-medium mb-0.5 uppercase tracking-wide">
                                {new Date(log.timestamp).toLocaleString()}
                            </div>
                            <div className="text-xs font-bold text-slate-700 mb-0.5">{log.actor}</div>
                            <div className="text-xs text-slate-600 leading-relaxed bg-slate-50 p-2 rounded-md border border-slate-100">
                                {log.message}
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        )}
    </div>
  );
};

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { User, RequestCard, Status, LogEntry, Priority, Area, UserRole } from '../types';
import { USERS, AREA_HEADS } from '../constants';
import { loadRequests, saveRequests } from '../services/storage';

interface SisreqContextType {
  currentUser: User;
  setCurrentUser: (user: User) => void;
  requests: RequestCard[];
  selectedRequestId: string | null;
  setSelectedRequestId: (id: string | null) => void;
  addRequest: (title: string, detail: string, area: Area, priority: Priority, requester: string) => void;
  updateStatus: (id: string, newStatus: Status) => void;
  returnRequest: (id: string, reason: string) => void;
  assignAnalyst: (id: string, analystName: string) => void;
  addLog: (id: string, message: string) => void;
  updateRequestDetails: (id: string, title: string, detail: string) => void;
}

const SisreqContext = createContext<SisreqContextType | undefined>(undefined);

export const SisreqProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User>(USERS[0]); // Default to Evelin
  const [requests, setRequests] = useState<RequestCard[]>([]);
  const [selectedRequestId, setSelectedRequestId] = useState<string | null>(null);

  useEffect(() => {
    setRequests(loadRequests());
  }, []);

  useEffect(() => {
    if (requests.length > 0) {
      saveRequests(requests);
    }
  }, [requests]);

  const addRequest = useCallback((title: string, detail: string, area: Area, priority: Priority, requester: string) => {
    const newRequest: RequestCard = {
      id: `req-${Date.now()}`,
      title,
      detail,
      area,
      status: Status.RECIBIDO,
      priority,
      requester,
      responsibleHead: AREA_HEADS[area],
      createdAt: new Date().toISOString(),
      logs: [{
        id: `log-${Date.now()}`,
        timestamp: new Date().toISOString(),
        message: `Requerimiento creado por ${currentUser.name}`,
        actor: currentUser.name
      }]
    };
    setRequests(prev => [...prev, newRequest]);
  }, [currentUser]);

  const addLog = useCallback((id: string, message: string) => {
    setRequests(prev => prev.map(req => {
      if (req.id !== id) return req;
      return {
        ...req,
        logs: [
          ...req.logs,
          {
            id: `log-${Date.now()}`,
            timestamp: new Date().toISOString(),
            message,
            actor: currentUser.name
          }
        ]
      };
    }));
  }, [currentUser]);

  const updateRequestDetails = useCallback((id: string, title: string, detail: string) => {
    setRequests(prev => prev.map(req => {
      if (req.id !== id) return req;
      return {
        ...req,
        title,
        detail,
        logs: [
          ...req.logs,
          {
            id: `log-${Date.now()}`,
            timestamp: new Date().toISOString(),
            message: `Detalles actualizados por ${currentUser.name}`,
            actor: currentUser.name
          }
        ]
      };
    }));
  }, [currentUser]);

  const updateStatus = useCallback((id: string, newStatus: Status) => {
    setRequests(prev => prev.map(req => {
      if (req.id !== id) return req;

      // Prevent redundant updates
      if (req.status === newStatus) return req;

      const statusChangeLog = `Estado cambiado a: ${newStatus}`;
      const finishedLog = newStatus === Status.FINALIZADO ? `Requerimiento finalizado por ${currentUser.name}` : statusChangeLog;

      return {
        ...req,
        status: newStatus,
        finishedAt: newStatus === Status.FINALIZADO ? new Date().toISOString() : req.finishedAt,
        isReturned: false, // Reset returned flag if it moves forward
        logs: [
          ...req.logs,
          {
            id: `log-${Date.now()}`,
            timestamp: new Date().toISOString(),
            message: newStatus === Status.DERIVACION 
              ? `Requerimiento derivado al área ${req.area} por ${currentUser.name}`
              : newStatus === Status.EJECUCION
                ? `Ejecución iniciada por ${currentUser.name}`
                : finishedLog,
            actor: currentUser.name
          }
        ]
      };
    }));
  }, [currentUser]);

  const returnRequest = useCallback((id: string, reason: string) => {
    setRequests(prev => prev.map(req => {
      if (req.id !== id) return req;
      return {
        ...req,
        status: Status.RECIBIDO, // Back to start for Admin to review
        isReturned: true,
        logs: [
          ...req.logs,
          {
            id: `log-${Date.now()}`,
            timestamp: new Date().toISOString(),
            message: `DEVUELTO: ${reason}`,
            actor: currentUser.name
          }
        ]
      };
    }));
  }, [currentUser]);

  const assignAnalyst = useCallback((id: string, analystName: string) => {
    setRequests(prev => prev.map(req => {
      if (req.id !== id) return req;
      return {
        ...req,
        assignedAnalyst: analystName,
        logs: [
          ...req.logs,
          {
            id: `log-${Date.now()}`,
            timestamp: new Date().toISOString(),
            message: `Analista asignado: ${analystName}`,
            actor: currentUser.name
          }
        ]
      };
    }));
  }, [currentUser]);

  return (
    <SisreqContext.Provider value={{
      currentUser,
      setCurrentUser,
      requests,
      selectedRequestId,
      setSelectedRequestId,
      addRequest,
      updateStatus,
      returnRequest,
      assignAnalyst,
      addLog,
      updateRequestDetails
    }}>
      {children}
    </SisreqContext.Provider>
  );
};

export const useSisreq = () => {
  const context = useContext(SisreqContext);
  if (context === undefined) {
    throw new Error('useSisreq must be used within a SisreqProvider');
  }
  return context;
};

