        )}
    </div>
  );
};

import React, { useState } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { STATUS_BADGE_COLORS, USERS } from '../constants';
import { UserRole, Status } from '../types';
import { X, Calendar, User, Building, AlertCircle, Clock, Tag, ArrowRight, CheckCircle, Briefcase, ChevronUp } from 'lucide-react';

