import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { User, RequestCard, Status, LogEntry, Priority, Area, UserRole } from '../types';
import { USERS, AREA_HEADS } from '../constants';
import { loadRequests, saveRequests } from '../services/storage';

interface SisreqContextType {
  currentUser: User;
  isAuthenticated: boolean;
  login: (user: User) => void;
  logout: () => void;
  setCurrentUser: (user: User) => void;
  requests: RequestCard[];
  selectedRequestId: string | null;
  setSelectedRequestId: (id: string | null) => void;
  addRequest: (title: string, detail: string, area: Area, priority: Priority, requester: string) => void;
  updateStatus: (id: string, newStatus: Status) => void;
  returnRequest: (id: string, reason: string) => void;
  assignAnalyst: (id: string, analystName: string) => void;
  addLog: (id: string, message: string) => void;
  updateRequestDetails: (id: string, title: string, detail: string) => void;
}

const SisreqContext = createContext<SisreqContextType | undefined>(undefined);

export const SisreqProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User>(USERS[0]); 
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [requests, setRequests] = useState<RequestCard[]>([]);
  const [selectedRequestId, setSelectedRequestId] = useState<string | null>(null);

  useEffect(() => {
    setRequests(loadRequests());
  }, []);

  useEffect(() => {
    if (requests.length > 0) {
      saveRequests(requests);
    }
  }, [requests]);

  const login = (user: User) => {
    setCurrentUser(user);
    setIsAuthenticated(true);
  };

  const logout = () => {
    setIsAuthenticated(false);
    setSelectedRequestId(null);
  };

  const addRequest = useCallback((title: string, detail: string, area: Area, priority: Priority, requester: string) => {
    const newRequest: RequestCard = {
      id: `req-${Date.now()}`,
      title,
      detail,
      area,
      status: Status.RECIBIDO,
      priority,
      requester,
      responsibleHead: AREA_HEADS[area],
      createdAt: new Date().toISOString(),
      logs: [{
        id: `log-${Date.now()}`,
        timestamp: new Date().toISOString(),
        message: `Requerimiento creado por ${currentUser.name}`,
        actor: currentUser.name
      }]
    };
    setRequests(prev => [...prev, newRequest]);
  }, [currentUser]);

  const addLog = useCallback((id: string, message: string) => {
    setRequests(prev => prev.map(req => {
      if (req.id !== id) return req;
      return {
        ...req,
        logs: [
          ...req.logs,
          {
            id: `log-${Date.now()}`,
            timestamp: new Date().toISOString(),
            message,
            actor: currentUser.name
          }
        ]
      };
    }));
  }, [currentUser]);

  const updateRequestDetails = useCallback((id: string, title: string, detail: string) => {
    setRequests(prev => prev.map(req => {
      if (req.id !== id) return req;
      return {
        ...req,
        title,
        detail,
        logs: [
          ...req.logs,
          {
            id: `log-${Date.now()}`,
            timestamp: new Date().toISOString(),
            message: `Detalles actualizados por ${currentUser.name}`,
            actor: currentUser.name
          }
        ]
      };
    }));
  }, [currentUser]);

  const updateStatus = useCallback((id: string, newStatus: Status) => {
    setRequests(prev => prev.map(req => {
      if (req.id !== id) return req;

      // Prevent redundant updates
      if (req.status === newStatus) return req;

      const statusChangeLog = `Estado cambiado a: ${newStatus}`;
      const finishedLog = newStatus === Status.FINALIZADO ? `Requerimiento finalizado por ${currentUser.name}` : statusChangeLog;

      return {
        ...req,
        status: newStatus,
        finishedAt: newStatus === Status.FINALIZADO ? new Date().toISOString() : req.finishedAt,
        isReturned: false, // Reset returned flag if it moves forward
        logs: [
          ...req.logs,
          {
            id: `log-${Date.now()}`,
            timestamp: new Date().toISOString(),
            message: newStatus === Status.DERIVACION 
              ? `Requerimiento derivado al área ${req.area} por ${currentUser.name}`
              : newStatus === Status.EJECUCION
                ? `Ejecución iniciada por ${currentUser.name}`
                : finishedLog,
            actor: currentUser.name
          }
        ]
      };
    }));
  }, [currentUser]);

  const returnRequest = useCallback((id: string, reason: string) => {
    setRequests(prev => prev.map(req => {
      if (req.id !== id) return req;
      return {
        ...req,
        status: Status.RECIBIDO, // Back to start for Admin to review
        isReturned: true,
        logs: [
          ...req.logs,
          {
            id: `log-${Date.now()}`,
            timestamp: new Date().toISOString(),
            message: `DEVUELTO: ${reason}`,
            actor: currentUser.name
          }
        ]
      };
    }));
  }, [currentUser]);

  const assignAnalyst = useCallback((id: string, analystName: string) => {
    setRequests(prev => prev.map(req => {
      if (req.id !== id) return req;
      return {
        ...req,
        assignedAnalyst: analystName,
        logs: [
          ...req.logs,
          {
            id: `log-${Date.now()}`,
            timestamp: new Date().toISOString(),
            message: `Analista asignado: ${analystName}`,
            actor: currentUser.name
          }
        ]
      };
    }));
  }, [currentUser]);

  return (
    <SisreqContext.Provider value={{
      currentUser,
      setCurrentUser,
      isAuthenticated,
      login,
      logout,
      requests,
      selectedRequestId,
      setSelectedRequestId,
      addRequest,
      updateStatus,
      returnRequest,
      assignAnalyst,
      addLog,
      updateRequestDetails
    }}>
      {children}
    </SisreqContext.Provider>
  );
};

export const useSisreq = () => {
  const context = useContext(SisreqContext);
  if (context === undefined) {
    throw new Error('useSisreq must be used within a SisreqProvider');
  }
  return context;
};

