import React, { useState } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { RequestCard } from './RequestCard';
import { Status, UserRole, Priority } from '../types';
import { LayoutGrid, List, ArrowUpRight, Calendar, User, AlertCircle } from 'lucide-react';
import { STATUS_BADGE_COLORS } from '../constants';

export const Board: React.FC = () => {
  const { requests, currentUser, updateStatus, setSelectedRequestId } = useSisreq();
  const [dragOverColumn, setDragOverColumn] = useState<Status | null>(null);
  const [viewMode, setViewMode] = useState<'board' | 'list'>('board');

  // Filter requests based on role
  const filteredRequests = requests.filter(req => {
    // Admin sees everything
    if (currentUser.role === UserRole.ADMIN) return true;

    // Heads and Analysts see:
    // 1. Their own area
    // 2. Unless it is in "RECIBIDO" (Not yet derived to them)
    if (req.area === currentUser.area && req.status !== Status.RECIBIDO) {
        return true;
    }
    return false;
  });

  const getRequestsByStatus = (status: Status) => {
    return filteredRequests.filter(req => req.status === status);
  };

  // --- Drag & Drop Logic (Only active in Board View) ---
  const handleDragOver = (e: React.DragEvent, status: Status) => {
    e.preventDefault();
    if (dragOverColumn !== status) {
        setDragOverColumn(status);
    }
  };

  const handleDragLeave = () => {
    setDragOverColumn(null);
  };

  const handleDrop = (e: React.DragEvent, targetStatus: Status) => {
    e.preventDefault();
    setDragOverColumn(null);
    const requestId = e.dataTransfer.getData('requestId');
    const currentStatus = e.dataTransfer.getData('currentStatus') as Status;

    // Strict Workflow Rules for Drag & Drop
    let isValidMove = false;

    // Admin: Recibido -> Derivacion
    if (currentUser.role === UserRole.ADMIN) {
        if (currentStatus === Status.RECIBIDO && targetStatus === Status.DERIVACION) isValidMove = true;
    }

    // Head: Derivacion -> Ejecucion -> Finalizado
    if (currentUser.role === UserRole.HEAD) {
        // Find the request to check area owner
        const req = requests.find(r => r.id === requestId);
        if (req && req.area === currentUser.area) {
            if (currentStatus === Status.DERIVACION && targetStatus === Status.EJECUCION) isValidMove = true;
            if (currentStatus === Status.EJECUCION && targetStatus === Status.FINALIZADO) isValidMove = true;
        }
    }

    if (isValidMove) {
        updateStatus(requestId, targetStatus);
    }
  };

  const columns = [
    { title: 'Recibido', status: Status.RECIBIDO, color: 'border-blue-400 text-blue-700' },
    { title: 'En Derivación', status: Status.DERIVACION, color: 'border-orange-400 text-orange-700' },
    { title: 'En Ejecución', status: Status.EJECUCION, color: 'border-amber-400 text-amber-700' },
    { title: 'Finalizado', status: Status.FINALIZADO, color: 'border-emerald-400 text-emerald-700' }
  ];

  return (
    <div className="flex flex-col h-full overflow-hidden">

      {/* View Switcher Toolbar */}
      <div className="px-6 py-4 flex justify-between items-center shrink-0">
          <div className="flex items-center gap-3">
             <h2 className="text-lg font-bold text-slate-800">Gestión de Requerimientos</h2>
             <span className="bg-slate-200 text-slate-600 px-2 py-0.5 rounded-full text-xs font-bold">{filteredRequests.length}</span>
          </div>

          <div className="bg-white p-1 rounded-lg border border-slate-200 shadow-sm flex items-center gap-1">
             <button 
                onClick={() => setViewMode('board')}
                className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all ${
                    viewMode === 'board' 
                    ? 'bg-indigo-50 text-indigo-600 shadow-sm ring-1 ring-indigo-100' 
                    : 'text-slate-500 hover:bg-slate-50 hover:text-slate-700'
                }`}
             >
                <LayoutGrid size={14} /> Tablero
             </button>
             <div className="w-px h-4 bg-slate-200 mx-1"></div>
             <button 
                onClick={() => setViewMode('list')}
                className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all ${
                    viewMode === 'list' 
                    ? 'bg-indigo-50 text-indigo-600 shadow-sm ring-1 ring-indigo-100' 
                    : 'text-slate-500 hover:bg-slate-50 hover:text-slate-700'
                }`}
             >
                <List size={14} /> Lista
             </button>
          </div>
      </div>

      {/* --- BOARD VIEW (Horizontal Scroll) --- */}
      {viewMode === 'board' && (
        <div className="flex-1 overflow-x-auto overflow-y-hidden">
            <div className="h-full flex px-6 pb-6 gap-6 min-w-[1000px]">
                {columns.map((col) => {
                    const items = getRequestsByStatus(col.status);
                    const isOver = dragOverColumn === col.status;

                    return (
                        <div 
                            key={col.status} 
                            className={`flex-1 flex flex-col min-w-[280px] max-w-[350px] transition-colors rounded-xl ${isOver ? 'bg-indigo-50/50 ring-2 ring-indigo-200 ring-inset' : ''}`}
                            onDragOver={(e) => handleDragOver(e, col.status)}
                            onDragLeave={handleDragLeave}
                            onDrop={(e) => handleDrop(e, col.status)}
                        >
                            <div className={`flex items-center justify-between mb-4 pb-2 border-b-2 mx-1 ${col.color.split(' ')[0]}`}>
                                <h2 className={`font-bold uppercase text-xs tracking-wider ${col.color.split(' ')[1]}`}>{col.title}</h2>
                                <span className="bg-white border border-slate-200 text-slate-600 px-2 py-0.5 rounded-full text-[10px] font-bold shadow-sm">
                                    {items.length}
                                </span>
                            </div>

                            <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar pb-10 px-1">
                                {items.length === 0 ? (
                                    <div className={`h-32 border-2 border-dashed rounded-xl flex items-center justify-center text-slate-400 text-sm italic transition-colors ${isOver ? 'border-indigo-300 bg-indigo-50' : 'border-slate-200 bg-slate-50/50'}`}>
                                        {isOver ? 'Soltar aquí' : 'Sin tarjetas'}
                                    </div>
                                ) : (
                                    items.map(req => (
                                        <RequestCard key={req.id} data={req} />
                                    ))
                                )}
                            </div>
                        </div>
                    )
                })}
            </div>
        </div>
      )}

      {/* --- LIST VIEW (Vertical Scroll) --- */}
      {viewMode === 'list' && (
          <div className="flex-1 overflow-hidden px-6 pb-6">
              <div className="bg-white h-full rounded-2xl border border-slate-200 shadow-sm flex flex-col">

                {/* Table Header */}
                <div className="grid grid-cols-[80px_2fr_1.5fr_1.5fr_100px_140px_140px] gap-4 px-6 py-4 bg-slate-50/80 border-b border-slate-200 text-xs font-bold text-slate-500 uppercase tracking-wider shrink-0 backdrop-blur-sm">
                    <div>ID</div>
                    <div>Título</div>
                    <div>Solicitante</div>
                    <div>Área Destino</div>
                    <div>Prioridad</div>
                    <div>Estado</div>
                    <div>Fecha</div>
                </div>

                {/* Table Body */}
                <div className="overflow-y-auto custom-scrollbar flex-1">
                    {filteredRequests.length > 0 ? (
                        <div className="divide-y divide-slate-100">
                            {filteredRequests.map(req => (
                                <div 
                                    key={req.id}
                                    onClick={() => setSelectedRequestId(req.id)}
                                    className="grid grid-cols-[80px_2fr_1.5fr_1.5fr_100px_140px_140px] gap-4 px-6 py-4 hover:bg-indigo-50/50 cursor-pointer transition-colors group items-center"
                                >
                                    <div className="font-mono text-xs text-slate-400 group-hover:text-indigo-500 font-medium">
                                        #{req.id.split('-')[1]}
                                    </div>
                                    <div className="font-bold text-slate-700 text-sm truncate pr-4 group-hover:text-indigo-700">
                                        {req.title}
                                    </div>
                                    <div className="flex items-center gap-2 text-xs text-slate-600 truncate">
                                        <User size={12} className="text-slate-400"/> {req.requester}
                                    </div>
                                    <div className="text-xs text-slate-600 truncate">
                                        {req.area}
                                    </div>
                                    <div>
                                        <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full border ${
                                            req.priority === Priority.HIGH ? 'bg-red-50 border-red-100 text-red-600' : 
                                            req.priority === Priority.MEDIUM ? 'bg-amber-50 border-amber-100 text-amber-600' : 
                                            'bg-slate-50 border-slate-200 text-slate-500'
                                        }`}>
                                            {req.priority}
                                        </span>
                                    </div>
                                    <div>
                                         <span className={`inline-block px-2 py-0.5 rounded-full text-[10px] font-bold tracking-wide uppercase ${STATUS_BADGE_COLORS[req.status]}`}>
                                            {req.status}
                                        </span>
                                    </div>
                                    <div className="flex items-center gap-2 text-xs text-slate-400">
                                        <Calendar size={12}/>
                                        {new Date(req.createdAt).toLocaleDateString()}
                                    </div>
                                </div>
                            ))}
                        </div>
                    ) : (
                        <div className="flex flex-col items-center justify-center h-64 text-slate-400">
                            <List size={48} className="mb-4 text-slate-200" />
                            <p className="font-medium">No se encontraron requerimientos</p>
                        </div>
                    )}
                </div>
              </div>
          </div>
      )}
    </div>
  );
};

import React, { useMemo } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { Status, Area, Priority } from '../types';
import { BarChart3, TrendingUp, CheckCircle, Clock, PieChart, Activity, Users, AlertTriangle } from 'lucide-react';
import { STATUS_COLORS, STATUS_BADGE_COLORS } from '../constants';

export const ReportsView: React.FC = () => {
  const { requests } = useSisreq();

  // --- Calculations ---
  const stats = useMemo(() => {
    const total = requests.length;
    const completed = requests.filter(r => r.status === Status.FINALIZADO).length;
    const pending = total - completed;
    const completionRate = total > 0 ? Math.round((completed / total) * 100) : 0;

    // By Status
    const byStatus = Object.values(Status).map(status => ({
        name: status,
        count: requests.filter(r => r.status === status).length,
        color: STATUS_BADGE_COLORS[status]
    }));

    // By Area
    const byArea = Object.values(Area).map(area => ({
        name: area,
        count: requests.filter(r => r.area === area).length,
        total: total
    }));

    // By Priority
    const byPriority = Object.values(Priority).map(p => ({
        name: p,
        count: requests.filter(r => r.priority === p).length
    }));

    // Average Resolution Time (Mock logic for demo based on completed items)
    const completedItems = requests.filter(r => r.status === Status.FINALIZADO && r.finishedAt);
    let avgDays = 0;
    if (completedItems.length > 0) {
        const totalMs = completedItems.reduce((acc, curr) => {
            const start = new Date(curr.createdAt).getTime();
            const end = new Date(curr.finishedAt!).getTime();
            return acc + (end - start);
        }, 0);
        avgDays = Math.round(totalMs / (1000 * 60 * 60 * 24) / completedItems.length);
    }

    return { total, completed, pending, completionRate, byStatus, byArea, byPriority, avgDays };
  }, [requests]);

  return (
    <div className="flex-1 overflow-y-auto custom-scrollbar p-6 space-y-6">

        {/* Header Section */}
        <div className="flex flex-col gap-1 mb-2">
            <h2 className="text-2xl font-black text-slate-800 tracking-tight">Panel de Control de Gestión</h2>
            <p className="text-slate-500 text-sm">Resumen ejecutivo del rendimiento del sistema SISREQ.</p>
        </div>

        {/* KPI Cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            {/* Total */}
            <div className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm flex items-center gap-4">
                <div className="p-3 bg-indigo-50 text-indigo-600 rounded-xl">
                    <Activity size={24} />
                </div>
                <div>
                    <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Total Requerimientos</p>
                    <p className="text-2xl font-black text-slate-800">{stats.total}</p>
                </div>
            </div>

            {/* Completed */}
            <div className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm flex items-center gap-4">
                <div className="p-3 bg-emerald-50 text-emerald-600 rounded-xl">
                    <CheckCircle size={24} />
                </div>
                <div>
                    <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Tasa Finalización</p>
                    <div className="flex items-baseline gap-2">
                         <p className="text-2xl font-black text-slate-800">{stats.completionRate}%</p>
                         <span className="text-xs font-bold text-emerald-600 bg-emerald-50 px-1.5 py-0.5 rounded flex items-center">
                            <TrendingUp size={10} className="mr-1"/> +12%
                         </span>
                    </div>
                </div>
            </div>

            {/* Pending */}
            <div className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm flex items-center gap-4">
                <div className="p-3 bg-amber-50 text-amber-600 rounded-xl">
                    <Clock size={24} />
                </div>
                <div>
                    <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">En Proceso</p>
                    <p className="text-2xl font-black text-slate-800">{stats.pending}</p>
                </div>
            </div>

            {/* Avg Time */}
            <div className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm flex items-center gap-4">
                <div className="p-3 bg-blue-50 text-blue-600 rounded-xl">
                    <BarChart3 size={24} />
                </div>
                <div>
                    <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Tiempo Promedio</p>
                    <p className="text-2xl font-black text-slate-800">{stats.avgDays} <span className="text-sm font-medium text-slate-400">días</span></p>
                </div>
            </div>
        </div>

        {/* Main Charts Area */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

            {/* Column 1: Status Distribution (2 cols wide) */}
            <div className="lg:col-span-2 bg-white rounded-2xl shadow-sm border border-slate-200 p-6">
                <div className="flex justify-between items-center mb-6">
                    <h3 className="font-bold text-slate-800 flex items-center gap-2">
                        <TrendingUp size={18} className="text-indigo-500"/> Estado del Flujo de Trabajo
                    </h3>
                </div>

                <div className="space-y-6">
                    {stats.byStatus.map((item) => (
                        <div key={item.name} className="group">
                            <div className="flex justify-between text-sm mb-2">
                                <span className={`font-bold px-2 py-0.5 rounded text-xs uppercase ${item.color}`}>
                                    {item.name}
                                </span>
                                <span className="font-bold text-slate-700">{item.count} <span className="text-slate-400 font-normal">/ {stats.total}</span></span>
                            </div>
                            <div className="w-full bg-slate-100 rounded-full h-3 overflow-hidden">
                                <div 
                                    className="h-full rounded-full transition-all duration-1000 ease-out bg-indigo-500 relative overflow-hidden"
                                    style={{ width: `${(item.count / stats.total) * 100}%` }}
                                >
                                    <div className="absolute inset-0 bg-white/20 opacity-0 group-hover:opacity-100 transition-opacity"></div>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            {/* Column 2: Breakdown by Priority & Area */}
            <div className="space-y-6">

                {/* Priority */}
                <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6">
                    <h3 className="font-bold text-slate-800 mb-4 flex items-center gap-2">
                        <AlertTriangle size={18} className="text-amber-500"/> Por Prioridad
                    </h3>
                    <div className="flex gap-4 items-end justify-center h-40">
                        {stats.byPriority.map((p) => {
                            const height = stats.total > 0 ? (p.count / stats.total) * 100 : 0;
                            const color = p.name === Priority.HIGH ? 'bg-red-400' : p.name === Priority.MEDIUM ? 'bg-amber-400' : 'bg-slate-300';
                            return (
                                <div key={p.name} className="flex flex-col items-center gap-2 w-16 group">
                                    <div className="text-xs font-bold text-slate-600 mb-1 opacity-0 group-hover:opacity-100 transition-opacity">{p.count}</div>
                                    <div 
                                        className={`w-full rounded-t-lg transition-all duration-700 ${color}`} 
                                        style={{ height: `${Math.max(height, 5)}%` }}
                                    ></div>
                                    <div className="text-[10px] font-bold text-slate-400 uppercase">{p.name}</div>
                                </div>
                            )
                        })}
                    </div>
                </div>

                {/* Area Distribution */}
                 <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6">
                    <h3 className="font-bold text-slate-800 mb-4 flex items-center gap-2">
                        <PieChart size={18} className="text-indigo-500"/> Carga por Área
                    </h3>
                    <div className="space-y-4">
                        {stats.byArea.map(area => (
                            <div key={area.name} className="flex items-center justify-between">
                                <div className="flex items-center gap-3">
                                    <div className="w-8 h-8 rounded-full bg-slate-100 flex items-center justify-center text-slate-500 font-bold text-xs">
                                        {area.name.substring(0,2).toUpperCase()}
                                    </div>
                                    <div>
                                        <div className="text-xs font-bold text-slate-700">{area.name}</div>
                                        <div className="text-[10px] text-slate-400 font-medium">
                                            {area.total > 0 ? Math.round((area.count / area.total) * 100) : 0}% del total
                                        </div>
                                    </div>
                                </div>
                                <div className="font-bold text-slate-800 text-sm">{area.count}</div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { RequestCard } from './RequestCard';
import { ReportsView } from './ReportsView';
import { Status, UserRole, Priority } from '../types';
import { LayoutGrid, List, BarChart3, Calendar, User, ListFilter } from 'lucide-react';
import { STATUS_BADGE_COLORS } from '../constants';

export const Board: React.FC = () => {
  const { requests, currentUser, updateStatus, setSelectedRequestId } = useSisreq();
  const [dragOverColumn, setDragOverColumn] = useState<Status | null>(null);
  const [viewMode, setViewMode] = useState<'board' | 'list' | 'reports'>('board');

  // Filter requests based on role
  const filteredRequests = requests.filter(req => {
    // Admin sees everything
    if (currentUser.role === UserRole.ADMIN) return true;

    // Heads and Analysts see:
    // 1. Their own area
    // 2. Unless it is in "RECIBIDO" (Not yet derived to them)
    if (req.area === currentUser.area && req.status !== Status.RECIBIDO) {
        return true;
    }
    return false;
  });

  const getRequestsByStatus = (status: Status) => {
    return filteredRequests.filter(req => req.status === status);
  };

  // --- Drag & Drop Logic (Only active in Board View) ---
  const handleDragOver = (e: React.DragEvent, status: Status) => {
    e.preventDefault();
    if (dragOverColumn !== status) {
        setDragOverColumn(status);
    }
  };

  const handleDragLeave = () => {
    setDragOverColumn(null);
  };

  const handleDrop = (e: React.DragEvent, targetStatus: Status) => {
    e.preventDefault();
    setDragOverColumn(null);
    const requestId = e.dataTransfer.getData('requestId');
    const currentStatus = e.dataTransfer.getData('currentStatus') as Status;

    // Strict Workflow Rules for Drag & Drop
    let isValidMove = false;

    // Admin: Recibido -> Derivacion
    if (currentUser.role === UserRole.ADMIN) {
        if (currentStatus === Status.RECIBIDO && targetStatus === Status.DERIVACION) isValidMove = true;
    }

    // Head: Derivacion -> Ejecucion -> Finalizado
    if (currentUser.role === UserRole.HEAD) {
        // Find the request to check area owner
        const req = requests.find(r => r.id === requestId);
        if (req && req.area === currentUser.area) {
            if (currentStatus === Status.DERIVACION && targetStatus === Status.EJECUCION) isValidMove = true;
            if (currentStatus === Status.EJECUCION && targetStatus === Status.FINALIZADO) isValidMove = true;
        }
    }

    if (isValidMove) {
        updateStatus(requestId, targetStatus);
    }
  };

  const columns = [
    { title: 'Recibido', status: Status.RECIBIDO, color: 'border-blue-400 text-blue-700' },
    { title: 'En Derivación', status: Status.DERIVACION, color: 'border-orange-400 text-orange-700' },
    { title: 'En Ejecución', status: Status.EJECUCION, color: 'border-amber-400 text-amber-700' },
    { title: 'Finalizado', status: Status.FINALIZADO, color: 'border-emerald-400 text-emerald-700' }
  ];

  return (
    <div className="flex flex-col h-full overflow-hidden">

      {/* View Switcher Toolbar */}
      <div className="px-6 py-4 flex justify-between items-center shrink-0">
          <div className="flex items-center gap-3">
             <h2 className="text-lg font-bold text-slate-800">
                {viewMode === 'reports' ? 'Reportes de Gestión' : 'Gestión de Requerimientos'}
             </h2>
             {viewMode !== 'reports' && (
                <span className="bg-slate-200 text-slate-600 px-2 py-0.5 rounded-full text-xs font-bold">{filteredRequests.length}</span>
             )}
          </div>

          <div className="bg-white p-1 rounded-lg border border-slate-200 shadow-sm flex items-center gap-1">
             <button 
                onClick={() => setViewMode('board')}
                className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all ${
                    viewMode === 'board' 
                    ? 'bg-indigo-50 text-indigo-600 shadow-sm ring-1 ring-indigo-100' 
                    : 'text-slate-500 hover:bg-slate-50 hover:text-slate-700'
                }`}
             >
                <LayoutGrid size={14} /> Tablero
             </button>
             <div className="w-px h-4 bg-slate-200 mx-1"></div>
             <button 
                onClick={() => setViewMode('list')}
                className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all ${
                    viewMode === 'list' 
                    ? 'bg-indigo-50 text-indigo-600 shadow-sm ring-1 ring-indigo-100' 
                    : 'text-slate-500 hover:bg-slate-50 hover:text-slate-700'
                }`}
             >
                <List size={14} /> Lista
             </button>

             {/* Admin / Super Admin Reports Toggle */}
             {currentUser.role === UserRole.ADMIN && (
                <>
                    <div className="w-px h-4 bg-slate-200 mx-1"></div>
                    <button 
                        onClick={() => setViewMode('reports')}
                        className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all ${
                            viewMode === 'reports' 
                            ? 'bg-indigo-50 text-indigo-600 shadow-sm ring-1 ring-indigo-100' 
                            : 'text-slate-500 hover:bg-slate-50 hover:text-slate-700'
                        }`}
                    >
                        <BarChart3 size={14} /> Reportes
                    </button>
                </>
             )}
          </div>
      </div>

      {/* --- REPORTS VIEW (Super Admin) --- */}
      {viewMode === 'reports' && currentUser.role === UserRole.ADMIN && (
         <ReportsView />
      )}

      {/* --- BOARD VIEW (Horizontal Scroll) --- */}
      {viewMode === 'board' && (
        <div className="flex-1 overflow-x-auto overflow-y-hidden">
            <div className="h-full flex px-6 pb-6 gap-6 min-w-[1000px]">
                {columns.map((col) => {
                    const items = getRequestsByStatus(col.status);
                    const isOver = dragOverColumn === col.status;

                    return (
                        <div 
                            key={col.status} 
                            className={`flex-1 flex flex-col min-w-[280px] max-w-[350px] transition-colors rounded-xl ${isOver ? 'bg-indigo-50/50 ring-2 ring-indigo-200 ring-inset' : ''}`}
                            onDragOver={(e) => handleDragOver(e, col.status)}
                            onDragLeave={handleDragLeave}
                            onDrop={(e) => handleDrop(e, col.status)}
                        >
                            <div className={`flex items-center justify-between mb-4 pb-2 border-b-2 mx-1 ${col.color.split(' ')[0]}`}>
                                <h2 className={`font-bold uppercase text-xs tracking-wider ${col.color.split(' ')[1]}`}>{col.title}</h2>
                                <span className="bg-white border border-slate-200 text-slate-600 px-2 py-0.5 rounded-full text-[10px] font-bold shadow-sm">
                                    {items.length}
                                </span>
                            </div>

                            <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar pb-10 px-1">
                                {items.length === 0 ? (
                                    <div className={`h-32 border-2 border-dashed rounded-xl flex items-center justify-center text-slate-400 text-sm italic transition-colors ${isOver ? 'border-indigo-300 bg-indigo-50' : 'border-slate-200 bg-slate-50/50'}`}>
                                        {isOver ? 'Soltar aquí' : 'Sin tarjetas'}
                                    </div>
                                ) : (
                                    items.map(req => (
                                        <RequestCard key={req.id} data={req} />
                                    ))
                                )}
                            </div>
                        </div>
                    )
                })}
            </div>
        </div>
      )}

      {/* --- LIST VIEW (Vertical Scroll) --- */}
      {viewMode === 'list' && (
          <div className="flex-1 overflow-hidden px-6 pb-6">
              <div className="bg-white h-full rounded-2xl border border-slate-200 shadow-sm flex flex-col">

                {/* Table Header */}
                <div className="grid grid-cols-[80px_2fr_1.5fr_1.5fr_100px_140px_140px] gap-4 px-6 py-4 bg-slate-50/80 border-b border-slate-200 text-xs font-bold text-slate-500 uppercase tracking-wider shrink-0 backdrop-blur-sm">
                    <div>ID</div>
                    <div>Título</div>
                    <div>Solicitante</div>
                    <div>Área Destino</div>
                    <div>Prioridad</div>
                    <div>Estado</div>
                    <div>Fecha</div>
                </div>

                {/* Table Body */}
                <div className="overflow-y-auto custom-scrollbar flex-1">
                    {filteredRequests.length > 0 ? (
                        <div className="divide-y divide-slate-100">
                            {filteredRequests.map(req => (
                                <div 
                                    key={req.id}
                                    onClick={() => setSelectedRequestId(req.id)}
                                    className="grid grid-cols-[80px_2fr_1.5fr_1.5fr_100px_140px_140px] gap-4 px-6 py-4 hover:bg-indigo-50/50 cursor-pointer transition-colors group items-center"
                                >
                                    <div className="font-mono text-xs text-slate-400 group-hover:text-indigo-500 font-medium">
                                        #{req.id.split('-')[1]}
                                    </div>
                                    <div className="font-bold text-slate-700 text-sm truncate pr-4 group-hover:text-indigo-700">
                                        {req.title}
                                    </div>
                                    <div className="flex items-center gap-2 text-xs text-slate-600 truncate">
                                        <User size={12} className="text-slate-400"/> {req.requester}
                                    </div>
                                    <div className="text-xs text-slate-600 truncate">
                                        {req.area}
                                    </div>
                                    <div>
                                        <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full border ${
                                            req.priority === Priority.HIGH ? 'bg-red-50 border-red-100 text-red-600' : 
                                            req.priority === Priority.MEDIUM ? 'bg-amber-50 border-amber-100 text-amber-600' : 
                                            'bg-slate-50 border-slate-200 text-slate-500'
                                        }`}>
                                            {req.priority}
                                        </span>
                                    </div>
                                    <div>
                                         <span className={`inline-block px-2 py-0.5 rounded-full text-[10px] font-bold tracking-wide uppercase ${STATUS_BADGE_COLORS[req.status]}`}>
                                            {req.status}
                                        </span>
                                    </div>
                                    <div className="flex items-center gap-2 text-xs text-slate-400">
                                        <Calendar size={12}/>
                                        {new Date(req.createdAt).toLocaleDateString()}
                                    </div>
                                </div>
                            ))}
                        </div>
                    ) : (
                        <div className="flex flex-col items-center justify-center h-64 text-slate-400">
                            <ListFilter size={48} className="mb-4 text-slate-200" />
                            <p className="font-medium">No se encontraron requerimientos</p>
                        </div>
                    )}
                </div>
              </div>
          </div>
      )}
    </div>
  );
};

