import React, { useState } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { RequestCard } from './RequestCard';
import { Status, UserRole, Priority } from '../types';
import { LayoutGrid, List, Calendar, User, ListFilter } from 'lucide-react';
import { STATUS_BADGE_COLORS } from '../constants';

export const Board: React.FC = () => {
  const { requests, currentUser, updateStatus, setSelectedRequestId } = useSisreq();
  const [dragOverColumn, setDragOverColumn] = useState<Status | null>(null);
  const [viewMode, setViewMode] = useState<'board' | 'list'>('board');

  // Filter requests based on role
  const filteredRequests = requests.filter(req => {
    // Admin & SuperAdmin sees everything
    if (currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.SUPERADMIN) return true;

    // Heads and Analysts see:
    // 1. Their own area
    // 2. Unless it is in "RECIBIDO" (Not yet derived to them)
    if (req.area === currentUser.area && req.status !== Status.RECIBIDO) {
        return true;
    }
    return false;
  });

  const getRequestsByStatus = (status: Status) => {
    return filteredRequests.filter(req => req.status === status);
  };

  // --- Drag & Drop Logic (Only active in Board View) ---
  const handleDragOver = (e: React.DragEvent, status: Status) => {
    e.preventDefault();
    if (dragOverColumn !== status) {
        setDragOverColumn(status);
    }
  };

  const handleDragLeave = () => {
    setDragOverColumn(null);
  };

  const handleDrop = (e: React.DragEvent, targetStatus: Status) => {
    e.preventDefault();
    setDragOverColumn(null);
    const requestId = e.dataTransfer.getData('requestId');
    const currentStatus = e.dataTransfer.getData('currentStatus') as Status;

    // Strict Workflow Rules for Drag & Drop
    let isValidMove = false;

    // Admin: Recibido -> Derivacion
    if (currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.SUPERADMIN) {
        if (currentStatus === Status.RECIBIDO && targetStatus === Status.DERIVACION) isValidMove = true;
    }

    // Head: Derivacion -> Ejecucion -> Finalizado
    if (currentUser.role === UserRole.HEAD) {
        // Find the request to check area owner
        const req = requests.find(r => r.id === requestId);
        if (req && req.area === currentUser.area) {
            if (currentStatus === Status.DERIVACION && targetStatus === Status.EJECUCION) isValidMove = true;
            if (currentStatus === Status.EJECUCION && targetStatus === Status.FINALIZADO) isValidMove = true;
        }
    }

    if (isValidMove) {
        updateStatus(requestId, targetStatus);
    }
  };

  const columns = [
    { title: 'Recibido', status: Status.RECIBIDO, color: 'border-blue-400 text-blue-700' },
    { title: 'En Derivación', status: Status.DERIVACION, color: 'border-orange-400 text-orange-700' },
    { title: 'En Ejecución', status: Status.EJECUCION, color: 'border-amber-400 text-amber-700' },
    { title: 'Finalizado', status: Status.FINALIZADO, color: 'border-emerald-400 text-emerald-700' }
  ];

  return (
    <div className="flex flex-col h-full overflow-hidden">

      {/* View Switcher Toolbar */}
      <div className="px-6 py-4 flex justify-between items-center shrink-0">
          <div className="flex items-center gap-3">
             <h2 className="text-lg font-bold text-slate-800">
                Gestión de Requerimientos
             </h2>
             <span className="bg-slate-200 text-slate-600 px-2 py-0.5 rounded-full text-xs font-bold">{filteredRequests.length}</span>
          </div>

          <div className="bg-white p-1 rounded-lg border border-slate-200 shadow-sm flex items-center gap-1">
             <button 
                onClick={() => setViewMode('board')}
                className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all ${
                    viewMode === 'board' 
                    ? 'bg-indigo-50 text-indigo-600 shadow-sm ring-1 ring-indigo-100' 
                    : 'text-slate-500 hover:bg-slate-50 hover:text-slate-700'
                }`}
             >
                <LayoutGrid size={14} /> Tablero
             </button>
             <div className="w-px h-4 bg-slate-200 mx-1"></div>
             <button 
                onClick={() => setViewMode('list')}
                className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all ${
                    viewMode === 'list' 
                    ? 'bg-indigo-50 text-indigo-600 shadow-sm ring-1 ring-indigo-100' 
                    : 'text-slate-500 hover:bg-slate-50 hover:text-slate-700'
                }`}
             >
                <List size={14} /> Lista
             </button>
          </div>
      </div>

      {/* --- BOARD VIEW (Horizontal Scroll) --- */}
      {viewMode === 'board' && (
        <div className="flex-1 overflow-x-auto overflow-y-hidden">
            <div className="h-full flex px-6 pb-6 gap-6 min-w-[1000px]">
                {columns.map((col) => {
                    const items = getRequestsByStatus(col.status);
                    const isOver = dragOverColumn === col.status;

                    return (
                        <div 
                            key={col.status} 
                            className={`flex-1 flex flex-col min-w-[280px] max-w-[350px] transition-colors rounded-xl ${isOver ? 'bg-indigo-50/50 ring-2 ring-indigo-200 ring-inset' : ''}`}
                            onDragOver={(e) => handleDragOver(e, col.status)}
                            onDragLeave={handleDragLeave}
                            onDrop={(e) => handleDrop(e, col.status)}
                        >
                            <div className={`flex items-center justify-between mb-4 pb-2 border-b-2 mx-1 ${col.color.split(' ')[0]}`}>
                                <h2 className={`font-bold uppercase text-xs tracking-wider ${col.color.split(' ')[1]}`}>{col.title}</h2>
                                <span className="bg-white border border-slate-200 text-slate-600 px-2 py-0.5 rounded-full text-[10px] font-bold shadow-sm">
                                    {items.length}
                                </span>
                            </div>

                            <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar pb-10 px-1">
                                {items.length === 0 ? (
                                    <div className={`h-32 border-2 border-dashed rounded-xl flex items-center justify-center text-slate-400 text-sm italic transition-colors ${isOver ? 'border-indigo-300 bg-indigo-50' : 'border-slate-200 bg-slate-50/50'}`}>
                                        {isOver ? 'Soltar aquí' : 'Sin tarjetas'}
                                    </div>
                                ) : (
                                    items.map(req => (
                                        <RequestCard key={req.id} data={req} />
                                    ))
                                )}
                            </div>
                        </div>
                    )
                })}
            </div>
        </div>
      )}

      {/* --- LIST VIEW (Vertical Scroll) --- */}
      {viewMode === 'list' && (
          <div className="flex-1 overflow-hidden px-6 pb-6">
              <div className="bg-white h-full rounded-2xl border border-slate-200 shadow-sm flex flex-col">

                {/* Table Header */}
                <div className="grid grid-cols-[80px_2fr_1.5fr_1.5fr_100px_140px_140px] gap-4 px-6 py-4 bg-slate-50/80 border-b border-slate-200 text-xs font-bold text-slate-500 uppercase tracking-wider shrink-0 backdrop-blur-sm">
                    <div>ID</div>
                    <div>Título</div>
                    <div>Solicitante</div>
                    <div>Área Destino</div>
                    <div>Prioridad</div>
                    <div>Estado</div>
                    <div>Fecha</div>
                </div>

                {/* Table Body */}
                <div className="overflow-y-auto custom-scrollbar flex-1">
                    {filteredRequests.length > 0 ? (
