import React, { useState, useEffect } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { STATUS_BADGE_COLORS, USERS } from '../constants';
import { UserRole, Status } from '../types';
import { X, Calendar, User, Building, AlertCircle, Clock, Tag, ArrowRight, CheckCircle, Briefcase, ChevronUp, Pencil, Save } from 'lucide-react';

export const RequestDetailModal: React.FC = () => {
  const { 
    selectedRequestId, 
    setSelectedRequestId, 
    requests, 
    currentUser, 
    updateStatus, 
    returnRequest, 
    assignAnalyst,
    updateRequestDetails
  } = useSisreq();

  // Local state for actions
  const [returnReason, setReturnReason] = useState('');
  const [showReturnInput, setShowReturnInput] = useState(false);
  const [showAnalystSelect, setShowAnalystSelect] = useState(false);

  // Edit Mode State
  const [isEditing, setIsEditing] = useState(false);
  const [editTitle, setEditTitle] = useState('');
  const [editDetail, setEditDetail] = useState('');

  const data = requests.find(r => r.id === selectedRequestId);

  useEffect(() => {
     if (data) {
        setEditTitle(data.title);
        setEditDetail(data.detail);
        setIsEditing(false); // Reset edit mode when opening a new one
        setShowReturnInput(false);
        setShowAnalystSelect(false);
     }
  }, [selectedRequestId, data]);

  if (!selectedRequestId || !data) return null;

  const handleClose = () => {
    setSelectedRequestId(null);
  };

  // --- Edit Handlers ---
  const handleSaveEdit = () => {
    if (editTitle.trim() && editDetail.trim()) {
        updateRequestDetails(data.id, editTitle, editDetail);
        setIsEditing(false);
    }
  };

  const handleCancelEdit = () => {
    setEditTitle(data.title);
    setEditDetail(data.detail);
    setIsEditing(false);
  };

  // --- Action Handlers ---
  const handleDerive = () => {
    if (confirm('¿Derivar este requerimiento al área correspondiente?')) {
      updateStatus(data.id, Status.DERIVACION);
    }
  };

  const handleStartExecution = () => {
    updateStatus(data.id, Status.EJECUCION);
  };

  const handleFinalize = () => {
    if (confirm('¿Confirmar finalización del requerimiento?')) {
      updateStatus(data.id, Status.FINALIZADO);
    }
  };

  const handleReturnSubmit = () => {
    if (returnReason.trim()) {
      returnRequest(data.id, returnReason);
      setShowReturnInput(false);
      setReturnReason('');
    }
  };

  const handleAssignAnalyst = (analystName: string) => {
    assignAnalyst(data.id, analystName);
    setShowAnalystSelect(false);
  };

  // --- Permission Logic ---
  const isAdmin = currentUser.role === UserRole.ADMIN;
  const isSuperAdmin = currentUser.role === UserRole.SUPERADMIN;
  const isHead = currentUser.role === UserRole.HEAD;

  // Edit permission: 
  // 1. SuperAdmin: Always
  // 2. Admin: Only when status is RECIBIDO (Cannot touch Execution/Finalized cards)
  // 3. Head/Analyst: Only their area
  const canEdit = isSuperAdmin || 
                  (isAdmin && data.status === Status.RECIBIDO) || 
                  ((isHead || currentUser.role === UserRole.ANALYST) && data.area === currentUser.area);

  // Filter analysts
  const availableAnalysts = USERS.filter(u => u.role === UserRole.ANALYST && u.area === data.area);

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity"
        onClick={handleClose}
      ></div>

      {/* Modal Content */}
      <div className="relative bg-white rounded-2xl shadow-2xl w-full max-w-4xl max-h-[90vh] flex flex-col overflow-hidden animate-in fade-in zoom-in-95 duration-200 border border-white/20">

        {/* Header */}
        <div className="bg-slate-50 border-b border-slate-100 px-6 py-4 flex justify-between items-start shrink-0">
            <div className="flex-1 pr-4">
                <div className="flex items-center gap-3 mb-2">
                    <span className={`px-3 py-1 rounded-full text-xs font-bold tracking-wide uppercase shadow-sm ${STATUS_BADGE_COLORS[data.status]}`}>
                        {data.status}
                    </span>
                    <span className="text-xs text-slate-400 font-mono">#{data.id.split('-')[1]}</span>
                    {data.isReturned && (
                        <span className="flex items-center gap-1 text-xs bg-red-100 text-red-700 px-2 py-0.5 rounded-full font-bold">
                            <AlertCircle size={12} /> DEVUELTO
                        </span>
                    )}
                    {/* Edit Button Toggle in Header */}
                    {!isEditing && canEdit && (
                         <button 
                         onClick={() => setIsEditing(true)}
                         className="ml-2 text-slate-400 hover:text-indigo-600 transition-colors p-1 rounded hover:bg-indigo-50"
                         title="Editar Requerimiento"
                         >
                             <Pencil size={14} />
                         </button>
                    )}
                </div>

                {isEditing ? (
                    <input 
                        value={editTitle}
                        onChange={(e) => setEditTitle(e.target.value)}
                        className="w-full text-xl md:text-2xl font-black text-slate-800 bg-white border border-slate-200 rounded-lg px-3 py-1 focus:ring-2 focus:ring-indigo-200 focus:border-indigo-400 outline-none"
                        placeholder="Título del requerimiento"
                        autoFocus
                    />
                ) : (
                    <h2 className="text-xl md:text-2xl font-black text-slate-800 leading-tight">
                        {data.title}
                    </h2>
                )}
            </div>

            {isEditing ? (
                 <div className="flex gap-2">
                     <button 
                        onClick={handleCancelEdit}
                        className="p-2 bg-white hover:bg-slate-100 text-slate-500 rounded-lg border border-slate-200 text-xs font-bold"
                     >
                         Cancelar
                     </button>
                     <button 
                        onClick={handleSaveEdit}
                        className="p-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg shadow-sm text-xs font-bold flex items-center gap-1"
                     >
                         <Save size={16}/> Guardar
                     </button>
                 </div>
            ) : (
                <button 
                    onClick={handleClose}
                    className="p-2 bg-white hover:bg-slate-100 text-slate-400 hover:text-slate-600 rounded-full transition-colors shadow-sm border border-slate-200"
                >
                    <X size={20} />
                </button>
            )}
        </div>

        {/* Scrollable Body */}
        <div className="flex-1 overflow-y-auto custom-scrollbar flex flex-col md:flex-row">

            {/* Left Column: Details */}
            <div className="flex-1 p-6 md:p-8 space-y-6">

                {/* Description Box */}
                <div className="space-y-2">
                    <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider flex items-center gap-2">
                        <Tag size={14}/> Detalle del Requerimiento
                    </h3>
                    {isEditing ? (
                        <textarea 
                            value={editDetail}
                            onChange={(e) => setEditDetail(e.target.value)}
                            className="w-full h-48 bg-white p-5 rounded-xl border border-slate-200 text-slate-700 leading-relaxed text-sm focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 outline-none resize-none"
                            placeholder="Descripción detallada..."
                        />
                    ) : (
                        <div className="bg-slate-50 p-5 rounded-xl border border-slate-100 text-slate-700 leading-relaxed text-sm whitespace-pre-wrap">
                            {data.detail}
                        </div>
                    )}
                </div>

                {/* Metadata Grid */}
                <div className="grid grid-cols-2 gap-4">
                    <div className="bg-white p-4 rounded-xl border border-slate-100 shadow-sm">
                        <div className="flex items-center gap-2 text-slate-400 mb-1">
                            <User size={14} />
                            <span className="text-xs font-bold uppercase">Solicitante</span>
                        </div>
                        <div className="font-semibold text-slate-700">{data.requester}</div>
                    </div>
                    <div className="bg-white p-4 rounded-xl border border-slate-100 shadow-sm">
                         <div className="flex items-center gap-2 text-slate-400 mb-1">
                            <Building size={14} />
                            <span className="text-xs font-bold uppercase">Área Destino</span>
                        </div>
                        <div className="font-semibold text-slate-700">{data.area}</div>
                        <div className="text-xs text-slate-400">Jefe: {data.responsibleHead}</div>
                    </div>
                    <div className="bg-white p-4 rounded-xl border border-slate-100 shadow-sm">
                         <div className="flex items-center gap-2 text-slate-400 mb-1">
                            <Calendar size={14} />
                            <span className="text-xs font-bold uppercase">Fecha Creación</span>
                        </div>
                        <div className="font-semibold text-slate-700">{new Date(data.createdAt).toLocaleDateString()}</div>
                        <div className="text-xs text-slate-400">{new Date(data.createdAt).toLocaleTimeString()}</div>
                    </div>
                    <div className="bg-white p-4 rounded-xl border border-slate-100 shadow-sm">
                         <div className="flex items-center gap-2 text-slate-400 mb-1">
                            <AlertCircle size={14} />
                            <span className="text-xs font-bold uppercase">Prioridad</span>
                        </div>
                        <div className={`font-bold ${
                             data.priority === 'Alta' ? 'text-red-600' : 
                             data.priority === 'Media' ? 'text-amber-600' : 'text-slate-600'
                        }`}>
                            {data.priority}
                        </div>
                    </div>
                </div>

                {data.assignedAnalyst && (
                     <div className="bg-indigo-50 p-4 rounded-xl border border-indigo-100 flex items-center gap-4">
                        <div className="w-10 h-10 rounded-full bg-indigo-200 flex items-center justify-center text-indigo-700 font-bold">
                            {data.assignedAnalyst.substring(0,2).toUpperCase()}
                        </div>
                        <div>
                            <div className="text-xs text-indigo-500 font-bold uppercase">Analista Asignado</div>
                            <div className="font-bold text-indigo-900">{data.assignedAnalyst}</div>
                        </div>
                     </div>
                )}
            </div>

            {/* Right Column: Timeline / History */}
            <div className="w-full md:w-80 bg-slate-50/50 border-t md:border-t-0 md:border-l border-slate-200 p-6 overflow-y-auto">
                <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-5 flex items-center gap-2">
                    <Clock size={14}/> Historial de Actividad
                </h3>

                <div className="relative space-y-6 before:absolute before:inset-0 before:ml-2.5 before:-translate-x-px md:before:mx-auto md:before:translate-x-0 before:h-full before:w-0.5 before:bg-gradient-to-b before:from-transparent before:via-slate-200 before:to-transparent">
                    {[...data.logs].reverse().map((log, index) => (
                        <div key={log.id} className="relative flex items-start group">
                            <div className={`absolute left-0 h-5 w-5 rounded-full border-2 border-white shadow-sm flex items-center justify-center z-10 ${
                                index === 0 ? 'bg-indigo-500 ring-4 ring-indigo-100' : 'bg-slate-300'
                            }`}>
                                {index === 0 && <div className="w-1.5 h-1.5 bg-white rounded-full"></div>}
                            </div>
                            <div className="ml-8">
                                <div className="flex flex-col sm:flex-row sm:justify-between sm:items-baseline mb-1">
                                    <span className="text-xs font-bold text-slate-700">{log.actor}</span>
                                    <span className="text-[10px] text-slate-400">{new Date(log.timestamp).toLocaleString(undefined, { month: 'short', day: 'numeric', hour: '2-digit', minute:'2-digit'})}</span>
                                </div>
                                <div className="text-xs text-slate-600 bg-white p-2.5 rounded-lg border border-slate-200 shadow-sm">
                                    {log.message}
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </div>

        {/* Footer Actions - Dynamic based on Role & Status */}
        <div className="bg-white border-t border-slate-200 p-4 shrink-0 flex items-center justify-between gap-4 z-20 relative">
             <button 
                onClick={handleClose}
                className="px-4 py-2 bg-white hover:bg-slate-50 border border-slate-300 text-slate-700 text-sm font-medium rounded-lg shadow-sm transition-colors"
            >
                Cerrar
            </button>

            <div className="flex items-center gap-2 flex-1 justify-end">

                {/* --- ADMIN ACTIONS --- */}
                {/* Admin/SuperAdmin can only derive if Status is RECIBIDO */}
                {(isAdmin || isSuperAdmin) && data.status === Status.RECIBIDO && (
                     <button 
                     onClick={handleDerive}
                     className="flex items-center gap-2 bg-gradient-to-r from-orange-500 to-orange-600 hover:from-orange-600 hover:to-orange-700 text-white py-2 px-6 rounded-lg text-sm font-bold shadow-md transition-all active:scale-95"
                   >
                     Derivar al Área <ArrowRight size={16}/>
                   </button>
                )}

                {/* --- HEAD ACTIONS: DERIVATION PHASE --- */}
                {isHead && data.status === Status.DERIVACION && data.area === currentUser.area && (
                    <div className="flex items-center gap-2 w-full justify-end relative">

                         {/* Return Input Overlay or Button */}
                         {showReturnInput ? (
                             <div className="flex-1 flex gap-2 items-center bg-red-50 p-1.5 rounded-lg border border-red-100 animate-in slide-in-from-right-10 fade-in">
                                <input 
                                    className="flex-1 text-sm p-1.5 border border-red-200 rounded-md focus:outline-none focus:ring-1 focus:ring-red-300"
                                    placeholder="Razón de devolución..."
                                    value={returnReason}
                                    onChange={e => setReturnReason(e.target.value)}
                                    autoFocus
                                />
                                <button onClick={handleReturnSubmit} className="bg-red-500 text-white px-3 py-1.5 rounded-md text-xs font-bold">Confirmar</button>
                                <button onClick={() => setShowReturnInput(false)} className="text-slate-500 px-2 text-xs">Cancelar</button>
                             </div>
                         ) : (
                             <button 
                                onClick={() => setShowReturnInput(true)}
                                className="px-4 py-2 text-slate-600 hover:text-red-600 hover:bg-red-50 border border-slate-200 rounded-lg text-xs font-bold transition-colors"
                             >
                                Devolver
                             </button>
                         )}

                         {!showReturnInput && (
                            <>
                                {/* Analyst Selection */}
                                <div className="relative">
                                    <button 
                                        onClick={() => setShowAnalystSelect(!showAnalystSelect)}
                                        className="bg-indigo-600 hover:bg-indigo-700 text-white py-2 px-4 rounded-lg text-sm font-bold shadow-sm transition-colors flex items-center gap-2"
                                    >
                                        <User size={16}/> Asignar Analista
                                        {showAnalystSelect && <ChevronUp size={14}/>}
                                    </button>

                                    {showAnalystSelect && (
                                        <div className="absolute bottom-full right-0 mb-2 w-64 bg-white rounded-xl shadow-xl border border-slate-200 p-2 animate-in slide-in-from-bottom-2 z-50">
                                             <p className="text-xs font-bold text-slate-400 uppercase p-2">Seleccionar del equipo:</p>
                                             <div className="max-h-48 overflow-y-auto custom-scrollbar flex flex-col gap-1">
                                                {availableAnalysts.length > 0 ? availableAnalysts.map(a => (
                                                    <button 
                                                        key={a.id} 
                                                        onClick={() => handleAssignAnalyst(a.name)}
                                                        className="flex items-center gap-3 w-full text-left px-3 py-2 hover:bg-indigo-50 rounded-lg transition-colors text-sm text-slate-700"
                                                    >
                                                        <div className="w-6 h-6 rounded-full bg-indigo-100 text-indigo-600 flex items-center justify-center text-xs font-bold">
                                                            {a.name.substring(0,2).toUpperCase()}
                                                        </div>
                                                        {a.name}
                                                    </button>
                                                )) : (
                                                    <p className="text-xs text-slate-400 italic p-2 text-center">No hay analistas.</p>
                                                )}
                                             </div>
                                        </div>
                                    )}
                                </div>

                                <button 
                                    onClick={handleStartExecution}
                                    className="bg-amber-500 hover:bg-amber-600 text-white py-2 px-6 rounded-lg text-sm font-bold shadow-md transition-colors flex items-center gap-2"
                                >
                                    <Briefcase size={18}/> Iniciar Ejecución
                                </button>
                            </>
                         )}
                    </div>
                )}

                {/* --- HEAD ACTIONS: EXECUTION PHASE --- */}
                {isHead && data.status === Status.EJECUCION && data.area === currentUser.area && (
                     <button 
                     onClick={handleFinalize}
                     className="bg-emerald-600 hover:bg-emerald-700 text-white py-2 px-6 rounded-lg text-sm font-bold shadow-md hover:shadow-lg transition-all active:scale-95 flex items-center gap-2"
                     >
                     <CheckCircle size={18}/> Finalizar Tarea
                     </button>
                )}
            </div>
        </div>

      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { RequestCard as RequestCardType, UserRole, Status, Area } from '../types';
import { useSisreq } from '../context/SisreqContext';
import { STATUS_BADGE_COLORS, USERS } from '../constants';
import { ArrowRight, User as UserIcon, MessageSquare, Clock, CheckCircle, GripVertical, X, MapPin, AlertCircle, Maximize2 } from 'lucide-react';

interface Props {
  data: RequestCardType;
}

export const RequestCard: React.FC<Props> = ({ data }) => {
  const { currentUser, updateStatus, returnRequest, assignAnalyst, addLog, setSelectedRequestId } = useSisreq();
  const [showLogs, setShowLogs] = useState(false);
  const [showReturnInput, setShowReturnInput] = useState(false);
  const [returnReason, setReturnReason] = useState('');
  const [showAnalystSelect, setShowAnalystSelect] = useState(false);
  const [newComment, setNewComment] = useState('');
  const [showCommentInput, setShowCommentInput] = useState(false);

  // LOGIC HELPERS
  const isAdmin = currentUser.role === UserRole.ADMIN;
  const isSuperAdmin = currentUser.role === UserRole.SUPERADMIN;
  const isHead = currentUser.role === UserRole.HEAD;
  const isAnalyst = currentUser.role === UserRole.ANALYST;

  // Check if user can drag this card
  const isDraggable = () => {
    // Admin/SuperAdmin can only drag if status is RECIBIDO
    if ((isAdmin || isSuperAdmin) && data.status === Status.RECIBIDO) return true;

    if (isHead && data.area === currentUser.area) {
        // Can drag from Derivacion -> Ejecucion OR Ejecucion -> Finalizado
        if (data.status === Status.DERIVACION || data.status === Status.EJECUCION) return true;
    }
    return false;
  };

  // Check if user can add comments/notes (Interference check)
  const canComment = isHead || isAnalyst || isSuperAdmin || (isAdmin && (data.status === Status.RECIBIDO || data.status === Status.DERIVACION));

  const handleDragStart = (e: React.DragEvent) => {
    e.dataTransfer.setData('requestId', data.id);
    e.dataTransfer.setData('currentStatus', data.status);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDerive = () => {
    if (confirm('¿Derivar este requerimiento al área correspondiente?')) {
      updateStatus(data.id, Status.DERIVACION);
    }
  };

  const handleStartExecution = () => {
    updateStatus(data.id, Status.EJECUCION);
  };

  const handleFinalize = () => {
    if (confirm('¿Confirmar finalización del requerimiento?')) {
      updateStatus(data.id, Status.FINALIZADO);
    }
  };

  const handleReturnSubmit = () => {
    if (returnReason.trim()) {
      returnRequest(data.id, returnReason);
      setShowReturnInput(false);
      setReturnReason('');
    }
  };

  const handleAssignAnalyst = (analystName: string) => {
    assignAnalyst(data.id, analystName);
    setShowAnalystSelect(false);
  };

  const handleAddComment = () => {
    if (newComment.trim()) {
      addLog(data.id, `Nota: ${newComment}`);
      setNewComment('');
      setShowCommentInput(false);
    }
  };

  // Filter analysts for dropdown
  const availableAnalysts = USERS.filter(u => u.role === UserRole.ANALYST && u.area === data.area);

  // Helper for border colors
  const getBorderColor = (status: Status) => {
    switch (status) {
        case Status.RECIBIDO: return 'border-blue-400';
        case Status.DERIVACION: return 'border-orange-400';
        case Status.EJECUCION: return 'border-amber-400';
        case Status.FINALIZADO: return 'border-emerald-400';
        default: return 'border-slate-200';
    }
  };

  return (
    <div 
        draggable={isDraggable()}
        onDragStart={handleDragStart}
        className={`
            bg-white rounded-xl mb-4 p-5 relative group
            transition-all duration-300 ease-out
            shadow-sm hover:shadow-xl hover:shadow-slate-200/60
            border-y border-r border-slate-100
            border-l-[4px] hover:border-l-[6px]
            ${getBorderColor(data.status)}
            ${isDraggable() ? 'cursor-grab active:cursor-grabbing hover:-translate-y-0.5' : ''}
        `}
    >

      {/* Header: Status, Drag Handle, Actions */}
      <div className="flex justify-between items-start mb-3">
        <div className="flex items-center gap-2">
            {isDraggable() && <GripVertical size={14} className="text-slate-300 hover:text-slate-500 transition-colors" />}
            <span className={`px-2.5 py-0.5 rounded-full text-[10px] font-bold tracking-wide uppercase ${STATUS_BADGE_COLORS[data.status]}`}>
            {data.status}
            </span>
        </div>
        <div className="flex items-center gap-1.5">
            {data.isReturned && (
                 <span className="flex items-center gap-1 text-[10px] bg-red-50 text-red-600 px-2 py-0.5 rounded-full font-bold ring-1 ring-red-100">
                    <AlertCircle size={10} /> DEVUELTO
                 </span>
            )}
           <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full border ${
             data.priority === 'Alta' ? 'bg-red-50 border-red-100 text-red-600' : 
             data.priority === 'Media' ? 'bg-amber-50 border-amber-100 text-amber-600' : 
             'bg-slate-50 border-slate-200 text-slate-500'
           }`}>
             {data.priority}
           </span>

           <button 
                onClick={() => setSelectedRequestId(data.id)}
                className="ml-1 p-1.5 text-slate-400 hover:text-indigo-600 rounded-full hover:bg-indigo-50 transition-colors opacity-0 group-hover:opacity-100"
                title="Ver Detalle Completo"
           >
               <Maximize2 size={12}/>
           </button>
        </div>
      </div>

      {/* Main Content Area - Read Only */}
      <div className="mb-4 px-1 cursor-pointer" onClick={() => setSelectedRequestId(data.id)}>
        <h3 className="font-bold text-slate-800 text-[15px] mb-2 leading-snug tracking-tight hover:text-indigo-600 transition-colors">
            {data.title}
        </h3>
        <p className="text-sm text-slate-600 leading-relaxed line-clamp-4 font-normal">
            {data.detail}
        </p>
      </div>

      {/* Meta Data Section */}
      <div className="flex flex-col gap-2 mb-4 px-1">
        <div className="flex items-center gap-2 text-xs text-slate-500">
            <UserIcon size={14} className="text-slate-400 flex-shrink-0"/>
            <span className="truncate">Por: <span className="font-medium text-slate-700">{data.requester}</span></span>
        </div>
        <div className="flex items-center gap-2 text-xs text-slate-500">
            <MapPin size={14} className="text-slate-400 flex-shrink-0"/>
            <span className="truncate">Destino: <span className="font-medium text-slate-700">{data.area}</span> <span className="text-slate-400">({data.responsibleHead})</span></span>
        </div>
        {data.assignedAnalyst && (
          <div className="flex items-center gap-2 text-xs bg-indigo-50 text-indigo-700 p-2 rounded-lg border border-indigo-100 mt-1">
             <div className="w-2 h-2 rounded-full bg-indigo-500 animate-pulse"></div>
             <span className="font-semibold">Analista: {data.assignedAnalyst}</span>
          </div>
        )}
      </div>

      {/* Actions Section */}
      <div className="border-t border-slate-100 pt-3 mt-2 flex flex-col gap-2.5">

        {/* Admin Actions */}
        {(isAdmin || isSuperAdmin) && data.status === Status.RECIBIDO && (
          <button 
            onClick={handleDerive}
            className="w-full flex justify-center items-center gap-2 bg-gradient-to-r from-orange-500 to-orange-600 hover:from-orange-600 hover:to-orange-700 text-white py-2 px-3 rounded-lg text-sm font-medium transition-all shadow-md hover:shadow-lg active:scale-95"
          >
            Derivar Requerimiento <ArrowRight size={16}/>
          </button>
        )}

        {/* Head Actions - Derivation Phase */}
        {isHead && data.status === Status.DERIVACION && data.area === currentUser.area && (
          <div className="flex flex-col gap-2">
            <div className="grid grid-cols-2 gap-2">
                <button 
                onClick={handleStartExecution}
                className="bg-amber-500 hover:bg-amber-600 text-white py-2 px-2 rounded-lg text-xs font-bold uppercase tracking-wide shadow-sm transition-colors"
                >
                Iniciar Ejecución
                </button>
                <button 
                onClick={() => setShowAnalystSelect(!showAnalystSelect)}
                className="bg-indigo-600 hover:bg-indigo-700 text-white py-2 px-2 rounded-lg text-xs font-bold uppercase tracking-wide shadow-sm transition-colors"
                >
                Asignar Analista
                </button>
            </div>

            {!showReturnInput ? (
                 <button 
                 onClick={() => setShowReturnInput(true)}
                 className="w-full bg-slate-100 hover:bg-slate-200 text-slate-600 py-1.5 px-2 rounded-lg text-xs font-semibold transition-colors border border-slate-200"
               >
                 Devolver / Rechazar
               </button>
            ) : (
                <div className="bg-red-50 p-3 rounded-lg border border-red-100 animate-in slide-in-from-top-2">
                    <label className="text-[10px] font-bold text-red-500 mb-1 block uppercase">Motivo de devolución</label>
                    <input 
                        className="w-full text-xs p-2 border border-red-200 rounded-md mb-2 focus:outline-none focus:ring-1 focus:ring-red-300 bg-white"
                        placeholder="Describa el problema..."
                        value={returnReason}
                        onChange={e => setReturnReason(e.target.value)}
                        autoFocus
                    />
                    <div className="flex gap-2 justify-end">
                        <button onClick={() => setShowReturnInput(false)} className="text-slate-500 px-3 py-1 text-xs font-medium hover:text-slate-700">Cancelar</button>
                        <button onClick={handleReturnSubmit} className="bg-red-500 hover:bg-red-600 text-white px-3 py-1 rounded text-xs font-bold shadow-sm">Confirmar</button>
                    </div>
                </div>
            )}

            {showAnalystSelect && (
                 <div className="bg-white p-3 rounded-lg border border-indigo-100 shadow-lg animate-in slide-in-from-top-2 absolute left-0 right-0 z-20 mt-[-10px] mx-4">
                    <div className="flex justify-between items-center mb-2">
                        <p className="text-xs text-indigo-900 font-bold uppercase">Seleccionar Analista</p>
                        <button onClick={() => setShowAnalystSelect(false)} className="text-slate-400 hover:text-slate-600"><X size={14}/></button>
                    </div>
                    <div className="flex flex-col gap-1 max-h-[150px] overflow-y-auto custom-scrollbar">
                        {availableAnalysts.length > 0 ? availableAnalysts.map(a => (
                            <button 
                                key={a.id} 
                                onClick={() => handleAssignAnalyst(a.name)}
                                className="text-left text-xs text-slate-600 hover:text-indigo-700 bg-slate-50 hover:bg-indigo-50 p-2 rounded transition-colors flex items-center gap-2"
                            >
                                <div className="w-6 h-6 rounded-full bg-indigo-200 flex items-center justify-center text-[10px] font-bold text-indigo-700">
                                    {a.name.substring(0,2).toUpperCase()}
                                </div>
                                {a.name}
                            </button>
                        )) : (
                            <p className="text-xs text-slate-400 italic p-2">No hay analistas disponibles para esta área.</p>
                        )}
                    </div>
                 </div>
            )}
          </div>
        )}

        {/* Head Actions - Execution Phase */}
        {isHead && data.status === Status.EJECUCION && data.area === currentUser.area && (
             <button 
             onClick={handleFinalize}
             className="w-full flex justify-center items-center gap-2 bg-emerald-600 hover:bg-emerald-700 text-white py-2.5 px-3 rounded-lg text-sm font-bold shadow-md hover:shadow-lg transition-all active:scale-95"
             >
             <CheckCircle size={18}/> Finalizar Tarea
             </button>
        )}

        {/* Comment / Log Actions */}
        {canComment && (
            <div className="mt-1">
                {!showCommentInput ? (
                    <div className="flex justify-between text-xs pt-2">
                         <button 
                            onClick={() => setShowLogs(!showLogs)} 
                            className="text-slate-400 hover:text-indigo-600 flex items-center gap-1.5 transition-colors font-medium"
                         >
                            <Clock size={14}/> Historial ({data.logs.length})
                        </button>
                        <button 
                            onClick={() => setShowCommentInput(true)} 
                            className="text-slate-400 hover:text-indigo-600 flex items-center gap-1.5 transition-colors font-medium"
                        >
                            <MessageSquare size={14}/> Nota Interna
                        </button>
                    </div>
                ) : (
                    <div className="mt-2 bg-slate-50 p-3 rounded-lg border border-slate-200 animate-in fade-in">
                        <textarea
                            value={newComment}
                            onChange={e => setNewComment(e.target.value)}
                            className="w-full text-xs p-2 border border-slate-300 rounded focus:ring-1 focus:ring-indigo-500 bg-white mb-2"
                            placeholder="Escribe una nota interna..."
                            rows={2}
                            autoFocus
                        />
                         <div className="flex justify-end gap-2">
                            <button onClick={() => setShowCommentInput(false)} className="text-xs text-slate-500 font-medium hover:text-slate-700">Cancelar</button>
                            <button onClick={handleAddComment} className="text-xs bg-indigo-600 hover:bg-indigo-700 text-white px-3 py-1 rounded font-bold shadow-sm">Guardar</button>
                        </div>
                    </div>
                )}
            </div>
        )}
      </div>

        {/* Logs Overlay */}
        {showLogs && (
            <div className="absolute inset-0 bg-white/95 backdrop-blur-sm z-20 p-5 rounded-xl overflow-y-auto custom-scrollbar animate-in fade-in zoom-in-95 duration-200">
                <div className="flex justify-between items-center mb-4 pb-2 border-b border-slate-100">
                    <h4 className="font-bold text-slate-800 flex items-center gap-2">
                        <Clock size={16} className="text-indigo-500"/> Historial
                    </h4>
                    <button 
                        onClick={() => setShowLogs(false)}
                        className="p-1 rounded-full hover:bg-slate-100 text-slate-400 hover:text-slate-600 transition-colors"
                    >
                        <X size={18}/>
                    </button>
                </div>
                <div className="space-y-4">
                    {data.logs.map((log) => (
                        <div key={log.id} className="relative pl-4 border-l-2 border-indigo-100">
                            <div className="absolute -left-[5px] top-1.5 w-2.5 h-2.5 rounded-full bg-indigo-200 border-2 border-white"></div>
                            <div className="text-[10px] text-slate-400 font-medium mb-0.5 uppercase tracking-wide">
                                {new Date(log.timestamp).toLocaleString()}
                            </div>
                            <div className="text-xs font-bold text-slate-700 mb-0.5">{log.actor}</div>
                            <div className="text-xs text-slate-600 leading-relaxed bg-slate-50 p-2 rounded-md border border-slate-100">
                                {log.message}
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { RequestCard } from './RequestCard';
import { Status, UserRole, Priority } from '../types';
import { LayoutGrid, List, Calendar, User, ListFilter, AlignLeft } from 'lucide-react';
import { STATUS_BADGE_COLORS } from '../constants';

export const Board: React.FC = () => {
  const { requests, currentUser, updateStatus, setSelectedRequestId } = useSisreq();
  const [dragOverColumn, setDragOverColumn] = useState<Status | null>(null);
  const [viewMode, setViewMode] = useState<'board' | 'list'>('board');

  // Filter requests based on role
  const filteredRequests = requests.filter(req => {
    // Admin & SuperAdmin sees everything
    if (currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.SUPERADMIN) return true;

    // Heads and Analysts see:
    // 1. Their own area
    // 2. Unless it is in "RECIBIDO" (Not yet derived to them)
    if (req.area === currentUser.area && req.status !== Status.RECIBIDO) {
        return true;
    }
    return false;
  });

  const getRequestsByStatus = (status: Status) => {
    return filteredRequests.filter(req => req.status === status);
  };

  // --- Drag & Drop Logic (Only active in Board View) ---
  const handleDragOver = (e: React.DragEvent, status: Status) => {
    e.preventDefault();
    if (dragOverColumn !== status) {
        setDragOverColumn(status);
    }
  };

  const handleDragLeave = () => {
    setDragOverColumn(null);
  };

  const handleDrop = (e: React.DragEvent, targetStatus: Status) => {
    e.preventDefault();
    setDragOverColumn(null);
    const requestId = e.dataTransfer.getData('requestId');
    const currentStatus = e.dataTransfer.getData('currentStatus') as Status;

    // Strict Workflow Rules for Drag & Drop
    let isValidMove = false;

    // Admin: Recibido -> Derivacion
    if (currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.SUPERADMIN) {
        if (currentStatus === Status.RECIBIDO && targetStatus === Status.DERIVACION) isValidMove = true;
    }

    // Head: Derivacion -> Ejecucion -> Finalizado
    if (currentUser.role === UserRole.HEAD) {
        // Find the request to check area owner
        const req = requests.find(r => r.id === requestId);
        if (req && req.area === currentUser.area) {
            if (currentStatus === Status.DERIVACION && targetStatus === Status.EJECUCION) isValidMove = true;
            if (currentStatus === Status.EJECUCION && targetStatus === Status.FINALIZADO) isValidMove = true;
        }
    }

    if (isValidMove) {
        updateStatus(requestId, targetStatus);
    }
  };

  const columns = [
    { title: 'Recibido', status: Status.RECIBIDO, color: 'border-blue-400 text-blue-700' },
    { title: 'En Derivación', status: Status.DERIVACION, color: 'border-orange-400 text-orange-700' },
    { title: 'En Ejecución', status: Status.EJECUCION, color: 'border-amber-400 text-amber-700' },
    { title: 'Finalizado', status: Status.FINALIZADO, color: 'border-emerald-400 text-emerald-700' }
  ];

  return (
    <div className="flex flex-col h-full overflow-hidden">

      {/* View Switcher Toolbar */}
      <div className="px-6 py-4 flex justify-between items-center shrink-0">
          <div className="flex items-center gap-3">
             <h2 className="text-lg font-bold text-slate-800">
                Gestión de Requerimientos
             </h2>
             <span className="bg-slate-200 text-slate-600 px-2 py-0.5 rounded-full text-xs font-bold">{filteredRequests.length}</span>
          </div>

          <div className="bg-white p-1 rounded-lg border border-slate-200 shadow-sm flex items-center gap-1">
             <button 
                onClick={() => setViewMode('board')}
                className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all ${
                    viewMode === 'board' 
                    ? 'bg-indigo-50 text-indigo-600 shadow-sm ring-1 ring-indigo-100' 
                    : 'text-slate-500 hover:bg-slate-50 hover:text-slate-700'
                }`}
             >
                <LayoutGrid size={14} /> Tablero
             </button>
             <div className="w-px h-4 bg-slate-200 mx-1"></div>
             <button 
                onClick={() => setViewMode('list')}
                className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all ${
                    viewMode === 'list' 
                    ? 'bg-indigo-50 text-indigo-600 shadow-sm ring-1 ring-indigo-100' 
                    : 'text-slate-500 hover:bg-slate-50 hover:text-slate-700'
                }`}
             >
                <List size={14} /> Lista
             </button>
          </div>
      </div>

      {/* --- BOARD VIEW (Horizontal Scroll) --- */}
      {viewMode === 'board' && (
        <div className="flex-1 overflow-x-auto overflow-y-hidden">
            <div className="h-full flex px-6 pb-6 gap-6 min-w-[1000px]">
                {columns.map((col) => {
                    const items = getRequestsByStatus(col.status);
                    const isOver = dragOverColumn === col.status;

                    return (
                        <div 
                            key={col.status} 
                            className={`flex-1 flex flex-col min-w-[280px] max-w-[350px] transition-colors rounded-xl ${isOver ? 'bg-indigo-50/50 ring-2 ring-indigo-200 ring-inset' : ''}`}
                            onDragOver={(e) => handleDragOver(e, col.status)}
                            onDragLeave={handleDragLeave}
                            onDrop={(e) => handleDrop(e, col.status)}
                        >
                            <div className={`flex items-center justify-between mb-4 pb-2 border-b-2 mx-1 ${col.color.split(' ')[0]}`}>
                                <h2 className={`font-bold uppercase text-xs tracking-wider ${col.color.split(' ')[1]}`}>{col.title}</h2>
                                <span className="bg-white border border-slate-200 text-slate-600 px-2 py-0.5 rounded-full text-[10px] font-bold shadow-sm">
                                    {items.length}
                                </span>
                            </div>

                            <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar pb-10 px-1">
                                {items.length === 0 ? (
                                    <div className={`h-32 border-2 border-dashed rounded-xl flex items-center justify-center text-slate-400 text-sm italic transition-colors ${isOver ? 'border-indigo-300 bg-indigo-50' : 'border-slate-200 bg-slate-50/50'}`}>
                                        {isOver ? 'Soltar aquí' : 'Sin tarjetas'}
                                    </div>
                                ) : (
                                    items.map(req => (
                                        <RequestCard key={req.id} data={req} />
                                    ))
                                )}
                            </div>
                        </div>
                    )
                })}
            </div>
        </div>
      )}

      {/* --- LIST VIEW (Vertical Scroll) --- */}
      {viewMode === 'list' && (
          <div className="flex-1 overflow-hidden px-6 pb-6">
              <div className="bg-white h-full rounded-2xl border border-slate-200 shadow-sm flex flex-col overflow-hidden">

                {/* Table Header */}
                <div className="grid grid-cols-[60px_1.5fr_2.5fr_1fr_1fr_90px_110px_100px] gap-4 px-6 py-4 bg-slate-50 border-b border-slate-200 text-[11px] font-bold text-slate-400 uppercase tracking-wider shrink-0 sticky top-0 z-10">
                    <div>ID</div>
                    <div>Título</div>
                    <div className="flex items-center gap-1"><AlignLeft size={10}/> Detalle</div>
                    <div>Solicitante</div>
                    <div>Área Destino</div>
                    <div className="text-center">Prioridad</div>
                    <div className="text-center">Estado</div>
                    <div className="text-right">Fecha</div>
                </div>

                {/* Table Body */}
                <div className="overflow-y-auto custom-scrollbar flex-1 bg-white">
                    {filteredRequests.length > 0 ? (
                        <div className="divide-y divide-slate-100">
                            {filteredRequests.map(req => (
                                <div 
                                    key={req.id}
                                    onClick={() => setSelectedRequestId(req.id)}
                                    className="grid grid-cols-[60px_1.5fr_2.5fr_1fr_1fr_90px_110px_100px] gap-4 px-6 py-4 hover:bg-slate-50/80 cursor-pointer transition-colors group items-center text-sm"
                                >
                                    {/* ID */}
                                    <div className="font-mono text-xs text-slate-400 group-hover:text-indigo-500 font-bold">
                                        #{req.id.split('-')[1]}
                                    </div>

                                    {/* Title */}
                                    <div className="font-bold text-slate-700 truncate pr-2 group-hover:text-indigo-700 transition-colors">
                                        {req.title}
                                    </div>

                                    {/* Detail (New Column) */}
                                    <div className="text-xs text-slate-500 truncate pr-4" title={req.detail}>
                                        {req.detail}
                                    </div>

                                    {/* Requester */}
                                    <div className="flex items-center gap-2 text-xs text-slate-600 truncate">
                                        <User size={12} className="text-slate-400 shrink-0"/> 
                                        <span className="truncate">{req.requester}</span>
                                    </div>

                                    {/* Area */}
                                    <div className="text-xs text-slate-600 truncate font-medium bg-slate-100/50 px-2 py-1 rounded w-fit border border-slate-100">
                                        {req.area}
                                    </div>

                                    {/* Priority */}
                                    <div className="text-center">
                                        <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full border inline-flex items-center justify-center min-w-[60px] ${
                                            req.priority === Priority.HIGH ? 'bg-red-50 border-red-100 text-red-600' : 
                                            req.priority === Priority.MEDIUM ? 'bg-amber-50 border-amber-100 text-amber-600' : 
                                            'bg-slate-50 border-slate-200 text-slate-500'
                                        }`}>
                                            {req.priority}
                                        </span>
                                    </div>

                                    {/* Status */}
                                    <div className="text-center">
                                         <span className={`inline-block px-2 py-0.5 rounded-full text-[10px] font-bold tracking-wide uppercase shadow-sm ${STATUS_BADGE_COLORS[req.status]}`}>
                                            {req.status}
                                        </span>
                                    </div>

                                    {/* Date */}
                                    <div className="flex items-center justify-end gap-2 text-xs text-slate-400 font-mono">
                                        {new Date(req.createdAt).toLocaleDateString()}
                                    </div>
                                </div>
                            ))}
                        </div>
                    ) : (
                        <div className="flex flex-col items-center justify-center h-64 text-slate-400">
                            <ListFilter size={48} className="mb-4 text-slate-200" />
                            <p className="font-medium">No se encontraron requerimientos</p>
                        </div>
                    )}
                </div>
              </div>
          </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { RequestCard } from './RequestCard';
import { Status, UserRole, Priority, Area } from '../types';
import { LayoutGrid, List, ListFilter, AlignLeft, Search, Filter, XCircle } from 'lucide-react';
import { STATUS_BADGE_COLORS } from '../constants';

export const Board: React.FC = () => {
  const { requests, currentUser, updateStatus, setSelectedRequestId } = useSisreq();
  const [dragOverColumn, setDragOverColumn] = useState<Status | null>(null);
  const [viewMode, setViewMode] = useState<'board' | 'list'>('board');

  // Filters State
  const [searchTerm, setSearchTerm] = useState('');
  const [filterArea, setFilterArea] = useState<Area | 'ALL'>('ALL');

  // Filter requests based on Role AND Search/Filter State
  const filteredRequests = requests.filter(req => {
    // 1. Role Based Access (Base Visibility)
    let hasAccess = false;
    // Admin & SuperAdmin sees everything
    if (currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.SUPERADMIN) {
        hasAccess = true;
    } 
    // Heads and Analysts see their own area (unless Recibido)
    else if (req.area === currentUser.area && req.status !== Status.RECIBIDO) {
        hasAccess = true;
    }

    if (!hasAccess) return false;

    // 2. Text Search (Title, ID, Requester)
    const matchesSearch = searchTerm === '' || 
        req.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
        req.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
        req.requester.toLowerCase().includes(searchTerm.toLowerCase());

    // 3. Area Filter (For Admins/SuperAdmins who see all areas)
    const matchesArea = filterArea === 'ALL' || req.area === filterArea;

    return matchesSearch && matchesArea;
  });

  const getRequestsByStatus = (status: Status) => {
    return filteredRequests.filter(req => req.status === status);
  };

  // --- Drag & Drop Logic (Only active in Board View) ---
  const handleDragOver = (e: React.DragEvent, status: Status) => {
    e.preventDefault();
    if (dragOverColumn !== status) {
        setDragOverColumn(status);
    }
  };

  const handleDragLeave = () => {
    setDragOverColumn(null);
  };

  const handleDrop = (e: React.DragEvent, targetStatus: Status) => {
    e.preventDefault();
    setDragOverColumn(null);
    const requestId = e.dataTransfer.getData('requestId');
    const currentStatus = e.dataTransfer.getData('currentStatus') as Status;

    // Strict Workflow Rules for Drag & Drop
    let isValidMove = false;

    // Admin: Recibido -> Derivacion
    if (currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.SUPERADMIN) {
        if (currentStatus === Status.RECIBIDO && targetStatus === Status.DERIVACION) isValidMove = true;
    }

    // Head: Derivacion -> Ejecucion -> Finalizado
    if (currentUser.role === UserRole.HEAD) {
        // Find the request to check area owner
        const req = requests.find(r => r.id === requestId);
        if (req && req.area === currentUser.area) {
            if (currentStatus === Status.DERIVACION && targetStatus === Status.EJECUCION) isValidMove = true;
            if (currentStatus === Status.EJECUCION && targetStatus === Status.FINALIZADO) isValidMove = true;
        }
    }

    if (isValidMove) {
        updateStatus(requestId, targetStatus);
    }
  };

  const columns = [
    { title: 'Recibido', status: Status.RECIBIDO, color: 'border-blue-400 text-blue-700' },
    { title: 'En Derivación', status: Status.DERIVACION, color: 'border-orange-400 text-orange-700' },
    { title: 'En Ejecución', status: Status.EJECUCION, color: 'border-amber-400 text-amber-700' },
    { title: 'Finalizado', status: Status.FINALIZADO, color: 'border-emerald-400 text-emerald-700' }
  ];

  // Logic to show/hide filter controls
  const showAreaFilter = currentUser.role === UserRole.SUPERADMIN || currentUser.role === UserRole.ADMIN;

  return (
    <div className="flex flex-col h-full overflow-hidden">

      {/* Toolbar */}
      <div className="px-6 py-4 flex flex-col md:flex-row md:items-center justify-between gap-4 shrink-0 bg-white/50 backdrop-blur-sm border-b border-slate-200/50">

          {/* Title & Stats */}
          <div className="flex items-center gap-3">
             <h2 className="text-lg font-bold text-slate-800">
                Gestión de Requerimientos
             </h2>
             <span className="bg-slate-200 text-slate-600 px-2 py-0.5 rounded-full text-xs font-bold">
                {filteredRequests.length}
                {searchTerm || filterArea !== 'ALL' ? <span className="text-slate-400 font-normal"> / {requests.length}</span> : ''}
             </span>
          </div>

          {/* Controls Group */}
          <div className="flex items-center gap-3">

             {/* Search Input */}
             <div className="relative group">
                <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-indigo-500 transition-colors"/>
                <input 
                    type="text"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    placeholder="Buscar..."
