                    </div>
                    <select
                        value={filterArea}
                        onChange={(e) => setFilterArea(e.target.value as Area | 'ALL')}
                        className={`pl-8 pr-8 py-1.5 text-xs font-bold border rounded-lg appearance-none cursor-pointer focus:outline-none focus:ring-2 focus:ring-indigo-100 transition-all ${
                            filterArea !== 'ALL' 
                            ? 'bg-indigo-50 border-indigo-200 text-indigo-700' 
                            : 'bg-white border-slate-200 text-slate-600 hover:border-slate-300'
