                        ))}
                    </select>
                 </div>
             )}

             <div className="w-px h-6 bg-slate-200 mx-1 hidden md:block"></div>

             {/* View Mode Switcher */}
             <div className="bg-white p-1 rounded-lg border border-slate-200 shadow-sm flex items-center gap-1">
                <button 
