                     <button 
                     onClick={handleFinalize}
                     className="bg-emerald-600 hover:bg-emerald-700 text-white py-2 px-6 rounded-lg text-sm font-bold shadow-md hover:shadow-lg transition-all active:scale-95 flex items-center gap-2"
                     >
                     <CheckCircle size={18}/> Finalizar Tarea
                     </button>
                )}
            </div>
        </div>

      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { RequestCard as RequestCardType, UserRole, Status } from '../types';
import { useSisreq } from '../context/SisreqContext';
import { STATUS_BADGE_COLORS } from '../constants';
import { User as UserIcon, GripVertical, MapPin, AlertCircle, ChevronUp, ChevronDown, MessageSquare } from 'lucide-react';

interface Props {
  data: RequestCardType;
}

export const RequestCard: React.FC<Props> = ({ data }) => {
  const { currentUser, setSelectedRequestId } = useSisreq();
  // Initialize minimized state based on status: Finalized cards start minimized
  const [isMinimized, setIsMinimized] = useState(data.status === Status.FINALIZADO);

  // LOGIC HELPERS
  const isAdmin = currentUser.role === UserRole.ADMIN;
  const isSuperAdmin = currentUser.role === UserRole.SUPERADMIN;
  const isHead = currentUser.role === UserRole.HEAD;

  // Check if user can drag this card
  const isDraggable = () => {
    // Admin/SuperAdmin can only drag if status is RECIBIDO
    if ((isAdmin || isSuperAdmin) && data.status === Status.RECIBIDO) return true;

    if (isHead && data.area === currentUser.area) {
        // Can drag from Derivacion -> Ejecucion OR Ejecucion -> Finalizado
        if (data.status === Status.DERIVACION || data.status === Status.EJECUCION) return true;
    }
    return false;
  };

  const handleDragStart = (e: React.DragEvent) => {
    e.dataTransfer.setData('requestId', data.id);
    e.dataTransfer.setData('currentStatus', data.status);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleCardClick = () => {
    setSelectedRequestId(data.id);
  };

  // Helper for border colors
  const getBorderColor = (status: Status) => {
    switch (status) {
        case Status.RECIBIDO: return 'border-blue-400';
        case Status.DERIVACION: return 'border-orange-400';
        case Status.EJECUCION: return 'border-amber-400';
        case Status.FINALIZADO: return 'border-emerald-400';
        default: return 'border-slate-200';
    }
  };

  return (
    <div 
        draggable={isDraggable()}
        onDragStart={handleDragStart}
        onClick={handleCardClick}
        className={`
            bg-white rounded-xl mb-3 relative group
            transition-all duration-300 ease-out
            shadow-sm hover:shadow-md
            border-y border-r border-slate-100
            border-l-[4px] hover:border-l-[6px]
            cursor-pointer
            ${getBorderColor(data.status)}
            ${isDraggable() ? 'active:cursor-grabbing hover:-translate-y-0.5' : ''}
            ${isMinimized ? 'py-3 px-4' : 'p-5'}
        `}
    >

      {/* Header: Status, Drag Handle, Actions */}
      <div className={`flex justify-between items-start ${isMinimized ? '' : 'mb-3'}`}>
        <div className="flex items-center gap-2">
            {isDraggable() && (
                <div onMouseDown={(e) => e.stopPropagation()}>
                    <GripVertical size={14} className="text-slate-300 hover:text-slate-500 transition-colors cursor-grab active:cursor-grabbing" />
                </div>
            )}

            <span className={`px-2.5 py-0.5 rounded-full text-[10px] font-bold tracking-wide uppercase ${STATUS_BADGE_COLORS[data.status]}`}>
                {data.status}
            </span>
        </div>

        <div className="flex items-center gap-1.5">
            {data.isReturned && (
                 <span className="flex items-center gap-1 text-[10px] bg-red-50 text-red-600 px-2 py-0.5 rounded-full font-bold ring-1 ring-red-100">
                    <AlertCircle size={10} /> <span className={isMinimized ? 'hidden' : 'inline'}>DEVUELTO</span>
                 </span>
            )}
           <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full border ${
             data.priority === 'Alta' ? 'bg-red-50 border-red-100 text-red-600' : 
             data.priority === 'Media' ? 'bg-amber-50 border-amber-100 text-amber-600' : 
             'bg-slate-50 border-slate-200 text-slate-500'
           }`}>
             {data.priority}
           </span>

           <div className="flex items-center ml-1 opacity-0 group-hover:opacity-100 transition-opacity" onClick={(e) => e.stopPropagation()}>
               <button 
                    onClick={() => setIsMinimized(!isMinimized)}
                    className="p-1 text-slate-400 hover:text-indigo-600 hover:bg-slate-50 rounded-md transition-all"
                    title={isMinimized ? "Expandir vista previa" : "Minimizar"}
               >
                   {isMinimized ? <ChevronDown size={14}/> : <ChevronUp size={14}/>}
               </button>
           </div>
        </div>
      </div>

      {/* Main Content Area */}
      <div className={`${isMinimized ? 'mt-1 pl-6' : 'mb-4 px-1'}`}>
        <h3 className={`font-bold text-slate-800 group-hover:text-indigo-600 transition-colors ${isMinimized ? 'text-xs truncate' : 'text-[15px] mb-2 leading-snug tracking-tight'}`}>
            {data.title}
        </h3>

        {/* Full Details - Only if NOT minimized */}
        {!isMinimized && (
            <p className="text-sm text-slate-600 leading-relaxed line-clamp-3 font-normal">
                {data.detail}
            </p>
        )}
      </div>

      {/* Footer Info */}
      {!isMinimized && (
          <div className="flex flex-col gap-2 px-1 animate-in fade-in duration-300">
             <div className="flex items-center justify-between text-xs text-slate-500 border-t border-slate-50 pt-3 mt-1">
                <div className="flex items-center gap-2">
                    <UserIcon size={12} className="text-slate-400"/>
                    <span className="truncate max-w-[100px] font-medium">{data.requester}</span>
                </div>
                <div className="flex items-center gap-2">
                    <MapPin size={12} className="text-slate-400"/>
                    <span className="truncate max-w-[100px]">{data.area}</span>
                </div>
             </div>

             {/* Modifiers: Analyst or Logs count */}
             <div className="flex items-center gap-2 mt-1">
                 {data.assignedAnalyst && (
                    <div className="flex items-center gap-1.5 text-[10px] bg-indigo-50 text-indigo-700 px-2 py-1 rounded border border-indigo-100 font-bold">
                        <div className="w-1.5 h-1.5 rounded-full bg-indigo-500"></div>
                        {data.assignedAnalyst}
                    </div>
                 )}
                 {data.logs.length > 0 && (
                     <div className="ml-auto flex items-center gap-1 text-[10px] text-slate-400 font-medium">
                         <MessageSquare size={10} /> {data.logs.length}
                     </div>
                 )}
             </div>
          </div>
      )}
    </div>
  );
};

