                </div>
                <div className="flex items-center gap-2">
                    <MapPin size={12} className="text-slate-400"/>
                    <span className="truncate max-w-[100px]">{data.area}</span>
                </div>
             </div>

             {/* Modifiers: Analyst or Logs count */}
             <div className="flex items-center gap-2 mt-1">
                 {data.assignedAnalyst && (
                    <div className="flex items-center gap-1.5 text-[10px] bg-indigo-50 text-indigo-700 px-2 py-1 rounded border border-indigo-100 font-bold">
                        <div className="w-1.5 h-1.5 rounded-full bg-indigo-500"></div>
                        {data.assignedAnalyst}
                    </div>
                 )}
                 {data.logs.length > 0 && (
                     <div className="ml-auto flex items-center gap-1 text-[10px] text-slate-400 font-medium">
                         <MessageSquare size={10} /> {data.logs.length}
                     </div>
                 )}
             </div>
          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { STATUS_BADGE_COLORS } from '../constants';
import { UserRole, Status } from '../types';
import { X, Calendar, User, Building, AlertCircle, Clock, Tag, ArrowRight, CheckCircle, Briefcase, ChevronUp, Pencil, Save, Send, MessageSquare } from 'lucide-react';

export const RequestDetailModal: React.FC = () => {
  const { 
    selectedRequestId, 
    setSelectedRequestId, 
    requests, 
    currentUser, 
    updateStatus, 
    returnRequest, 
    assignAnalyst,
    updateRequestDetails,
    addLog,
    users // Use users from context to ensure latest data
  } = useSisreq();

  // Local state for actions
  const [returnReason, setReturnReason] = useState('');
  const [showReturnInput, setShowReturnInput] = useState(false);
  const [showAnalystSelect, setShowAnalystSelect] = useState(false);

  // Edit Mode State
  const [isEditing, setIsEditing] = useState(false);
  const [editTitle, setEditTitle] = useState('');
  const [editDetail, setEditDetail] = useState('');

  // Comment State
  const [newComment, setNewComment] = useState('');

  const data = requests.find(r => r.id === selectedRequestId);

  useEffect(() => {
     if (data) {
        setEditTitle(data.title);
        setEditDetail(data.detail);
        setIsEditing(false); // Reset edit mode when opening a new one
        setShowReturnInput(false);
        setShowAnalystSelect(false);
        setNewComment('');
     }
  }, [selectedRequestId, data]);

  if (!selectedRequestId || !data) return null;

  const handleClose = () => {
    setSelectedRequestId(null);
  };

  // --- Edit Handlers ---
  const handleSaveEdit = () => {
    if (editTitle.trim() && editDetail.trim()) {
        updateRequestDetails(data.id, editTitle, editDetail);
        setIsEditing(false);
    }
  };

  const handleCancelEdit = () => {
    setEditTitle(data.title);
    setEditDetail(data.detail);
    setIsEditing(false);
  };

  // --- Comment Handler ---
  const handleAddComment = () => {
      if (newComment.trim()) {
          addLog(data.id, `Nota: ${newComment}`);
          setNewComment('');
      }
  }

  // --- Action Handlers ---
  const handleDerive = () => {
    if (confirm('¿Derivar este requerimiento al área correspondiente?')) {
      updateStatus(data.id, Status.DERIVACION);
    }
  };

  const handleStartExecution = () => {
    updateStatus(data.id, Status.EJECUCION);
  };

  const handleFinalize = () => {
    if (confirm('¿Confirmar finalización del requerimiento?')) {
      updateStatus(data.id, Status.FINALIZADO);
    }
  };

  const handleReturnSubmit = () => {
    if (returnReason.trim()) {
      returnRequest(data.id, returnReason);
      setShowReturnInput(false);
      setReturnReason('');
    }
  };

  const handleAssignAnalyst = (analystName: string) => {
    assignAnalyst(data.id, analystName);
    setShowAnalystSelect(false);
  };

  // --- Permission Logic ---
  const isAdmin = currentUser.role === UserRole.ADMIN;
  const isSuperAdmin = currentUser.role === UserRole.SUPERADMIN;
  const isHead = currentUser.role === UserRole.HEAD;
  const isAnalyst = currentUser.role === UserRole.ANALYST;

  // Edit permission: 
  const canEdit = isSuperAdmin || 
                  (isAdmin && data.status === Status.RECIBIDO) || 
                  ((isHead || isAnalyst) && data.area === currentUser.area);

  // Comment permission
  const canComment = isSuperAdmin || 
                     (isAdmin && (data.status === Status.RECIBIDO || data.status === Status.DERIVACION)) ||
                     ((isHead || isAnalyst) && data.area === currentUser.area);

  // Filter analysts from Context Users
  const availableAnalysts = users.filter(u => u.role === UserRole.ANALYST && u.area === data.area);

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity"
        onClick={handleClose}
      ></div>

      {/* Modal Content */}
      <div className="relative bg-white rounded-2xl shadow-2xl w-full max-w-4xl max-h-[90vh] flex flex-col overflow-hidden animate-in fade-in zoom-in-95 duration-200 border border-white/20">

        {/* Header */}
        <div className="bg-slate-50 border-b border-slate-100 px-6 py-4 flex justify-between items-start shrink-0">
            <div className="flex-1 pr-4">
                <div className="flex items-center gap-3 mb-2">
                    <span className={`px-3 py-1 rounded-full text-xs font-bold tracking-wide uppercase shadow-sm ${STATUS_BADGE_COLORS[data.status]}`}>
                        {data.status}
                    </span>
                    <span className="text-xs text-slate-400 font-mono">#{data.id.split('-')[1]}</span>
                    {data.isReturned && (
                        <span className="flex items-center gap-1 text-xs bg-red-100 text-red-700 px-2 py-0.5 rounded-full font-bold">
                            <AlertCircle size={12} /> DEVUELTO
                        </span>
                    )}
                    {/* Edit Button Toggle in Header */}
                    {!isEditing && canEdit && (
                         <button 
                         onClick={() => setIsEditing(true)}
                         className="ml-2 text-slate-400 hover:text-indigo-600 transition-colors p-1 rounded hover:bg-indigo-50"
                         title="Editar Requerimiento"
                         >
                             <Pencil size={14} />
                         </button>
                    )}
                </div>

                {isEditing ? (
                    <input 
                        value={editTitle}
                        onChange={(e) => setEditTitle(e.target.value)}
                        className="w-full text-xl md:text-2xl font-black text-slate-800 bg-white border border-slate-200 rounded-lg px-3 py-1 focus:ring-2 focus:ring-indigo-200 focus:border-indigo-400 outline-none transition-all shadow-sm"
                        placeholder="Título del requerimiento"
                        autoFocus
                    />
                ) : (
                    <h2 className="text-xl md:text-2xl font-black text-slate-800 leading-tight">
                        {data.title}
                    </h2>
                )}
            </div>

            {isEditing ? (
                 <div className="flex gap-2">
                     <button 
                        onClick={handleCancelEdit}
                        className="p-2 bg-white hover:bg-slate-100 text-slate-500 rounded-lg border border-slate-200 text-xs font-bold transition-colors"
                     >
                         Cancelar
                     </button>
                     <button 
                        onClick={handleSaveEdit}
                        className="p-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg shadow-sm text-xs font-bold flex items-center gap-1 transition-colors"
                     >
                         <Save size={16}/> Guardar
                     </button>
                 </div>
            ) : (
                <button 
                    onClick={handleClose}
                    className="p-2 bg-white hover:bg-slate-100 text-slate-400 hover:text-slate-600 rounded-full transition-colors shadow-sm border border-slate-200"
                >
                    <X size={20} />
                </button>
            )}
        </div>

        {/* Scrollable Body */}
        <div className="flex-1 overflow-y-auto custom-scrollbar flex flex-col md:flex-row">

            {/* Left Column: Details */}
            <div className="flex-1 p-6 md:p-8 space-y-6">

                {/* Description Box */}
                <div className="space-y-2">
                    <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider flex items-center gap-2">
                        <Tag size={14}/> Detalle del Requerimiento
                    </h3>
                    {isEditing ? (
                        <textarea 
                            value={editDetail}
                            onChange={(e) => setEditDetail(e.target.value)}
                            className="w-full h-48 bg-white p-5 rounded-xl border border-slate-200 text-slate-700 leading-relaxed text-sm focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 outline-none resize-none transition-all shadow-sm"
                            placeholder="Descripción detallada..."
                        />
                    ) : (
                        <div className="bg-slate-50 p-5 rounded-xl border border-slate-100 text-slate-700 leading-relaxed text-sm whitespace-pre-wrap">
                            {data.detail}
                        </div>
                    )}
                </div>

                {/* Metadata Grid */}
                <div className="grid grid-cols-2 gap-4">
                    <div className="bg-white p-4 rounded-xl border border-slate-100 shadow-sm">
                        <div className="flex items-center gap-2 text-slate-400 mb-1">
                            <User size={14} />
                            <span className="text-xs font-bold uppercase">Solicitante</span>
                        </div>
                        <div className="font-semibold text-slate-700">{data.requester}</div>
                    </div>
                    <div className="bg-white p-4 rounded-xl border border-slate-100 shadow-sm">
                         <div className="flex items-center gap-2 text-slate-400 mb-1">
                            <Building size={14} />
                            <span className="text-xs font-bold uppercase">Área Destino</span>
                        </div>
                        <div className="font-semibold text-slate-700">{data.area}</div>
                        <div className="text-xs text-slate-400">Jefe: {data.responsibleHead}</div>
                    </div>
                    <div className="bg-white p-4 rounded-xl border border-slate-100 shadow-sm">
                         <div className="flex items-center gap-2 text-slate-400 mb-1">
                            <Calendar size={14} />
                            <span className="text-xs font-bold uppercase">Fecha Creación</span>
                        </div>
                        <div className="font-semibold text-slate-700">{new Date(data.createdAt).toLocaleDateString()}</div>
                        <div className="text-xs text-slate-400">{new Date(data.createdAt).toLocaleTimeString()}</div>
                    </div>
                    <div className="bg-white p-4 rounded-xl border border-slate-100 shadow-sm">
                         <div className="flex items-center gap-2 text-slate-400 mb-1">
                            <AlertCircle size={14} />
                            <span className="text-xs font-bold uppercase">Prioridad</span>
                        </div>
                        <div className={`font-bold ${
                             data.priority === 'Alta' ? 'text-red-600' : 
                             data.priority === 'Media' ? 'text-amber-600' : 'text-slate-600'
                        }`}>
                            {data.priority}
                        </div>
                    </div>
                </div>

                {data.assignedAnalyst && (
                     <div className="bg-indigo-50 p-4 rounded-xl border border-indigo-100 flex items-center gap-4">
                        <div className="w-10 h-10 rounded-full bg-indigo-200 flex items-center justify-center text-indigo-700 font-bold">
                            {data.assignedAnalyst.substring(0,2).toUpperCase()}
                        </div>
                        <div>
                            <div className="text-xs text-indigo-500 font-bold uppercase">Analista Asignado</div>
                            <div className="font-bold text-indigo-900">{data.assignedAnalyst}</div>
                        </div>
                     </div>
                )}
            </div>

            {/* Right Column: Timeline / History & Notes */}
            <div className="w-full md:w-80 bg-slate-50/50 border-t md:border-t-0 md:border-l border-slate-200 flex flex-col h-full">

                {/* Notes Input */}
                {canComment && (
                    <div className="p-4 border-b border-slate-200 bg-white">
                        <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2 flex items-center gap-2">
                            <MessageSquare size={14}/> Nota Interna
                        </h3>
                        <div className="relative">
                            <textarea
                                value={newComment}
                                onChange={e => setNewComment(e.target.value)}
                                className="w-full text-xs p-3 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 bg-white pr-10 resize-none outline-none transition-all shadow-sm"
                                placeholder="Escribe un comentario..."
                                rows={2}
                            />
                            <button 
                                onClick={handleAddComment}
                                disabled={!newComment.trim()}
                                className="absolute right-2 bottom-2 p-1.5 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 disabled:opacity-50 disabled:hover:bg-indigo-600 transition-colors shadow-sm"
                            >
                                <Send size={12}/>
                            </button>
                        </div>
                    </div>
                )}

                {/* Timeline */}
                <div className="flex-1 overflow-y-auto p-6">
                    <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-5 flex items-center gap-2">
                        <Clock size={14}/> Historial
                    </h3>

                    <div className="relative space-y-6 before:absolute before:inset-0 before:ml-2.5 before:-translate-x-px md:before:mx-auto md:before:translate-x-0 before:h-full before:w-0.5 before:bg-gradient-to-b before:from-transparent before:via-slate-200 before:to-transparent">
                        {[...data.logs].reverse().map((log, index) => (
                            <div key={log.id} className="relative flex items-start group">
                                <div className={`absolute left-0 h-5 w-5 rounded-full border-2 border-white shadow-sm flex items-center justify-center z-10 ${
                                    index === 0 ? 'bg-indigo-500 ring-4 ring-indigo-100' : 'bg-slate-300'
                                }`}>
                                    {index === 0 && <div className="w-1.5 h-1.5 bg-white rounded-full"></div>}
                                </div>
                                <div className="ml-8 w-full">
                                    <div className="flex flex-col sm:flex-row sm:justify-between sm:items-baseline mb-1">
                                        <span className="text-xs font-bold text-slate-700 truncate max-w-[120px]" title={log.actor}>{log.actor}</span>
                                        <span className="text-[9px] text-slate-400">{new Date(log.timestamp).toLocaleString(undefined, { month: 'short', day: 'numeric', hour: '2-digit', minute:'2-digit'})}</span>
                                    </div>
                                    <div className="text-xs text-slate-600 bg-white p-2.5 rounded-lg border border-slate-200 shadow-sm leading-relaxed">
                                        {log.message}
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </div>

        {/* Footer Actions - Dynamic based on Role & Status */}
        <div className="bg-white border-t border-slate-200 p-4 shrink-0 flex items-center justify-between gap-4 z-20 relative">
             <button 
                onClick={handleClose}
                className="px-4 py-2 bg-white hover:bg-slate-50 border border-slate-300 text-slate-700 text-sm font-medium rounded-lg shadow-sm transition-colors"
            >
                Cerrar
            </button>

            <div className="flex items-center gap-2 flex-1 justify-end">

                {/* --- ADMIN ACTIONS --- */}
                {/* Admin/SuperAdmin can only derive if Status is RECIBIDO */}
                {(isAdmin || isSuperAdmin) && data.status === Status.RECIBIDO && (
                     <button 
                     onClick={handleDerive}
                     className="flex items-center gap-2 bg-gradient-to-r from-orange-500 to-orange-600 hover:from-orange-600 hover:to-orange-700 text-white py-2 px-6 rounded-lg text-sm font-bold shadow-md transition-all active:scale-95"
                   >
                     Derivar al Área <ArrowRight size={16}/>
                   </button>
                )}

                {/* --- HEAD ACTIONS: DERIVATION PHASE --- */}
                {isHead && data.status === Status.DERIVACION && data.area === currentUser.area && (
                    <div className="flex items-center gap-2 w-full justify-end relative">

                         {/* Return Input Overlay or Button */}
                         {showReturnInput ? (
                             <div className="flex-1 flex gap-2 items-center bg-red-50 p-1.5 rounded-lg border border-red-100 animate-in slide-in-from-right-10 fade-in">
                                <input 
                                    className="flex-1 text-sm p-1.5 border border-red-200 rounded-md focus:outline-none focus:ring-1 focus:ring-red-300"
                                    placeholder="Razón de devolución..."
                                    value={returnReason}
                                    onChange={e => setReturnReason(e.target.value)}
                                    autoFocus
                                />
                                <button onClick={handleReturnSubmit} className="bg-red-500 text-white px-3 py-1.5 rounded-md text-xs font-bold">Confirmar</button>
                                <button onClick={() => setShowReturnInput(false)} className="text-slate-500 px-2 text-xs">Cancelar</button>
                             </div>
                         ) : (
                             <button 
                                onClick={() => setShowReturnInput(true)}
                                className="px-4 py-2 text-slate-600 hover:text-red-600 hover:bg-red-50 border border-slate-200 rounded-lg text-xs font-bold transition-colors"
                             >
                                Devolver
                             </button>
                         )}

                         {!showReturnInput && (
                            <>
                                {/* Analyst Selection */}
                                <div className="relative">
                                    <button 
                                        onClick={() => setShowAnalystSelect(!showAnalystSelect)}
                                        className="bg-indigo-600 hover:bg-indigo-700 text-white py-2 px-4 rounded-lg text-sm font-bold shadow-sm transition-colors flex items-center gap-2"
                                    >
                                        <User size={16}/> Asignar Analista
                                        {showAnalystSelect && <ChevronUp size={14}/>}
                                    </button>

                                    {showAnalystSelect && (
                                        <div className="absolute bottom-full right-0 mb-2 w-64 bg-white rounded-xl shadow-xl border border-slate-200 p-2 animate-in slide-in-from-bottom-2 z-50">
                                             <p className="text-xs font-bold text-slate-400 uppercase p-2">Seleccionar del equipo:</p>
                                             <div className="max-h-48 overflow-y-auto custom-scrollbar flex flex-col gap-1">
                                                {availableAnalysts.length > 0 ? availableAnalysts.map(a => (
                                                    <button 
                                                        key={a.id} 
                                                        onClick={() => handleAssignAnalyst(a.name)}
                                                        className="flex items-center gap-3 w-full text-left px-3 py-2 hover:bg-indigo-50 rounded-lg transition-colors text-sm text-slate-700"
                                                    >
                                                        <div className="w-6 h-6 rounded-full bg-indigo-100 text-indigo-600 flex items-center justify-center text-xs font-bold">
                                                            {a.name.substring(0,2).toUpperCase()}
                                                        </div>
                                                        {a.name}
                                                    </button>
                                                )) : (
                                                    <p className="text-xs text-slate-400 italic p-2 text-center">No hay analistas.</p>
                                                )}
                                             </div>
                                        </div>
                                    )}
                                </div>

                                <button 
                                    onClick={handleStartExecution}
                                    className="bg-amber-500 hover:bg-amber-600 text-white py-2 px-6 rounded-lg text-sm font-bold shadow-md transition-colors flex items-center gap-2"
                                >
                                    <Briefcase size={18}/> Iniciar Ejecución
                                </button>
                            </>
                         )}
                    </div>
                )}

                {/* --- HEAD ACTIONS: EXECUTION PHASE --- */}
                {isHead && data.status === Status.EJECUCION && data.area === currentUser.area && (
                     <button 
                     onClick={handleFinalize}
                     className="bg-emerald-600 hover:bg-emerald-700 text-white py-2 px-6 rounded-lg text-sm font-bold shadow-md hover:shadow-lg transition-all active:scale-95 flex items-center gap-2"
                     >
                     <CheckCircle size={18}/> Finalizar Tarea
                     </button>
                )}
            </div>
        </div>

      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { User, UserRole, Area } from '../types';
import { User as UserIcon, Edit2, Check, X, Shield, KeyRound, Save } from 'lucide-react';

export const UsersView: React.FC = () => {
  const { users, updateUser } = useSisreq();
  const [editingId, setEditingId] = useState<string | null>(null);

  // Edit States
  const [editName, setEditName] = useState('');
  const [editRole, setEditRole] = useState<UserRole>(UserRole.ANALYST);
  const [editArea, setEditArea] = useState<Area | undefined>(undefined);
  const [editPass, setEditPass] = useState('');

  const handleEditClick = (user: User) => {
    setEditingId(user.id);
    setEditName(user.name);
    setEditRole(user.role);
    setEditArea(user.area);
    setEditPass(user.password || '');
  };

  const handleCancel = () => {
    setEditingId(null);
  };

  const handleSave = (id: string) => {
    const updated: User = {
        id,
        name: editName,
        role: editRole,
        area: editArea,
        password: editPass
    };
    updateUser(updated);
    setEditingId(null);
  };

  // Helper to determine if area selector should be shown
  const needsArea = (role: UserRole) => role === UserRole.HEAD || role === UserRole.ANALYST;

  return (
    <div className="flex-1 overflow-y-auto custom-scrollbar p-6">
        <div className="mb-6">
            <h2 className="text-2xl font-black text-slate-800 tracking-tight">Gestión de Usuarios</h2>
            <p className="text-slate-500 text-sm">Administra el acceso y roles de los miembros del equipo.</p>
        </div>

        <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
             {/* Header */}
             <div className="grid grid-cols-[1fr_120px_150px_120px_100px] gap-4 px-6 py-4 bg-slate-50 border-b border-slate-200 text-xs font-bold text-slate-500 uppercase tracking-wider">
                <div>Usuario</div>
                <div>Rol</div>
                <div>Área</div>
                <div>Contraseña</div>
                <div className="text-right">Acciones</div>
             </div>

             <div className="divide-y divide-slate-100">
                {users.map(user => (
                    <div key={user.id} className="grid grid-cols-[1fr_120px_150px_120px_100px] gap-4 px-6 py-4 items-center hover:bg-slate-50/50 transition-colors">

                        {/* Name */}
                        <div>
                            {editingId === user.id ? (
                                <input 
                                    className="w-full text-sm border border-slate-200 rounded-lg px-3 py-2 focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 bg-white transition-all shadow-sm"
                                    value={editName}
                                    onChange={e => setEditName(e.target.value)}
                                    placeholder="Nombre"
                                />
                            ) : (
                                <div className="flex items-center gap-3">
                                    <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-xs ${
                                        user.role === UserRole.SUPERADMIN ? 'bg-slate-800 text-white' :
                                        user.role === UserRole.ADMIN ? 'bg-red-100 text-red-600' :
                                        user.role === UserRole.HEAD ? 'bg-indigo-100 text-indigo-600' :
                                        'bg-slate-200 text-slate-600'
                                    }`}>
                                        {user.name.substring(0,2).toUpperCase()}
                                    </div>
                                    <span className="font-bold text-slate-700 text-sm">{user.name}</span>
                                </div>
                            )}
                        </div>

                        {/* Role */}
                        <div>
                            {editingId === user.id ? (
                                <div className="relative">
                                    <select 
                                        className="w-full text-xs border border-slate-200 rounded-lg px-2 py-2 focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 bg-white transition-all cursor-pointer shadow-sm appearance-none"
                                        value={editRole}
                                        onChange={e => {
                                            setEditRole(e.target.value as UserRole);
                                            // Reset area if switching to Admin/Super
                                            if (e.target.value === UserRole.ADMIN || e.target.value === UserRole.SUPERADMIN) {
                                                setEditArea(undefined);
                                            } else if (!editArea) {
                                                setEditArea(Area.CONTABILIDAD); // Default
                                            }
                                        }}
                                    >
                                        {Object.values(UserRole).map(r => (
                                            <option key={r} value={r}>{r}</option>
                                        ))}
                                    </select>
                                </div>
                            ) : (
                                <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold border ${
                                    user.role === UserRole.SUPERADMIN ? 'bg-slate-800 text-white border-slate-900' :
                                    user.role === UserRole.ADMIN ? 'bg-red-50 text-red-600 border-red-100' :
                                    user.role === UserRole.HEAD ? 'bg-indigo-50 text-indigo-600 border-indigo-100' :
                                    'bg-slate-100 text-slate-500 border-slate-200'
                                }`}>
                                    {user.role}
                                </span>
                            )}
                        </div>

                        {/* Area */}
                        <div>
                            {editingId === user.id ? (
                                needsArea(editRole) ? (
                                    <div className="relative">
                                        <select 
                                            className="w-full text-xs border border-slate-200 rounded-lg px-2 py-2 focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 bg-white transition-all cursor-pointer shadow-sm appearance-none"
                                            value={editArea}
                                            onChange={e => setEditArea(e.target.value as Area)}
                                        >
                                            {Object.values(Area).map(a => (
                                                <option key={a} value={a}>{a}</option>
                                            ))}
                                        </select>
                                    </div>
                                ) : (
                                    <span className="text-slate-300 text-xs italic">N/A</span>
                                )
                            ) : (
                                <span className="text-xs text-slate-600 font-medium">{user.area || '-'}</span>
                            )}
                        </div>

                        {/* Password */}
                        <div>
                             {editingId === user.id ? (
                                <div className="relative">
                                    <input 
                                        type="text"
                                        className="w-full text-xs border border-slate-200 rounded-lg px-2 py-2 pr-7 focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 bg-white transition-all shadow-sm"
                                        value={editPass}
                                        onChange={e => setEditPass(e.target.value)}
                                        placeholder="Nueva clave"
                                    />
                                    <KeyRound size={12} className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none"/>
                                </div>
                            ) : (
                                <span className="text-slate-400 text-xs">••••••</span>
                            )}
                        </div>

                        {/* Actions */}
                        <div className="flex justify-end gap-2">
                            {editingId === user.id ? (
                                <>
                                    <button onClick={handleCancel} className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors" title="Cancelar">
                                        <X size={16}/>
                                    </button>
                                    <button onClick={() => handleSave(user.id)} className="p-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg shadow-sm transition-colors" title="Guardar">
                                        <Save size={16}/>
                                    </button>
                                </>
                            ) : (
                                <button onClick={() => handleEditClick(user)} className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors border border-transparent hover:border-indigo-100" title="Editar">
                                    <Edit2 size={16}/>
                                </button>
                            )}
                        </div>

                    </div>
                ))}
             </div>
        </div>
    </div>
  );
};

