        <div className="min-h-screen flex flex-col items-center justify-center bg-slate-50 gap-4">
            <div className="bg-gradient-to-br from-indigo-600 to-blue-600 p-3 rounded-xl shadow-lg shadow-indigo-200 animate-pulse">
                <LayoutDashboard className="text-white" size={32} />
            </div>
            <div className="text-slate-500 font-bold text-sm tracking-wide animate-pulse">Conectando a Base de Datos...</div>
        </div>
    );
  }

  if (!isAuthenticated) {
    return <LoginPage />;
  }

  return (
    <Layout>
      {viewMode === 'superadmin' ? <SuperAdminView /> : <Board />}
    </Layout>
  );
};

