    const inactive = total - active;
    const roles = {
        [UserRole.SUPERADMIN]: users.filter(u => u.role === UserRole.SUPERADMIN).length,
        [UserRole.ADMIN]: users.filter(u => u.role === UserRole.ADMIN).length,
        [UserRole.HEAD]: users.filter(u => u.role === UserRole.HEAD).length,
        [UserRole.ANALYST]: users.filter(u => u.role === UserRole.ANALYST).length,
    };
    return { total, active, inactive, roles };
  }, [users]);

  const handleEditClick = (user: User) => {
    setEditingId(user.id);
    setEditName(user.name);
    setEditEmail(user.email || '');
    setEditRole(user.role);
    setEditArea(user.area);
    setEditPass(user.password || '');
    setEditStatus(user.status || 'ACTIVE');
  };

  const handleCancel = () => {
    setEditingId(null);
  };

  const handleSave = (user: User) => {
    const updated: User = {
        ...user,
        name: editName,
        email: editEmail,
        role: editRole,
        area: editArea,
        password: editPass,
        status: editStatus,
        // Preserve joinedAt if it exists, otherwise use current date for new/migrated records
        joinedAt: user.joinedAt || new Date().toISOString()
    };
    updateUser(updated);
    setEditingId(null);
  };

  // Helper to determine if area selector should be shown
  const needsArea = (role: UserRole) => role === UserRole.HEAD || role === UserRole.ANALYST;

  return (
    <div className="flex-1 overflow-y-auto custom-scrollbar p-6 space-y-6 relative">
        {/* Header & Stats */}
        <div className="flex flex-col md:flex-row gap-6">

            {/* Stats Cards */}
            <div className="flex-1 grid grid-cols-1 md:grid-cols-3 gap-4">
                <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex items-center gap-4">
                    <div className="p-3 bg-indigo-50 text-indigo-600 rounded-lg">
                        <UserIcon size={20} />
                    </div>
                    <div>
                        <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Total Usuarios</p>
                        <p className="text-2xl font-black text-slate-800">{stats.total}</p>
                    </div>
                </div>
                <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex items-center gap-4">
                    <div className="p-3 bg-emerald-50 text-emerald-600 rounded-lg">
                        <Activity size={20} />
                    </div>
                    <div>
                        <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Activos</p>
                        <p className="text-2xl font-black text-slate-800">{stats.active}</p>
                    </div>
                </div>
                <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex flex-col justify-center gap-2">
                    <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Distribución</p>
                    <div className="flex gap-1 h-2 w-full rounded-full overflow-hidden bg-slate-100">
                        <div className="bg-slate-800 h-full" style={{ width: `${(stats.roles.SUPERADMIN / stats.total) * 100}%` }} title="SuperAdmin"></div>
                        <div className="bg-red-500 h-full" style={{ width: `${(stats.roles.ADMIN / stats.total) * 100}%` }} title="Admin"></div>
                        <div className="bg-indigo-500 h-full" style={{ width: `${(stats.roles.HEAD / stats.total) * 100}%` }} title="Jefaturas"></div>
                        <div className="bg-slate-400 h-full" style={{ width: `${(stats.roles.ANALYST / stats.total) * 100}%` }} title="Analistas"></div>
                    </div>
                    <div className="flex gap-3 text-[10px] font-medium text-slate-500">
                        <span className="flex items-center gap-1"><div className="w-2 h-2 rounded-full bg-indigo-500"></div> Jefes</span>
                        <span className="flex items-center gap-1"><div className="w-2 h-2 rounded-full bg-slate-400"></div> Analistas</span>
                    </div>
                </div>
            </div>

            {/* Create Button (Placed to the right) */}
            <div className="flex items-start">
                <button 
                    onClick={() => setIsNewUserModalOpen(true)}
                    className="bg-slate-800 hover:bg-slate-900 text-white px-5 py-4 rounded-xl shadow-lg shadow-slate-300 flex items-center gap-2 text-sm font-bold transition-all active:scale-95 whitespace-nowrap"
                >
                    <UserPlus size={18}/> Nuevo Usuario
                </button>
            </div>
        </div>

        <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
             {/* Table Header */}
             <div className="grid grid-cols-[2.5fr_1.5fr_1.5fr_1fr_1fr_100px_80px] gap-4 px-6 py-4 bg-slate-50 border-b border-slate-200 text-[11px] font-bold text-slate-400 uppercase tracking-wider sticky top-0 z-10">
                <div>Usuario / Email</div>
                <div>Rol</div>
                <div>Área</div>
                <div>Estado</div>
                <div>Fecha Ingreso</div>
                <div>Acceso</div>
                <div className="text-right">Editar</div>
             </div>

             <div className="divide-y divide-slate-100">
                {users.map(user => (
                    <div key={user.id} className="grid grid-cols-[2.5fr_1.5fr_1.5fr_1fr_1fr_100px_80px] gap-4 px-6 py-4 items-center hover:bg-slate-50/50 transition-colors group">

                        {/* Name & Email */}
                        <div>
                            {editingId === user.id ? (
                                <div className="space-y-2">
                                    <input 
                                        className="w-full text-sm border border-slate-200 rounded-lg px-3 py-1.5 focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 bg-white shadow-sm"
                                        value={editName}
                                        onChange={e => setEditName(e.target.value)}
                                        placeholder="Nombre Completo"
                                    />
                                    <div className="relative">
                                        <Mail size={12} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"/>
                                        <input 
                                            className="w-full text-xs border border-slate-200 rounded-lg pl-8 pr-3 py-1.5 focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 bg-white shadow-sm"
                                            value={editEmail}
                                            onChange={e => setEditEmail(e.target.value)}
                                            placeholder="correo@sisreq.com"
                                        />
                                    </div>
                                </div>
                            ) : (
                                <div className="flex items-center gap-3">
                                    <div className={`w-9 h-9 rounded-full flex items-center justify-center font-bold text-xs shadow-sm border border-white ${
                                        user.role === UserRole.SUPERADMIN ? 'bg-slate-800 text-white' :
                                        user.role === UserRole.ADMIN ? 'bg-red-100 text-red-600' :
                                        user.role === UserRole.HEAD ? 'bg-indigo-100 text-indigo-600' :
                                        'bg-slate-100 text-slate-500'
                                    }`}>
                                        {user.name.substring(0,2).toUpperCase()}
                                    </div>
                                    <div>
                                        <div className="font-bold text-slate-700 text-sm">{user.name}</div>
                                        <div className="text-xs text-slate-400 font-medium">{user.email || 'Sin correo registrado'}</div>
                                    </div>
                                </div>
                            )}
                        </div>

                        {/* Role */}
                        <div>
                            {editingId === user.id ? (
                                <select 
                                    className="w-full text-xs border border-slate-200 rounded-lg px-2 py-2 focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 bg-white transition-all cursor-pointer shadow-sm"
                                    value={editRole}
                                    onChange={e => {
                                        setEditRole(e.target.value as UserRole);
                                        if (e.target.value === UserRole.ADMIN || e.target.value === UserRole.SUPERADMIN) {
                                            setEditArea(undefined);
                                        } else if (!editArea) {
                                            setEditArea(Area.CONTABILIDAD);
                                        }
                                    }}
                                >
                                    {Object.values(UserRole).map(r => (
                                        <option key={r} value={r}>{r}</option>
                                    ))}
                                </select>
                            ) : (
                                <span className={`px-2.5 py-1 rounded-full text-[10px] font-bold border ${
                                    user.role === UserRole.SUPERADMIN ? 'bg-slate-800 text-white border-slate-900' :
                                    user.role === UserRole.ADMIN ? 'bg-red-50 text-red-600 border-red-100' :
                                    user.role === UserRole.HEAD ? 'bg-indigo-50 text-indigo-600 border-indigo-100' :
                                    'bg-slate-100 text-slate-500 border-slate-200'
                                }`}>
                                    {user.role}
                                </span>
                            )}
                        </div>

                        {/* Area */}
                        <div>
                            {editingId === user.id ? (
                                needsArea(editRole) ? (
                                    <select 
                                        className="w-full text-xs border border-slate-200 rounded-lg px-2 py-2 focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 bg-white transition-all cursor-pointer shadow-sm"
                                        value={editArea}
                                        onChange={e => setEditArea(e.target.value as Area)}
                                    >
                                        {Object.values(Area).map(a => (
                                            <option key={a} value={a}>{a}</option>
                                        ))}
                                    </select>
                                ) : (
                                    <span className="text-slate-300 text-xs italic">N/A</span>
                                )
                            ) : (
                                <span className="text-xs text-slate-600 font-medium">{user.area || '-'}</span>
                            )}
                        </div>

                        {/* Status */}
                        <div>
                            {editingId === user.id ? (
                                <button 
                                    onClick={() => setEditStatus(editStatus === 'ACTIVE' ? 'INACTIVE' : 'ACTIVE')}
                                    className={`px-3 py-1.5 rounded-lg text-xs font-bold border flex items-center gap-2 transition-all ${
                                        editStatus === 'ACTIVE' 
                                        ? 'bg-emerald-50 text-emerald-600 border-emerald-200' 
                                        : 'bg-slate-50 text-slate-500 border-slate-200'
                                    }`}
                                >
                                    {editStatus === 'ACTIVE' ? <Unlock size={12}/> : <Lock size={12}/>}
                                    {editStatus === 'ACTIVE' ? 'Activo' : 'Inactivo'}
                                </button>
                            ) : (
                                <div className="flex items-center gap-2">
                                    <div className={`w-2 h-2 rounded-full ${(!user.status || user.status === 'ACTIVE') ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.4)]' : 'bg-slate-300'}`}></div>
                                    <span className={`text-xs font-bold ${(!user.status || user.status === 'ACTIVE') ? 'text-slate-700' : 'text-slate-400'}`}>
                                        {(!user.status || user.status === 'ACTIVE') ? 'Activo' : 'Inactivo'}
                                    </span>
                                </div>
                            )}
                        </div>

                        {/* Joined Date */}
                        <div className="flex items-center gap-2 text-xs text-slate-500">
                            <Calendar size={12} className="text-slate-400"/>
                            {user.joinedAt ? new Date(user.joinedAt).toLocaleDateString() : '-'}
                        </div>

                        {/* Password / Security */}
                        <div>
                             {editingId === user.id ? (
                                <div className="relative">
                                    <input 
                                        type="text"
                                        className="w-full text-xs border border-slate-200 rounded-lg pl-2 pr-6 py-2 focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 bg-white shadow-sm"
                                        value={editPass}
                                        onChange={e => setEditPass(e.target.value)}
                                        placeholder="Clave"
                                    />
                                    <KeyRound size={10} className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none"/>
                                </div>
                            ) : (
                                <span className="text-slate-400 text-xs font-mono tracking-widest">••••••</span>
                            )}
                        </div>

                        {/* Actions */}
                        <div className="flex justify-end gap-2">
                            {editingId === user.id ? (
                                <>
                                    <button onClick={handleCancel} className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors" title="Cancelar">
                                        <X size={16}/>
                                    </button>
                                    <button onClick={() => handleSave(user)} className="p-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg shadow-sm transition-colors" title="Guardar">
                                        <Save size={16}/>
                                    </button>
                                </>
                            ) : (
                                <button onClick={() => handleEditClick(user)} className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors border border-transparent hover:border-indigo-100 opacity-0 group-hover:opacity-100" title="Editar">
                                    <Edit2 size={16}/>
                                </button>
                            )}
                        </div>

                    </div>
                ))}
             </div>
        </div>

        <NewUserModal isOpen={isNewUserModalOpen} onClose={() => setIsNewUserModalOpen(false)} />
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { Area, UserRole, User, UserStatus } from '../types';
import { X, UserPlus, User as UserIcon, Building, Lock, Mail, Shield, Check, Save, Power } from 'lucide-react';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  userToEdit?: User | null; // Optional prop for editing mode
}

export const NewUserModal: React.FC<Props> = ({ isOpen, onClose, userToEdit }) => {
  const { addUser, updateUser } = useSisreq();
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [role, setRole] = useState<UserRole>(UserRole.ANALYST);
  const [area, setArea] = useState<Area | 'NONE'>('NONE');
  const [password, setPassword] = useState('');
  const [status, setStatus] = useState<UserStatus>('ACTIVE');

  // Reset or Populate form when opening
  useEffect(() => {
    if (isOpen) {
        if (userToEdit) {
            // Edit Mode
            setName(userToEdit.name);
            setEmail(userToEdit.email || '');
            setRole(userToEdit.role);
            setArea(userToEdit.area || 'NONE');
            setStatus(userToEdit.status || 'ACTIVE');
            setPassword(''); // Clear password field for security (leave empty to keep current)
        } else {
            // Create Mode
            setName('');
            setEmail('');
            setRole(UserRole.ANALYST);
            setArea('NONE');
            setStatus('ACTIVE');
            setPassword('');
        }
    }
  }, [isOpen, userToEdit]);

  // Determine if Area is needed based on Role
  const needsArea = role === UserRole.HEAD || role === UserRole.ANALYST;

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name || !email) return;

    // For creation, password is required. For edit, it's optional.
    if (!userToEdit && !password) return;

    const finalArea = needsArea && area !== 'NONE' ? (area as Area) : undefined;

    if (userToEdit) {
        // Update Logic
        const updatedUser: User = {
            ...userToEdit,
            name,
            email,
            role,
            area: finalArea,
            status,
            // Only update password if user typed something new
            password: password.trim() ? password : userToEdit.password
        };
        updateUser(updatedUser);
    } else {
        // Create Logic
        addUser(name, email, role, password, finalArea);
    }

    onClose();
  };

  const isEditMode = !!userToEdit;

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm transition-opacity" 
        onClick={onClose} 
      />

      {/* Modal Card */}
      <div className="relative bg-white rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden animate-in fade-in zoom-in-95 duration-200 border border-white/20">

        {/* Header */}
        <div className="bg-gradient-to-r from-slate-50 to-white border-b border-slate-100 px-6 py-5 flex justify-between items-center">
          <div className="flex items-center gap-3">
             <div className={`p-2.5 rounded-xl shadow-sm border ${isEditMode ? 'bg-indigo-600 text-white border-indigo-700' : 'bg-indigo-100 text-indigo-600 border-indigo-200/50'}`}>
                {isEditMode ? <UserIcon size={20} /> : <UserPlus size={20} className="stroke-2"/>}
             </div>
             <div>
                <h2 className="text-lg font-black text-slate-800 tracking-tight leading-none mb-1">
                    {isEditMode ? 'Editar Usuario' : 'Nuevo Usuario'}
                </h2>
                <p className="text-xs text-slate-500 font-medium">
                    {isEditMode ? 'Modificar datos de acceso y perfil' : 'Registrar nuevo miembro del equipo'}
                </p>
             </div>
          </div>
          <button 
            onClick={onClose} 
            className="text-slate-400 hover:text-slate-600 p-2 hover:bg-slate-100 rounded-full transition-colors"
          >
            <X size={20} />
          </button>
        </div>

        {/* Form Body */}
        <form onSubmit={handleSubmit} className="p-6 space-y-5">

            {/* Name */}
            <div className="space-y-2">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider flex items-center gap-1.5">
                    <UserIcon size={12} /> Nombre Completo
                </label>
                <input
                    type="text"
                    required
                    className="w-full bg-slate-50 border border-slate-200 text-slate-700 text-sm rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 transition-all placeholder:text-slate-400 font-medium"
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    placeholder="Ej: Juan Pérez"
                    autoFocus
                />
            </div>

            {/* Email */}
            <div className="space-y-2">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider flex items-center gap-1.5">
                    <Mail size={12} /> Correo Electrónico
                </label>
                <input
                    type="email"
                    required
                    className="w-full bg-slate-50 border border-slate-200 text-slate-700 text-sm rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 transition-all placeholder:text-slate-400 font-medium"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    placeholder="ejemplo@sisreq.com"
                />
            </div>

            <div className="grid grid-cols-2 gap-4">
                {/* Role */}
                <div className="space-y-2">
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider flex items-center gap-1.5">
                        <Shield size={12} /> Rol
                    </label>
                    <div className="relative">
                        <select
                            className="w-full bg-slate-50 border border-slate-200 text-slate-700 text-sm rounded-xl px-4 py-3 appearance-none focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 transition-all cursor-pointer font-medium"
                            value={role}
                            onChange={(e) => {
                                setRole(e.target.value as UserRole);
                                if (e.target.value === UserRole.ADMIN || e.target.value === UserRole.SUPERADMIN) {
                                    setArea('NONE');
                                } else if (!userToEdit) {
                                    // Only auto-set area on creation, not edit (unless user specifically changes role)
                                    setArea(Area.CONTABILIDAD);
                                }
                            }}
                        >
                            {Object.values(UserRole).map((r) => (
                                <option key={r} value={r}>{r}</option>
                            ))}
                        </select>
                         <div className="absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">
                            <svg className="w-4 h-4 fill-current" viewBox="0 0 20 20"><path d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z"/></svg>
                        </div>
                    </div>
                </div>

                {/* Area (Conditional) */}
                <div className="space-y-2">
                    <label className={`text-[10px] font-bold uppercase tracking-wider flex items-center gap-1.5 ${needsArea ? 'text-slate-400' : 'text-slate-300'}`}>
                        <Building size={12} /> Área
                    </label>
                    <div className="relative">
                        <select
                            disabled={!needsArea}
                            className={`w-full border text-sm rounded-xl px-4 py-3 appearance-none transition-all font-medium ${
                                needsArea 
                                ? 'bg-slate-50 border-slate-200 text-slate-700 focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 cursor-pointer' 
                                : 'bg-slate-100 border-slate-200 text-slate-400 cursor-not-allowed'
                            }`}
                            value={area}
                            onChange={(e) => setArea(e.target.value as Area)}
                        >
                             {!needsArea && <option value="NONE">N/A</option>}
                             {Object.values(Area).map((a) => (
                                <option key={a} value={a}>{a}</option>
                             ))}
                        </select>
                        <div className={`absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none ${needsArea ? 'text-slate-400' : 'text-slate-300'}`}>
                            <svg className="w-4 h-4 fill-current" viewBox="0 0 20 20"><path d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z"/></svg>
                        </div>
                    </div>
                </div>
            </div>

            {/* Password */}
            <div className="space-y-2">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider flex items-center gap-1.5">
                    <Lock size={12} /> Contraseña
                </label>
                <input
                    type="text"
                    required={!isEditMode}
                    className="w-full bg-slate-50 border border-slate-200 text-slate-700 text-sm rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 transition-all placeholder:text-slate-400 font-medium"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    placeholder={isEditMode ? "Dejar en blanco para mantener actual" : "Clave de acceso"}
                />
            </div>

            {/* Status (Only show in edit mode) */}
            {isEditMode && (
                <div className="space-y-2">
                     <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider flex items-center gap-1.5">
                        <Power size={12} /> Estado del Usuario
                    </label>
                    <div className="flex gap-4">
                        <button
                            type="button"
                            onClick={() => setStatus('ACTIVE')}
                            className={`flex-1 py-2.5 rounded-xl border text-xs font-bold transition-all flex items-center justify-center gap-2 ${
                                status === 'ACTIVE' 
                                ? 'bg-emerald-50 border-emerald-200 text-emerald-600 ring-1 ring-emerald-500/20' 
                                : 'bg-white border-slate-200 text-slate-400 hover:bg-slate-50'
                            }`}
                        >
                            <Check size={14} /> Activo
                        </button>
                        <button
                            type="button"
                            onClick={() => setStatus('INACTIVE')}
                             className={`flex-1 py-2.5 rounded-xl border text-xs font-bold transition-all flex items-center justify-center gap-2 ${
                                status === 'INACTIVE' 
                                ? 'bg-slate-100 border-slate-300 text-slate-600 ring-1 ring-slate-500/20' 
                                : 'bg-white border-slate-200 text-slate-400 hover:bg-slate-50'
                            }`}
                        >
                            <Lock size={14} /> Inactivo
                        </button>
                    </div>
                </div>
            )}

           {/* Footer */}
           <div className="pt-4 flex items-center justify-end gap-3 border-t border-slate-100 mt-2">
                <button
                    type="button"
                    onClick={onClose}
                    className="px-5 py-2.5 text-slate-500 font-bold text-sm hover:bg-slate-50 rounded-xl transition-colors"
                >
                    Cancelar
                </button>
                <button
                    type="submit"
                    className="bg-indigo-600 hover:bg-indigo-700 text-white font-bold text-sm px-6 py-2.5 rounded-xl shadow-lg shadow-indigo-200 hover:shadow-xl hover:translate-y-[-1px] transition-all flex items-center gap-2 active:scale-95"
                >
                    {isEditMode ? <Save size={16}/> : <Check size={16} />} 
                    {isEditMode ? 'Guardar Cambios' : 'Crear Usuario'}
                </button>
           </div>
        </form>
      </div>
    </div>
  );
};

