                                            <div className={`text-xs p-3 rounded-xl border ${config.bg} ${config.text.replace('text-', 'text-opacity-90 text-')} ${config.border} relative`}>
                                                {/* Little triangle for chat bubble effect */}
                                                <div className={`absolute top-2 -left-1.5 w-3 h-3 rotate-45 border-l border-b ${config.bg} ${config.border}`}></div>
                                                <p className="relative z-10 font-medium leading-relaxed">{log.message}</p>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            </div>
        </div>

        {/* Footer Actions - Dynamic based on Role & Status */}
        <div className="bg-white border-t border-slate-200 p-4 shrink-0 flex items-center justify-between gap-4 z-20 relative shadow-[0_-4px_20px_rgba(0,0,0,0.02)]">
             <button 
                onClick={handleClose}
                className="px-4 py-2 bg-white hover:bg-slate-50 border border-slate-300 text-slate-700 text-sm font-medium rounded-lg shadow-sm transition-colors"
            >
                Cerrar
            </button>

            <div className="flex items-center gap-2 flex-1 justify-end">

                {/* --- ADMIN ACTIONS --- */}
                {/* Admin/SuperAdmin can only derive if Status is RECIBIDO */}
                {(isAdmin || isSuperAdmin) && data.status === Status.RECIBIDO && (
                     <button 
                     onClick={handleDerive}
                     className="flex items-center gap-2 bg-gradient-to-r from-orange-500 to-orange-600 hover:from-orange-600 hover:to-orange-700 text-white py-2 px-6 rounded-lg text-sm font-bold shadow-md transition-all active:scale-95"
                   >
                     Derivar al Área <ArrowRight size={16}/>
                   </button>
                )}

                {/* --- HEAD ACTIONS: DERIVATION PHASE --- */}
                {isHead && data.status === Status.DERIVACION && data.area === currentUser.area && (
                    <div className="flex items-center gap-2 w-full justify-end relative">

                         {/* Return Input Overlay or Button */}
                         {showReturnInput ? (
                             <div className="flex-1 flex gap-2 items-center bg-red-50 p-1.5 rounded-lg border border-red-100 animate-in slide-in-from-right-10 fade-in">
                                <input 
                                    className="flex-1 text-sm p-1.5 border border-red-200 rounded-md focus:outline-none focus:ring-1 focus:ring-red-300"
                                    placeholder="Razón de devolución..."
                                    value={returnReason}
                                    onChange={e => setReturnReason(e.target.value)}
                                    autoFocus
                                />
                                <button onClick={handleReturnSubmit} className="bg-red-500 text-white px-3 py-1.5 rounded-md text-xs font-bold">Confirmar</button>
                                <button onClick={() => setShowReturnInput(false)} className="text-slate-500 px-2 text-xs">Cancelar</button>
                             </div>
                         ) : (
                             <button 
                                onClick={() => setShowReturnInput(true)}
                                className="px-4 py-2 text-slate-600 hover:text-red-600 hover:bg-red-50 border border-slate-200 rounded-lg text-xs font-bold transition-colors"
                             >
                                Devolver
                             </button>
                         )}

                         {!showReturnInput && (
                            <>
                                {/* Analyst Selection */}
                                <div className="relative">
                                    <button 
                                        onClick={() => setShowAnalystSelect(!showAnalystSelect)}
                                        className="bg-indigo-600 hover:bg-indigo-700 text-white py-2 px-4 rounded-lg text-sm font-bold shadow-sm transition-colors flex items-center gap-2"
                                    >
                                        <User size={16}/> Asignar Analista
                                        {showAnalystSelect && <ChevronUp size={14}/>}
                                    </button>

                                    {showAnalystSelect && (
                                        <div className="absolute bottom-full right-0 mb-2 w-64 bg-white rounded-xl shadow-xl border border-slate-200 p-2 animate-in slide-in-from-bottom-2 z-50">
                                             <p className="text-xs font-bold text-slate-400 uppercase p-2">Seleccionar del equipo:</p>
                                             <div className="max-h-48 overflow-y-auto custom-scrollbar flex flex-col gap-1">
                                                {availableAnalysts.length > 0 ? availableAnalysts.map(a => (
                                                    <button 
                                                        key={a.id} 
                                                        onClick={() => handleAssignAnalyst(a.name)}
                                                        className="flex items-center gap-3 w-full text-left px-3 py-2 hover:bg-indigo-50 rounded-lg transition-colors text-sm text-slate-700"
                                                    >
                                                        <div className="w-6 h-6 rounded-full bg-indigo-100 text-indigo-600 flex items-center justify-center text-xs font-bold">
                                                            {a.name.substring(0,2).toUpperCase()}
                                                        </div>
                                                        {a.name}
                                                    </button>
                                                )) : (
                                                    <p className="text-xs text-slate-400 italic p-2 text-center">No hay analistas.</p>
                                                )}
                                             </div>
                                        </div>
                                    )}
                                </div>

                                <button 
                                    onClick={handleStartExecution}
                                    className="bg-amber-500 hover:bg-amber-600 text-white py-2 px-6 rounded-lg text-sm font-bold shadow-md transition-colors flex items-center gap-2"
                                >
                                    <Briefcase size={18}/> Iniciar Ejecución
                                </button>
                            </>
                         )}
                    </div>
                )}

                {/* --- HEAD ACTIONS: EXECUTION PHASE --- */}
                {isHead && data.status === Status.EJECUCION && data.area === currentUser.area && (
                     <button 
                     onClick={handleFinalize}
                     className="bg-emerald-600 hover:bg-emerald-700 text-white py-2 px-6 rounded-lg text-sm font-bold shadow-md hover:shadow-lg transition-all active:scale-95 flex items-center gap-2"
                     >
                     <CheckCircle size={18}/> Finalizar Tarea
                     </button>
                )}
            </div>
        </div>

      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { Area, UserRole, User, UserStatus } from '../types';
import { X, UserPlus, User as UserIcon, Building, Lock, Mail, Shield, Check, Save, Power } from 'lucide-react';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  userToEdit?: User | null; // Optional prop for editing mode
}

export const NewUserModal: React.FC<Props> = ({ isOpen, onClose, userToEdit }) => {
  const { addUser, updateUser } = useSisreq();
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [role, setRole] = useState<UserRole>(UserRole.ANALYST);
  const [area, setArea] = useState<Area | 'NONE'>('NONE');
  const [password, setPassword] = useState('');
  const [status, setStatus] = useState<UserStatus>('ACTIVE');

  // Reset or Populate form when opening
  useEffect(() => {
    if (isOpen) {
        if (userToEdit) {
            // Edit Mode
            setName(userToEdit.name);
            setEmail(userToEdit.email || '');
            setRole(userToEdit.role);
            setArea(userToEdit.area || 'NONE');
            setStatus(userToEdit.status || 'ACTIVE');
            setPassword(''); // Clear password field for security (leave empty to keep current)
        } else {
            // Create Mode
            setName('');
            setEmail('');
            setRole(UserRole.ANALYST);
            setArea(Area.CONTABILIDAD); // Default area for Analyst
            setStatus('ACTIVE');
            setPassword('');
        }
    }
  }, [isOpen, userToEdit]);

  // Determine if Area is needed based on Role
  const needsArea = role === UserRole.HEAD || role === UserRole.ANALYST;

  const handleRoleChange = (newRole: UserRole) => {
    setRole(newRole);

    const roleRequiresArea = newRole === UserRole.HEAD || newRole === UserRole.ANALYST;

    if (!roleRequiresArea) {
        setArea('NONE');
    } else {
        // If we switched to a role needing area, and currently don't have one (or it's NONE), set default
        if (area === 'NONE' || !area) {
             setArea(Area.CONTABILIDAD);
        }
    }
  };

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name || !email) return;

    // For creation, password is required. For edit, it's optional.
    if (!userToEdit && !password) return;

    // Ensure finalArea is undefined if not needed, or the specific area if needed
    const finalArea = needsArea && area !== 'NONE' ? (area as Area) : undefined;

    if (userToEdit) {
        // Update Logic
        const updatedUser: User = {
            ...userToEdit,
            name,
            email,
            role,
            area: finalArea,
            status,
            // Only update password if user typed something new
            password: password.trim() ? password : userToEdit.password
        };
        updateUser(updatedUser);
    } else {
        // Create Logic
        addUser(name, email, role, password, finalArea);
    }

    onClose();
  };

  const isEditMode = !!userToEdit;

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm transition-opacity" 
        onClick={onClose} 
      />

      {/* Modal Card */}
      <div className="relative bg-white rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden animate-in fade-in zoom-in-95 duration-200 border border-white/20">

        {/* Header */}
        <div className="bg-gradient-to-r from-slate-50 to-white border-b border-slate-100 px-6 py-5 flex justify-between items-center">
          <div className="flex items-center gap-3">
             <div className={`p-2.5 rounded-xl shadow-sm border ${isEditMode ? 'bg-indigo-600 text-white border-indigo-700' : 'bg-indigo-100 text-indigo-600 border-indigo-200/50'}`}>
                {isEditMode ? <UserIcon size={20} /> : <UserPlus size={20} className="stroke-2"/>}
             </div>
             <div>
                <h2 className="text-lg font-black text-slate-800 tracking-tight leading-none mb-1">
                    {isEditMode ? 'Editar Usuario' : 'Nuevo Usuario'}
                </h2>
                <p className="text-xs text-slate-500 font-medium">
                    {isEditMode ? 'Modificar datos de acceso y perfil' : 'Registrar nuevo miembro del equipo'}
                </p>
             </div>
          </div>
          <button 
            onClick={onClose} 
            className="text-slate-400 hover:text-slate-600 p-2 hover:bg-slate-100 rounded-full transition-colors"
          >
            <X size={20} />
          </button>
        </div>

        {/* Form Body */}
        <form onSubmit={handleSubmit} className="p-6 space-y-5">

            {/* Name */}
            <div className="space-y-2">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider flex items-center gap-1.5">
                    <UserIcon size={12} /> Nombre Completo
                </label>
                <input
                    type="text"
                    required
                    className="w-full bg-slate-50 border border-slate-200 text-slate-700 text-sm rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 transition-all placeholder:text-slate-400 font-medium"
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    placeholder="Ej: Juan Pérez"
                    autoFocus
                />
            </div>

            {/* Email */}
            <div className="space-y-2">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider flex items-center gap-1.5">
                    <Mail size={12} /> Correo Electrónico
                </label>
                <input
                    type="email"
                    required
                    className="w-full bg-slate-50 border border-slate-200 text-slate-700 text-sm rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 transition-all placeholder:text-slate-400 font-medium"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    placeholder="ejemplo@sisreq.com"
                />
            </div>

            <div className="grid grid-cols-2 gap-4">
                {/* Role */}
                <div className="space-y-2">
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider flex items-center gap-1.5">
                        <Shield size={12} /> Rol
                    </label>
                    <div className="relative">
                        <select
                            className="w-full bg-slate-50 border border-slate-200 text-slate-700 text-sm rounded-xl px-4 py-3 appearance-none focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 transition-all cursor-pointer font-medium"
                            value={role}
                            onChange={(e) => handleRoleChange(e.target.value as UserRole)}
                        >
                            {Object.values(UserRole).map((r) => (
                                <option key={r} value={r}>{r}</option>
                            ))}
                        </select>
                         <div className="absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">
                            <svg className="w-4 h-4 fill-current" viewBox="0 0 20 20"><path d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z"/></svg>
                        </div>
                    </div>
                </div>

                {/* Area (Conditional) */}
                <div className="space-y-2">
                    <label className={`text-[10px] font-bold uppercase tracking-wider flex items-center gap-1.5 ${needsArea ? 'text-slate-400' : 'text-slate-300'}`}>
                        <Building size={12} /> Área
                    </label>
                    <div className="relative">
                        <select
                            disabled={!needsArea}
                            className={`w-full border text-sm rounded-xl px-4 py-3 appearance-none transition-all font-medium ${
                                needsArea 
                                ? 'bg-slate-50 border-slate-200 text-slate-700 focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 cursor-pointer' 
                                : 'bg-slate-100 border-slate-200 text-slate-400 cursor-not-allowed'
                            }`}
                            value={area}
                            onChange={(e) => setArea(e.target.value as Area)}
                        >
                             {!needsArea && <option value="NONE">N/A</option>}
                             {Object.values(Area).map((a) => (
                                <option key={a} value={a}>{a}</option>
                             ))}
                        </select>
                        <div className={`absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none ${needsArea ? 'text-slate-400' : 'text-slate-300'}`}>
                            <svg className="w-4 h-4 fill-current" viewBox="0 0 20 20"><path d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z"/></svg>
                        </div>
                    </div>
                </div>
            </div>

            {/* Password */}
            <div className="space-y-2">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider flex items-center gap-1.5">
                    <Lock size={12} /> Contraseña
                </label>
                <input
                    type="text"
                    required={!isEditMode}
                    className="w-full bg-slate-50 border border-slate-200 text-slate-700 text-sm rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 transition-all placeholder:text-slate-400 font-medium"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    placeholder={isEditMode ? "Dejar en blanco para mantener actual" : "Clave de acceso"}
                />
            </div>

            {/* Status (Only show in edit mode) */}
            {isEditMode && (
                <div className="space-y-2">
                     <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider flex items-center gap-1.5">
                        <Power size={12} /> Estado del Usuario
                    </label>
                    <div className="flex gap-4">
                        <button
                            type="button"
                            onClick={() => setStatus('ACTIVE')}
                            className={`flex-1 py-2.5 rounded-xl border text-xs font-bold transition-all flex items-center justify-center gap-2 ${
                                status === 'ACTIVE' 
                                ? 'bg-emerald-50 border-emerald-200 text-emerald-600 ring-1 ring-emerald-500/20' 
                                : 'bg-white border-slate-200 text-slate-400 hover:bg-slate-50'
                            }`}
                        >
                            <Check size={14} /> Activo
                        </button>
                        <button
                            type="button"
                            onClick={() => setStatus('INACTIVE')}
                             className={`flex-1 py-2.5 rounded-xl border text-xs font-bold transition-all flex items-center justify-center gap-2 ${
                                status === 'INACTIVE' 
                                ? 'bg-slate-100 border-slate-300 text-slate-600 ring-1 ring-slate-500/20' 
                                : 'bg-white border-slate-200 text-slate-400 hover:bg-slate-50'
                            }`}
                        >
                            <Lock size={14} /> Inactivo
                        </button>
                    </div>
                </div>
            )}

           {/* Footer */}
           <div className="pt-4 flex items-center justify-end gap-3 border-t border-slate-100 mt-2">
                <button
                    type="button"
                    onClick={onClose}
                    className="px-5 py-2.5 text-slate-500 font-bold text-sm hover:bg-slate-50 rounded-xl transition-colors"
                >
                    Cancelar
                </button>
                <button
                    type="submit"
                    className="bg-indigo-600 hover:bg-indigo-700 text-white font-bold text-sm px-6 py-2.5 rounded-xl shadow-lg shadow-indigo-200 hover:shadow-xl hover:translate-y-[-1px] transition-all flex items-center gap-2 active:scale-95"
                >
                    {isEditMode ? <Save size={16}/> : <Check size={16} />} 
                    {isEditMode ? 'Guardar Cambios' : 'Crear Usuario'}
                </button>
           </div>
        </form>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { RequestCard as RequestCardType, UserRole, Status } from '../types';
import { useSisreq } from '../context/SisreqContext';
import { STATUS_BADGE_COLORS } from '../constants';
import { User as UserIcon, GripVertical, MapPin, AlertCircle, ChevronUp, ChevronDown, MessageSquare } from 'lucide-react';

interface Props {
  data: RequestCardType;
}

export const RequestCard: React.FC<Props> = ({ data }) => {
  const { currentUser, setSelectedRequestId } = useSisreq();
  const [isMinimized, setIsMinimized] = useState(data.status === Status.FINALIZADO);

  // React to status changes: Auto-minimize if moved to FINALIZADO dynamically
  useEffect(() => {
    if (data.status === Status.FINALIZADO) {
        setIsMinimized(true);
    }
  }, [data.status]);

  // LOGIC HELPERS
  const isAdmin = currentUser.role === UserRole.ADMIN;
  const isSuperAdmin = currentUser.role === UserRole.SUPERADMIN;
  const isHead = currentUser.role === UserRole.HEAD;

  // Check if user can drag this card
  const isDraggable = () => {
    // SuperAdmin can drag anything anywhere
    if (isSuperAdmin) return true;

    // Admin can only drag if status is RECIBIDO
    if (isAdmin && data.status === Status.RECIBIDO) return true;

    if (isHead && data.area === currentUser.area) {
        // Can drag from Derivacion -> Ejecucion OR Ejecucion -> Finalizado
        if (data.status === Status.DERIVACION || data.status === Status.EJECUCION) return true;
    }
    return false;
  };

  const handleDragStart = (e: React.DragEvent) => {
    e.dataTransfer.setData('requestId', data.id);
    e.dataTransfer.setData('currentStatus', data.status);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleCardClick = () => {
    setSelectedRequestId(data.id);
  };

  // Helper for border colors
  const getBorderColor = (status: Status) => {
    switch (status) {
        case Status.RECIBIDO: return 'border-blue-400';
        case Status.DERIVACION: return 'border-orange-400';
        case Status.EJECUCION: return 'border-amber-400';
        case Status.FINALIZADO: return 'border-emerald-400';
        default: return 'border-slate-200';
    }
  };

  return (
    <div 
        draggable={isDraggable()}
        onDragStart={handleDragStart}
        onClick={handleCardClick}
        className={`
            bg-white rounded-xl mb-3 relative group
            transition-all duration-300 ease-out
            shadow-sm hover:shadow-md
            border-y border-r border-slate-100
            border-l-[4px] hover:border-l-[6px]
            cursor-pointer
            ${getBorderColor(data.status)}
            ${isDraggable() ? 'active:cursor-grabbing hover:-translate-y-0.5' : ''}
            ${isMinimized ? 'py-3 px-4' : 'p-5'}
        `}
    >

      {/* Header: Status, Drag Handle, Actions */}
      <div className={`flex justify-between items-start ${isMinimized ? '' : 'mb-3'}`}>
        <div className="flex items-center gap-2">
            {isDraggable() && (
                <div onMouseDown={(e) => e.stopPropagation()}>
                    <GripVertical size={14} className="text-slate-300 hover:text-slate-500 transition-colors cursor-grab active:cursor-grabbing" />
                </div>
            )}

            <span className={`px-2.5 py-0.5 rounded-full text-[10px] font-bold tracking-wide uppercase ${STATUS_BADGE_COLORS[data.status]}`}>
                {data.status}
            </span>
        </div>

        <div className="flex items-center gap-1.5">
            {data.isReturned && (
                 <span className="flex items-center gap-1 text-[10px] bg-red-50 text-red-600 px-2 py-0.5 rounded-full font-bold ring-1 ring-red-100">
                    <AlertCircle size={10} /> <span className={isMinimized ? 'hidden' : 'inline'}>DEVUELTO</span>
                 </span>
            )}
           <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full border ${
             data.priority === 'Alta' ? 'bg-red-50 border-red-100 text-red-600' : 
             data.priority === 'Media' ? 'bg-amber-50 border-amber-100 text-amber-600' : 
             'bg-slate-50 border-slate-200 text-slate-500'
           }`}>
             {data.priority}
           </span>

           <div className="flex items-center ml-1 opacity-0 group-hover:opacity-100 transition-opacity" onClick={(e) => e.stopPropagation()}>
               <button 
                    onClick={(e) => { e.stopPropagation(); setIsMinimized(!isMinimized); }}
                    className="p-1 text-slate-400 hover:text-indigo-600 hover:bg-slate-50 rounded-md transition-all"
                    title={isMinimized ? "Expandir vista previa" : "Minimizar"}
               >
                   {isMinimized ? <ChevronDown size={14}/> : <ChevronUp size={14}/>}
               </button>
           </div>
        </div>
      </div>

      {/* Main Content Area */}
      <div className={`${isMinimized ? 'mt-1 pl-6' : 'mb-4 px-1'}`}>
        <h3 className={`font-bold text-slate-800 group-hover:text-indigo-600 transition-colors ${isMinimized ? 'text-xs truncate' : 'text-[15px] mb-2 leading-snug tracking-tight'}`}>
            {data.title}
        </h3>

        {/* Full Details - Only if NOT minimized */}
        {!isMinimized && (
            <p className="text-sm text-slate-600 leading-relaxed line-clamp-3 font-normal">
                {data.detail}
            </p>
        )}
      </div>

      {/* Footer Info */}
      {!isMinimized && (
          <div className="flex flex-col gap-2 px-1 animate-in fade-in duration-300">
             <div className="flex items-center justify-between text-xs text-slate-500 border-t border-slate-50 pt-3 mt-1">
                <div className="flex items-center gap-2">
                    <UserIcon size={12} className="text-slate-400"/>
                    <span className="truncate max-w-[100px] font-medium">{data.requester}</span>
                </div>
                <div className="flex items-center gap-2">
                    <MapPin size={12} className="text-slate-400"/>
                    <span className="truncate max-w-[100px]">{data.area}</span>
                </div>
             </div>

             {/* Modifiers: Analyst or Logs count */}
             <div className="flex items-center gap-2 mt-1">
                 {data.assignedAnalyst && (
                    <div className="flex items-center gap-1.5 text-[10px] bg-indigo-50 text-indigo-700 px-2 py-1 rounded border border-indigo-100 font-bold">
                        <div className="w-1.5 h-1.5 rounded-full bg-indigo-500"></div>
                        {data.assignedAnalyst}
                    </div>
                 )}
                 {data.logs.length > 0 && (
                     <div className="ml-auto flex items-center gap-1 text-[10px] text-slate-400 font-medium">
                         <MessageSquare size={10} /> {data.logs.length}
                     </div>
                 )}
             </div>
          </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { RequestCard } from './RequestCard';
import { Status, UserRole, Priority, Area } from '../types';
import { LayoutGrid, List, ListFilter, AlignLeft, Search, Filter, XCircle } from 'lucide-react';
import { STATUS_BADGE_COLORS } from '../constants';

export const Board: React.FC = () => {
  const { requests, currentUser, updateStatus, setSelectedRequestId } = useSisreq();
  const [dragOverColumn, setDragOverColumn] = useState<Status | null>(null);
  const [viewMode, setViewMode] = useState<'board' | 'list'>('board');

  // Filters State
  const [searchTerm, setSearchTerm] = useState('');
  const [filterArea, setFilterArea] = useState<Area | 'ALL'>('ALL');

  // Filter requests based on Role AND Search/Filter State
  const filteredRequests = requests.filter(req => {
    // 1. Role Based Access (Base Visibility)
    let hasAccess = false;
    // Admin & SuperAdmin sees everything
    if (currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.SUPERADMIN) {
        hasAccess = true;
    } 
    // Heads and Analysts see their own area (unless Recibido)
    else if (req.area === currentUser.area && req.status !== Status.RECIBIDO) {
        hasAccess = true;
    }

    if (!hasAccess) return false;

    // 2. Text Search (Title, ID, Requester)
    const matchesSearch = searchTerm === '' || 
        req.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
        req.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
        req.requester.toLowerCase().includes(searchTerm.toLowerCase());

    // 3. Area Filter (For Admins/SuperAdmins who see all areas)
    const matchesArea = filterArea === 'ALL' || req.area === filterArea;

    return matchesSearch && matchesArea;
  });

  const getRequestsByStatus = (status: Status) => {
    return filteredRequests.filter(req => req.status === status);
  };

  // --- Drag & Drop Logic (Only active in Board View) ---
  const handleDragOver = (e: React.DragEvent, status: Status) => {
    e.preventDefault();
    if (dragOverColumn !== status) {
        setDragOverColumn(status);
    }
  };

  const handleDragLeave = () => {
    setDragOverColumn(null);
  };

  const handleDrop = (e: React.DragEvent, targetStatus: Status) => {
    e.preventDefault();
    setDragOverColumn(null);
    const requestId = e.dataTransfer.getData('requestId');
    const currentStatus = e.dataTransfer.getData('currentStatus') as Status;

    // Strict Workflow Rules for Drag & Drop
    let isValidMove = false;

    // SuperAdmin: unrestricted movement
    if (currentUser.role === UserRole.SUPERADMIN) {
        isValidMove = true;
    } else {
        // Admin: Recibido -> Derivacion
        if (currentUser.role === UserRole.ADMIN) {
            if (currentStatus === Status.RECIBIDO && targetStatus === Status.DERIVACION) isValidMove = true;
        }

        // Head: Derivacion -> Ejecucion -> Finalizado
        if (currentUser.role === UserRole.HEAD) {
            // Find the request to check area owner
            const req = requests.find(r => r.id === requestId);
            if (req && req.area === currentUser.area) {
                if (currentStatus === Status.DERIVACION && targetStatus === Status.EJECUCION) isValidMove = true;
                if (currentStatus === Status.EJECUCION && targetStatus === Status.FINALIZADO) isValidMove = true;
            }
        }
    }

    if (isValidMove) {
        updateStatus(requestId, targetStatus);
    }
  };

  const columns = [
    { title: 'Recibido', status: Status.RECIBIDO, color: 'border-blue-400 text-blue-700' },
    { title: 'En Derivación', status: Status.DERIVACION, color: 'border-orange-400 text-orange-700' },
    { title: 'En Ejecución', status: Status.EJECUCION, color: 'border-amber-400 text-amber-700' },
    { title: 'Finalizado', status: Status.FINALIZADO, color: 'border-emerald-400 text-emerald-700' }
  ];

  // Logic to show/hide filter controls
  const showAreaFilter = currentUser.role === UserRole.SUPERADMIN || currentUser.role === UserRole.ADMIN;

  return (
    <div className="flex flex-col h-full overflow-hidden">

      {/* Toolbar */}
      <div className="px-6 py-4 flex flex-col md:flex-row md:items-center justify-between gap-4 shrink-0 bg-white/50 backdrop-blur-sm border-b border-slate-200/50">

          {/* Title & Stats */}
          <div className="flex items-center gap-3">
             <h2 className="text-lg font-bold text-slate-800">
                Gestión de Requerimientos
             </h2>
             <span className="bg-slate-200 text-slate-600 px-2 py-0.5 rounded-full text-xs font-bold">
                {filteredRequests.length}
                {searchTerm || filterArea !== 'ALL' ? <span className="text-slate-400 font-normal"> / {requests.length}</span> : ''}
             </span>
          </div>

          {/* Controls Group */}
          <div className="flex items-center gap-3">

             {/* Search Input */}
             <div className="relative group">
                <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-indigo-500 transition-colors"/>
                <input 
                    type="text"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    placeholder="Buscar..."
                    className="pl-9 pr-3 py-1.5 text-xs font-medium bg-white border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 w-40 md:w-56 transition-all"
                />
                {searchTerm && (
                    <button 
                        onClick={() => setSearchTerm('')}
                        className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-300 hover:text-slate-500"
                    >
                        <XCircle size={12} className="fill-slate-100"/>
                    </button>
                )}
             </div>

             {/* Area Filter (Only for Admin/SuperAdmin) */}
             {showAreaFilter && (
                 <div className="relative">
                    <div className="absolute left-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">
                        <Filter size={12} />
                    </div>
                    <select
                        value={filterArea}
                        onChange={(e) => setFilterArea(e.target.value as Area | 'ALL')}
                        className={`pl-8 pr-8 py-1.5 text-xs font-bold border rounded-lg appearance-none cursor-pointer focus:outline-none focus:ring-2 focus:ring-indigo-100 transition-all ${
                            filterArea !== 'ALL' 
                            ? 'bg-indigo-50 border-indigo-200 text-indigo-700' 
                            : 'bg-white border-slate-200 text-slate-600 hover:border-slate-300'
                        }`}
                    >
                        <option value="ALL">Todas las Áreas</option>
                        {Object.values(Area).map(a => (
                            <option key={a} value={a}>{a}</option>
                        ))}
                    </select>
                 </div>
             )}

             <div className="w-px h-6 bg-slate-200 mx-1 hidden md:block"></div>

             {/* View Mode Switcher */}
             <div className="bg-white p-1 rounded-lg border border-slate-200 shadow-sm flex items-center gap-1">
                <button 
                    onClick={() => setViewMode('board')}
                    className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all ${
                        viewMode === 'board' 
                        ? 'bg-indigo-50 text-indigo-600 shadow-sm ring-1 ring-indigo-100' 
                        : 'text-slate-500 hover:bg-slate-50 hover:text-slate-700'
                    }`}
                >
                    <LayoutGrid size={14} /> <span className="hidden sm:inline">Tablero</span>
                </button>
                <div className="w-px h-4 bg-slate-200 mx-1"></div>
                <button 
                    onClick={() => setViewMode('list')}
                    className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all ${
                        viewMode === 'list' 
                        ? 'bg-indigo-50 text-indigo-600 shadow-sm ring-1 ring-indigo-100' 
                        : 'text-slate-500 hover:bg-slate-50 hover:text-slate-700'
                    }`}
                >
                    <List size={14} /> <span className="hidden sm:inline">Lista</span>
                </button>
             </div>
          </div>
      </div>

      {/* --- BOARD VIEW (Horizontal Scroll) --- */}
      {viewMode === 'board' && (
        <div className="flex-1 overflow-x-auto overflow-y-hidden">
            <div className="h-full flex px-6 pb-6 gap-6 min-w-[1000px] pt-4">
                {columns.map((col) => {
                    const items = getRequestsByStatus(col.status);
                    const isOver = dragOverColumn === col.status;

                    return (
                        <div 
                            key={col.status} 
                            className={`flex-1 flex flex-col min-w-[280px] max-w-[350px] transition-colors rounded-xl ${isOver ? 'bg-indigo-50/50 ring-2 ring-indigo-200 ring-inset' : ''}`}
                            onDragOver={(e) => handleDragOver(e, col.status)}
                            onDragLeave={handleDragLeave}
                            onDrop={(e) => handleDrop(e, col.status)}
                        >
                            <div className={`flex items-center justify-between mb-4 pb-2 border-b-2 mx-1 ${col.color.split(' ')[0]}`}>
                                <h2 className={`font-bold uppercase text-xs tracking-wider ${col.color.split(' ')[1]}`}>{col.title}</h2>
                                <span className="bg-white border border-slate-200 text-slate-600 px-2 py-0.5 rounded-full text-[10px] font-bold shadow-sm">
                                    {items.length}
                                </span>
                            </div>

                            <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar pb-10 px-1">
                                {items.length === 0 ? (
                                    <div className={`h-32 border-2 border-dashed rounded-xl flex items-center justify-center text-slate-400 text-sm italic transition-colors ${isOver ? 'border-indigo-300 bg-indigo-50' : 'border-slate-200 bg-slate-50/50'}`}>
                                        {isOver ? 'Soltar aquí' : 'Sin tarjetas'}
                                    </div>
                                ) : (
                                    items.map(req => (
                                        <RequestCard key={req.id} data={req} />
                                    ))
                                )}
                            </div>
                        </div>
                    )
                })}
            </div>
        </div>
      )}

      {/* --- LIST VIEW (Vertical Scroll) --- */}
      {viewMode === 'list' && (
          <div className="flex-1 overflow-hidden px-6 pb-6 pt-4">
              <div className="bg-white h-full rounded-2xl border border-slate-200 shadow-sm flex flex-col overflow-hidden">

                {/* Table Header - Updated Layout */}
                <div className="grid grid-cols-[60px_90px_120px_1.5fr_2fr_1fr_1fr_100px] gap-4 px-6 py-4 bg-slate-50 border-b border-slate-200 text-[11px] font-bold text-slate-400 uppercase tracking-wider shrink-0 sticky top-0 z-10">
                    <div>ID</div>
                    <div>Prioridad</div>
                    <div>Estado</div>
                    <div>Título</div>
                    <div className="flex items-center gap-1"><AlignLeft size={10}/> Detalle</div>
                    <div>Solicitante</div>
                    <div>Área Destino</div>
                    <div className="text-right">Fecha</div>
                </div>

                {/* Table Body - Updated Layout */}
                <div className="overflow-y-auto custom-scrollbar flex-1 bg-white">
                    {filteredRequests.length > 0 ? (
                        <div className="divide-y divide-slate-100">
                            {filteredRequests.map(req => (
                                <div 
                                    key={req.id}
                                    onClick={() => setSelectedRequestId(req.id)}
                                    className="grid grid-cols-[60px_90px_120px_1.5fr_2fr_1fr_1fr_100px] gap-4 px-6 py-4 hover:bg-slate-50/80 cursor-pointer transition-colors group items-center text-sm"
                                >
                                    {/* ID */}
                                    <div className="font-mono text-xs text-slate-400 group-hover:text-indigo-500 font-bold">
                                        #{req.id.split('-')[1]}
                                    </div>

                                    {/* Priority (Moved Left) */}
                                    <div>
                                        <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full border inline-flex items-center justify-center min-w-[60px] ${
                                            req.priority === Priority.HIGH ? 'bg-red-50 border-red-100 text-red-600' : 
                                            req.priority === Priority.MEDIUM ? 'bg-amber-50 border-amber-100 text-amber-600' : 
                                            'bg-slate-50 border-slate-200 text-slate-500'
                                        }`}>
                                            {req.priority}
                                        </span>
                                    </div>

                                    {/* Status (Moved Left) */}
                                    <div>
                                         <span className={`inline-block px-2 py-0.5 rounded-full text-[10px] font-bold tracking-wide uppercase shadow-sm ${STATUS_BADGE_COLORS[req.status]}`}>
                                            {req.status}
                                        </span>
                                    </div>

                                    {/* Title */}
                                    <div className="font-bold text-slate-700 truncate pr-2 group-hover:text-indigo-700 transition-colors">
                                        {req.title}
                                    </div>

                                    {/* Detail */}
                                    <div className="text-xs text-slate-500 truncate pr-4" title={req.detail}>
                                        {req.detail}
                                    </div>

                                    {/* Requester */}
                                    <div className="flex items-center gap-2 text-xs text-slate-600 truncate">
                                        <div className="w-5 h-5 rounded-full bg-slate-100 flex items-center justify-center shrink-0">
                                            {req.requester.charAt(0)}
                                        </div>
                                        <span className="truncate">{req.requester}</span>
                                    </div>

                                    {/* Area */}
                                    <div className="text-xs text-slate-600 truncate font-medium bg-slate-100/50 px-2 py-1 rounded w-fit border border-slate-100">
                                        {req.area}
                                    </div>

                                    {/* Date */}
                                    <div className="flex items-center justify-end gap-2 text-xs text-slate-400 font-mono">
                                        {new Date(req.createdAt).toLocaleDateString()}
                                    </div>
                                </div>
                            ))}
                        </div>
                    ) : (
                        <div className="flex flex-col items-center justify-center h-64 text-slate-400">
                            <ListFilter size={48} className="mb-4 text-slate-200" />
                            <p className="font-medium">No se encontraron requerimientos</p>
                            {(searchTerm || filterArea !== 'ALL') && (
                                <button 
                                    onClick={() => {setSearchTerm(''); setFilterArea('ALL');}}
                                    className="text-xs text-indigo-500 font-bold mt-2 hover:underline"
                                >
                                    Limpiar filtros
                                </button>
                            )}
                        </div>
                    )}
                </div>
              </div>
          </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { UserRole } from '../types';
import { LayoutDashboard, Plus, Briefcase, Layers, LogOut, Shield } from 'lucide-react';
