                            <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar pb-10 px-1">
                                {items.length === 0 ? (
                                    <div className={`h-32 border-2 border-dashed rounded-xl flex items-center justify-center text-slate-400 text-sm italic transition-colors ${isOver ? 'border-indigo-300 bg-indigo-50' : 'border-slate-200 bg-slate-50/50'}`}>
                                        {isOver ? 'Soltar aquí' : 'Sin tarjetas'}
                                    </div>
                                ) : (
                                    items.map(req => (
                                        <RequestCard key={req.id} data={req} />
                                    ))
                                )}
                            </div>
                        </div>
                    )
                })}
            </div>
        </div>
      )}

      {/* --- LIST VIEW (Vertical Scroll) --- */}
      {viewMode === 'list' && (
          <div className="flex-1 overflow-hidden px-2 md:px-6 pb-6 pt-2 md:pt-4">
              <div className="bg-white h-full rounded-2xl border border-slate-200 shadow-sm flex flex-col overflow-hidden">

                {/* Table Header - Updated Layout for Responsive */}
                <div className="grid grid-cols-[1fr_auto] md:grid-cols-[60px_90px_120px_1.5fr_2fr_1fr_1fr_100px] gap-2 md:gap-4 px-4 md:px-6 py-4 bg-slate-50 border-b border-slate-200 text-[11px] font-bold text-slate-400 uppercase tracking-wider shrink-0 sticky top-0 z-10">
                    <div className="hidden md:block">ID</div>
                    <div className="hidden md:block">Prioridad</div>
                    <div className="hidden md:block">Estado</div>
                    <div>Título / Info</div>
                    <div className="hidden md:flex items-center gap-1"><AlignLeft size={10}/> Detalle</div>
                    <div className="hidden md:block">Solicitante</div>
                    <div className="hidden md:block">Área Destino</div>
                    <div className="text-right hidden md:block">Fecha</div>
                    <div className="text-right md:hidden">Estado</div>
                </div>

                {/* Table Body - Updated Layout */}
                <div className="overflow-y-auto custom-scrollbar flex-1 bg-white">
                    {filteredRequests.length > 0 ? (
                        <div className="divide-y divide-slate-100">
                            {filteredRequests.map(req => (
                                <div 
                                    key={req.id}
                                    onClick={() => setSelectedRequestId(req.id)}
