  const { users } = useSisreq();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedUser, setSelectedUser] = useState<User | null>(null);

  // Dashboard Stats
  const stats = useMemo(() => {
    const total = users.length;
    const active = users.filter(u => u.status === 'ACTIVE' || !u.status).length;
    const inactive = total - active;
    const roles = {
        [UserRole.SUPERADMIN]: users.filter(u => u.role === UserRole.SUPERADMIN).length,
        [UserRole.ADMIN]: users.filter(u => u.role === UserRole.ADMIN).length,
        [UserRole.HEAD]: users.filter(u => u.role === UserRole.HEAD).length,
        [UserRole.ANALYST]: users.filter(u => u.role === UserRole.ANALYST).length,
    };
    return { total, active, inactive, roles };
  }, [users]);

  const handleEditClick = (user: User) => {
    setSelectedUser(user);
    setIsModalOpen(true);
  };

  const handleNewUserClick = () => {
    setSelectedUser(null);
    setIsModalOpen(true);
  };

  return (
    <div className="flex-1 overflow-y-auto custom-scrollbar p-4 md:p-6 space-y-6 relative">
        {/* Header & Stats */}
        <div className="flex flex-col md:flex-row gap-6">

            {/* Stats Cards */}
            <div className="flex-1 grid grid-cols-1 md:grid-cols-3 gap-4">
                <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex items-center gap-4">
                    <div className="p-3 bg-indigo-50 text-indigo-600 rounded-lg">
                        <UserIcon size={20} />
                    </div>
                    <div>
                        <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Total Usuarios</p>
                        <p className="text-2xl font-black text-slate-800">{stats.total}</p>
                    </div>
                </div>
                <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex items-center gap-4">
                    <div className="p-3 bg-emerald-50 text-emerald-600 rounded-lg">
                        <Activity size={20} />
                    </div>
                    <div>
                        <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Activos</p>
                        <p className="text-2xl font-black text-slate-800">{stats.active}</p>
                    </div>
                </div>
                <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex flex-col justify-center gap-2">
                    <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Distribución</p>
                    <div className="flex gap-1 h-2 w-full rounded-full overflow-hidden bg-slate-100">
                        <div className="bg-slate-800 h-full" style={{ width: `${(stats.roles.SUPERADMIN / stats.total) * 100}%` }} title="SuperAdmin"></div>
                        <div className="bg-red-500 h-full" style={{ width: `${(stats.roles.ADMIN / stats.total) * 100}%` }} title="Admin"></div>
                        <div className="bg-indigo-500 h-full" style={{ width: `${(stats.roles.HEAD / stats.total) * 100}%` }} title="Jefaturas"></div>
                        <div className="bg-slate-400 h-full" style={{ width: `${(stats.roles.ANALYST / stats.total) * 100}%` }} title="Analistas"></div>
                    </div>
                    <div className="flex gap-3 text-[10px] font-medium text-slate-500">
                        <span className="flex items-center gap-1"><div className="w-2 h-2 rounded-full bg-indigo-500"></div> Jefes</span>
                        <span className="flex items-center gap-1"><div className="w-2 h-2 rounded-full bg-slate-400"></div> Analistas</span>
                    </div>
                </div>
            </div>

            {/* Create Button (Placed to the right) */}
            <div className="flex items-start">
                <button 
                    onClick={handleNewUserClick}
                    className="w-full md:w-auto bg-slate-800 hover:bg-slate-900 text-white px-5 py-4 rounded-xl shadow-lg shadow-slate-300 flex items-center justify-center gap-2 text-sm font-bold transition-all active:scale-95 whitespace-nowrap"
                >
                    <UserPlus size={18}/> Nuevo Usuario
                </button>
            </div>
        </div>

        <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
             {/* Table Header - Responsive Grid */}
             <div className="grid grid-cols-[1fr_auto_80px] md:grid-cols-[2.5fr_1.5fr_1.5fr_1fr_1fr_100px_80px] gap-2 md:gap-4 px-4 md:px-6 py-4 bg-slate-50 border-b border-slate-200 text-[11px] font-bold text-slate-400 uppercase tracking-wider sticky top-0 z-10">
                <div>Usuario</div>
                <div className="hidden md:block">Rol</div>
                <div className="hidden md:block">Área</div>
                <div className="hidden md:block">Estado</div>
                <div className="hidden md:block">Fecha Ingreso</div>
                <div className="hidden md:block">Acceso</div>
                <div className="text-right">Acción</div>
             </div>

             <div className="divide-y divide-slate-100">
                {users.map(user => (
                    <div key={user.id} className="grid grid-cols-[1fr_auto_80px] md:grid-cols-[2.5fr_1.5fr_1.5fr_1fr_1fr_100px_80px] gap-2 md:gap-4 px-4 md:px-6 py-4 items-center hover:bg-slate-50/50 transition-colors group">

                        {/* Name & Email */}
                        <div>
                            <div className="flex items-center gap-3">
                                <div className={`w-9 h-9 rounded-full flex items-center justify-center font-bold text-xs shadow-sm border border-white shrink-0 ${
                                    user.role === UserRole.SUPERADMIN ? 'bg-slate-800 text-white' :
                                    user.role === UserRole.ADMIN ? 'bg-red-100 text-red-600' :
                                    user.role === UserRole.HEAD ? 'bg-indigo-100 text-indigo-600' :
                                    'bg-slate-100 text-slate-500'
                                }`}>
                                    {user.name.substring(0,2).toUpperCase()}
                                </div>
                                <div className="min-w-0">
                                    <div className="font-bold text-slate-700 text-sm truncate">{user.name}</div>
                                    <div className="text-xs text-slate-400 font-medium truncate hidden md:block">{user.email || 'Sin correo registrado'}</div>
                                    <div className="md:hidden text-[10px] text-slate-500 font-medium truncate flex gap-1 mt-0.5">
                                        <span>{user.role}</span>
                                        {user.area && <span className="opacity-50">| {user.area}</span>}
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* Role (Desktop) */}
                        <div className="hidden md:block">
                            <span className={`px-2.5 py-1 rounded-full text-[10px] font-bold border ${
                                user.role === UserRole.SUPERADMIN ? 'bg-slate-800 text-white border-slate-900' :
                                user.role === UserRole.ADMIN ? 'bg-red-50 text-red-600 border-red-100' :
                                user.role === UserRole.HEAD ? 'bg-indigo-50 text-indigo-600 border-indigo-100' :
                                'bg-slate-100 text-slate-500 border-slate-200'
                            }`}>
                                {user.role}
                            </span>
                        </div>

                        {/* Area */}
                        <div className="hidden md:block">
                            <span className="text-xs text-slate-600 font-medium">{user.area || '-'}</span>
                        </div>

                        {/* Status (Mobile & Desktop) */}
                        <div className="flex justify-end md:justify-start">
                            <div className="flex items-center gap-2">
                                <div className={`w-2 h-2 rounded-full ${(!user.status || user.status === 'ACTIVE') ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.4)]' : 'bg-slate-300'}`}></div>
                                <span className={`text-xs font-bold hidden md:inline ${(!user.status || user.status === 'ACTIVE') ? 'text-slate-700' : 'text-slate-400'}`}>
                                    {(!user.status || user.status === 'ACTIVE') ? 'Activo' : 'Inactivo'}
                                </span>
                            </div>
                        </div>

                        {/* Joined Date */}
                        <div className="hidden md:flex items-center gap-2 text-xs text-slate-500">
                            <Calendar size={12} className="text-slate-400"/>
                            {user.joinedAt ? new Date(user.joinedAt).toLocaleDateString() : '-'}
                        </div>

                        {/* Password / Security */}
                        <div className="hidden md:block">
                            <span className="text-slate-400 text-xs font-mono tracking-widest">••••••</span>
                        </div>

                        {/* Actions */}
                        <div className="flex justify-end gap-2">
                            <button onClick={() => handleEditClick(user)} className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors border border-transparent hover:border-indigo-100" title="Editar Usuario">
                                <Edit2 size={16}/>
                            </button>
                        </div>

                    </div>
                ))}
             </div>
        </div>

        <NewUserModal 
            isOpen={isModalOpen} 
            onClose={() => setIsModalOpen(false)} 
            userToEdit={selectedUser}
        />
    </div>
  );
};

import React, { useState } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { RequestCard } from './RequestCard';
import { Status, UserRole, Priority, Area } from '../types';
import { LayoutGrid, List, ListFilter, AlignLeft, Search, Filter, XCircle, Inbox, GitPullRequest, PlayCircle, CheckCircle2 } from 'lucide-react';
import { STATUS_BADGE_COLORS } from '../constants';

export const Board: React.FC = () => {
  const { requests, currentUser, updateStatus, setSelectedRequestId } = useSisreq();
  const [dragOverColumn, setDragOverColumn] = useState<Status | null>(null);
  const [viewMode, setViewMode] = useState<'board' | 'list'>('board');

  // Filters State
  const [searchTerm, setSearchTerm] = useState('');
  const [filterArea, setFilterArea] = useState<Area | 'ALL'>('ALL');

  // Filter requests based on Role AND Search/Filter State
  const filteredRequests = requests.filter(req => {
    // 1. Role Based Access (Base Visibility)
    let hasAccess = false;
    // Admin & SuperAdmin sees everything
    if (currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.SUPERADMIN) {
        hasAccess = true;
    } 
    // Heads and Analysts see their own area (unless Recibido)
    else if (req.area === currentUser.area && req.status !== Status.RECIBIDO) {
        hasAccess = true;
    }

    if (!hasAccess) return false;

    // 2. Text Search (Title, ID, Requester)
    const matchesSearch = searchTerm === '' || 
        req.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
        req.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
        req.requester.toLowerCase().includes(searchTerm.toLowerCase());

    // 3. Area Filter (For Admins/SuperAdmins who see all areas)
    const matchesArea = filterArea === 'ALL' || req.area === filterArea;

    return matchesSearch && matchesArea;
  });

  const getRequestsByStatus = (status: Status) => {
    return filteredRequests.filter(req => req.status === status);
  };

  // --- Drag & Drop Logic (Only active in Board View) ---
  const handleDragOver = (e: React.DragEvent, status: Status) => {
    e.preventDefault();
    if (dragOverColumn !== status) {
        setDragOverColumn(status);
    }
  };

  const handleDragLeave = () => {
    setDragOverColumn(null);
  };

  const handleDrop = (e: React.DragEvent, targetStatus: Status) => {
    e.preventDefault();
    setDragOverColumn(null);
    const requestId = e.dataTransfer.getData('requestId');
    const currentStatus = e.dataTransfer.getData('currentStatus') as Status;

    // Strict Workflow Rules for Drag & Drop
    let isValidMove = false;

    // SuperAdmin: unrestricted movement
    if (currentUser.role === UserRole.SUPERADMIN) {
        isValidMove = true;
    } else {
        // Admin: Recibido -> Derivacion
        if (currentUser.role === UserRole.ADMIN) {
            if (currentStatus === Status.RECIBIDO && targetStatus === Status.DERIVACION) isValidMove = true;
        }

        // Head: Derivacion -> Ejecucion -> Finalizado
        if (currentUser.role === UserRole.HEAD) {
            // Find the request to check area owner
            const req = requests.find(r => r.id === requestId);
            if (req && req.area === currentUser.area) {
                if (currentStatus === Status.DERIVACION && targetStatus === Status.EJECUCION) isValidMove = true;
                if (currentStatus === Status.EJECUCION && targetStatus === Status.FINALIZADO) isValidMove = true;
            }
        }
    }

    if (isValidMove) {
        updateStatus(requestId, targetStatus);
    }
  };

  // Column Visual Configuration
  const COLUMNS_CONFIG = [
    { 
        title: 'Bandeja de Entrada', 
        status: Status.RECIBIDO, 
        icon: <Inbox size={18} />,
        headerColor: 'text-blue-700 bg-blue-50/80 border-blue-100',
        bodyTint: 'bg-slate-50/50', // Subtle tint for the column body
        borderColor: 'border-blue-200'
    },
    { 
        title: 'Derivación', 
        status: Status.DERIVACION, 
        icon: <GitPullRequest size={18} />,
        headerColor: 'text-orange-700 bg-orange-50/80 border-orange-100',
        bodyTint: 'bg-orange-50/10',
        borderColor: 'border-orange-200'
    },
    { 
        title: 'En Ejecución', 
        status: Status.EJECUCION, 
        icon: <PlayCircle size={18} />,
        headerColor: 'text-amber-700 bg-amber-50/80 border-amber-100',
        bodyTint: 'bg-amber-50/10',
        borderColor: 'border-amber-200'
    },
    { 
        title: 'Finalizado', 
        status: Status.FINALIZADO, 
        icon: <CheckCircle2 size={18} />,
        headerColor: 'text-emerald-700 bg-emerald-50/80 border-emerald-100',
        bodyTint: 'bg-emerald-50/10',
        borderColor: 'border-emerald-200'
    }
  ];

  // Logic to show/hide filter controls
  const showAreaFilter = currentUser.role === UserRole.SUPERADMIN || currentUser.role === UserRole.ADMIN;

  return (
    <div className="flex flex-col h-full overflow-hidden">

      {/* Toolbar */}
      <div className="px-4 md:px-6 py-4 flex flex-col md:flex-row md:items-center justify-between gap-4 shrink-0 bg-white/50 backdrop-blur-sm border-b border-slate-200/50 z-20">

          {/* Title & Stats */}
          <div className="flex items-center justify-between md:justify-start gap-3">
             <div className="flex items-center gap-3">
                 <h2 className="text-lg font-bold text-slate-800">
                    Gestión
                 </h2>
                 <span className="bg-white border border-slate-200 text-slate-600 px-2.5 py-0.5 rounded-full text-xs font-bold shadow-sm">
                    {filteredRequests.length}
                    {searchTerm || filterArea !== 'ALL' ? <span className="text-slate-400 font-normal"> / {requests.length}</span> : ''}
                 </span>
             </div>

             {/* Mobile View Toggle */}
             <div className="md:hidden bg-white p-1 rounded-lg border border-slate-200 shadow-sm flex items-center gap-1">
                <button onClick={() => setViewMode('board')} className={`p-1.5 rounded ${viewMode === 'board' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400'}`}><LayoutGrid size={16}/></button>
                <button onClick={() => setViewMode('list')} className={`p-1.5 rounded ${viewMode === 'list' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400'}`}><List size={16}/></button>
             </div>
          </div>

          {/* Controls Group */}
          <div className="flex flex-col md:flex-row items-stretch md:items-center gap-3">

             {/* Search Input */}
             <div className="relative group w-full md:w-auto">
                <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-indigo-500 transition-colors"/>
                <input 
                    type="text"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    placeholder="Buscar..."
                    className="w-full md:w-56 pl-9 pr-3 py-2 md:py-1.5 text-sm md:text-xs font-medium bg-white border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 transition-all shadow-sm"
                />
                {searchTerm && (
                    <button 
                        onClick={() => setSearchTerm('')}
                        className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-300 hover:text-slate-500"
                    >
                        <XCircle size={12} className="fill-slate-100"/>
                    </button>
                )}
             </div>

             {/* Area Filter (Only for Admin/SuperAdmin) */}
             {showAreaFilter && (
                 <div className="relative w-full md:w-auto">
                    <div className="absolute left-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">
                        <Filter size={12} />
                    </div>
                    <select
                        value={filterArea}
                        onChange={(e) => setFilterArea(e.target.value as Area | 'ALL')}
                        className={`w-full md:w-auto pl-8 pr-8 py-2 md:py-1.5 text-sm md:text-xs font-bold border rounded-lg appearance-none cursor-pointer focus:outline-none focus:ring-2 focus:ring-indigo-100 transition-all shadow-sm ${
                            filterArea !== 'ALL' 
                            ? 'bg-indigo-50 border-indigo-200 text-indigo-700' 
                            : 'bg-white border-slate-200 text-slate-600 hover:border-slate-300'
                        }`}
                    >
                        <option value="ALL">Todas las Áreas</option>
                        {Object.values(Area).map(a => (
                            <option key={a} value={a}>{a}</option>
                        ))}
                    </select>
                 </div>
             )}

             <div className="w-px h-6 bg-slate-200 mx-1 hidden md:block"></div>

             {/* Desktop View Switcher */}
             <div className="hidden md:flex bg-white p-1 rounded-lg border border-slate-200 shadow-sm items-center gap-1">
                <button 
                    onClick={() => setViewMode('board')}
                    className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all ${
                        viewMode === 'board' 
                        ? 'bg-indigo-50 text-indigo-600 shadow-sm ring-1 ring-indigo-100' 
                        : 'text-slate-500 hover:bg-slate-50 hover:text-slate-700'
                    }`}
                >
                    <LayoutGrid size={14} /> <span>Tablero</span>
                </button>
                <div className="w-px h-4 bg-slate-200 mx-1"></div>
                <button 
                    onClick={() => setViewMode('list')}
                    className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all ${
                        viewMode === 'list' 
                        ? 'bg-indigo-50 text-indigo-600 shadow-sm ring-1 ring-indigo-100' 
                        : 'text-slate-500 hover:bg-slate-50 hover:text-slate-700'
                    }`}
                >
                    <List size={14} /> <span>Lista</span>
                </button>
             </div>
          </div>
      </div>

      {/* --- BOARD VIEW (Horizontal Scroll) --- */}
      {viewMode === 'board' && (
        <div className="flex-1 overflow-x-auto overflow-y-hidden">
            <div className="h-full flex px-4 md:px-6 pb-6 gap-6 min-w-[320px] md:min-w-[1200px] pt-4 snap-x snap-mandatory md:snap-none">
                {COLUMNS_CONFIG.map((col) => {
                    const items = getRequestsByStatus(col.status);
                    const isOver = dragOverColumn === col.status;

                    return (
                        <div 
                            key={col.status} 
                            className={`flex-1 flex flex-col min-w-[280px] max-w-[350px] transition-all duration-300 rounded-2xl snap-center border overflow-hidden
                                ${isOver ? 'bg-indigo-50 ring-2 ring-indigo-300 border-indigo-300 shadow-lg scale-[1.01]' : `${col.bodyTint} border-transparent`}
                            `}
                            onDragOver={(e) => handleDragOver(e, col.status)}
                            onDragLeave={handleDragLeave}
                            onDrop={(e) => handleDrop(e, col.status)}
                        >
                            {/* Column Header */}
                            <div className={`flex items-center justify-between p-3 mx-2 mt-2 rounded-xl border mb-2 shadow-sm shrink-0 ${col.headerColor}`}>
                                <div className="flex items-center gap-2 font-bold text-sm tracking-tight">
                                    {col.icon}
                                    {col.title}
                                </div>
                                <span className="bg-white/80 backdrop-blur-sm px-2 py-0.5 rounded-md text-[10px] font-black min-w-[20px] text-center">
                                    {items.length}
                                </span>
                            </div>

                            {/* Column Body */}
                            <div className="flex-1 overflow-y-auto px-2 pb-4 custom-scrollbar">
                                {items.length === 0 ? (
                                    <div className={`h-32 border-2 border-dashed rounded-xl flex flex-col gap-2 items-center justify-center text-slate-400 text-sm transition-colors mt-2 mx-1 ${isOver ? 'border-indigo-400 bg-indigo-100/50' : 'border-slate-200/60'}`}>
                                        <Inbox size={24} className="opacity-20"/>
                                        <span className="text-xs font-medium opacity-60 italic">{isOver ? 'Soltar aquí' : 'Sin tarjetas'}</span>
                                    </div>
                                ) : (
                                    items.map(req => (
                                        <RequestCard key={req.id} data={req} />
                                    ))
                                )}
                            </div>
                        </div>
                    )
                })}
            </div>
        </div>
      )}

      {/* --- LIST VIEW (Vertical Scroll) --- */}
      {viewMode === 'list' && (
          <div className="flex-1 overflow-hidden px-2 md:px-6 pb-6 pt-2 md:pt-4">
              <div className="h-full flex flex-col">

                {/* Table Header - Clean floating header */}
                <div className="grid grid-cols-[1fr_auto] md:grid-cols-[60px_90px_120px_1.5fr_2fr_1fr_1fr_100px] gap-2 md:gap-4 px-6 py-3 mb-2 rounded-xl bg-slate-100 border border-slate-200 text-[11px] font-bold text-slate-500 uppercase tracking-wider shrink-0 sticky top-0 z-10 mx-1">
                    <div className="hidden md:block">ID</div>
                    <div className="hidden md:block">Prioridad</div>
                    <div className="hidden md:block">Estado</div>
                    <div>Título / Info</div>
                    <div className="hidden md:flex items-center gap-1"><AlignLeft size={10}/> Detalle</div>
                    <div className="hidden md:block">Solicitante</div>
                    <div className="hidden md:block">Área Destino</div>
                    <div className="text-right hidden md:block">Fecha</div>
                    <div className="text-right md:hidden">Estado</div>
                </div>

                {/* Table Body - Floating Rows */}
                <div className="overflow-y-auto custom-scrollbar flex-1 pb-4 px-1">
                    {filteredRequests.length > 0 ? (
                        <div className="space-y-2">
                            {filteredRequests.map(req => (
                                <div 
                                    key={req.id}
                                    onClick={() => setSelectedRequestId(req.id)}
                                    className="grid grid-cols-[1fr_auto] md:grid-cols-[60px_90px_120px_1.5fr_2fr_1fr_1fr_100px] gap-2 md:gap-4 px-6 py-4 bg-white hover:bg-indigo-50/30 rounded-xl border border-slate-100 hover:border-indigo-200 shadow-sm hover:shadow-md cursor-pointer transition-all duration-200 group items-center text-sm relative overflow-hidden"
                                >
                                    {/* Accent Bar on hover */}
                                    <div className="absolute left-0 top-0 bottom-0 w-1 bg-indigo-500 opacity-0 group-hover:opacity-100 transition-opacity"></div>

                                    {/* ID */}
                                    <div className="font-mono text-xs text-slate-400 group-hover:text-indigo-600 font-bold hidden md:block">
                                        #{req.id.split('-')[1]}
                                    </div>

                                    {/* Priority */}
                                    <div className="hidden md:block">
                                        <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full border inline-flex items-center justify-center min-w-[60px] ${
                                            req.priority === Priority.HIGH ? 'bg-red-50 border-red-100 text-red-600' : 
                                            req.priority === Priority.MEDIUM ? 'bg-amber-50 border-amber-100 text-amber-600' : 
                                            'bg-slate-50 border-slate-200 text-slate-500'
                                        }`}>
                                            {req.priority}
                                        </span>
                                    </div>

                                    {/* Status (Desktop) */}
                                    <div className="hidden md:block">
                                         <span className={`inline-block px-2 py-0.5 rounded-md text-[10px] font-bold tracking-wide uppercase shadow-sm ${STATUS_BADGE_COLORS[req.status]}`}>
                                            {req.status}
                                        </span>
                                    </div>

                                    {/* Title & Mobile Info Wrapper */}
                                    <div className="min-w-0">
                                        <div className="flex items-center gap-2 md:hidden mb-1">
                                            <span className="font-mono text-[10px] text-slate-400">#{req.id.split('-')[1]}</span>
