                            {(searchTerm || filterArea !== 'ALL') && (
                                <button 
                                    onClick={() => {setSearchTerm(''); setFilterArea('ALL');}}
                                    className="text-xs text-indigo-500 font-bold mt-2 hover:underline"
                                >
                                    Limpiar filtros
                                </button>
                            )}
                        </div>
                    )}
                </div>
              </div>
          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { RequestCard as RequestCardType, UserRole, Status } from '../types';
import { useSisreq } from '../context/SisreqContext';
import { STATUS_BADGE_COLORS } from '../constants';
import { User as UserIcon, GripVertical, MapPin, AlertCircle, ChevronUp, ChevronDown, MessageSquare, Clock } from 'lucide-react';

interface Props {
  data: RequestCardType;
}

export const RequestCard: React.FC<Props> = ({ data }) => {
  const { currentUser, setSelectedRequestId } = useSisreq();
  const [isMinimized, setIsMinimized] = useState(data.status === Status.FINALIZADO);

  // React to status changes: Auto-minimize if moved to FINALIZADO dynamically
  useEffect(() => {
    if (data.status === Status.FINALIZADO) {
        setIsMinimized(true);
    }
  }, [data.status]);

  // LOGIC HELPERS
  const isAdmin = currentUser.role === UserRole.ADMIN;
  const isSuperAdmin = currentUser.role === UserRole.SUPERADMIN;
  const isHead = currentUser.role === UserRole.HEAD;

  // Check if user can drag this card
  const isDraggable = () => {
    // SuperAdmin can drag anything anywhere
    if (isSuperAdmin) return true;

    // Admin can only drag if status is RECIBIDO
    if (isAdmin && data.status === Status.RECIBIDO) return true;

    if (isHead && data.area === currentUser.area) {
        // Can drag from Derivacion -> Ejecucion OR Ejecucion -> Finalizado
        if (data.status === Status.DERIVACION || data.status === Status.EJECUCION) return true;
    }
    return false;
  };

  const handleDragStart = (e: React.DragEvent) => {
    e.dataTransfer.setData('requestId', data.id);
    e.dataTransfer.setData('currentStatus', data.status);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleCardClick = () => {
    setSelectedRequestId(data.id);
  };

  // Helper for border colors
  const getAccentColor = (status: Status) => {
    switch (status) {
        case Status.RECIBIDO: return 'border-blue-500';
        case Status.DERIVACION: return 'border-orange-500';
        case Status.EJECUCION: return 'border-amber-500';
        case Status.FINALIZADO: return 'border-emerald-500';
        default: return 'border-slate-300';
    }
  };

  return (
    <div 
        draggable={isDraggable()}
        onDragStart={handleDragStart}
        onClick={handleCardClick}
        className={`
            bg-white rounded-xl mb-3 relative group
            transition-all duration-300 ease-out
            shadow-[0_2px_8px_-2px_rgba(0,0,0,0.05)] hover:shadow-[0_8px_16px_-4px_rgba(0,0,0,0.1)]
            border border-slate-100
            border-l-[4px]
            cursor-pointer
            ${getAccentColor(data.status)}
            ${isDraggable() ? 'active:cursor-grabbing hover:-translate-y-1 active:scale-[0.98]' : 'hover:bg-slate-50/50'}
            ${isMinimized ? 'py-3 px-4' : 'p-4'}
        `}
    >

      {/* Header: Status, Drag Handle, Actions */}
      <div className={`flex justify-between items-start ${isMinimized ? '' : 'mb-3'}`}>
        <div className="flex items-center gap-2 overflow-hidden">
             {/* Drag Handle (Only visible if draggable) */}
            {isDraggable() && (
                <div onMouseDown={(e) => e.stopPropagation()} className="cursor-grab active:cursor-grabbing -ml-1 text-slate-300 hover:text-indigo-400 transition-colors">
                    <GripVertical size={16} />
                </div>
            )}

            {/* ID Badge */}
            <span className="font-mono text-[10px] text-slate-400 font-bold bg-slate-50 px-1.5 rounded border border-slate-100">
                #{data.id.split('-')[1]}
            </span>

            {/* Returned Badge */}
            {data.isReturned && (
                 <span className="flex items-center gap-1 text-[9px] bg-red-50 text-red-600 px-1.5 py-0.5 rounded font-bold border border-red-100">
                    <AlertCircle size={8} /> DEVUELTO
                 </span>
            )}
        </div>

        <div className="flex items-center gap-2">
           {/* Priority Pill */}
           <span className={`text-[10px] font-black px-2 py-0.5 rounded-full border shadow-sm ${
             data.priority === 'Alta' ? 'bg-red-50 border-red-100 text-red-600' : 
             data.priority === 'Media' ? 'bg-amber-50 border-amber-100 text-amber-600' : 
             'bg-slate-50 border-slate-200 text-slate-500'
           }`}>
             {data.priority}
           </span>

           {/* Expand/Collapse */}
           <div className="opacity-0 group-hover:opacity-100 transition-opacity" onClick={(e) => e.stopPropagation()}>
               <button 
                    onClick={(e) => { e.stopPropagation(); setIsMinimized(!isMinimized); }}
                    className="p-1 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-md transition-all"
               >
                   {isMinimized ? <ChevronDown size={14}/> : <ChevronUp size={14}/>}
               </button>
           </div>
        </div>
      </div>

      {/* Main Content Area */}
      <div className={`${isMinimized ? 'mt-0 pl-0' : 'mb-4 px-1'}`}>
        <h3 className={`font-bold text-slate-800 leading-snug tracking-tight group-hover:text-indigo-600 transition-colors ${isMinimized ? 'text-xs truncate pt-1' : 'text-sm mb-2'}`}>
            {data.title}
        </h3>

        {/* Full Details - Only if NOT minimized */}
        {!isMinimized && (
            <p className="text-xs text-slate-500 leading-relaxed line-clamp-3 font-normal bg-slate-50 p-2.5 rounded-lg border border-slate-100/50">
                {data.detail}
            </p>
        )}
      </div>

      {/* Footer Info */}
      {!isMinimized && (
          <div className="flex flex-col gap-2 animate-in fade-in duration-300">
             <div className="flex items-center justify-between text-[11px] text-slate-500 mt-1">
                <div className="flex items-center gap-1.5 overflow-hidden">
                    <div className="w-5 h-5 rounded-full bg-slate-100 border border-slate-200 flex items-center justify-center shrink-0 text-[9px] font-bold text-slate-500">
                        {data.requester.charAt(0)}
                    </div>
                    <span className="truncate max-w-[90px] font-medium">{data.requester}</span>
                </div>

                {/* Modifiers: Analyst or Logs count */}
                <div className="flex items-center gap-2">
                    {data.assignedAnalyst && (
                        <div className="flex items-center gap-1 text-[10px] bg-indigo-50 text-indigo-700 px-1.5 py-0.5 rounded border border-indigo-100 font-bold" title="Analista asignado">
                            <div className="w-1.5 h-1.5 rounded-full bg-indigo-500"></div>
                            {data.assignedAnalyst.split(' ')[0]}
                        </div>
                    )}
                    <div className="flex items-center gap-1 text-[10px] text-slate-400 font-medium bg-slate-50 px-1.5 py-0.5 rounded border border-slate-100">
                         <MessageSquare size={10} /> {data.logs.length}
                     </div>
                </div>
             </div>

             {/* Bottom bar date/area */}
             <div className="flex items-center justify-between pt-2 border-t border-slate-50 mt-1">
                 <div className="flex items-center gap-1 text-[10px] text-slate-400 font-medium">
                    <MapPin size={10} /> {data.area}
                 </div>
                 <div className="flex items-center gap-1 text-[10px] text-slate-300 font-mono">
                    <Clock size={10} /> {new Date(data.createdAt).toLocaleDateString()}
                 </div>
             </div>
          </div>
      )}
    </div>
  );
};

