                <p className="text-slate-500 text-sm font-medium mt-1">Métricas clave de rendimiento y flujo de trabajo.</p>
            </div>

            {/* Visual Date Filter */}
            <div className="flex bg-white p-1 rounded-xl border border-slate-200 shadow-sm">
                {['Semanal', 'Mensual', 'Anual'].map((range) => (
                    <button
