                                </div>
                            </div>
                        )
                    })}
                </div>
            </div>

            {/* Top Analysts (Derived from data) */}
            <div className="bg-white rounded-2xl shadow-sm border border-slate-100 p-6 md:p-8 flex flex-col">
                <h3 className="font-bold text-slate-800 mb-6 flex items-center gap-2">
