                {stats.topAnalysts.length > 0 ? (
                    <div className="space-y-4">
                        {stats.topAnalysts.map((analyst, index) => (
                            <div key={analyst.name} className="flex items-center gap-4 p-3 rounded-xl hover:bg-slate-50 transition-colors border border-transparent hover:border-slate-100 group">
                                <div className={`w-8 h-8 flex items-center justify-center font-black text-sm rounded-full shadow-sm ${
                                    index === 0 ? 'bg-yellow-100 text-yellow-700 ring-4 ring-yellow-50' : 
                                    index === 1 ? 'bg-slate-200 text-slate-600' : 
                                    'bg-orange-100 text-orange-700'
