                                    <div className="font-bold text-slate-800 text-sm">{analyst.name}</div>
                                    <div className="text-xs text-slate-400 font-medium">{users.find(u => u.name === analyst.name)?.area || 'General'}</div>
                                </div>
                                <div className="text-right">
                                    <div className="text-lg font-black text-slate-800 leading-none">{analyst.count}</div>
                                    <div className="text-[10px] text-slate-400 font-bold uppercase">Tareas</div>
                                </div>
                            </div>
                        ))}
