          </div>
      )}
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { Status, Area, Priority, UserRole } from '../types';
import { 
    BarChart3, TrendingUp, CheckCircle2, Clock, 
    Activity, AlertTriangle, CalendarRange, ArrowRight,
    Briefcase, Zap, Layers, Filter
} from 'lucide-react';
import { STATUS_BADGE_COLORS } from '../constants';

export const ReportsView: React.FC = () => {
  const { requests, users, setViewMode, setGlobalFilterArea } = useSisreq();
  const [timeRange, setTimeRange] = useState<'Semanal' | 'Mensual' | 'Anual' | 'Todo'>('Mensual');

  // --- Date Filtering Logic ---
  const filteredRequests = useMemo(() => {
    if (timeRange === 'Todo') return requests;

    const now = new Date();
    return requests.filter(r => {
        const reqDate = new Date(r.createdAt);
        const diffTime = Math.abs(now.getTime() - reqDate.getTime());
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

        if (timeRange === 'Semanal') return diffDays <= 7;
        if (timeRange === 'Mensual') return diffDays <= 30;
        if (timeRange === 'Anual') return diffDays <= 365;
        return true;
    });
  }, [requests, timeRange]);

  // --- Advanced Stats Calculations (Based on Filtered Data) ---
  const stats = useMemo(() => {
    const total = filteredRequests.length;
    const completed = filteredRequests.filter(r => r.status === Status.FINALIZADO).length;
    const pending = total - completed;
    const completionRate = total > 0 ? Math.round((completed / total) * 100) : 0;

    // Status Flow (Pipeline)
    const byStatus = [Status.RECIBIDO, Status.DERIVACION, Status.EJECUCION, Status.FINALIZADO].map(status => {
        const count = filteredRequests.filter(r => r.status === status).length;
        const percentage = total > 0 ? Math.round((count / total) * 100) : 0;
        return { name: status, count, percentage };
    });

    // Area Load
    const byArea = Object.values(Area).map(area => {
        const count = filteredRequests.filter(r => r.area === area).length;
        return { name: area, count, total };
    }).sort((a, b) => b.count - a.count); // Sort by highest load

    // Priority Breakdown
    const byPriority = Object.values(Priority).map(p => ({
        name: p,
        count: filteredRequests.filter(r => r.priority === p).length
    }));

    // Avg Time (Mock logic)
    const completedItems = filteredRequests.filter(r => r.status === Status.FINALIZADO && r.finishedAt);
    let avgDays = 0;
    if (completedItems.length > 0) {
        const totalMs = completedItems.reduce((acc, curr) => {
            const start = new Date(curr.createdAt).getTime();
            const end = new Date(curr.finishedAt!).getTime();
            return acc + (end - start);
        }, 0);
        avgDays = Math.round(totalMs / (1000 * 60 * 60 * 24) / completedItems.length);
    }

    // Top Analysts Logic
    const analystCounts: Record<string, number> = {};
    filteredRequests.forEach(r => {
        if (r.assignedAnalyst) {
            analystCounts[r.assignedAnalyst] = (analystCounts[r.assignedAnalyst] || 0) + 1;
        }
    });

    const topAnalysts = Object.entries(analystCounts)
        .map(([name, count]) => ({ name, count }))
        .sort((a, b) => b.count - a.count)
        .slice(0, 3); // Top 3

    return { total, completed, pending, completionRate, byStatus, byArea, byPriority, avgDays, topAnalysts };
  }, [filteredRequests]);

  // Handle Navigation to Board
  const handleViewDetails = () => {
    setGlobalFilterArea('ALL'); // Reset or set specific area if needed
    setViewMode('work');
  };

  const handleTimeRangeChange = (range: string) => {
      setTimeRange(range as any);
  };

  return (
    <div className="flex-1 overflow-y-auto custom-scrollbar p-4 md:p-8 space-y-8 bg-slate-50/50">

        {/* Header Section */}
        <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
            <div>
                <h2 className="text-2xl font-black text-slate-800 tracking-tight flex items-center gap-2">
                    <Activity className="text-indigo-600" /> Panel de Control
                </h2>
                <p className="text-slate-500 text-sm font-medium mt-1">
                    Mostrando métricas para: <span className="text-indigo-600 font-bold">{timeRange}</span>
                </p>
            </div>

            {/* Visual Date Filter - Now Operational */}
            <div className="flex bg-white p-1 rounded-xl border border-slate-200 shadow-sm">
                {['Semanal', 'Mensual', 'Anual', 'Todo'].map((range) => (
                    <button
                        key={range}
                        onClick={() => handleTimeRangeChange(range)}
                        className={`px-4 py-1.5 text-xs font-bold rounded-lg transition-all ${
                            timeRange === range 
                            ? 'bg-slate-800 text-white shadow-sm' 
                            : 'text-slate-500 hover:bg-slate-50 hover:text-slate-700'
                        }`}
                    >
                        {range}
                    </button>
                ))}
            </div>
        </div>

        {/* KPI Cards Row */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
            {/* Total */}
            <div className="bg-white p-5 rounded-2xl border border-slate-100 shadow-[0_4px_20px_-12px_rgba(0,0,0,0.1)] hover:-translate-y-1 transition-transform duration-300 relative overflow-hidden group">
                <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
                    <Layers size={60} className="text-indigo-600"/>
                </div>
                <div className="flex flex-col justify-between h-full relative z-10">
                    <div className="flex items-center gap-3 mb-3">
                        <div className="p-2.5 bg-gradient-to-br from-indigo-500 to-blue-600 text-white rounded-lg shadow-md shadow-indigo-200">
                            <Briefcase size={18} strokeWidth={2.5}/>
                        </div>
                        <span className="text-xs font-bold text-slate-400 uppercase tracking-wider">Total Req.</span>
                    </div>
                    <div>
                        <p className="text-3xl font-black text-slate-800 tracking-tight">{stats.total}</p>
                        <div className="flex items-center gap-1 mt-1 text-[10px] font-bold text-emerald-600 bg-emerald-50 w-fit px-1.5 py-0.5 rounded-md">
                            <TrendingUp size={10} /> +8% vs periodo anterior
                        </div>
                    </div>
                </div>
            </div>

            {/* Pending */}
            <div className="bg-white p-5 rounded-2xl border border-slate-100 shadow-[0_4px_20px_-12px_rgba(0,0,0,0.1)] hover:-translate-y-1 transition-transform duration-300 relative overflow-hidden group">
