                    <Clock size={60} className="text-amber-500"/>
                </div>
                <div className="flex flex-col justify-between h-full relative z-10">
                    <div className="flex items-center gap-3 mb-3">
                        <div className="p-2.5 bg-gradient-to-br from-amber-400 to-orange-500 text-white rounded-lg shadow-md shadow-amber-200">
                            <Zap size={18} strokeWidth={2.5}/>
                        </div>
                        <span className="text-xs font-bold text-slate-400 uppercase tracking-wider">En Proceso</span>
                    </div>
                    <div>
                        <p className="text-3xl font-black text-slate-800 tracking-tight">{stats.pending}</p>
                        <div className="flex items-center gap-1 mt-1 text-[10px] font-bold text-amber-600 bg-amber-50 w-fit px-1.5 py-0.5 rounded-md">
                            <Activity size={10} /> {stats.byStatus[2].count} en ejecución
                        </div>
                    </div>
                </div>
            </div>

            {/* Completion Rate */}
            <div className="bg-white p-5 rounded-2xl border border-slate-100 shadow-[0_4px_20px_-12px_rgba(0,0,0,0.1)] hover:-translate-y-1 transition-transform duration-300 relative overflow-hidden group">
                 <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
                    <CheckCircle2 size={60} className="text-emerald-500"/>
                </div>
                <div className="flex flex-col justify-between h-full relative z-10">
                    <div className="flex items-center gap-3 mb-3">
                         <div className="p-2.5 bg-gradient-to-br from-emerald-400 to-teal-500 text-white rounded-lg shadow-md shadow-emerald-200">
                            <CheckCircle2 size={18} strokeWidth={2.5}/>
                        </div>
                        <span className="text-xs font-bold text-slate-400 uppercase tracking-wider">Eficiencia</span>
                    </div>
                    <div>
                        <div className="flex items-baseline gap-2">
                             <p className="text-3xl font-black text-slate-800 tracking-tight">{stats.completionRate}%</p>
                        </div>
                         {/* Mini Progress Bar */}
                         <div className="w-full h-1.5 bg-slate-100 rounded-full mt-2 overflow-hidden">
                            <div className="h-full bg-emerald-500 rounded-full" style={{ width: `${stats.completionRate}%` }}></div>
                         </div>
                    </div>
                </div>
            </div>

            {/* Avg Time */}
            <div className="bg-white p-5 rounded-2xl border border-slate-100 shadow-[0_4px_20px_-12px_rgba(0,0,0,0.1)] hover:-translate-y-1 transition-transform duration-300 relative overflow-hidden group">
                <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
                    <CalendarRange size={60} className="text-blue-500"/>
                </div>
                <div className="flex flex-col justify-between h-full relative z-10">
                    <div className="flex items-center gap-3 mb-3">
                        <div className="p-2.5 bg-gradient-to-br from-blue-400 to-indigo-500 text-white rounded-lg shadow-md shadow-blue-200">
                            <Clock size={18} strokeWidth={2.5}/>
