                                    {/* Mobile Right Column: Status Badge */}
                                    <div className="md:hidden text-right">
                                        <span className={`inline-block px-2 py-1 rounded-lg text-[10px] font-bold uppercase ${STATUS_BADGE_COLORS[req.status]}`}>
