                                >
                                    Limpiar filtros
                                </button>
                            )}
                        </div>
                    )}
                </div>
              </div>
          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { Area, UserRole, User, UserStatus } from '../types';
import { X, UserPlus, User as UserIcon, Building, Lock, Mail, Shield, Check, Save, Power } from 'lucide-react';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  userToEdit?: User | null; // Optional prop for editing mode
}

export const NewUserModal: React.FC<Props> = ({ isOpen, onClose, userToEdit }) => {
  const { addUser, updateUser } = useSisreq();
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [role, setRole] = useState<UserRole>(UserRole.ANALYST);
  const [area, setArea] = useState<Area | 'NONE'>('NONE');
  const [password, setPassword] = useState('');
  const [status, setStatus] = useState<UserStatus>('ACTIVE');

  // Reset or Populate form when opening
  useEffect(() => {
    if (isOpen) {
        if (userToEdit) {
            // Edit Mode
            setName(userToEdit.name);
            setEmail(userToEdit.email || '');
            setRole(userToEdit.role);
            setArea(userToEdit.area || 'NONE');
            setStatus(userToEdit.status || 'ACTIVE');
            setPassword(''); // Clear password field for security (leave empty to keep current)
        } else {
            // Create Mode
            setName('');
            setEmail('');
            setRole(UserRole.ANALYST);
            setArea(Area.CONTABILIDAD); // Default area for Analyst
            setStatus('ACTIVE');
            setPassword('');
        }
    }
  }, [isOpen, userToEdit]);

  // Determine if Area is needed based on Role
  const needsArea = role === UserRole.HEAD || role === UserRole.ANALYST;

  const handleRoleChange = (newRole: UserRole) => {
    setRole(newRole);

    const roleRequiresArea = newRole === UserRole.HEAD || newRole === UserRole.ANALYST;

    if (!roleRequiresArea) {
        setArea('NONE');
    } else {
        // If we switched to a role needing area, and currently don't have one (or it's NONE), set default
        if (area === 'NONE' || !area) {
             setArea(Area.CONTABILIDAD);
        }
    }
  };

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name || !email) return;

    // For creation, password is required. For edit, it's optional.
    if (!userToEdit && !password) return;

    // Ensure finalArea is undefined if not needed, or the specific area if needed
    const finalArea = needsArea && area !== 'NONE' ? (area as Area) : undefined;

    if (userToEdit) {
        // Update Logic
        const updatedUser: User = {
            ...userToEdit,
            name,
            email,
            role,
            area: finalArea,
            status,
            // Only update password if user typed something new
            password: password.trim() ? password : userToEdit.password
        };
        updateUser(updatedUser);
    } else {
        // Create Logic
        addUser(name, email, role, password, finalArea);
    }

    onClose();
  };

  const isEditMode = !!userToEdit;

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm transition-opacity" 
        onClick={onClose} 
      />

      {/* Modal Card */}
      <div className="relative bg-white rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden animate-in fade-in zoom-in-95 duration-200 border border-white/20">

        {/* Header */}
        <div className="bg-gradient-to-r from-slate-50 to-white border-b border-slate-100 px-6 py-5 flex justify-between items-center">
          <div className="flex items-center gap-3">
             <div className={`p-2.5 rounded-xl shadow-sm border ${isEditMode ? 'bg-indigo-600 text-white border-indigo-700' : 'bg-indigo-100 text-indigo-600 border-indigo-200/50'}`}>
                {isEditMode ? <UserIcon size={20} /> : <UserPlus size={20} className="stroke-2"/>}
             </div>
             <div>
                <h2 className="text-lg font-black text-slate-800 tracking-tight leading-none mb-1">
                    {isEditMode ? 'Editar Usuario' : 'Nuevo Usuario'}
                </h2>
                <p className="text-xs text-slate-500 font-medium">
                    {isEditMode ? 'Modificar datos de acceso y perfil' : 'Registrar nuevo miembro del equipo'}
                </p>
             </div>
          </div>
          <button 
            onClick={onClose} 
            className="text-slate-400 hover:text-slate-600 p-2 hover:bg-slate-100 rounded-full transition-colors"
          >
            <X size={20} />
          </button>
        </div>

        {/* Form Body */}
        <form onSubmit={handleSubmit} className="p-6 space-y-5">

            {/* Name */}
            <div className="space-y-2">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider flex items-center gap-1.5">
                    <UserIcon size={12} /> Nombre Completo
                </label>
                <input
                    type="text"
                    required
                    className="w-full bg-slate-50 border border-slate-200 text-slate-700 text-sm rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 transition-all placeholder:text-slate-400 font-medium"
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    placeholder="Ej: Juan Pérez"
                    autoFocus
                />
            </div>

            {/* Email */}
            <div className="space-y-2">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider flex items-center gap-1.5">
                    <Mail size={12} /> Correo Electrónico
                </label>
                <input
                    type="email"
                    required
                    className="w-full bg-slate-50 border border-slate-200 text-slate-700 text-sm rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 transition-all placeholder:text-slate-400 font-medium"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    placeholder="ejemplo@sisreq.com"
                />
            </div>

            <div className="grid grid-cols-2 gap-4">
                {/* Role */}
                <div className="space-y-2">
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider flex items-center gap-1.5">
                        <Shield size={12} /> Rol
                    </label>
                    <div className="relative">
                        <select
                            className="w-full bg-slate-50 border border-slate-200 text-slate-700 text-sm rounded-xl px-4 py-3 appearance-none focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 transition-all cursor-pointer font-medium"
                            value={role}
                            onChange={(e) => handleRoleChange(e.target.value as UserRole)}
                        >
                            {Object.values(UserRole).map((r) => (
                                <option key={r} value={r}>{r}</option>
                            ))}
                        </select>
                         <div className="absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">
                            <svg className="w-4 h-4 fill-current" viewBox="0 0 20 20"><path d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z"/></svg>
                        </div>
                    </div>
                </div>

                {/* Area (Conditional) */}
                <div className="space-y-2">
                    <label className={`text-[10px] font-bold uppercase tracking-wider flex items-center gap-1.5 ${needsArea ? 'text-slate-400' : 'text-slate-300'}`}>
                        <Building size={12} /> Área
                    </label>
                    <div className="relative">
                        <select
                            disabled={!needsArea}
                            className={`w-full border text-sm rounded-xl px-4 py-3 appearance-none transition-all font-medium ${
                                needsArea 
                                ? 'bg-slate-50 border-slate-200 text-slate-700 focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 cursor-pointer' 
                                : 'bg-slate-100 border-slate-200 text-slate-400 cursor-not-allowed'
                            }`}
                            value={area}
                            onChange={(e) => setArea(e.target.value as Area)}
                        >
                             {!needsArea && <option value="NONE">N/A</option>}
                             {Object.values(Area).map((a) => (
                                <option key={a} value={a}>{a}</option>
                             ))}
                        </select>
                        <div className={`absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none ${needsArea ? 'text-slate-400' : 'text-slate-300'}`}>
                            <svg className="w-4 h-4 fill-current" viewBox="0 0 20 20"><path d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z"/></svg>
                        </div>
                    </div>
                </div>
            </div>

            {/* Password */}
            <div className="space-y-2">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider flex items-center gap-1.5">
                    <Lock size={12} /> Contraseña
                </label>
                <input
                    type="text"
                    required={!isEditMode}
                    className="w-full bg-slate-50 border border-slate-200 text-slate-700 text-sm rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 transition-all placeholder:text-slate-400 font-medium"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    placeholder={isEditMode ? "Dejar en blanco para mantener actual" : "Clave de acceso"}
                />
            </div>

            {/* Status (Only show in edit mode) */}
            {isEditMode && (
                <div className="space-y-2">
                     <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider flex items-center gap-1.5">
                        <Power size={12} /> Estado del Usuario
                    </label>
                    <div className="flex gap-4">
                        <button
                            type="button"
                            onClick={() => setStatus('ACTIVE')}
                            className={`flex-1 py-2.5 rounded-xl border text-xs font-bold transition-all flex items-center justify-center gap-2 ${
                                status === 'ACTIVE' 
                                ? 'bg-emerald-50 border-emerald-200 text-emerald-600 ring-1 ring-emerald-500/20' 
                                : 'bg-white border-slate-200 text-slate-400 hover:bg-slate-50'
                            }`}
                        >
                            <Check size={14} /> Activo
                        </button>
                        <button
                            type="button"
                            onClick={() => setStatus('INACTIVE')}
                             className={`flex-1 py-2.5 rounded-xl border text-xs font-bold transition-all flex items-center justify-center gap-2 ${
                                status === 'INACTIVE' 
                                ? 'bg-slate-100 border-slate-300 text-slate-600 ring-1 ring-slate-500/20' 
                                : 'bg-white border-slate-200 text-slate-400 hover:bg-slate-50'
                            }`}
                        >
                            <Lock size={14} /> Inactivo
                        </button>
                    </div>
                </div>
            )}

           {/* Footer */}
           <div className="pt-4 flex items-center justify-end gap-3 border-t border-slate-100 mt-2">
                <button
                    type="button"
                    onClick={onClose}
                    className="px-5 py-2.5 text-slate-500 font-bold text-sm hover:bg-slate-50 rounded-xl transition-colors"
                >
                    Cancelar
                </button>
                <button
                    type="submit"
                    className="bg-indigo-600 hover:bg-indigo-700 text-white font-bold text-sm px-6 py-2.5 rounded-xl shadow-lg shadow-indigo-200 hover:shadow-xl hover:translate-y-[-1px] transition-all flex items-center gap-2 active:scale-95"
                >
                    {isEditMode ? <Save size={16}/> : <Check size={16} />} 
                    {isEditMode ? 'Guardar Cambios' : 'Crear Usuario'}
                </button>
           </div>
        </form>
      </div>
    </div>
  );
};

