                {/* Description Box */}
                <div className="space-y-2">
                    <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider flex items-center gap-2">
                        <Tag size={14}/> Detalle del Requerimiento
                    </h3>
                    {isEditing ? (
                        <textarea 
                            value={editDetail}
                            onChange={(e) => setEditDetail(e.target.value)}
                            className="w-full h-48 bg-white p-5 rounded-xl border border-slate-200 text-slate-700 leading-relaxed text-sm focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 outline-none resize-none transition-all shadow-sm"
                            placeholder="Descripción detallada..."
                        />
                    ) : (
                        <div className="bg-slate-50 p-5 rounded-xl border border-slate-100 text-slate-700 leading-relaxed text-sm whitespace-pre-wrap">
                            {data.detail}
                        </div>
                    )}
                </div>

                {/* Metadata Grid */}
                <div className="grid grid-cols-2 gap-4">
                    <div className="bg-white p-4 rounded-xl border border-slate-100 shadow-sm">
                        <div className="flex items-center gap-2 text-slate-400 mb-1">
                            <User size={14} />
                            <span className="text-xs font-bold uppercase">Solicitante</span>
                        </div>
                        <div className="font-semibold text-slate-700">{data.requester}</div>
                    </div>
                    <div className="bg-white p-4 rounded-xl border border-slate-100 shadow-sm">
                         <div className="flex items-center gap-2 text-slate-400 mb-1">
                            <Building size={14} />
                            <span className="text-xs font-bold uppercase">Área Destino</span>
                        </div>
                        <div className="font-semibold text-slate-700">{data.area}</div>
                        <div className="text-xs text-slate-400">Jefe: {data.responsibleHead}</div>
                    </div>
                    <div className="bg-white p-4 rounded-xl border border-slate-100 shadow-sm">
                         <div className="flex items-center gap-2 text-slate-400 mb-1">
                            <Calendar size={14} />
                            <span className="text-xs font-bold uppercase">Fecha Creación</span>
                        </div>
                        <div className="font-semibold text-slate-700">{new Date(data.createdAt).toLocaleDateString()}</div>
                        <div className="text-xs text-slate-400">{new Date(data.createdAt).toLocaleTimeString()}</div>
                    </div>
                    <div className="bg-white p-4 rounded-xl border border-slate-100 shadow-sm">
                         <div className="flex items-center gap-2 text-slate-400 mb-1">
                            <AlertCircle size={14} />
                            <span className="text-xs font-bold uppercase">Prioridad</span>
                        </div>
                        <div className={`font-bold ${
                             data.priority === 'Alta' ? 'text-red-600' : 
                             data.priority === 'Media' ? 'text-amber-600' : 'text-slate-600'
                        }`}>
                            {data.priority}
                        </div>
                    </div>
                </div>

                {data.assignedAnalyst && (
                     <div className="bg-indigo-50 p-4 rounded-xl border border-indigo-100 flex items-center gap-4">
                        <div className="w-10 h-10 rounded-full bg-indigo-200 flex items-center justify-center text-indigo-700 font-bold">
                            {data.assignedAnalyst.substring(0,2).toUpperCase()}
                        </div>
                        <div>
                            <div className="text-xs text-indigo-500 font-bold uppercase">Analista Asignado</div>
                            <div className="font-bold text-indigo-900">{data.assignedAnalyst}</div>
                        </div>
                     </div>
                )}
            </div>

            {/* Right Column: Timeline / History & Notes */}
            <div className="w-full md:w-96 bg-slate-50/50 border-t md:border-t-0 md:border-l border-slate-200 flex flex-col h-full">

                {/* Notes Input */}
                {canComment && (
                    <div className="p-4 border-b border-slate-200 bg-white shadow-[0_4px_12px_-4px_rgba(0,0,0,0.05)] z-10">
                        <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2 flex items-center gap-2">
                            <MessageSquare size={14}/> Nota Interna
                        </h3>
                        <div className="relative">
                            <textarea
                                value={newComment}
                                onChange={e => setNewComment(e.target.value)}
                                className="w-full text-xs p-3 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 bg-slate-50 focus:bg-white pr-10 resize-none outline-none transition-all"
                                placeholder="Escribe un comentario o actualización..."
                                rows={2}
                            />
                            <button 
                                onClick={handleAddComment}
                                disabled={!newComment.trim()}
                                className="absolute right-2 bottom-2 p-1.5 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 disabled:opacity-50 disabled:hover:bg-indigo-600 transition-colors shadow-sm"
                            >
                                <Send size={12}/>
                            </button>
                        </div>
                    </div>
                )}

                {/* Timeline */}
                <div className="flex-1 overflow-y-auto p-6 custom-scrollbar">
                    <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-6 flex items-center gap-2">
                        <Clock size={14}/> Historial de Actividad
                    </h3>

                    <div className="relative pl-2 space-y-6 before:absolute before:left-2 before:top-2 before:bottom-0 before:w-0.5 before:bg-slate-200 before:rounded-full">
                        {[...data.logs].reverse().map((log, index) => {
                            const config = getTimelineConfig(log.message);
                            return (
                                <div key={log.id} className="relative flex gap-4 group">
                                    {/* Timeline Node */}
                                    <div className={`
                                        absolute left-[-5px] top-0 w-6 h-6 rounded-full border-2 border-white shadow-sm flex items-center justify-center z-10 transition-colors
                                        ${index === 0 ? config.bg + ' ' + config.text + ' ring-2 ring-white ring-offset-1 ring-offset-slate-200' : 'bg-white text-slate-400 border-slate-200'}
                                    `}>
                                        {config.icon}
                                    </div>

                                    {/* Content */}
                                    <div className="ml-5 flex-1 min-w-0">
                                        <div className="flex flex-col gap-1">
                                            <div className="flex items-center justify-between">
                                                <span className="text-xs font-bold text-slate-700 truncate" title={log.actor}>
                                                    {log.actor}
                                                </span>
                                                <span className="text-[10px] text-slate-400 font-mono">
                                                    {new Date(log.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                                    <span className="mx-1 opacity-50">|</span>
                                                    {new Date(log.timestamp).toLocaleDateString([], { month: 'short', day: 'numeric' })}
                                                </span>
                                            </div>

                                            <div className={`text-xs p-3 rounded-xl border ${config.bg} ${config.text.replace('text-', 'text-opacity-90 text-')} ${config.border} relative`}>
                                                {/* Little triangle for chat bubble effect */}
                                                <div className={`absolute top-2 -left-1.5 w-3 h-3 rotate-45 border-l border-b ${config.bg} ${config.border}`}></div>
                                                <p className="relative z-10 font-medium leading-relaxed">{log.message}</p>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            </div>
        </div>

        {/* Footer Actions - Dynamic based on Role & Status */}
        <div className="bg-white border-t border-slate-200 p-4 shrink-0 flex items-center justify-between gap-4 z-20 relative shadow-[0_-4px_20px_rgba(0,0,0,0.02)]">
             <button 
                onClick={handleClose}
                className="px-4 py-2 bg-white hover:bg-slate-50 border border-slate-300 text-slate-700 text-sm font-medium rounded-lg shadow-sm transition-colors"
            >
                Cerrar
            </button>

            <div className="flex items-center gap-2 flex-1 justify-end">

                {/* --- ADMIN ACTIONS --- */}
                {/* Admin/SuperAdmin can only derive if Status is RECIBIDO */}
                {(isAdmin || isSuperAdmin) && data.status === Status.RECIBIDO && (
                     <button 
                     onClick={handleDerive}
                     className="flex items-center gap-2 bg-gradient-to-r from-orange-500 to-orange-600 hover:from-orange-600 hover:to-orange-700 text-white py-2 px-6 rounded-lg text-sm font-bold shadow-md transition-all active:scale-95"
                   >
                     Derivar al Área <ArrowRight size={16}/>
                   </button>
                )}

                {/* --- HEAD ACTIONS: DERIVATION PHASE --- */}
                {isHead && data.status === Status.DERIVACION && data.area === currentUser.area && (
                    <div className="flex items-center gap-2 w-full justify-end relative">

                         {/* Return Input Overlay or Button */}
                         {showReturnInput ? (
                             <div className="flex-1 flex gap-2 items-center bg-red-50 p-1.5 rounded-lg border border-red-100 animate-in slide-in-from-right-10 fade-in">
                                <input 
                                    className="flex-1 text-sm p-1.5 border border-red-200 rounded-md focus:outline-none focus:ring-1 focus:ring-red-300"
                                    placeholder="Razón de devolución..."
                                    value={returnReason}
                                    onChange={e => setReturnReason(e.target.value)}
                                    autoFocus
                                />
                                <button onClick={handleReturnSubmit} className="bg-red-500 text-white px-3 py-1.5 rounded-md text-xs font-bold">Confirmar</button>
                                <button onClick={() => setShowReturnInput(false)} className="text-slate-500 px-2 text-xs">Cancelar</button>
                             </div>
                         ) : (
                             <button 
                                onClick={() => setShowReturnInput(true)}
                                className="px-4 py-2 text-slate-600 hover:text-red-600 hover:bg-red-50 border border-slate-200 rounded-lg text-xs font-bold transition-colors"
                             >
                                Devolver
                             </button>
                         )}

                         {!showReturnInput && (
                            <>
                                {/* Analyst Selection */}
                                <div className="relative">
                                    <button 
                                        onClick={() => setShowAnalystSelect(!showAnalystSelect)}
                                        className="bg-indigo-600 hover:bg-indigo-700 text-white py-2 px-4 rounded-lg text-sm font-bold shadow-sm transition-colors flex items-center gap-2"
                                    >
                                        <User size={16}/> Asignar Analista
                                        {showAnalystSelect && <ChevronUp size={14}/>}
                                    </button>

                                    {showAnalystSelect && (
                                        <div className="absolute bottom-full right-0 mb-2 w-64 bg-white rounded-xl shadow-xl border border-slate-200 p-2 animate-in slide-in-from-bottom-2 z-50">
                                             <p className="text-xs font-bold text-slate-400 uppercase p-2">Seleccionar del equipo:</p>
                                             <div className="max-h-48 overflow-y-auto custom-scrollbar flex flex-col gap-1">
                                                {availableAnalysts.length > 0 ? availableAnalysts.map(a => (
                                                    <button 
                                                        key={a.id} 
                                                        onClick={() => handleAssignAnalyst(a.name)}
                                                        className="flex items-center gap-3 w-full text-left px-3 py-2 hover:bg-indigo-50 rounded-lg transition-colors text-sm text-slate-700"
                                                    >
                                                        <div className="w-6 h-6 rounded-full bg-indigo-100 text-indigo-600 flex items-center justify-center text-xs font-bold">
                                                            {a.name.substring(0,2).toUpperCase()}
                                                        </div>
                                                        {a.name}
                                                    </button>
                                                )) : (
                                                    <p className="text-xs text-slate-400 italic p-2 text-center">No hay analistas.</p>
                                                )}
                                             </div>
                                        </div>
                                    )}
                                </div>

                                <button 
                                    onClick={handleStartExecution}
                                    className="bg-amber-500 hover:bg-amber-600 text-white py-2 px-6 rounded-lg text-sm font-bold shadow-md transition-colors flex items-center gap-2"
                                >
                                    <Briefcase size={18}/> Iniciar Ejecución
                                </button>
                            </>
                         )}
                    </div>
                )}

                {/* --- HEAD & ANALYST ACTIONS: EXECUTION PHASE --- */}
                {(isHead || isAnalyst) && data.status === Status.EJECUCION && data.area === currentUser.area && (
                     <button 
                     onClick={handleFinalize}
                     className="bg-emerald-600 hover:bg-emerald-700 text-white py-2 px-6 rounded-lg text-sm font-bold shadow-md hover:shadow-lg transition-all active:scale-95 flex items-center gap-2"
                     >
                     <CheckCircle size={18}/> Finalizar Tarea
                     </button>
                )}
            </div>
        </div>

      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { RequestCard } from './RequestCard';
import { Status, UserRole, Priority, Area } from '../types';
import { LayoutGrid, List, ListFilter, AlignLeft, Search, Filter, XCircle, Inbox, GitPullRequest, PlayCircle, CheckCircle2 } from 'lucide-react';
import { STATUS_BADGE_COLORS } from '../constants';

export const Board: React.FC = () => {
  const { requests, currentUser, updateStatus, setSelectedRequestId, globalFilterArea, setGlobalFilterArea } = useSisreq();
  const [dragOverColumn, setDragOverColumn] = useState<Status | null>(null);
  const [viewMode, setViewMode] = useState<'board' | 'list'>('board');

  // Filters State
  const [searchTerm, setSearchTerm] = useState('');

  // Note: filterArea is now managed via Context (globalFilterArea)

  // Filter requests based on Role AND Search/Filter State
  const filteredRequests = requests.filter(req => {
    // 1. Role Based Access (Base Visibility)
    let hasAccess = false;
    // Admin & SuperAdmin sees everything
    if (currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.SUPERADMIN) {
        hasAccess = true;
    } 
    // Heads and Analysts see their own area (unless Recibido)
    else if (req.area === currentUser.area && req.status !== Status.RECIBIDO) {
        hasAccess = true;
    }

    if (!hasAccess) return false;

    // 2. Text Search (Title, ID, Requester)
    const matchesSearch = searchTerm === '' || 
        req.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
        req.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
        req.requester.toLowerCase().includes(searchTerm.toLowerCase());

    // 3. Area Filter (For Admins/SuperAdmins who see all areas)
    const matchesArea = globalFilterArea === 'ALL' || req.area === globalFilterArea;

    return matchesSearch && matchesArea;
  });

  const getRequestsByStatus = (status: Status) => {
    return filteredRequests.filter(req => req.status === status);
  };

  // --- Drag & Drop Logic (Only active in Board View) ---
  const handleDragOver = (e: React.DragEvent, status: Status) => {
    e.preventDefault();
    if (dragOverColumn !== status) {
        setDragOverColumn(status);
    }
  };

  const handleDragLeave = () => {
    setDragOverColumn(null);
  };

  const handleDrop = (e: React.DragEvent, targetStatus: Status) => {
    e.preventDefault();
    setDragOverColumn(null);
    const requestId = e.dataTransfer.getData('requestId');
    const currentStatus = e.dataTransfer.getData('currentStatus') as Status;

    // Strict Workflow Rules for Drag & Drop
    let isValidMove = false;

    // SuperAdmin: unrestricted movement
    if (currentUser.role === UserRole.SUPERADMIN) {
        isValidMove = true;
    } else {
        // Admin: Recibido -> Derivacion
        if (currentUser.role === UserRole.ADMIN) {
            if (currentStatus === Status.RECIBIDO && targetStatus === Status.DERIVACION) isValidMove = true;
        }

        // Head & Analyst Logic
        if (currentUser.role === UserRole.HEAD || currentUser.role === UserRole.ANALYST) {
            // Find the request to check area owner
            const req = requests.find(r => r.id === requestId);
            if (req && req.area === currentUser.area) {
                // Head specific: Derivacion -> Ejecucion
                if (currentUser.role === UserRole.HEAD && currentStatus === Status.DERIVACION && targetStatus === Status.EJECUCION) isValidMove = true;

                // Head & Analyst: Ejecucion -> Finalizado
                if (currentStatus === Status.EJECUCION && targetStatus === Status.FINALIZADO) isValidMove = true;
            }
        }
    }

    if (isValidMove) {
        updateStatus(requestId, targetStatus);
    }
  };

  // Column Visual Configuration
  const COLUMNS_CONFIG = [
    { 
        title: 'Bandeja de Entrada', 
        status: Status.RECIBIDO, 
        icon: <Inbox size={18} />,
        headerColor: 'text-blue-700 bg-blue-50/80 border-blue-100',
        bodyTint: 'bg-slate-50/50', // Subtle tint for the column body
        borderColor: 'border-blue-200'
    },
    { 
        title: 'Derivación', 
        status: Status.DERIVACION, 
        icon: <GitPullRequest size={18} />,
        headerColor: 'text-orange-700 bg-orange-50/80 border-orange-100',
        bodyTint: 'bg-orange-50/10',
        borderColor: 'border-orange-200'
    },
    { 
        title: 'En Ejecución', 
        status: Status.EJECUCION, 
        icon: <PlayCircle size={18} />,
        headerColor: 'text-amber-700 bg-amber-50/80 border-amber-100',
        bodyTint: 'bg-amber-50/10',
        borderColor: 'border-amber-200'
    },
    { 
        title: 'Finalizado', 
        status: Status.FINALIZADO, 
        icon: <CheckCircle2 size={18} />,
        headerColor: 'text-emerald-700 bg-emerald-50/80 border-emerald-100',
        bodyTint: 'bg-emerald-50/10',
        borderColor: 'border-emerald-200'
    }
  ];

  // Logic to show/hide filter controls
  const showAreaFilter = currentUser.role === UserRole.SUPERADMIN || currentUser.role === UserRole.ADMIN;

  return (
    <div className="flex flex-col h-full overflow-hidden">

      {/* Toolbar */}
      <div className="px-4 md:px-6 py-4 flex flex-col md:flex-row md:items-center justify-between gap-4 shrink-0 bg-white/50 backdrop-blur-sm border-b border-slate-200/50 z-20">

          {/* Title & Stats */}
          <div className="flex items-center justify-between md:justify-start gap-3">
             <div className="flex items-center gap-3">
                 <h2 className="text-lg font-bold text-slate-800">
                    Gestión
                 </h2>
                 <span className="bg-white border border-slate-200 text-slate-600 px-2.5 py-0.5 rounded-full text-xs font-bold shadow-sm">
                    {filteredRequests.length}
                    {searchTerm || globalFilterArea !== 'ALL' ? <span className="text-slate-400 font-normal"> / {requests.length}</span> : ''}
                 </span>
             </div>

             {/* Mobile View Toggle */}
             <div className="md:hidden bg-white p-1 rounded-lg border border-slate-200 shadow-sm flex items-center gap-1">
                <button onClick={() => setViewMode('board')} className={`p-1.5 rounded ${viewMode === 'board' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400'}`}><LayoutGrid size={16}/></button>
                <button onClick={() => setViewMode('list')} className={`p-1.5 rounded ${viewMode === 'list' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400'}`}><List size={16}/></button>
             </div>
          </div>

          {/* Controls Group */}
          <div className="flex flex-col md:flex-row items-stretch md:items-center gap-3">

             {/* Search Input */}
             <div className="relative group w-full md:w-auto">
                <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-indigo-500 transition-colors"/>
                <input 
                    type="text"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    placeholder="Buscar..."
                    className="w-full md:w-56 pl-9 pr-3 py-2 md:py-1.5 text-sm md:text-xs font-medium bg-white border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 transition-all shadow-sm"
                />
                {searchTerm && (
                    <button 
                        onClick={() => setSearchTerm('')}
                        className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-300 hover:text-slate-500"
                    >
                        <XCircle size={12} className="fill-slate-100"/>
                    </button>
                )}
             </div>

             {/* Area Filter (Only for Admin/SuperAdmin) */}
             {showAreaFilter && (
                 <div className="relative w-full md:w-auto">
                    <div className="absolute left-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">
                        <Filter size={12} />
                    </div>
                    <select
                        value={globalFilterArea}
                        onChange={(e) => setGlobalFilterArea(e.target.value as Area | 'ALL')}
                        className={`w-full md:w-auto pl-8 pr-8 py-2 md:py-1.5 text-sm md:text-xs font-bold border rounded-lg appearance-none cursor-pointer focus:outline-none focus:ring-2 focus:ring-indigo-100 transition-all shadow-sm ${
                            globalFilterArea !== 'ALL' 
                            ? 'bg-indigo-50 border-indigo-200 text-indigo-700' 
                            : 'bg-white border-slate-200 text-slate-600 hover:border-slate-300'
                        }`}
                    >
                        <option value="ALL">Todas las Áreas</option>
                        {Object.values(Area).map(a => (
                            <option key={a} value={a}>{a}</option>
                        ))}
                    </select>
                 </div>
             )}

             <div className="w-px h-6 bg-slate-200 mx-1 hidden md:block"></div>

             {/* Desktop View Switcher */}
             <div className="hidden md:flex bg-white p-1 rounded-lg border border-slate-200 shadow-sm items-center gap-1">
                <button 
                    onClick={() => setViewMode('board')}
                    className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all ${
                        viewMode === 'board' 
                        ? 'bg-indigo-50 text-indigo-600 shadow-sm ring-1 ring-indigo-100' 
                        : 'text-slate-500 hover:bg-slate-50 hover:text-slate-700'
                    }`}
                >
                    <LayoutGrid size={14} /> <span>Tablero</span>
                </button>
                <div className="w-px h-4 bg-slate-200 mx-1"></div>
                <button 
                    onClick={() => setViewMode('list')}
                    className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all ${
                        viewMode === 'list' 
                        ? 'bg-indigo-50 text-indigo-600 shadow-sm ring-1 ring-indigo-100' 
                        : 'text-slate-500 hover:bg-slate-50 hover:text-slate-700'
                    }`}
                >
                    <List size={14} /> <span>Lista</span>
                </button>
             </div>
          </div>
      </div>

      {/* --- BOARD VIEW (Horizontal Scroll) --- */}
      {viewMode === 'board' && (
        <div className="flex-1 overflow-x-auto overflow-y-hidden">
            <div className="h-full flex px-4 md:px-6 pb-6 gap-6 min-w-[320px] md:min-w-[1200px] pt-4 snap-x snap-mandatory md:snap-none">
                {COLUMNS_CONFIG.map((col) => {
                    const items = getRequestsByStatus(col.status);
                    const isOver = dragOverColumn === col.status;

                    return (
                        <div 
                            key={col.status} 
                            className={`flex-1 flex flex-col min-w-[280px] max-w-[350px] transition-all duration-300 rounded-2xl snap-center border overflow-hidden
                                ${isOver ? 'bg-indigo-50 ring-2 ring-indigo-300 border-indigo-300 shadow-lg scale-[1.01]' : `${col.bodyTint} border-transparent`}
                            `}
                            onDragOver={(e) => handleDragOver(e, col.status)}
                            onDragLeave={handleDragLeave}
                            onDrop={(e) => handleDrop(e, col.status)}
                        >
                            {/* Column Header */}
                            <div className={`flex items-center justify-between p-3 mx-2 mt-2 rounded-xl border mb-2 shadow-sm shrink-0 ${col.headerColor}`}>
                                <div className="flex items-center gap-2 font-bold text-sm tracking-tight">
                                    {col.icon}
                                    {col.title}
                                </div>
                                <span className="bg-white/80 backdrop-blur-sm px-2 py-0.5 rounded-md text-[10px] font-black min-w-[20px] text-center">
                                    {items.length}
                                </span>
                            </div>

                            {/* Column Body */}
                            <div className="flex-1 overflow-y-auto px-2 pb-4 custom-scrollbar flex flex-col">
                                {items.length === 0 ? (
                                    <div className={`flex-1 min-h-[150px] border-2 border-dashed rounded-xl flex flex-col gap-2 items-center justify-center text-slate-400 text-sm transition-colors mt-2 mx-1 ${isOver ? 'border-indigo-400 bg-indigo-100/50' : 'border-slate-200/60'}`}>
                                        <Inbox size={24} className="opacity-20"/>
                                        <span className="text-xs font-medium opacity-60 italic">{isOver ? 'Soltar aquí' : 'Sin tarjetas'}</span>
                                    </div>
                                ) : (
                                    <>
                                        {items.map(req => (
                                            <RequestCard key={req.id} data={req} />
                                        ))}
