export const Board: React.FC = () => {
  const { requests, currentUser, updateStatus, setSelectedRequestId, globalFilterArea, setGlobalFilterArea, canMoveRequest } = useSisreq();
  const [dragOverColumn, setDragOverColumn] = useState<Status | null>(null);
  const [viewMode, setViewMode] = useState<'board' | 'list'>('board');
  const [searchTerm, setSearchTerm] = useState('');

  const filteredRequests = requests.filter(req => {
    const isAdmin = currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.SUPERADMIN;
    const isOwnerArea = req.area === currentUser.area && req.status !== Status.RECIBIDO;
    if (!isAdmin && !isOwnerArea) return false;

    const matchesSearch = searchTerm === '' || 
        req.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
        req.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
        req.requester.toLowerCase().includes(searchTerm.toLowerCase());

    const matchesArea = globalFilterArea === 'ALL' || req.area === globalFilterArea;
    return matchesSearch && matchesArea;
  });

  const getRequestsByStatus = (status: Status) => filteredRequests.filter(req => req.status === status);

  const handleDrop = (e: React.DragEvent, targetStatus: Status) => {
    e.preventDefault();
    setDragOverColumn(null);
    const requestId = e.dataTransfer.getData('requestId');
    const req = requests.find(r => r.id === requestId);
    if (req && canMoveRequest(req, targetStatus)) {
      updateStatus(requestId, targetStatus);
    }
  };

  const COLUMNS = [
    { title: 'Bandeja', status: Status.RECIBIDO, icon: <Inbox size={18} />, color: 'text-blue-700 bg-blue-50 border-blue-100' },
    { title: 'Derivación', status: Status.DERIVACION, icon: <GitPullRequest size={18} />, color: 'text-orange-700 bg-orange-50 border-orange-100' },
    { title: 'Ejecución', status: Status.EJECUCION, icon: <PlayCircle size={18} />, color: 'text-amber-700 bg-amber-50 border-amber-100' },
    { title: 'Finalizado', status: Status.FINALIZADO, icon: <CheckCircle2 size={18} />, color: 'text-emerald-700 bg-emerald-50 border-emerald-100' }
  ];

  return (
    <div className="flex flex-col h-full overflow-hidden">
      <div className="px-6 py-4 flex flex-col md:flex-row items-center justify-between gap-4 border-b bg-white/50 backdrop-blur-sm z-20">
          <div className="flex items-center gap-3">
             <h2 className="text-lg font-bold text-slate-800">Gestión</h2>
             <span className="bg-white border px-2.5 py-0.5 rounded-full text-xs font-bold shadow-sm">{filteredRequests.length}</span>
          </div>

          <div className="flex flex-wrap items-center gap-3">
             <div className="relative group">
                <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"/>
                <input 
                    type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="Buscar..."
                    className="pl-9 pr-3 py-1.5 text-xs font-medium bg-white border rounded-lg focus:ring-2 focus:ring-indigo-100 outline-none w-48 transition-all"
                />
             </div>

             {(currentUser.role === UserRole.SUPERADMIN || currentUser.role === UserRole.ADMIN) && (
                <select
                    value={globalFilterArea} onChange={(e) => setGlobalFilterArea(e.target.value as Area | 'ALL')}
                    className="pl-3 pr-8 py-1.5 text-xs font-bold border rounded-lg bg-white outline-none cursor-pointer"
                >
                    <option value="ALL">Todas las Áreas</option>
                    {Object.values(Area).map(a => <option key={a} value={a}>{a}</option>)}
                </select>
             )}

             <div className="flex bg-white p-1 rounded-lg border shadow-sm items-center gap-1">
                <button onClick={() => setViewMode('board')} className={`p-1.5 rounded ${viewMode === 'board' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400'}`}><LayoutGrid size={14}/></button>
                <button onClick={() => setViewMode('list')} className={`p-1.5 rounded ${viewMode === 'list' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400'}`}><AlignLeft size={14}/></button>
             </div>
          </div>
      </div>

      {viewMode === 'board' ? (
        <div className="flex-1 overflow-x-auto p-6 flex gap-6 min-w-full">
            {COLUMNS.map((col) => {
                const items = getRequestsByStatus(col.status);
                const isOver = dragOverColumn === col.status;
                return (
                    <div 
                        key={col.status} 
                        className={`flex-1 flex flex-col min-w-[280px] max-w-[350px] rounded-2xl border transition-all ${isOver ? 'bg-indigo-50 ring-2 ring-indigo-200' : 'bg-slate-50/50 border-transparent'}`}
                        onDragOver={(e) => { e.preventDefault(); setDragOverColumn(col.status); }}
                        onDragLeave={() => setDragOverColumn(null)}
                        onDrop={(e) => handleDrop(e, col.status)}
                    >
                        <div className={`flex items-center justify-between p-3 mx-2 mt-2 rounded-xl border mb-2 shadow-sm ${col.color}`}>
                            <div className="flex items-center gap-2 font-bold text-sm">{col.icon} {col.title}</div>
                            <span className="bg-white/80 px-2 py-0.5 rounded-md text-[10px] font-black">{items.length}</span>
                        </div>
                        <div className="flex-1 overflow-y-auto px-2 pb-4 flex flex-col gap-3">
                            {items.map(req => <RequestCard key={req.id} data={req} />)}
                            <div className="flex-1 min-h-[100px]"></div>
                        </div>
                    </div>
                )
            })}
        </div>
      ) : (
          <div className="flex-1 overflow-auto p-6">
              <div className="bg-white rounded-xl border shadow-sm overflow-hidden">
                  <table className="w-full text-left text-sm">
                      <thead className="bg-slate-50 border-b text-[11px] font-bold text-slate-500 uppercase tracking-wider">
                          <tr>
                              <th className="px-6 py-3">ID</th>
                              <th className="px-6 py-3">Título</th>
                              <th className="px-6 py-3">Área</th>
                              <th className="px-6 py-3">Estado</th>
                              <th className="px-6 py-3">Solicitante</th>
                          </tr>
                      </thead>
                      <tbody className="divide-y">
                          {filteredRequests.map(req => (
                              <tr key={req.id} onClick={() => setSelectedRequestId(req.id)} className="hover:bg-slate-50 cursor-pointer transition-colors">
                                  <td className="px-6 py-4 font-mono text-xs">#{req.id.split('-')[1]}</td>
