                                      <span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase ${STATUS_BADGE_COLORS[req.status]}`}>{req.status}</span>
                                  </td>
                                  <td className="px-6 py-4 text-slate-500">{req.requester}</td>
                              </tr>
                          ))}
                      </tbody>
                  </table>
              </div>
          </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { RequestCard as RequestCardType, Status } from '../types';
import { useSisreq } from '../context/SisreqContext';
import { GripVertical, AlertCircle, ChevronUp, ChevronDown, Clock } from 'lucide-react';

export const RequestCard: React.FC<{ data: RequestCardType }> = ({ data }) => {
  const { setSelectedRequestId, canMoveRequest } = useSisreq();
  const [minimized, setMinimized] = useState(data.status === Status.FINALIZADO);

  const isDraggable = Object.values(Status).some(s => canMoveRequest(data, s));

  const handleDragStart = (e: React.DragEvent) => {
    e.dataTransfer.setData('requestId', data.id);
    e.dataTransfer.effectAllowed = 'move';
  };

  const colors: Record<Status, string> = {
    [Status.RECIBIDO]: 'border-blue-500',
    [Status.DERIVACION]: 'border-orange-500',
    [Status.EJECUCION]: 'border-amber-500',
    [Status.FINALIZADO]: 'border-emerald-500',
  };

  return (
    <div 
        draggable={isDraggable}
        onDragStart={handleDragStart}
        onClick={() => setSelectedRequestId(data.id)}
        className={`bg-white rounded-xl relative group transition-all border border-slate-100 border-l-[4px] cursor-pointer shadow-sm hover:shadow-md ${colors[data.status]} ${isDraggable ? 'active:scale-95' : ''} ${minimized ? 'p-3' : 'p-4'}`}
    >
      <div className="flex justify-between items-start mb-1">
        <div className="flex items-center gap-2">
            {isDraggable && <GripVertical size={14} className="text-slate-300 group-hover:text-indigo-400" />}
            <span className="font-mono text-[9px] text-slate-400">#{data.id.split('-')[1]}</span>
            {data.isReturned && <span className="text-[8px] bg-red-50 text-red-600 px-1.5 py-0.5 rounded font-bold border border-red-100 flex items-center gap-1"><AlertCircle size={8}/> DEVUELTO</span>}
        </div>
        <button onClick={(e) => { e.stopPropagation(); setMinimized(!minimized); }} className="text-slate-300 hover:text-indigo-500 p-1 rounded opacity-0 group-hover:opacity-100 transition-opacity">
            {minimized ? <ChevronDown size={14}/> : <ChevronUp size={14}/>}
        </button>
      </div>

      <h3 className={`font-bold text-slate-800 leading-tight group-hover:text-indigo-600 ${minimized ? 'text-xs truncate' : 'text-sm mb-2'}`}>
          {data.title}
      </h3>

      {!minimized && (
          <div className="animate-in fade-in duration-300">
             <p className="text-[11px] text-slate-500 line-clamp-2 mb-3 bg-slate-50 p-2 rounded">{data.detail}</p>
             <div className="flex items-center justify-between pt-2 border-t text-[10px] text-slate-400">
                 <span className="font-bold text-slate-600">{data.area}</span>
                 <span className="flex items-center gap-1"><Clock size={10}/> {new Date(data.createdAt).toLocaleDateString()}</span>
             </div>
          </div>
      )}
    </div>
  );
};

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { User, RequestCard, Status, Priority, Area, UserRole } from '../types';
import { AREA_HEADS } from '../constants';
import { db } from '../services/storage';

interface SisreqContextType {
  currentUser: User;
  users: User[];
  isAuthenticated: boolean;
  isLoading: boolean;
  login: (user: User) => void;
  logout: () => void;
  updateUser: (updatedUser: User) => Promise<void>;
  addUser: (name: string, email: string, role: UserRole, password: string, area?: Area) => Promise<void>;
  requests: RequestCard[];
  selectedRequestId: string | null;
  setSelectedRequestId: (id: string | null) => void;
  addRequest: (title: string, detail: string, area: Area, priority: Priority, requester: string) => Promise<void>;
  updateStatus: (id: string, newStatus: Status) => Promise<void>;
  returnRequest: (id: string, reason: string) => Promise<void>;
  assignAnalyst: (id: string, analystName: string) => Promise<void>;
  addLog: (id: string, message: string) => Promise<void>;
  updateRequestDetails: (id: string, title: string, detail: string) => Promise<void>;
  viewMode: 'work' | 'superadmin';
  setViewMode: (mode: 'work' | 'superadmin') => void;
  globalFilterArea: Area | 'ALL';
  setGlobalFilterArea: (area: Area | 'ALL') => void;
  canMoveRequest: (request: RequestCard, targetStatus: Status) => boolean;
}

const SisreqContext = createContext<SisreqContextType | undefined>(undefined);

export const SisreqProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [requests, setRequests] = useState<RequestCard[]>([]);
  const [selectedRequestId, setSelectedRequestId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'work' | 'superadmin'>('work');
  const [isLoading, setIsLoading] = useState(true);
  const [globalFilterArea, setGlobalFilterArea] = useState<Area | 'ALL'>('ALL');

  useEffect(() => {
    db.init().then(() => {
      Promise.all([db.getRequests(), db.getUsers()]).then(([reqs, usrs]) => {
        setRequests(reqs);
        setUsers(usrs);
        setIsLoading(false);
      });
    });
  }, []);

  const login = (user: User) => {
    setCurrentUser(users.find(u => u.id === user.id) || user);
    setIsAuthenticated(true);
  };

  const logout = () => {
    setIsAuthenticated(false);
    setCurrentUser(null);
  };

  const canMoveRequest = useCallback((request: RequestCard, target: Status): boolean => {
    if (!currentUser) return false;
    if (currentUser.role === UserRole.SUPERADMIN) return true;

    const isOwnerArea = currentUser.area === request.area;
    const isAssignedToMe = request.assignedAnalyst === currentUser.name;

    switch(currentUser.role) {
      case UserRole.ADMIN:
        return request.status === Status.RECIBIDO && target === Status.DERIVACION;
      case UserRole.HEAD:
        if (!isOwnerArea) return false;
        if (request.status === Status.DERIVACION && target === Status.EJECUCION) return true;
        if (request.status === Status.EJECUCION && target === Status.FINALIZADO) return true;
        return false;
      case UserRole.ANALYST:
        // Analistas: Solo pueden finalizar si el ticket está en ejecución Y les pertenece a su perfil
        return isOwnerArea && isAssignedToMe && request.status === Status.EJECUCION && target === Status.FINALIZADO;
      default: return false;
    }
  }, [currentUser]);

  const updateStatus = async (id: string, newStatus: Status) => {
    const req = requests.find(r => r.id === id);
    if (!req || !canMoveRequest(req, newStatus)) return;

    const updated = { 
      ...req, 
      status: newStatus,
      isReturned: false,
      finishedAt: newStatus === Status.FINALIZADO ? new Date().toISOString() : req.finishedAt,
      // Al volver a Bandeja, siempre se limpia el analista
      assignedAnalyst: newStatus === Status.RECIBIDO ? undefined : req.assignedAnalyst,
      logs: [...req.logs, { id: `l-${Date.now()}`, timestamp: new Date().toISOString(), message: `Estado: ${newStatus}`, actor: currentUser!.name }]
    };
    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const returnRequest = async (id: string, reason: string) => {
    const req = requests.find(r => r.id === id);
    if (!req) return;
    const updated = {
      ...req, status: Status.RECIBIDO, isReturned: true, assignedAnalyst: undefined,
      logs: [...req.logs, { id: `l-${Date.now()}`, timestamp: new Date().toISOString(), message: `DEVUELTO: ${reason}`, actor: currentUser!.name }]
    };
    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const assignAnalyst = async (id: string, analystName: string) => {
    const req = requests.find(r => r.id === id);
    if (!req) return;
    const updated = { 
        ...req, 
        assignedAnalyst: analystName, 
        logs: [...req.logs, { id: `l-${Date.now()}`, timestamp: new Date().toISOString(), message: `Asignado a: ${analystName}`, actor: currentUser!.name }] 
    };
    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const addRequest = async (title: string, detail: string, area: Area, priority: Priority, requester: string) => {
    const newReq: RequestCard = {
      id: `req-${Date.now()}`, title, detail, area, priority, requester,
      status: Status.RECIBIDO, responsibleHead: AREA_HEADS[area], createdAt: new Date().toISOString(),
      logs: [{ id: `l-${Date.now()}`, timestamp: new Date().toISOString(), message: 'Creado', actor: currentUser!.name }]
    };
    await db.saveRequest(newReq);
    setRequests(prev => [...prev, newReq]);
  };

  const addLog = async (id: string, message: string) => {
    const req = requests.find(r => r.id === id);
    if (!req) return;
    const updated = { ...req, logs: [...req.logs, { id: `l-${Date.now()}`, timestamp: new Date().toISOString(), message, actor: currentUser!.name }] };
    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const updateRequestDetails = async (id: string, title: string, detail: string) => {
    const req = requests.find(r => r.id === id);
    if (!req) return;
    const updated = { ...req, title, detail, logs: [...req.logs, { id: `l-${Date.now()}`, timestamp: new Date().toISOString(), message: 'Detalles editados', actor: currentUser!.name }] };
    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const updateUser = async (u: User) => {
    setUsers(prev => prev.map(old => old.id === u.id ? u : old));
    if (currentUser?.id === u.id) setCurrentUser(u);
    await db.saveUser(u);
  };

  const addUser = async (name: string, email: string, role: UserRole, password: string, area?: Area) => {
    const newUser: User = { id: `u-${Date.now()}`, name, email, role, area, password, status: 'ACTIVE', joinedAt: new Date().toISOString() };
    await db.saveUser(newUser);
    setUsers(prev => [...prev, newUser]);
  };

  return (
    <SisreqContext.Provider value={{
      currentUser: currentUser!, users, isAuthenticated, isLoading, login, logout, updateUser, addUser,
      requests, selectedRequestId, setSelectedRequestId, addRequest, updateStatus, returnRequest,
      assignAnalyst, addLog, updateRequestDetails, viewMode, setViewMode, globalFilterArea, setGlobalFilterArea,
      canMoveRequest
    }}>
      {children}
    </SisreqContext.Provider>
  );
};

export const useSisreq = () => {
  const context = useContext(SisreqContext);
  if (!context) throw new Error('useSisreq context error');
  return context;
};

