                        <button onClick={() => setShowReturnInput(true)} className="text-red-500 hover:bg-red-50 px-4 py-2 text-sm font-bold border border-red-100 rounded-lg transition-colors">Devolver</button>
                    </>
                )}

                {/* Finalize: Heads or Specific Analyst */}
                {canMoveRequest(data, Status.FINALIZADO) && (
                    <button onClick={() => updateStatus(data.id, Status.FINALIZADO)} className="bg-emerald-600 hover:bg-emerald-700 text-white px-6 py-2 rounded-lg text-sm font-black shadow-lg shadow-emerald-100 transition-all flex items-center gap-2 active:scale-95"><CheckCircle size={18}/> Finalizar</button>
                )}
             </div>
        </div>

        {/* Return Dialog Portal-like */}
        {showReturnInput && (
            <div className="absolute inset-0 z-[70] flex items-center justify-center bg-slate-900/40 backdrop-blur-[2px] animate-in fade-in">
                <div className="bg-white p-6 rounded-2xl shadow-2xl w-full max-w-sm border border-slate-100 mx-4">
                    <h4 className="text-lg font-black text-slate-800 mb-2">Devolver Requerimiento</h4>
                    <p className="text-xs text-slate-500 mb-4">Indique la razón para que la administración pueda corregir el ticket.</p>
                    <textarea value={returnReason} onChange={e => setReturnReason(e.target.value)} className="w-full border-2 border-slate-100 p-3 rounded-xl text-sm mb-4 outline-none focus:border-red-200 transition-all" placeholder="Ej: Faltan documentos adjuntos..." rows={3} autoFocus />
                    <div className="flex justify-end gap-3">
                        <button onClick={() => setShowReturnInput(false)} className="px-4 py-2 text-xs font-bold text-slate-400 hover:text-slate-600">Cancelar</button>
                        <button onClick={handleReturnSubmit} disabled={!returnReason.trim()} className="bg-red-500 hover:bg-red-600 text-white px-6 py-2 rounded-lg text-xs font-black shadow-md shadow-red-100 disabled:opacity-50">Confirmar Devolución</button>
                    </div>
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { RequestCard } from './RequestCard';
import { Status, UserRole, Area } from '../types';
import { LayoutGrid, List, Search, Filter, Inbox, GitPullRequest, PlayCircle, CheckCircle2 } from 'lucide-react';
import { STATUS_BADGE_COLORS } from '../constants';

export const Board: React.FC = () => {
  const { requests, currentUser, updateStatus, setSelectedRequestId, globalFilterArea, setGlobalFilterArea, canMoveRequest } = useSisreq();
  const [dragOverColumn, setDragOverColumn] = useState<Status | null>(null);
  const [viewMode, setViewMode] = useState<'board' | 'list'>('board');
  const [searchTerm, setSearchTerm] = useState('');

  const filteredRequests = useMemo(() => {
    return requests.filter(req => {
      const isAdmin = currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.SUPERADMIN;
      const isOwnerArea = req.area === currentUser.area && req.status !== Status.RECIBIDO;
      if (!isAdmin && !isOwnerArea) return false;

      const matchesSearch = searchTerm === '' || 
          req.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
          req.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
          req.requester.toLowerCase().includes(searchTerm.toLowerCase());

      const matchesArea = globalFilterArea === 'ALL' || req.area === globalFilterArea;
      return matchesSearch && matchesArea;
    });
  }, [requests, currentUser, searchTerm, globalFilterArea]);

  const handleDrop = (e: React.DragEvent, targetStatus: Status) => {
    e.preventDefault();
    setDragOverColumn(null);
    const requestId = e.dataTransfer.getData('requestId');
    const req = requests.find(r => r.id === requestId);
    if (req && canMoveRequest(req, targetStatus)) {
      updateStatus(requestId, targetStatus);
    }
