    { title: 'Bandeja', status: Status.RECIBIDO, icon: <Inbox size={18} />, color: 'text-blue-700 bg-blue-50 border-blue-100' },
    { title: 'Derivación', status: Status.DERIVACION, icon: <GitPullRequest size={18} />, color: 'text-orange-700 bg-orange-50 border-orange-100' },
    { title: 'Ejecución', status: Status.EJECUCION, icon: <PlayCircle size={18} />, color: 'text-amber-700 bg-amber-50 border-amber-100' },
