                        </div>
                    )}
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { RequestCard as RequestCardType, Status, Priority } from '../types';
import { useSisreq } from '../context/SisreqContext';
import { GripVertical, AlertCircle, ChevronUp, ChevronDown, Clock, User } from 'lucide-react';

export const RequestCard: React.FC<{ data: RequestCardType }> = ({ data }) => {
  const { setSelectedRequestId, canMoveRequest } = useSisreq();
  const [minimized, setMinimized] = useState(data.status === Status.FINALIZADO);

  const isDraggable = Object.values(Status).some(s => canMoveRequest(data, s));

  const handleDragStart = (e: React.DragEvent) => {
    e.dataTransfer.setData('requestId', data.id);
    e.dataTransfer.effectAllowed = 'move';
  };

  const statusColors: Record<Status, string> = {
    [Status.RECIBIDO]: 'border-blue-400',
    [Status.DERIVACION]: 'border-orange-400',
    [Status.EJECUCION]: 'border-amber-400',
    [Status.FINALIZADO]: 'border-emerald-400',
  };

  const isHighPriority = data.priority === Priority.HIGH;

  return (
    <div 
        draggable={isDraggable}
        onDragStart={handleDragStart}
        onClick={() => setSelectedRequestId(data.id)}
        className={`bg-white rounded-2xl relative group transition-all duration-200 border border-slate-200 border-l-[6px] cursor-pointer shadow-sm hover:shadow-xl hover:-translate-y-0.5 ${statusColors[data.status]} ${isDraggable ? 'active:scale-95 active:cursor-grabbing' : ''} ${minimized ? 'p-3' : 'p-4'}`}
    >
      {/* Top Meta Info */}
      <div className="flex justify-between items-start mb-1.5">
        <div className="flex items-center gap-2">
            {isDraggable && <GripVertical size={14} className="text-slate-200 group-hover:text-indigo-400 transition-colors" />}
            <span className="font-mono text-[9px] font-black text-slate-400 tracking-tight">#{data.id.split('-')[1]}</span>
            {data.isReturned && <span className="text-[8px] bg-red-50 text-red-600 px-1.5 py-0.5 rounded-md font-black border border-red-100 flex items-center gap-1"><AlertCircle size={8}/> DEVUELTO</span>}
            {isHighPriority && !data.isReturned && <div className="w-2 h-2 rounded-full bg-red-500 animate-pulse shadow-[0_0_8px_rgba(239,68,68,0.5)]" title="Alta Prioridad"></div>}
        </div>
        <button onClick={(e) => { e.stopPropagation(); setMinimized(!minimized); }} className="text-slate-300 hover:text-indigo-500 p-1 rounded-lg opacity-0 group-hover:opacity-100 transition-all hover:bg-indigo-50">
            {minimized ? <ChevronDown size={14}/> : <ChevronUp size={14}/>}
        </button>
      </div>

      {/* Title */}
      <h3 className={`font-black text-slate-800 leading-tight group-hover:text-indigo-600 transition-colors ${minimized ? 'text-xs truncate' : 'text-[13px] mb-2.5'}`}>
          {data.title}
      </h3>

      {/* Expanded Content */}
      {!minimized && (
          <div className="animate-in fade-in slide-in-from-top-1 duration-300 space-y-3">
             <p className="text-[11px] text-slate-500 line-clamp-2 leading-relaxed bg-slate-50/50 p-2 rounded-lg border border-slate-100 font-medium">{data.detail}</p>

             <div className="flex items-center justify-between pt-2 border-t border-slate-50 text-[10px] font-bold">
                 <div className="flex items-center gap-2">
                    {data.assignedAnalyst ? (
                        <div className="flex items-center gap-1.5 text-indigo-600 bg-indigo-50 px-2 py-0.5 rounded-full border border-indigo-100 shadow-sm">
                            <User size={10} />
                            <span className="truncate max-w-[80px]">{data.assignedAnalyst.split(' ')[0]}</span>
                        </div>
                    ) : (
                        <span className="text-slate-400 uppercase tracking-widest text-[9px]">{data.area}</span>
                    )}
                 </div>
                 <span className="flex items-center gap-1 text-slate-300 font-mono"><Clock size={10}/> {new Date(data.createdAt).toLocaleDateString([], {day:'2-digit', month:'2-digit'})}</span>
             </div>
          </div>
      )}

      {/* Visual Feedback for High Priority on Minimized */}
      {minimized && isHighPriority && <div className="absolute top-0 right-0 h-1.5 w-1.5 bg-red-500 rounded-full mt-2 mr-2"></div>}
    </div>
  );
};

