                    <table className="w-full text-left text-sm border-collapse">
                        <thead className="bg-slate-50 border-b text-[10px] font-black text-slate-500 uppercase tracking-widest">
                            <tr>
                                <th className="px-6 py-4">ID</th>
                                <th className="px-6 py-4">Título</th>
                                <th className="px-6 py-4">Área</th>
                                <th className="px-6 py-4">Prioridad</th>
                                <th className="px-6 py-4">Estado</th>
                                <th className="px-6 py-4">Solicitante</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                            {filteredRequests.map(req => (
                                <tr key={req.id} onClick={() => setSelectedRequestId(req.id)} className="hover:bg-indigo-50/40 cursor-pointer transition-all group">
                                    <td className="px-6 py-4 font-mono text-xs text-slate-400 group-hover:text-indigo-600">#{req.id.split('-')[1]}</td>
                                    <td className="px-6 py-4">
                                        <div className="font-bold text-slate-700 group-hover:text-indigo-800 transition-colors">{req.title}</div>
                                        {/* Clock is used here below */}
                                        <div className="text-[10px] text-slate-400 flex items-center gap-1 mt-0.5"><Clock size={10}/> {new Date(req.createdAt).toLocaleDateString()}</div>
                                    </td>
                                    <td className="px-6 py-4 text-xs font-bold text-slate-500">{req.area}</td>
                                    <td className="px-6 py-4">
                                        <span className={`px-2 py-0.5 rounded-full text-[9px] font-black uppercase ${req.priority === 'Alta' ? 'bg-red-100 text-red-600' : 'bg-slate-100 text-slate-500'}`}>{req.priority}</span>
                                    </td>
                                    <td className="px-6 py-4">
                                        <span className={`px-3 py-1 rounded-lg text-[10px] font-black uppercase shadow-sm ${STATUS_BADGE_COLORS[req.status]}`}>{req.status}</span>
                                    </td>
                                    <td className="px-6 py-4 text-slate-600 text-xs font-medium">{req.requester}</td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                    {filteredRequests.length === 0 && (
                        <div className="p-20 text-center flex flex-col items-center gap-2">
                             <Search size={40} className="text-slate-100"/>
                             <p className="text-slate-400 font-bold">No se encontraron resultados para tu búsqueda</p>
                        </div>
                    )}
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { Area, UserRole, User, UserStatus } from '../types';
import { X, UserPlus, User as UserIcon, Building, Lock, Mail, Shield, Check, Save, Power, AlertCircle } from 'lucide-react';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  userToEdit?: User | null; // Optional prop for editing mode
}

export const NewUserModal: React.FC<Props> = ({ isOpen, onClose, userToEdit }) => {
  const { addUser, updateUser } = useSisreq();
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [role, setRole] = useState<UserRole>(UserRole.ANALYST);
  const [area, setArea] = useState<Area | 'NONE'>('NONE');
  const [password, setPassword] = useState('');
  const [status, setStatus] = useState<UserStatus>('ACTIVE');
  const [errors, setErrors] = useState<{name?: string, email?: string, password?: string}>({});

  // Reset or Populate form when opening
  useEffect(() => {
    if (isOpen) {
        setErrors({});
        if (userToEdit) {
            // Edit Mode
            setName(userToEdit.name);
            setEmail(userToEdit.email || '');
            setRole(userToEdit.role);
            setArea(userToEdit.area || 'NONE');
            setStatus(userToEdit.status || 'ACTIVE');
            setPassword(''); // Clear password field for security (leave empty to keep current)
        } else {
            // Create Mode
            setName('');
            setEmail('');
            setRole(UserRole.ANALYST);
            setArea(Area.CONTABILIDAD); // Default area for Analyst
            setStatus('ACTIVE');
            setPassword('');
        }
    }
  }, [isOpen, userToEdit]);

  // Determine if Area is needed based on Role
  const needsArea = role === UserRole.HEAD || role === UserRole.ANALYST;

  const handleRoleChange = (newRole: UserRole) => {
    setRole(newRole);

    const roleRequiresArea = newRole === UserRole.HEAD || newRole === UserRole.ANALYST;

    if (!roleRequiresArea) {
        setArea('NONE');
    } else {
        // If we switched to a role needing area, and currently don't have one (or it's NONE), set default
        if (area === 'NONE' || !area) {
             setArea(Area.CONTABILIDAD);
        }
    }
  };

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    const newErrors: {name?: string, email?: string, password?: string} = {};

    if (!name.trim()) {
      newErrors.name = 'El nombre es requerido';
    }

    if (!email.trim()) {
      newErrors.email = 'El correo electrónico es requerido';
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      newErrors.email = 'Formato de correo no válido';
    }

    if (!userToEdit && !password.trim()) {
      newErrors.password = 'La contraseña es requerida para nuevos usuarios';
    }

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }

    setErrors({});

    // Ensure finalArea is undefined if not needed, or the specific area if needed
    const finalArea = needsArea && area !== 'NONE' ? (area as Area) : undefined;

    if (userToEdit) {
        // Update Logic
        const updatedUser: User = {
            ...userToEdit,
            name: name.trim(),
            email: email.trim(),
            role,
            area: finalArea,
            status,
            // Only update password if user typed something new
            password: password.trim() ? password.trim() : userToEdit.password
        };
        updateUser(updatedUser);
    } else {
        // Create Logic
        addUser(name.trim(), email.trim(), role, password.trim(), finalArea);
    }

    onClose();
  };

  const isEditMode = !!userToEdit;

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm transition-opacity" 
        onClick={onClose} 
      />

      {/* Modal Card */}
      <div className="relative bg-white rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden animate-in fade-in zoom-in-95 duration-200 border border-white/20">

        {/* Header */}
        <div className="bg-gradient-to-r from-slate-50 to-white border-b border-slate-100 px-6 py-5 flex justify-between items-center">
          <div className="flex items-center gap-3">
             <div className={`p-2.5 rounded-xl shadow-sm border ${isEditMode ? 'bg-indigo-600 text-white border-indigo-700' : 'bg-indigo-100 text-indigo-600 border-indigo-200/50'}`}>
                {isEditMode ? <UserIcon size={20} /> : <UserPlus size={20} className="stroke-2"/>}
             </div>
             <div>
                <h2 className="text-lg font-black text-slate-800 tracking-tight leading-none mb-1">
                    {isEditMode ? 'Editar Usuario' : 'Nuevo Usuario'}
                </h2>
                <p className="text-xs text-slate-500 font-medium">
                    {isEditMode ? 'Modificar datos de acceso y perfil' : 'Registrar nuevo miembro del equipo'}
                </p>
             </div>
          </div>
          <button 
            onClick={onClose} 
            className="text-slate-400 hover:text-slate-600 p-2 hover:bg-slate-100 rounded-full transition-colors"
          >
            <X size={20} />
          </button>
        </div>

        {/* Form Body */}
        <form onSubmit={handleSubmit} className="p-6 space-y-5">

            {/* Name */}
            <div className="space-y-2">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider flex items-center gap-1.5">
                    <UserIcon size={12} /> Nombre Completo
                </label>
                <input
                    type="text"
                    className={`w-full bg-slate-50 border ${errors.name ? 'border-red-500 ring-1 ring-red-100' : 'border-slate-200'} text-slate-700 text-sm rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 transition-all placeholder:text-slate-400 font-medium`}
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    placeholder="Ej: Juan Pérez"
                    autoFocus
                />
                {errors.name && (
                  <p className="text-[10px] text-red-500 font-bold flex items-center gap-1"><AlertCircle size={10}/> {errors.name}</p>
                )}
            </div>

            {/* Email */}
            <div className="space-y-2">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider flex items-center gap-1.5">
                    <Mail size={12} /> Correo Electrónico
                </label>
                <input
                    type="text"
                    className={`w-full bg-slate-50 border ${errors.email ? 'border-red-500 ring-1 ring-red-100' : 'border-slate-200'} text-slate-700 text-sm rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 transition-all placeholder:text-slate-400 font-medium`}
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    placeholder="ejemplo@sisreq.com"
                />
                {errors.email && (
                  <p className="text-[10px] text-red-500 font-bold flex items-center gap-1"><AlertCircle size={10}/> {errors.email}</p>
                )}
            </div>

            <div className="grid grid-cols-2 gap-4">
                {/* Role */}
                <div className="space-y-2">
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider flex items-center gap-1.5">
                        <Shield size={12} /> Rol
                    </label>
                    <div className="relative">
                        <select
                            className="w-full bg-slate-50 border border-slate-200 text-slate-700 text-sm rounded-xl px-4 py-3 appearance-none focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 transition-all cursor-pointer font-medium"
                            value={role}
                            onChange={(e) => handleRoleChange(e.target.value as UserRole)}
                        >
                            {Object.values(UserRole).map((r) => (
                                <option key={r} value={r}>{r}</option>
                            ))}
                        </select>
                         <div className="absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">
                            <svg className="w-4 h-4 fill-current" viewBox="0 0 20 20"><path d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z"/></svg>
                        </div>
                    </div>
                </div>

                {/* Area (Conditional) */}
                <div className="space-y-2">
                    <label className={`text-[10px] font-bold uppercase tracking-wider flex items-center gap-1.5 ${needsArea ? 'text-slate-400' : 'text-slate-300'}`}>
                        <Building size={12} /> Área
                    </label>
                    <div className="relative">
                        <select
                            disabled={!needsArea}
                            className={`w-full border text-sm rounded-xl px-4 py-3 appearance-none transition-all font-medium ${
                                needsArea 
                                ? 'bg-slate-50 border-slate-200 text-slate-700 focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 cursor-pointer' 
                                : 'bg-slate-100 border-slate-200 text-slate-400 cursor-not-allowed'
                            }`}
                            value={area}
                            onChange={(e) => setArea(e.target.value as Area)}
                        >
                             {!needsArea && <option value="NONE">N/A</option>}
                             {Object.values(Area).map((a) => (
                                <option key={a} value={a}>{a}</option>
                             ))}
                        </select>
                        <div className={`absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none ${needsArea ? 'text-slate-400' : 'text-slate-300'}`}>
                            <svg className="w-4 h-4 fill-current" viewBox="0 0 20 20"><path d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z"/></svg>
                        </div>
                    </div>
                </div>
            </div>

            {/* Password */}
            <div className="space-y-2">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider flex items-center gap-1.5">
                    <Lock size={12} /> Contraseña
                </label>
                <input
                    type="password"
                    className={`w-full bg-slate-50 border ${errors.password ? 'border-red-500 ring-1 ring-red-100' : 'border-slate-200'} text-slate-700 text-sm rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 transition-all placeholder:text-slate-400 font-medium`}
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    placeholder={isEditMode ? "Dejar en blanco para mantener actual" : "Clave de acceso"}
                />
                {errors.password && (
                  <p className="text-[10px] text-red-500 font-bold flex items-center gap-1"><AlertCircle size={10}/> {errors.password}</p>
                )}
            </div>

            {/* Status (Only show in edit mode) */}
            {isEditMode && (
                <div className="space-y-2">
                     <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider flex items-center gap-1.5">
                        <Power size={12} /> Estado del Usuario
                    </label>
                    <div className="flex gap-4">
                        <button
                            type="button"
                            onClick={() => setStatus('ACTIVE')}
                            className={`flex-1 py-2.5 rounded-xl border text-xs font-bold transition-all flex items-center justify-center gap-2 ${
                                status === 'ACTIVE' 
                                ? 'bg-emerald-50 border-emerald-200 text-emerald-600 ring-1 ring-emerald-500/20' 
                                : 'bg-white border-slate-200 text-slate-400 hover:bg-slate-50'
                            }`}
                        >
                            <Check size={14} /> Activo
                        </button>
                        <button
                            type="button"
                            onClick={() => setStatus('INACTIVE')}
                             className={`flex-1 py-2.5 rounded-xl border text-xs font-bold transition-all flex items-center justify-center gap-2 ${
                                status === 'INACTIVE' 
                                ? 'bg-slate-100 border-slate-300 text-slate-600 ring-1 ring-slate-500/20' 
                                : 'bg-white border-slate-200 text-slate-400 hover:bg-slate-50'
                            }`}
                        >
                            <Lock size={14} /> Inactivo
                        </button>
                    </div>
                </div>
            )}

           {/* Footer */}
           <div className="pt-4 flex items-center justify-end gap-3 border-t border-slate-100 mt-2">
                <button
                    type="button"
                    onClick={onClose}
                    className="px-5 py-2.5 text-slate-500 font-bold text-sm hover:bg-slate-50 rounded-xl transition-colors"
                >
                    Cancelar
                </button>
                <button
                    type="submit"
                    className="bg-indigo-600 hover:bg-indigo-700 text-white font-bold text-sm px-6 py-2.5 rounded-xl shadow-lg shadow-indigo-200 hover:shadow-xl hover:translate-y-[-1px] transition-all flex items-center gap-2 active:scale-95"
                >
                    {isEditMode ? <Save size={16}/> : <Check size={16} />} 
                    {isEditMode ? 'Guardar Cambios' : 'Crear Usuario'}
                </button>
           </div>
        </form>
      </div>
    </div>
  );
};

import React from 'react';
import { RequestCard as RequestCardType, Status, Priority } from '../types';
import { useSisreq } from '../context/SisreqContext';
import { Clock, User, AlertCircle } from 'lucide-react';

export const RequestCard: React.FC<{ data: RequestCardType }> = ({ data }) => {
  const { setSelectedRequestId, canMoveRequest } = useSisreq();

  const isDraggable = Object.values(Status).some(s => canMoveRequest(data, s));

  const handleDragStart = (e: React.DragEvent) => {
    e.dataTransfer.setData('requestId', data.id);
    e.dataTransfer.effectAllowed = 'move';
  };

  const priorityStyles = {
    [Priority.HIGH]: 'bg-red-50 text-red-600 border-red-100',
    [Priority.MEDIUM]: 'bg-amber-50 text-amber-600 border-amber-100',
    [Priority.LOW]: 'bg-slate-50 text-slate-500 border-slate-100',
  };

  return (
    <div 
        draggable={isDraggable}
        onDragStart={handleDragStart}
        onClick={() => setSelectedRequestId(data.id)}
        className={`bg-white rounded-xl p-4 border border-slate-200 transition-all duration-200 cursor-pointer shadow-sm hover:shadow-md hover:border-indigo-200 group relative flex flex-col gap-3 ${isDraggable ? 'active:scale-[0.98] active:cursor-grabbing' : ''}`}
    >
      {/* Header: ID y Prioridad */}
      <div className="flex justify-between items-center">
        <span className="text-[10px] font-mono font-medium text-slate-400">#{data.id.split('-')[1]}</span>
        <div className="flex items-center gap-1.5">
            {data.isReturned && (
                <span className="flex items-center gap-1 text-[9px] font-black text-red-500 bg-red-50 px-1.5 py-0.5 rounded-md border border-red-100">
                    <AlertCircle size={10}/> DEVUELTO
                </span>
            )}
            <span className={`text-[9px] font-bold px-2 py-0.5 rounded-full border ${priorityStyles[data.priority]}`}>
                {data.priority}
            </span>
        </div>
      </div>

      {/* Body: Título */}
      <h3 className="text-sm font-semibold text-slate-800 leading-tight group-hover:text-indigo-600 transition-colors line-clamp-2">
          {data.title}
      </h3>

      {/* Footer: Metadatos sutiles */}
      <div className="flex items-center justify-between mt-1 pt-3 border-t border-slate-50">
        <div className="flex items-center gap-3">
            <div className="flex items-center gap-1 text-[10px] text-slate-400 font-medium">
                <Clock size={12} className="text-slate-300" />
                {new Date(data.createdAt).toLocaleDateString([], { day: '2-digit', month: 'short' })}
            </div>
            {data.assignedAnalyst ? (
                <div className="flex items-center gap-1 text-[10px] text-indigo-500 font-bold" title={`Asignado a: ${data.assignedAnalyst}`}>
                    <User size={12} className="text-indigo-300" />
                    <span className="max-w-[60px] truncate">{data.assignedAnalyst.split(' ')[0]}</span>
                </div>
            ) : (
                <span className="text-[9px] font-bold text-slate-300 uppercase tracking-tighter">{data.area}</span>
            )}
        </div>

        {/* Indicador visual de "Click para ver más" sutil */}
        <div className="w-1 h-1 rounded-full bg-slate-200 group-hover:bg-indigo-400 group-hover:scale-150 transition-all"></div>
      </div>

      {/* Overlay sutil para drag handle visual si es necesario */}
      {isDraggable && (
        <div className="absolute left-0 top-1/2 -translate-y-1/2 w-0.5 h-8 bg-indigo-500/0 group-hover:bg-indigo-500/40 rounded-r-full transition-all"></div>
      )}
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { RequestCard } from './RequestCard';
import { Status, UserRole, Area } from '../types';
import { LayoutGrid, List, Search, Filter, Inbox, GitPullRequest, PlayCircle, CheckCircle2, Clock, ChevronDown } from 'lucide-react';
import { STATUS_BADGE_COLORS } from '../constants';

export const Board: React.FC = () => {
  const { requests, currentUser, updateStatus, setSelectedRequestId, globalFilterArea, setGlobalFilterArea, canMoveRequest } = useSisreq();
  const [dragOverColumn, setDragOverColumn] = useState<Status | null>(null);
  const [viewMode, setViewMode] = useState<'board' | 'list'>('board');
  const [searchTerm, setSearchTerm] = useState('');

  const filteredRequests = useMemo(() => {
    return requests.filter(req => {
      const isAdmin = currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.SUPERADMIN;
      const isOwnerArea = req.area === currentUser.area && req.status !== Status.RECIBIDO;
      if (!isAdmin && !isOwnerArea) return false;

      const matchesSearch = searchTerm === '' || 
          req.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
          req.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
          req.requester.toLowerCase().includes(searchTerm.toLowerCase());

      const matchesArea = globalFilterArea === 'ALL' || req.area === globalFilterArea;
      return matchesSearch && matchesArea;
    });
  }, [requests, currentUser, searchTerm, globalFilterArea]);

  const handleDrop = (e: React.DragEvent, targetStatus: Status) => {
    e.preventDefault();
    setDragOverColumn(null);
    const requestId = e.dataTransfer.getData('requestId');
    const req = requests.find(r => r.id === requestId);
    if (req && canMoveRequest(req, targetStatus)) {
      updateStatus(requestId, targetStatus);
    }
  };

  const COLUMNS = [
    { title: 'Bandeja', status: Status.RECIBIDO, icon: <Inbox size={16} />, color: 'border-blue-200' },
    { title: 'Derivación', status: Status.DERIVACION, icon: <GitPullRequest size={16} />, color: 'border-orange-200' },
    { title: 'Ejecución', status: Status.EJECUCION, icon: <PlayCircle size={16} />, color: 'border-amber-200' },
    { title: 'Finalizado', status: Status.FINALIZADO, icon: <CheckCircle2 size={16} />, color: 'border-emerald-200' }
  ];

  return (
    <div className="flex flex-col h-full overflow-hidden">
      {/* Minimalist Toolbar */}
      <div className="px-6 py-4 flex flex-col md:flex-row items-center justify-between gap-4 border-b bg-white z-20">
          <div className="flex items-center gap-6">
             <h2 className="text-base font-bold text-slate-800 tracking-tight">Gestión de Requerimientos</h2>
             <div className="flex bg-slate-100 p-1 rounded-lg items-center gap-0.5">
                <button onClick={() => setViewMode('board')} className={`p-1.5 rounded-md transition-all ${viewMode === 'board' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-500'}`}><LayoutGrid size={16}/></button>
                <button onClick={() => setViewMode('list')} className={`p-1.5 rounded-md transition-all ${viewMode === 'list' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-500'}`}><List size={16}/></button>
             </div>
          </div>

          <div className="flex items-center gap-3 w-full md:w-auto">
             <div className="relative flex-1 md:flex-none">
                <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"/>
                <input 
                    type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="Buscar..."
                    className="pl-9 pr-3 py-2 text-sm bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 outline-none w-full md:w-48 transition-all"
                />
             </div>

             {(currentUser.role === UserRole.SUPERADMIN || currentUser.role === UserRole.ADMIN) && (
                <div className="relative">
                    <select
                        value={globalFilterArea} onChange={(e) => setGlobalFilterArea(e.target.value as Area | 'ALL')}
                        className="pl-3 pr-8 py-2 text-sm font-semibold border border-slate-200 rounded-xl bg-slate-50 outline-none cursor-pointer hover:bg-white transition-all appearance-none"
                    >
                        <option value="ALL">Todas las Áreas</option>
                        {Object.values(Area).map(a => <option key={a} value={a}>{a}</option>)}
                    </select>
                    <ChevronDown size={14} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none"/>
                </div>
             )}
          </div>
      </div>

      {/* Main Board Area */}
      <div className="flex-1 overflow-hidden bg-slate-50/30">
        {viewMode === 'board' ? (
