import React, { useState, useEffect } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { Area, UserRole, User, UserStatus } from '../types';
import { X, UserPlus, User as UserIcon, Building, Lock, Mail, Shield, Check, Save, Power, AlertCircle } from 'lucide-react';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  userToEdit?: User | null;
}

export const NewUserModal: React.FC<Props> = ({ isOpen, onClose, userToEdit }) => {
  const { addUser, updateUser } = useSisreq();
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [role, setRole] = useState<UserRole>(UserRole.ANALYST);
  const [area, setArea] = useState<Area | 'NONE'>('NONE');
  const [password, setPassword] = useState('');
  const [status, setStatus] = useState<UserStatus>('ACTIVE');
  const [errors, setErrors] = useState<{name?: string, email?: string, password?: string}>({});

  useEffect(() => {
    if (isOpen) {
        setErrors({});
        if (userToEdit) {
            setName(userToEdit.name);
            setEmail(userToEdit.email || '');
            setRole(userToEdit.role);
            setArea(userToEdit.area || 'NONE');
            setStatus(userToEdit.status || 'ACTIVE');
            setPassword('');
        } else {
            setName('');
            setEmail('');
            setRole(UserRole.ANALYST);
            setArea(Area.CONTABILIDAD);
            setStatus('ACTIVE');
            setPassword('');
        }
    }
  }, [isOpen, userToEdit]);

  const needsArea = role === UserRole.HEAD || role === UserRole.ANALYST;

  const handleRoleChange = (newRole: UserRole) => {
    setRole(newRole);
    if (!(newRole === UserRole.HEAD || newRole === UserRole.ANALYST)) {
        setArea('NONE');
    } else if (area === 'NONE' || !area) {
        setArea(Area.CONTABILIDAD);
    }
  };

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newErrors: {name?: string, email?: string, password?: string} = {};

    if (!name.trim()) newErrors.name = 'El nombre es requerido';
    if (!email.trim()) newErrors.email = 'El email es requerido';
    else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) newErrors.email = 'Formato no válido';
    if (!userToEdit && !password.trim()) newErrors.password = 'La contraseña es requerida';

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }

    const finalArea = needsArea && area !== 'NONE' ? (area as Area) : undefined;

    if (userToEdit) {
        updateUser({
            ...userToEdit,
            name: name.trim(),
            email: email.trim(),
            role,
            area: finalArea,
            status,
            password: password.trim() ? password.trim() : userToEdit.password
        });
    } else {
        addUser(name.trim(), email.trim(), role, password.trim(), finalArea);
    }
    onClose();
  };

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={onClose} />
      <div className="relative bg-white rounded-2xl shadow-xl w-full max-w-md overflow-hidden animate-in fade-in zoom-in-95 duration-200">
        <div className="border-b px-6 py-4 flex justify-between items-center bg-slate-50">
          <h2 className="text-base font-bold text-slate-800">{userToEdit ? 'Editar Perfil' : 'Nuevo Usuario'}</h2>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600"><X size={20} /></button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-4">
            <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Nombre Completo</label>
                <input
                    type="text"
                    className={`w-full bg-slate-50 border ${errors.name ? 'border-red-400 ring-1 ring-red-100' : 'border-slate-200'} text-sm rounded-xl px-4 py-2.5 focus:outline-none focus:border-indigo-400 transition-all font-medium`}
                    value={name} onChange={(e) => setName(e.target.value)} placeholder="Ej: Juan Pérez"
                />
                {errors.name && <p className="text-[10px] text-red-500 font-bold">{errors.name}</p>}
            </div>

            <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Email</label>
                <input
                    type="text"
                    className={`w-full bg-slate-50 border ${errors.email ? 'border-red-400 ring-1 ring-red-100' : 'border-slate-200'} text-sm rounded-xl px-4 py-2.5 focus:outline-none focus:border-indigo-400 transition-all font-medium`}
                    value={email} onChange={(e) => setEmail(e.target.value)} placeholder="juan@empresa.com"
                />
                {errors.email && <p className="text-[10px] text-red-500 font-bold">{errors.email}</p>}
            </div>

            <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Rol</label>
                    <select
                        className="w-full bg-slate-50 border border-slate-200 text-sm rounded-xl px-3 py-2.5 outline-none focus:border-indigo-400 font-medium"
                        value={role} onChange={(e) => handleRoleChange(e.target.value as UserRole)}
                    >
                        {Object.values(UserRole).map(r => <option key={r} value={r}>{r}</option>)}
                    </select>
                </div>
                <div className="space-y-1">
                    <label className={`text-[10px] font-bold uppercase tracking-widest ${needsArea ? 'text-slate-400' : 'text-slate-200'}`}>Área</label>
                    <select
                        disabled={!needsArea}
                        className={`w-full text-sm rounded-xl px-3 py-2.5 outline-none font-medium transition-all ${needsArea ? 'bg-slate-50 border border-slate-200 focus:border-indigo-400' : 'bg-slate-100 border-transparent text-slate-300'}`}
                        value={area} onChange={(e) => setArea(e.target.value as Area)}
                    >
                        {!needsArea && <option value="NONE">N/A</option>}
                        {Object.values(Area).map(a => <option key={a} value={a}>{a}</option>)}
                    </select>
                </div>
            </div>

            <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Contraseña</label>
                <input
                    type="password"
                    className={`w-full bg-slate-50 border ${errors.password ? 'border-red-400' : 'border-slate-200'} text-sm rounded-xl px-4 py-2.5 focus:outline-none focus:border-indigo-400 font-medium`}
                    value={password} onChange={(e) => setPassword(e.target.value)} placeholder={userToEdit ? "••••••••" : "Clave de acceso"}
                />
                {errors.password && <p className="text-[10px] text-red-500 font-bold">{errors.password}</p>}
            </div>

            <div className="pt-4 flex justify-end gap-3 border-t">
                <button type="button" onClick={onClose} className="px-4 py-2 text-slate-400 text-xs font-bold">Cancelar</button>
                <button type="submit" className="bg-slate-800 text-white px-6 py-2 rounded-xl text-xs font-bold shadow-md hover:bg-slate-900 transition-all">
                    {userToEdit ? 'Guardar Cambios' : 'Crear Usuario'}
                </button>
            </div>
        </form>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { RequestCard } from './RequestCard';
// Added Priority to the imports below to fix the error on line 144
import { Status, UserRole, Area, Priority } from '../types';
import { LayoutGrid, List, Search, Filter, Inbox, GitPullRequest, PlayCircle, CheckCircle2, Clock, ChevronDown } from 'lucide-react';
import { STATUS_BADGE_COLORS } from '../constants';

export const Board: React.FC = () => {
  const { requests, currentUser, updateStatus, setSelectedRequestId, globalFilterArea, setGlobalFilterArea, canMoveRequest } = useSisreq();
  const [dragOverColumn, setDragOverColumn] = useState<Status | null>(null);
  const [viewMode, setViewMode] = useState<'board' | 'list'>('board');
  const [searchTerm, setSearchTerm] = useState('');

  const filteredRequests = useMemo(() => {
    return requests.filter(req => {
      const isAdmin = currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.SUPERADMIN;
      const isOwnerArea = req.area === currentUser.area && req.status !== Status.RECIBIDO;
      if (!isAdmin && !isOwnerArea) return false;

      const matchesSearch = searchTerm === '' || 
          req.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
          req.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
          req.requester.toLowerCase().includes(searchTerm.toLowerCase());

      const matchesArea = globalFilterArea === 'ALL' || req.area === globalFilterArea;
      return matchesSearch && matchesArea;
    });
  }, [requests, currentUser, searchTerm, globalFilterArea]);

  const handleDrop = (e: React.DragEvent, targetStatus: Status) => {
    e.preventDefault();
    setDragOverColumn(null);
    const requestId = e.dataTransfer.getData('requestId');
    const req = requests.find(r => r.id === requestId);
    if (req && canMoveRequest(req, targetStatus)) {
      updateStatus(requestId, targetStatus);
    }
  };

  const COLUMNS = [
    { title: 'Bandeja', status: Status.RECIBIDO, icon: <Inbox size={16} />, color: 'border-blue-200' },
    { title: 'Derivación', status: Status.DERIVACION, icon: <GitPullRequest size={16} />, color: 'border-orange-200' },
    { title: 'Ejecución', status: Status.EJECUCION, icon: <PlayCircle size={16} />, color: 'border-amber-200' },
    { title: 'Finalizado', status: Status.FINALIZADO, icon: <CheckCircle2 size={16} />, color: 'border-emerald-200' }
  ];

  return (
    <div className="flex flex-col h-full overflow-hidden">
      {/* Minimalist Toolbar */}
      <div className="px-6 py-4 flex flex-col md:flex-row items-center justify-between gap-4 border-b bg-white z-20">
          <div className="flex items-center gap-6">
             <h2 className="text-base font-bold text-slate-800 tracking-tight">Gestión de Requerimientos</h2>
             <div className="flex bg-slate-100 p-1 rounded-lg items-center gap-0.5">
                <button onClick={() => setViewMode('board')} className={`p-1.5 rounded-md transition-all ${viewMode === 'board' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-500'}`}><LayoutGrid size={16}/></button>
                <button onClick={() => setViewMode('list')} className={`p-1.5 rounded-md transition-all ${viewMode === 'list' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-500'}`}><List size={16}/></button>
             </div>
          </div>

          <div className="flex items-center gap-3 w-full md:w-auto">
             <div className="relative flex-1 md:flex-none">
                <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"/>
                <input 
                    type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="Buscar..."
                    className="pl-9 pr-3 py-2 text-sm bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 outline-none w-full md:w-48 transition-all"
                />
             </div>

             {(currentUser.role === UserRole.SUPERADMIN || currentUser.role === UserRole.ADMIN) && (
                <div className="relative">
                    <select
                        value={globalFilterArea} onChange={(e) => setGlobalFilterArea(e.target.value as Area | 'ALL')}
                        className="pl-3 pr-8 py-2 text-sm font-semibold border border-slate-200 rounded-xl bg-slate-50 outline-none cursor-pointer hover:bg-white transition-all appearance-none"
                    >
                        <option value="ALL">Todas las Áreas</option>
                        {Object.values(Area).map(a => <option key={a} value={a}>{a}</option>)}
                    </select>
                    <ChevronDown size={14} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none"/>
                </div>
             )}
          </div>
      </div>

      {/* Main Board Area */}
      <div className="flex-1 overflow-hidden bg-slate-50/30">
        {viewMode === 'board' ? (
          <div className="h-full overflow-x-auto p-6 flex gap-6 scroll-smooth">
              {COLUMNS.map((col) => {
                  const items = filteredRequests.filter(r => r.status === col.status);
                  const isOver = dragOverColumn === col.status;
                  return (
                      <div 
                          key={col.status} 
                          className={`flex-1 flex flex-col min-w-[300px] max-w-[350px] transition-all rounded-xl ${isOver ? 'bg-indigo-50/50 ring-2 ring-indigo-200' : ''}`}
                          onDragOver={(e) => { e.preventDefault(); setDragOverColumn(col.status); }}
                          onDragLeave={() => setDragOverColumn(null)}
                          onDrop={(e) => handleDrop(e, col.status)}
                      >
                          {/* Minimal Header */}
                          <div className="flex items-center justify-between mb-4 px-1">
                              <div className="flex items-center gap-2">
                                  <div className="text-slate-400">{col.icon}</div>
                                  <span className="text-xs font-bold text-slate-500 uppercase tracking-widest">{col.title}</span>
                              </div>
                              <span className="text-[10px] font-bold bg-slate-200 text-slate-500 px-2 py-0.5 rounded-full">{items.length}</span>
                          </div>

                          {/* Cards Scroll Area */}
                          <div className="flex-1 overflow-y-auto custom-scrollbar flex flex-col gap-3 pr-2">
                              {items.map(req => <RequestCard key={req.id} data={req} />)}
                              {items.length === 0 && !isOver && (
                                  <div className="flex-1 border-2 border-dashed border-slate-100 rounded-xl flex items-center justify-center">
