        ) : (
            /* List View also simplified for order */
            <div className="h-full overflow-auto p-6">
                <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
                    <table className="w-full text-left text-sm">
                        <thead className="bg-slate-50 text-[10px] font-bold text-slate-400 uppercase tracking-widest border-b">
                            <tr>
                                <th className="px-6 py-4">ID</th>
                                <th className="px-6 py-4">Requerimiento</th>
                                <th className="px-6 py-4">Estado</th>
                                <th className="px-6 py-4">Prioridad</th>
                                <th className="px-6 py-4">Área</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-50">
                            {filteredRequests.map(req => (
                                <tr key={req.id} onClick={() => setSelectedRequestId(req.id)} className="hover:bg-slate-50 cursor-pointer transition-colors group">
                                    <td className="px-6 py-4 font-mono text-[10px] text-slate-400">#{req.id.split('-')[1]}</td>
                                    <td className="px-6 py-4 font-semibold text-slate-700 group-hover:text-indigo-600">{req.title}</td>
                                    <td className="px-6 py-4">
                                        <span className={`px-2 py-1 rounded-md text-[10px] font-bold uppercase ${STATUS_BADGE_COLORS[req.status]}`}>{req.status}</span>
                                    </td>
                                    <td className="px-6 py-4">
                                        <span className={`text-[10px] font-bold ${req.priority === Priority.HIGH ? 'text-red-500' : 'text-slate-500'}`}>{req.priority}</span>
                                    </td>
                                    <td className="px-6 py-4 text-xs text-slate-500 font-medium">{req.area}</td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

import React from 'react';
import { RequestCard as RequestCardType, Status, Priority } from '../types';
import { useSisreq } from '../context/SisreqContext';
import { Clock, User, AlertCircle } from 'lucide-react';

export const RequestCard: React.FC<{ data: RequestCardType }> = ({ data }) => {
  const { setSelectedRequestId, canMoveRequest } = useSisreq();

  const isDraggable = Object.values(Status).some(s => canMoveRequest(data, s));

  const handleDragStart = (e: React.DragEvent) => {
    e.dataTransfer.setData('requestId', data.id);
    e.dataTransfer.effectAllowed = 'move';
  };

  // Mapeo de colores para el borde lateral según el estado (identificador visual fuerte)
  const statusBorderColors: Record<Status, string> = {
    [Status.RECIBIDO]: 'border-blue-400',
    [Status.DERIVACION]: 'border-orange-400',
    [Status.EJECUCION]: 'border-amber-400',
    [Status.FINALIZADO]: 'border-emerald-400',
  };

  const priorityStyles = {
    [Priority.HIGH]: 'bg-red-50 text-red-600 border-red-100',
    [Priority.MEDIUM]: 'bg-amber-50 text-amber-600 border-amber-100',
    [Priority.LOW]: 'bg-slate-50 text-slate-500 border-slate-100',
  };

  return (
    <div 
        draggable={isDraggable}
        onDragStart={handleDragStart}
        onClick={() => setSelectedRequestId(data.id)}
        className={`bg-white rounded-xl p-4 border border-slate-200 border-l-[6px] transition-all duration-200 cursor-pointer shadow-sm hover:shadow-md hover:border-indigo-300 group relative flex flex-col gap-3 ${statusBorderColors[data.status]} ${isDraggable ? 'active:scale-[0.98] active:cursor-grabbing' : ''}`}
    >
      {/* Header: ID y Prioridad */}
      <div className="flex justify-between items-center">
        <span className="text-[10px] font-mono font-black text-slate-400">#{data.id.split('-')[1]}</span>
        <div className="flex items-center gap-1.5">
            {data.isReturned && (
                <span className="flex items-center gap-1 text-[9px] font-black text-red-500 bg-red-50 px-1.5 py-0.5 rounded-md border border-red-100">
                    <AlertCircle size={10}/> DEVUELTO
                </span>
            )}
            <span className={`text-[9px] font-bold px-2 py-0.5 rounded-full border ${priorityStyles[data.priority]}`}>
                {data.priority}
            </span>
        </div>
      </div>

      {/* Body: Título con énfasis en legibilidad */}
      <h3 className="text-sm font-bold text-slate-800 leading-tight group-hover:text-indigo-600 transition-colors line-clamp-2">
          {data.title}
      </h3>

      {/* Footer: Metadatos sutiles y limpios */}
      <div className="flex items-center justify-between mt-1 pt-3 border-t border-slate-50">
        <div className="flex items-center gap-3">
            <div className="flex items-center gap-1 text-[10px] text-slate-400 font-bold">
                <Clock size={12} className="text-slate-300" />
                {new Date(data.createdAt).toLocaleDateString([], { day: '2-digit', month: 'short' })}
            </div>
            {data.assignedAnalyst ? (
                <div className="flex items-center gap-1 text-[10px] text-indigo-600 font-black" title={`Asignado a: ${data.assignedAnalyst}`}>
                    <User size={12} className="text-indigo-300" />
                    <span className="max-w-[65px] truncate">{data.assignedAnalyst.split(' ')[0]}</span>
                </div>
            ) : (
                <span className="text-[9px] font-black text-slate-300 uppercase tracking-tighter">{data.area}</span>
            )}
        </div>

        {/* Indicador de acción sutil */}
        <div className="text-[9px] font-black text-slate-300 opacity-0 group-hover:opacity-100 transition-opacity uppercase tracking-widest">Ver detalle</div>
      </div>

      {/* Handle de arrastre visual para usuarios con permisos */}
      {isDraggable && (
        <div className="absolute -left-[6px] top-1/2 -translate-y-1/2 w-1 h-8 bg-black/10 rounded-r-full transition-all group-hover:bg-black/20"></div>
      )}
    </div>
  );
};

