import React from 'react';
import { RequestCard as RequestCardType, Status, Priority } from '../types';
import { useSisreq } from '../context/SisreqContext';
import { Clock, User, AlertCircle } from 'lucide-react';

export const RequestCard: React.FC<{ data: RequestCardType }> = ({ data }) => {
  const { setSelectedRequestId, canMoveRequest } = useSisreq();

  const isDraggable = Object.values(Status).some(s => canMoveRequest(data, s));

  const handleDragStart = (e: React.DragEvent) => {
    e.dataTransfer.setData('requestId', data.id);
    e.dataTransfer.effectAllowed = 'move';
  };

  const statusBorderColors: Record<Status, string> = {
    [Status.RECIBIDO]: 'border-blue-400',
    [Status.DERIVACION]: 'border-orange-400',
    [Status.EJECUCION]: 'border-amber-400',
    [Status.FINALIZADO]: 'border-emerald-400',
  };

  const priorityStyles = {
    [Priority.HIGH]: { bg: 'bg-red-50', text: 'text-red-600', dot: 'bg-red-500', border: 'border-red-100' },
    [Priority.MEDIUM]: { bg: 'bg-amber-50', text: 'text-amber-600', dot: 'bg-amber-500', border: 'border-amber-100' },
    [Priority.LOW]: { bg: 'bg-slate-50', text: 'text-slate-500', dot: 'bg-slate-400', border: 'border-slate-100' },
  };

  const style = priorityStyles[data.priority];

  return (
    <div 
        draggable={isDraggable}
        onDragStart={handleDragStart}
        onClick={() => setSelectedRequestId(data.id)}
        className={`bg-white rounded-xl p-4 border border-slate-200 border-l-[6px] transition-all duration-200 cursor-pointer shadow-sm hover:shadow-md hover:border-indigo-300 group relative flex flex-col gap-3.5 ${statusBorderColors[data.status]} ${isDraggable ? 'active:scale-[0.98] active:cursor-grabbing' : ''}`}
    >
      {/* Header: ID y Prioridad */}
      <div className="flex justify-between items-center">
        <span className="text-[9px] font-mono font-bold text-slate-400 bg-slate-50 px-1.5 py-0.5 rounded border border-slate-100 tracking-tighter uppercase">
            ID-{data.id.split('-')[1]}
        </span>
        <div className="flex items-center gap-1.5">
            {data.isReturned && (
                <span className="flex items-center gap-1 text-[8px] font-black text-red-500 bg-red-50 px-1.5 py-0.5 rounded border border-red-100">
                    <AlertCircle size={10} strokeWidth={3}/> DEV
                </span>
            )}
            <span className={`flex items-center gap-1.5 text-[9px] font-bold px-2 py-0.5 rounded-full border ${style.bg} ${style.text} ${style.border}`}>
                <div className={`w-1 h-1 rounded-full ${style.dot}`}></div>
                {data.priority}
            </span>
        </div>
      </div>

      {/* Body: Título */}
      <h3 className="text-[13px] font-bold text-slate-700 leading-snug group-hover:text-indigo-600 transition-colors line-clamp-2">
          {data.title}
      </h3>

      {/* Footer: Metadatos con detalle de autor */}
      <div className="flex items-center justify-between mt-1 pt-3 border-t border-slate-100/60">
        <div className="flex items-center gap-3">
            <div className="flex items-center gap-1.5 text-[10px] text-slate-400 font-medium">
                <Clock size={12} className="text-slate-300" strokeWidth={2.5}/>
                {new Date(data.createdAt).toLocaleDateString([], { day: '2-digit', month: 'short' })}
            </div>

            {data.assignedAnalyst ? (
                <div className="flex items-center gap-1.5" title={`Asignado a: ${data.assignedAnalyst}`}>
                    <div className="w-4 h-4 rounded-full bg-indigo-100 flex items-center justify-center text-[8px] font-black text-indigo-600 border border-indigo-200">
                        {data.assignedAnalyst[0]}
                    </div>
                    <span className="text-[10px] text-indigo-600 font-bold max-w-[55px] truncate">
                        {data.assignedAnalyst.split(' ')[0]}
                    </span>
                </div>
            ) : (
                <div className="flex items-center gap-1 text-[9px] font-bold text-slate-300 uppercase tracking-tighter">
                    <User size={12} strokeWidth={2.5} className="text-slate-200"/>
                    {data.area}
                </div>
            )}
        </div>

        <div className="w-1.5 h-1.5 rounded-full bg-slate-100 group-hover:bg-indigo-400 transition-all"></div>
      </div>

      {isDraggable && (
        <div className="absolute -left-[6px] top-1/2 -translate-y-1/2 w-1 h-6 bg-white/40 rounded-r-full"></div>
      )}
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { RequestCard } from './RequestCard';
import { Status, UserRole, Area } from '../types';
import { LayoutGrid, List, Search, Inbox, GitPullRequest, PlayCircle, CheckCircle2, Clock, ChevronDown } from 'lucide-react';
import { STATUS_BADGE_COLORS } from '../constants';

export const Board: React.FC = () => {
  const { requests, currentUser, updateStatus, setSelectedRequestId, globalFilterArea, setGlobalFilterArea, canMoveRequest } = useSisreq();
  const [dragOverColumn, setDragOverColumn] = useState<Status | null>(null);
  const [viewMode, setViewMode] = useState<'board' | 'list'>('board');
  const [searchTerm, setSearchTerm] = useState('');

  const filteredRequests = useMemo(() => {
    return requests.filter(req => {
      const isAdmin = currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.SUPERADMIN;
      const isOwnerArea = req.area === currentUser.area && req.status !== Status.RECIBIDO;
      if (!isAdmin && !isOwnerArea) return false;

      const matchesSearch = searchTerm === '' || 
          req.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
          req.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
          req.requester.toLowerCase().includes(searchTerm.toLowerCase());

      const matchesArea = globalFilterArea === 'ALL' || req.area === globalFilterArea;
      return matchesSearch && matchesArea;
    });
  }, [requests, currentUser, searchTerm, globalFilterArea]);

  const handleDrop = (e: React.DragEvent, targetStatus: Status) => {
    e.preventDefault();
    setDragOverColumn(null);
    const requestId = e.dataTransfer.getData('requestId');
    const req = requests.find(r => r.id === requestId);
    if (req && canMoveRequest(req, targetStatus)) {
      updateStatus(requestId, targetStatus);
    }
  };

  const COLUMNS = [
    { title: 'Bandeja', status: Status.RECIBIDO, icon: <Inbox size={14} />, color: 'bg-blue-400' },
    { title: 'Derivación', status: Status.DERIVACION, icon: <GitPullRequest size={14} />, color: 'bg-orange-400' },
    { title: 'Ejecución', status: Status.EJECUCION, icon: <PlayCircle size={14} />, color: 'bg-amber-400' },
    { title: 'Finalizado', status: Status.FINALIZADO, icon: <CheckCircle2 size={14} />, color: 'bg-emerald-400' }
  ];

  return (
    <div className="flex flex-col h-full overflow-hidden">
      {/* Toolbar */}
      <div className="px-6 py-4 flex flex-col md:flex-row items-center justify-between gap-4 border-b bg-white z-20">
          <div className="flex items-center gap-6">
             <h2 className="text-sm font-black text-slate-800 tracking-tight uppercase">Dashboard Operativo</h2>
             <div className="flex bg-slate-100 p-0.5 rounded-lg border border-slate-200">
                <button onClick={() => setViewMode('board')} className={`p-1.5 rounded-md transition-all ${viewMode === 'board' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-500'}`}><LayoutGrid size={16}/></button>
                <button onClick={() => setViewMode('list')} className={`p-1.5 rounded-md transition-all ${viewMode === 'list' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-500'}`}><List size={16}/></button>
             </div>
          </div>

          <div className="flex items-center gap-3 w-full md:w-auto">
             <div className="relative flex-1 md:flex-none">
                <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"/>
                <input 
                    type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="Buscar por título o ID..."
                    className="pl-9 pr-3 py-2 text-xs bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 outline-none w-full md:w-56 transition-all placeholder:text-slate-400"
                />
             </div>

             {(currentUser.role === UserRole.SUPERADMIN || currentUser.role === UserRole.ADMIN) && (
                <div className="relative">
                    <select
                        value={globalFilterArea} onChange={(e) => setGlobalFilterArea(e.target.value as Area | 'ALL')}
                        className="pl-3 pr-8 py-2 text-xs font-bold border border-slate-200 rounded-xl bg-slate-50 outline-none cursor-pointer hover:bg-white transition-all appearance-none text-slate-600"
                    >
                        <option value="ALL">Todas las Áreas</option>
                        {Object.values(Area).map(a => <option key={a} value={a}>{a}</option>)}
                    </select>
                    <ChevronDown size={14} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none"/>
                </div>
             )}
          </div>
      </div>

      {/* Main Board Area */}
      <div className="flex-1 overflow-hidden bg-slate-50/40">
        {viewMode === 'board' ? (
          <div className="h-full overflow-x-auto p-6 flex gap-6 scroll-smooth">
              {COLUMNS.map((col) => {
                  const items = filteredRequests.filter(r => r.status === col.status);
                  const isOver = dragOverColumn === col.status;
                  return (
                      <div 
                          key={col.status} 
                          className={`flex-1 flex flex-col min-w-[280px] max-w-[320px] transition-all rounded-2xl ${isOver ? 'bg-indigo-50/50 ring-2 ring-indigo-200' : ''}`}
                          onDragOver={(e) => { e.preventDefault(); setDragOverColumn(col.status); }}
                          onDragLeave={() => setDragOverColumn(null)}
                          onDrop={(e) => handleDrop(e, col.status)}
                      >
                          {/* Column Header */}
                          <div className="mb-5 px-1">
                              <div className="flex items-center justify-between mb-2">
                                  <div className="flex items-center gap-2.5">
                                      <div className={`p-1.5 rounded-lg ${col.color.replace('bg-', 'bg-opacity-10 text-')} bg-opacity-10 flex items-center justify-center border border-current border-opacity-10`}>
                                          {col.icon}
                                      </div>
                                      <span className="text-[11px] font-black text-slate-500 uppercase tracking-[0.1em]">{col.title}</span>
                                  </div>
                                  <span className="text-[10px] font-black bg-white border border-slate-200 text-slate-400 px-2 py-0.5 rounded-full shadow-sm">
                                      {items.length}
                                  </span>
                              </div>
                              <div className={`w-full h-[2px] rounded-full ${col.color} opacity-30`}></div>
                          </div>

                          {/* Cards Area */}
                          <div className="flex-1 overflow-y-auto custom-scrollbar flex flex-col gap-3.5 pr-1 pb-4">
                              {items.map(req => <RequestCard key={req.id} data={req} />)}
                              {items.length === 0 && !isOver && (
                                  <div className="flex-1 border-2 border-dashed border-slate-200/50 rounded-2xl flex flex-col items-center justify-center p-8 text-center bg-white/30">
                                      <span className="text-[10px] font-bold text-slate-300 uppercase tracking-widest">Sin Pendientes</span>
                                  </div>
                              )}
                              {isOver && <div className="h-24 border-2 border-dashed border-indigo-200 rounded-2xl bg-indigo-50/30 animate-pulse"></div>}
                          </div>
                      </div>
                  )
              })}
          </div>
        ) : (
            <div className="h-full overflow-auto p-6">
                <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
                    <table className="w-full text-left text-sm">
                        <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-[0.15em] border-b">
                            <tr>
                                <th className="px-6 py-4">ID</th>
                                <th className="px-6 py-4">Descripción</th>
                                <th className="px-6 py-4">Estado</th>
                                <th className="px-6 py-4">Prioridad</th>
                                <th className="px-6 py-4">Área</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-50">
                            {filteredRequests.map(req => (
                                <tr key={req.id} onClick={() => setSelectedRequestId(req.id)} className="hover:bg-slate-50 cursor-pointer transition-colors group">
                                    <td className="px-6 py-4 font-mono text-[10px] text-slate-400">ID-{req.id.split('-')[1]}</td>
                                    <td className="px-6 py-4 font-bold text-slate-700 group-hover:text-indigo-600 transition-colors">{req.title}</td>
                                    <td className="px-6 py-4">
                                        <span className={`px-2 py-1 rounded-md text-[10px] font-bold uppercase ${STATUS_BADGE_COLORS[req.status]}`}>{req.status}</span>
                                    </td>
                                    <td className="px-6 py-4">
                                        <span className={`text-[10px] font-black ${req.priority === 'Alta' ? 'text-red-500' : 'text-slate-400'}`}>{req.priority}</span>
                                    </td>
                                    <td className="px-6 py-4 text-xs text-slate-500 font-bold">{req.area}</td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { STATUS_BADGE_COLORS } from '../constants';
import { UserRole, Status } from '../types';
import { 
    X, Tag, ArrowRight, Pencil, Save, Send, Clock, Circle, CheckCircle2
} from 'lucide-react';

export const RequestDetailModal: React.FC = () => {
  const { 
    selectedRequestId, setSelectedRequestId, requests, currentUser, 
    updateStatus, updateRequestDetails, addLog
  } = useSisreq();

  const [isEditing, setIsEditing] = useState(false);
  const [editTitle, setEditTitle] = useState('');
  const [editDetail, setEditDetail] = useState('');
  const [newComment, setNewComment] = useState('');

  const data = useMemo(() => requests.find(r => r.id === selectedRequestId), [requests, selectedRequestId]);

  useEffect(() => {
     if (data) {
        setEditTitle(data.title);
        setEditDetail(data.detail);
        setIsEditing(false);
        setNewComment('');
     }
  }, [selectedRequestId, data]);

  if (!selectedRequestId || !data) return null;

  const handleSaveEdit = () => {
    if (editTitle.trim() && editDetail.trim()) {
        updateRequestDetails(data.id, editTitle, editDetail);
        setIsEditing(false);
    }
  };

  const handleAddLog = () => {
    if (newComment.trim()) {
      addLog(data.id, newComment);
      setNewComment('');
    }
  };

  const canEdit = currentUser.role === UserRole.SUPERADMIN || 
                  (currentUser.role === UserRole.ADMIN && data.status === Status.RECIBIDO) ||
                  ((currentUser.role === UserRole.HEAD || currentUser.role === UserRole.ANALYST) && data.area === currentUser.area);

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity" onClick={() => setSelectedRequestId(null)}></div>

      <div className="relative bg-white rounded-[24px] shadow-2xl w-full max-w-4xl max-h-[90vh] flex flex-col overflow-hidden animate-in fade-in zoom-in-95 duration-200">

        {/* Header Section */}
        <div className="px-8 pt-8 pb-6 shrink-0 relative">
            <div className="flex items-center gap-3 mb-2">
                <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-wider ${STATUS_BADGE_COLORS[data.status]}`}>
                    {data.status}
                </span>
                <span className="text-xs font-bold text-slate-300 font-mono">#{data.id.split('-')[1]}</span>
                {canEdit && !isEditing && (
                    <button onClick={() => setIsEditing(true)} className="text-slate-300 hover:text-indigo-600 transition-colors">
                        <Pencil size={14} />
                    </button>
                )}
            </div>

            {isEditing ? (
                <div className="flex gap-2">
                    <input 
                        value={editTitle} 
                        onChange={(e) => setEditTitle(e.target.value)} 
                        className="flex-1 text-2xl font-black text-slate-800 border-b-2 border-indigo-500 outline-none pb-1"
                        autoFocus
                    />
                    <button onClick={handleSaveEdit} className="p-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors">
                        <Save size={18}/>
                    </button>
                </div>
            ) : (
                <h2 className="text-2xl font-black text-slate-800 tracking-tight">{data.title}</h2>
            )}

            {/* Circular Close Button */}
            <button 
                onClick={() => setSelectedRequestId(null)} 
                className="absolute top-6 right-8 w-10 h-10 flex items-center justify-center bg-white border border-slate-100 rounded-full text-slate-400 hover:text-slate-600 shadow-sm hover:shadow-md transition-all"
            >
                <X size={20} />
            </button>
        </div>

        {/* Content Body */}
        <div className="flex-1 overflow-hidden flex flex-col md:flex-row border-t border-slate-100">

            {/* Left Panel: Description and Info */}
            <div className="flex-1 overflow-y-auto custom-scrollbar p-8 space-y-8">
                <div className="space-y-3">
                    <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.15em] flex items-center gap-2">
                        <Tag size={12} className="text-slate-300"/> DESCRIPCIÓN
                    </h3>
                    {isEditing ? (
                        <textarea 
                            value={editDetail} 
                            onChange={(e) => setEditDetail(e.target.value)} 
                            className="w-full h-32 bg-slate-50 border border-slate-200 rounded-2xl p-4 text-sm outline-none focus:border-indigo-400 transition-all resize-none"
                        />
                    ) : (
                        <div className="bg-slate-50/80 p-6 rounded-[20px] border border-slate-100/50 text-sm text-slate-600 leading-relaxed font-medium">
                            {data.detail}
                        </div>
                    )}
                </div>

                <div className="grid grid-cols-2 gap-6">
                    <div className="bg-white p-5 rounded-[20px] border border-slate-100 shadow-sm">
                        <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest block mb-1">SOLICITANTE</span>
                        <span className="text-sm font-bold text-slate-700">{data.requester}</span>
                    </div>
                    <div className="bg-white p-5 rounded-[20px] border border-slate-100 shadow-sm">
                        <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest block mb-1">ÁREA DESTINO</span>
                        <span className="text-sm font-bold text-slate-700">{data.area}</span>
                    </div>
                </div>
            </div>

            {/* Right Panel: Activity */}
            <div className="w-full md:w-[380px] bg-slate-50/30 border-l border-slate-100 flex flex-col">
                <div className="p-6 border-b border-slate-100 bg-white/50">
                    <div className="relative group">
                        <textarea 
                            value={newComment} 
                            onChange={e => setNewComment(e.target.value)} 
                            className="w-full text-xs p-4 pr-12 border border-slate-200 rounded-2xl bg-slate-50 outline-none focus:ring-2 focus:ring-indigo-100 focus:bg-white transition-all resize-none placeholder:text-slate-400" 
                            placeholder="Agregar nota interna..." 
                            rows={3} 
                        />
                        <button 
                            onClick={handleAddLog} 
                            disabled={!newComment.trim()} 
                            className="absolute right-3 bottom-3 w-8 h-8 bg-indigo-500 text-white rounded-xl flex items-center justify-center disabled:opacity-30 hover:bg-indigo-600 transition-all"
                        >
                            <Send size={14}/>
                        </button>
                    </div>
                </div>

                <div className="flex-1 overflow-y-auto p-8 custom-scrollbar">
                    <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.15em] flex items-center gap-2 mb-6">
                        <Clock size={12} className="text-slate-300"/> ACTIVIDAD RECIENTE
                    </h3>
                    <div className="relative space-y-8 pl-4">
                        <div className="absolute left-[3px] top-0 bottom-2 w-px bg-slate-200"></div>

                        {[...data.logs].reverse().map(log => (
                            <div key={log.id} className="relative">
                                <div className="absolute -left-[18px] top-1 w-2.5 h-2.5 rounded-full bg-white border-2 border-slate-200 z-10 shadow-sm"></div>
                                <div className="flex flex-col gap-1.5">
                                    <div className="flex justify-between items-center">
                                        <span className="text-[11px] font-black text-slate-800">{log.actor}</span>
                                        <span className="text-[9px] text-slate-400 font-bold">{new Date(log.timestamp).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}</span>
                                    </div>
                                    <div className="bg-white p-3.5 rounded-2xl rounded-tl-none border border-slate-100 shadow-sm">
                                        <p className="text-[11px] text-slate-600 leading-relaxed font-medium">{log.message}</p>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </div>

        {/* Footer Actions */}
        <div className="bg-white border-t border-slate-100 p-6 flex items-center justify-between shrink-0">
             <button 
                onClick={() => setSelectedRequestId(null)} 
                className="px-4 py-2 text-slate-400 hover:text-slate-600 font-bold text-sm transition-colors"
             >
                Cerrar
             </button>

             <div className="flex gap-4">
                {data.status === Status.RECIBIDO && (currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.SUPERADMIN) && (
                    <button 
                        onClick={() => updateStatus(data.id, Status.DERIVACION)} 
                        className="bg-[#FF7F27] hover:bg-[#e66f1e] text-white px-6 py-2.5 rounded-xl text-sm font-black shadow-lg transition-all flex items-center gap-2"
                    >
                        <ArrowRight size={18} strokeWidth={2.5}/> Derivar Área
                    </button>
                )}

                {data.status !== Status.FINALIZADO && data.status !== Status.RECIBIDO && (
                    <button 
                        onClick={() => updateStatus(data.id, Status.FINALIZADO)} 
                        className="bg-[#00A65A] hover:bg-[#008d4c] text-white px-6 py-2.5 rounded-xl text-sm font-black shadow-lg transition-all flex items-center gap-2"
                    >
                        <CheckCircle2 size={18} strokeWidth={2.5}/> Finalizar
                    </button>
                )}
             </div>
        </div>
      </div>
    </div>
  );
};
